WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[9848] = { title = "Secrets of the Daggerfen", description = "Bugs, bugs, bugs! The marsh is full of them and my companions here seem obsessed with them.\n\nWell, I've had it with the bugs! Something far more intriguing has captured my interest. To the west, there is a village of Lost Ones who call themselves the Daggerfen.\n\nThe whole tribe consists of highly specialized assassins. I've noticed them mixing and using a particularly potent kind of poison. I'm dying to know more about the poison, but that's going to require a copy of the recipe and a sample vial.", objectives = "" }
WordHunterWoW_QuestEN[9849] = { title = "Shattering the Veil", description = "<Gordawg breaks off a piece of ebon rock from his back.>\n\nYou are granted a piece of the fury of the earth. Take the boulder of Gordawg and hurl it at the poison rock. Shatter their shells to discover the truth. Destroy the minions of the usurper and return to Gordawg with the name.\n\nYou find the shattered elements at the edge of the world. Southwest.", objectives = "" }
WordHunterWoW_QuestEN[9850] = { title = "Clefthoof Mastery", description = "You've proved to me that you can find and take down a regular clefthoof, but far more dangerous are the clefthoof bulls.\n\nBag yourself twelve of those.  Then you can talk to me of your hunting prowess.\n\nLook for them all along the middle region of Nagrand to the west and south.", objectives = "" }
WordHunterWoW_QuestEN[9851] = { title = "Clefthoof Mastery", description = "Banthar is the fiercest and most elusive of all the clefthoof in Outland.  She's also the hairiest.\n\nIt is said that she roams with her clefthoof herd in the Spirit Fields near Oshu'gun.\n\nYou want to truly prove your hunting mastery?  Bring me her horn!", objectives = "" }
WordHunterWoW_QuestEN[9852] = { title = "The Ultimate Bloodsport", description = "The queen of all that dwell in Nagrand is known as Tusker.  She's a giant elekk the likes of which you won't see anywhere else!\n\nYou're right to be fearful of that name.  Bach'lor, Gutripper, and Banthar are nothing when compared to her.  It is said that she can be found on a huge bluff far to the southwest overlooking Oshu'gun.  Bring me her massive heart if you dare.\n\nDo you want to leave a letter with me so that I can have it delivered to your next of kin in the likely event that you don't return?", objectives = "" }
WordHunterWoW_QuestEN[9853] = { title = "Gurok the Usurper", description = "Gurok must be summoned. You summon Gurok and you destroy.\n\nYou must go to Warmaul Hill to the northwest and find where ogre worships Gurok. You put ogre skull from Warmaul ogres on Gurok's earthen brand. Only then will Gurok come. Seven skulls.\n\nIf you live, bring Gordawg back Gurok earthen head. Gordawg crushes head.\n\n<Gordawg bites down hard, shaking the earth beneath your feet.>", objectives = "" }
WordHunterWoW_QuestEN[9854] = { title = "Windroc Mastery", description = "Do you live for the hunt as I do, {class}?  Do you seek the quietude that comes as you stalk your prey?  Would you know what it is to honor the last heartbeats of your fallen quarry?  I will help you to achieve this.\n\nNagrand is a lush land, full of life in the midst of this broken world.  Bring down a handful of the windrocs and then we will speak more.\n\nYou can find them in many places nearby in all directions around our camp.", objectives = "" }
WordHunterWoW_QuestEN[9855] = { title = "Windroc Mastery", description = "You must always push yourself if you are to one day stalk the mightiest of prey!  While you are not yet ready, I will point you in the right direction.\n\nThere is another breed of windroc even deadlier.  Seek out the ravenous windroc to test your mettle against.  You will find them in the heart of Nagrand to the west and southwest.", objectives = "" }
WordHunterWoW_QuestEN[9856] = { title = "Windroc Mastery", description = "You are ready, {class}.  Ready to face the mother of all windrocs, Gutripper!  Honor demands that after hunting so many of her children that you give her the chance to defeat you!  Seek her out amongst the greater windroc far to the west.\n\nShould you survive, bring her eye to me.", objectives = "" }
WordHunterWoW_QuestEN[9857] = { title = "Talbuk Mastery", description = "I don't think that I'm up to the hunt today.  Do you think that you might take my place?\n\nI told Hemet that I was going to see about bagging us some of those talbuk that seem to be all over the place.  The stags are especially nice to hunt.  You can find them congregated around the nearby trees.\n\nThink that you could take care of that for me?", objectives = "" }
WordHunterWoW_QuestEN[9858] = { title = "Talbuk Mastery", description = "This darned scratch is getting the worst of me it would seem.  So, are you up to filling...<cough>... in for me again?\n\nThis time you're going to bag yourself some thorngrazers.  They're tougher and wilier than the stags, so keep your wits about you.  Look for them... <cough>... sheltered under the trees in the middle of Nagrand to the west and south.\n\nGo on, get out there and...<cough>... show Hemet what you're made of.  I'll be fine.", objectives = "" }
WordHunterWoW_QuestEN[9859] = { title = "Talbuk Mastery", description = "<Wracking cough.>\n\nDon't worry about...<cough>... me.  I'll be fine.  It's just a...<cough>... scratch.\n\nJust the same, I think you'll... <cough>... have to fill in for me one more... <cough>... time.\n\nYou must seek out the great Bach'lor, king of...<cough>... the stags.\n\nBring me one of his hooves...<cough>, <cough>... as confirmation.\n\nLook for him...<cough>... leading his herd in the far west of Nagrand.", objectives = "" }
WordHunterWoW_QuestEN[9861] = { title = "The Howling Wind", description = "This amorphous mass of elemental air is speaking to you in a language that you cannot understand. You believe the language to be the tongue of the elements: Kalimag. Perhaps someone at the Throne of the Elements could shed some insight on this unusual find.", objectives = "" }
WordHunterWoW_QuestEN[9862] = { title = "Murkblood Corrupters", description = "Murkblood are capturing and torturing the spirits of air! Murkblood are my kin: A tribe of the Broken who serve the vile Musel'ek, beast lord of Coilfang.\n\nThe air spirit states that the Murkblood putrefiers are capturing other spirits of air and using them to sow chaos into the ranks of the elements. It would seem that the Murkblood have recently sacked an orc village to the southwest known as Sunspring and are using powerful elemental magic to disturb the lake. Find the putrefiers and destroy them.", objectives = "" }
WordHunterWoW_QuestEN[9863] = { title = "Vile Idolatry", description = "With our leadership in ruin, we are left open to attacks from all sides. The foul Murkblood tribe could not have picked a better time to attack us!\n\nIn recent days, we have been subject to no less than 5 assaults from the Broken. They have even taken over our only other territorial holding in the area: Sunspring Post.\n\nWe must strike and show them that we are not powerless! Strike down the vile idolaters and bring me their twisted idols of worship so that they may ride the lightning.", objectives = "" }
WordHunterWoW_QuestEN[9864] = { title = "The Missing War Party", description = "After the last Murkblood raid, a group of younglings decided to act. We tried to stop them but the rage had taken hold. It has now been one week since we last saw our beloved younglings.\n\nPlease, {race}, you must find them! They have just barely reached adolescence. How can they expect to defeat such savages?\n\nThey took the road leading west out of town. Follow that road around and look for signs of our younglings.\n\nAnd {name}, avoid Halaa if you value your life. It is a war-zone.", objectives = "" }
WordHunterWoW_QuestEN[9865] = { title = "Once Were Warriors", description = "I do not know you, stranger, but I ask for your help. I feel shame for this, but I am only one orc.\n\nEmotions have surfaced that I have never felt. I... I seek vengeance. Blood for blood. Do your people ever feel this? I wish to pick up my axe and split my enemies in two. To swing the weapon until my arms fall lifelessly at my sides, exhausted.\n\nSunspring Post is directly south of this procession. It is there that you will find our enemies... Kill them... Kill them all...", objectives = "" }
WordHunterWoW_QuestEN[9866] = { title = "He Will Walk The Earth...", description = "Will you do me one last honor, {name}? I do not wish to return to Garadar. I believe that my destiny lies elsewhere - that I will serve a greater purpose someday.\n\nPlease, return to Farseer Corhuk and tell him that I will not be returning. That I cannot return. I must walk the earth... He will understand.", objectives = "" }
WordHunterWoW_QuestEN[9867] = { title = "Murkblood Leaders...", description = "We have lost many friends in recent weeks.\n\nFor decades we have dealt with the ogres of Nagrand but now a new threat has arisen. The Broken tribe of Murkblood attacked our fishing village to the southwest, Sunspring Post, and managed to kill or evict all of the orcs that inhabited the town.\n\nWhile the others feel that the best course of action is to kill indiscriminately, I know that we must destroy their leadership. I do not know who their leader is but I suspect that you will know when you find him.", objectives = "" }
WordHunterWoW_QuestEN[9868] = { title = "The Totem of Kar'dash", description = "Thank you, stranger. They would have surely killed me had it not been for you.\n\nI was kidnapped by these Murkbloods 3 nights ago during a nighttime raid on Garadar. What I have since uncovered may very well shake the foundation of the Outland: these savages seek to recover the totem of Kar'dash! We cannot allow the totem to fall into the hands of the Murkbloods!\n\nYou must help me escape. And stranger, if I do not make it back to Garadar, you must tell Garrosh what happened here... ", objectives = "" }
WordHunterWoW_QuestEN[9869] = { title = "The Throne of the Elements", description = "Greetings, {race}. I am Ioki, elementalist of the Earthen Ring. I have come to Telaar to inform the Kurenai of the state of the elements.\n\nCould I ask a favor of you? Would you travel to the Throne of the Elements in the northern hills of Nagrand, beyond Skysong Lake, and tell elementalist Sharvak that I have arrived at Telaar safely? She will surely reward you for this small deed.", objectives = "" }
WordHunterWoW_QuestEN[9870] = { title = "The Throne of the Elements", description = "Greetings, {race}. I am Yal'hah, elementalist of the Earthen Ring. I have come to Garadar to inform the Mag'har of the state of the elements.\n\nCould I ask a favor of you? Would you travel to the Throne of the Elements in the northern hills of Nagrand, beyond Skysong Lake, and tell elementalist Sharvak that I have arrived at Garadar safely? She will surely reward you for this small deed.", objectives = "" }
WordHunterWoW_QuestEN[9871] = { title = "Murkblood Invaders", description = "The parchment holds a crudely painted map of Nagrand. There is a big red 'X' where Telaar would be on the map. It would seem that these savages are planning an attack on the city. Take the Murkblood invasion plans to Arechron in Telaar.\n", objectives = "" }
WordHunterWoW_QuestEN[9872] = { title = "Murkblood Invaders", description = "The parchment holds a crudely painted map of Nagrand. There is a big red 'X' where Garadar would be on the map. It would seem that these savages are planning an attack on the city. Take the Murkblood invasion plans to Garrosh in Garadar.", objectives = "" }
WordHunterWoW_QuestEN[9873] = { title = "Ortor My Old Friend...", description = "These invasion plans were written by someone I once knew. Ortor of Murkblood, once a noble Broken, versed in the way of the elements, now a muck addled yes-man of Musel'ek the bog lord.\n\nThe plans state that they have taken over an orc village northwest of here known as Sunspring.\n\nTravel to Sunspring Post and rid the world of Ortor of Murkblood. What you do, you do for the good of us all...", objectives = "" }
WordHunterWoW_QuestEN[9874] = { title = "Stopping the Spread", description = "I have just gotten word of a catastrophe of epic proportions, {name}. The foul Murkblood have sacked the orc village of Sunspring Post, northwest of here, and murdered its residents. To make matters worse, they have begun dumping the bodies into Sunspring Lake. Should those bodies rot, our primary source of water in the region will be compromised.\n\nIt's a gruesome task that I give you next but it must be done. Take this enchanted torch and return to Sunspring. Burn all of the rotting orc corpses...", objectives = "" }
WordHunterWoW_QuestEN[9878] = { title = "Solving the Problem", description = "The appearance of the Murkblood in Nagrand has had a profound negative impact on our environment. The elementals are all in flux which has, in turn, greatly disturbed the wildlife. Worse yet, the razing of Sunspring Post has reignited the hatred that the orcs held for our people.\n\nWhile the Kurenai are a different tribe than the Murkblood, all an orc sees is Broken.\n\nWe must make an effort to solve this dilemma. Travel to Sunspring Post, northwest of here, and resolve the Murkblood problem.", objectives = "" }
WordHunterWoW_QuestEN[9879] = { title = "The Totem of Kar'dash", description = "I would have been killed had you not come along, stranger. They have already murdered so many Kurenai in their search for a lost relic.\n\nWhat they seek is the totem of Kar'dash. Why they think that we would know anything about this totem, I cannot understand. Is a totem not an orcish implement by nature?\n\nThis information must be taken back to Arechron. Perhaps he knows why Murkblood are kidnapping Kurenai and torturing them for information regarding an orcish device.\n\nLet's go before more come.", objectives = "" }
WordHunterWoW_QuestEN[9882] = { title = "Stealing from Thieves", description = "Nexus Prince Haramad has ordered us to not begin work inside of Oshu'gun as it might anger a certain powerful naaru.  Sort of puts a damper on our operation.\n\nI think I might've found a loophole, however.\n\nYou see, we're not the only ethereals drawn to this colossal diamond.  A thief called Gava'xi has led a band of rogue ethereals into Oshu'gun and they've begun to dislodge large fragments from it.\n\nYour job, {race}, is to go there and retrieve what is rightfully ours.", objectives = "" }
WordHunterWoW_QuestEN[9884] = { title = "Membership Benefits", description = "", objectives = "" }
WordHunterWoW_QuestEN[9885] = { title = "Membership Benefits", description = "", objectives = "" }
WordHunterWoW_QuestEN[9886] = { title = "Membership Benefits", description = "", objectives = "" }
WordHunterWoW_QuestEN[9887] = { title = "Membership Benefits", description = "", objectives = "" }
WordHunterWoW_QuestEN[9888] = { title = "The Impotent Leader", description = "I have escaped certain death, surviving a cowardly nighttime attack by Boulderfist ogres upon my village.\n\nBut I ask you, stranger: For what?\n\n<Jorin points to Garrosh.>\n\nHe has refused to give us assistance. Ogres are rampaging through my town and he sits here, weeping into a fire. What has become of us? What will become of us?\n\nI've sent a scout, Kilrath, to the village, now the Bleeding Hollow Ruins. Will you find him and give him your assistance? He hides on the border of Nagrand and Terokkar.", objectives = "" }
WordHunterWoW_QuestEN[9889] = { title = "Don't Kill the Fat One", description = "I have been watching these beasts for days. The fat one says that he is waiting for something. What he is waiting for, however, is a mystery.\n\nI have a plan but it is going to involve some violence on your part. You will need to kill several of his subordinates and then beat him within an inch of his life. Do this and I am certain he will tell us everything that we need to know.", objectives = "" }
WordHunterWoW_QuestEN[9890] = { title = "Success!", description = "For many years, Boulderfist ruled all ogres in the Outland. The ogres were united under Krol and content with the lands that they were given. In the past few months, we have lost many ogres to a new clan known as Warmaul. Warmaul has taken most of our land in Nagrand and killed many of our people.\n\nWe had no choice but to take this town. We are being exterminated...\n\nKrol has gone missing and Boulderfist is in turmoil. Lantresor of the Blade rules in his absence.\n", objectives = "" }
WordHunterWoW_QuestEN[9891] = { title = "Because Kilrath is a Coward", description = "Take what you have learned and tell Jorin at Garadar. I can assure you that he won't be happy to know that our village was destroyed and many of our people killed because the ogres needed more space.\n\nMay the ancestors watch over you... I will be hiding in the bushes if you need me for anything else.", objectives = "" }
WordHunterWoW_QuestEN[9893] = { title = "Obsidian Warbeads", description = "All this waiting around for Oshu'gun to be ready for digging is eating into our profits, {name}.\n\nFortunately, I've devised an alternate source of income.  The ogres of Nagrand wear warbeads made of obsidian, a mineral that commands a hefty price in many other worlds.\n\nZerid already has had to take care a few of the brutes as a matter of security.  Think of the warbeads as an added bonus.  Or better yet, don't think about it too much and just bring them to me.", objectives = "" }
WordHunterWoW_QuestEN[9894] = { title = "Safeguarding the Watchers", description = "In your travels, you might have encountered some of the expedition's watchers. They do the majority of the field work: documenting the unique inhabitants of the marsh, collecting samples, and making contact with sentient species.\n\nThe safety of the watchers is paramount, {class}. We've had to recall the watchers we sent to explore Funggor Cavern to the south, because of marshbeast attacks. Warden Hamoot believes that killing their leader, Lord Klaq, will bring a swift end to the attacks. ", objectives = "" }
WordHunterWoW_QuestEN[9895] = { title = "The Dying Balance", description = "Have you observed your surroundings closely, {name}? This is an ailing landscape, struggling to keep itself in balance and losing the fight.\n\nIf you know where to look, you can see the symptoms. Members of some species rapidly outgrow their peers and become more aggressive.\n\nA good example of this uncontrolled growth is the marshtrekker Boglash. If you wish to see it for yourself, look no further than the waterways south of the refuge.\n\nBe prepared to defend yourself. The creature knows no mercy.", objectives = "" }
WordHunterWoW_QuestEN[9896] = { title = "Blacksting's Bane", description = "By Khaz'goroth's flaming navel, it's hot here! I can't blame the first party for leaving, but everyone knows 'twasn't the heat that drove them away. No, it was Blacksting, although they won't admit it.\n\nThey were camped just to the south of the glowing draenei towers to the west, just north of the Feralfen Village, when the giant wasp appears out of nowhere and attacks! I can't wait to see the looks on their faces when I bring the creature's stinger back to Ironforge and show it to them!", objectives = "" }
WordHunterWoW_QuestEN[9897] = { title = "I'm Saved!", description = "I don't mind sharing.  I'm just glad to be saved from that creep, Gankly!  And I collected tons of skins from Zangarmarsh, so it's no problem at all!", objectives = "" }
WordHunterWoW_QuestEN[9898] = { title = "The Respect of Another", description = "Magasha is the fiercest troll in the Marsh, but she only respects mighty hunters. \n\nI tried to prove myself to her, but the one beast that could impress her is beyond my skill. Maybe you could help me out? It's the giant bog wasp known as Blacksting that roams the area south of the glowing draenei towers to the west. If you bring me its stinger maybe she'll give me a chance to join her hunters.\n\nI know it's a little sneaky, but I promise to learn under her and do ya both proud.", objectives = "" }
WordHunterWoW_QuestEN[9899] = { title = "A Job Undone", description = "Someone needs to find a way to make Reavij come to his senses! He's ignoring his duty and instead, he's devoting all his energy to getting my attention. I've tried ignoring him and telling him to stop. Nothing seems to work.\n\nUntil he gets over this, I'm left cleaning up after him. He was supposed to have dealt with Sporewing, but I'll bet the monster is alive and well. If you have time, would you mind going to the western part of the Dead Mire and killing the bat? I'll deal with Reavij in the meantime.", objectives = "" }
WordHunterWoW_QuestEN[9900] = { title = "Gava'xi", description = "The presence of rogue ethereals in this area might amuse Gezhe, who sees nothing but opportunity wherever we go, but it's a true threat to the security of our operations.\n\nTheir leader, Gava'xi, is a dangerous criminal and I've made it my top priority to see to it that he is neutralized.\n\nIf you're looking to make yourself useful, go and take care of Gava'xi.  I will see to it that you're rewarded properly.", objectives = "" }
WordHunterWoW_QuestEN[9901] = { title = "Unfinished Business", description = "The first expedition the league sent reported encountering a gigantic spore bat they'd taken to calling Sporewing. They had to leave in a hurry, so they didn't have the chance to kill him while they were here, so I figured I'd finish the job for them.\n\nWhat's left of their report suggests that the creature can be found in the southwestern parts of the Dead Mire. I think Vindicator Idaar mentioned that it's to the northeast of Telredor.", objectives = "" }
WordHunterWoW_QuestEN[9902] = { title = "The Terror of Marshlight Lake", description = "Traveling through naga-infested lands has shown me the cruel truth about how my less fortunate brethren are treated. At Marshlight Lake, to the southwest, I observed a particularly malicious taskmaster playing a deadly game. He orders his slaves out to the islands in Marshlight Lake when he knows that Terrorclaw, a giant bogstrok, is ready to feed.\n\nI needn't describe what results. We are too few to take on the naga directly, but we can deprive them of their amusement by killing their pet.", objectives = "" }
WordHunterWoW_QuestEN[9903] = { title = "The Biggest of Them All", description = "You've dealt with most of the little hydra, but I doubt Mragesh was impressed by your display. He's a cunning, ferocious beast and he's dogged many an angler in his time.\n\nI intend to be the last one he'll ever bother. He's bound to be hiding deep in the waters of Serpent Lake, to the northeast. He's a has-been; he just doesn't know it yet.", objectives = "" }
WordHunterWoW_QuestEN[9904] = { title = "Pursuing Terrorclaw", description = "I've caught every kind of fish that lives in the marsh, but there's one that eludes me. Sure, I've caught eels and mudfin frenzies. But the last time I was out on one of the islands in Marshlight Lake, I hooked a gigantic bogstrok that snapped my line and got away.\n\nTerrorclaw, he's called, and I won't rest until he's dead. He's too big for any fisherman to catch, so I suppose we'll just have to kill him the old-fashioned way.", objectives = "" }
WordHunterWoW_QuestEN[9905] = { title = "Maktu's Revenge", description = "Last time Maktu was out hunting hydras for hides at Serpent Lake, he was attacked by the biggest hydra he's ever seen. Maktu reached for his spear, but it was too late. He had just enough time to escape becoming hydra food.\n\nWho knows? Maybe next time, Maktu not be so lucky. Maktu wants to be there so there won't be a next time. Will you help Maktu get his revenge on Mragesh?", objectives = "" }
WordHunterWoW_QuestEN[9906] = { title = "Message in a Battle", description = "Ogres are moved by one thing: Might. If we expose ourselves to them as being weak, they will take advantage of that weakness and wipe us out.\n\nGarrosh might be ready to lie down and let the ogre dogs take our lands but I am not! I need you to deliver a message to the Boulderfist, {name}. The only type of message that they are capable of understanding: Brutality.\n\nTravel to the Burning Blade Ruins, southeast of here and show them the might of the Mag'har.\n\nAnd {name}, check in with the others before leaving.", objectives = "" }
WordHunterWoW_QuestEN[9907] = { title = "An Audacious Advance", description = "Directly west of here you will find the Halaani Basin. Within the basin are the twin clefts of Nagrand: Northwind and Southwind. Boulderfist shock troops use the clefts to hide their ogre mounds.\n\nI need you to track down those troops and kill all that you encounter in the name of Mag'har.", objectives = "" }
WordHunterWoW_QuestEN[9910] = { title = "Standards and Practices", description = "If you're venturing into the Burning Blade Ruins, I have a task for you. Take these Mag'har battle standards and place them at three distinct locations in the ogre compound. An area of high visibility is recommended. Look for the gigantic flaming pyres on the upper levels. Place a standard near the first, second, and third Burning Blade pyres.\n\nThe standard will leave a lasting impression upon any ogres who may have missed the battle.", objectives = "" }
WordHunterWoW_QuestEN[9911] = { title = "The Count of the Marshes", description = "This bloody mandible comes from an unbelievably large creature. The nether ray that it belonged to has to be the largest ever seen in Zangarmarsh. Judging from the condition of the mandible, the count must've abandoned a diet of carrion in favor of living flesh.\n\nSurely the Cenarion Expedition would be interested in such a specimen. Watcher Leesa'oh has a small camp to the west of Quagg Ridge.", objectives = "" }
WordHunterWoW_QuestEN[9912] = { title = "The Cenarion Expedition", description = "The Cenarion Circle's main expeditionary force in Outland is known as the Cenarion Expedition.  Though it began as a small venture controlled directly by the Cenarion Circle, it's become a large and fairly autonomous body.\n\nThe expedition's leader, Ysiel Windsinger, has asked us to direct volunteers to her outpost.  Report to her at the Cenarion Refuge in eastern Zangarmarsh.  Take the main path to the west and it will lead you directly there.", objectives = "" }
WordHunterWoW_QuestEN[9913] = { title = "The Consortium Needs You!", description = "My organization, the Consortium, is looking for a few resourceful individuals just like yourself.  You'll be hard pressed to find ethereals more honest, hard-working or pleasant to be around than us.\n\nAll we require is loyalty, dedication and a reasonable amount of moral flexibility.  If you're interested, speak to Gezhe, our ground operations leader.  You will find him at Aeris Landing, north of Oshu'gun.", objectives = "" }
WordHunterWoW_QuestEN[9914] = { title = "A Head Full of Ivory", description = "Ivory is a much sought after prize.  I have many customers lined up in far off places to purchase it.\n\nI could be convinced to let you in on a cut of the profits.\n\nThe wild elekk roaming Nagrand have the high quality of tusks that I'm after.  Steer clear of the bull elekk; their ivory isn't in the condition that I desire.\n\nOh and don't worry, it's not poaching; I have an understanding with both the orcs and the draenei.\n\nDo you and I have an understanding?", objectives = "" }
WordHunterWoW_QuestEN[9916] = { title = "Bleeding Hollow Supply Crates", description = "The Boulderfist have moved the supplies they stole from our village to the twin clefts of Nagrand, found west of here in the Halaani Basin.\n\nWhile you are in the area, keep your eye out for the supply crates. If we can get those back, it would ease much of the burden that has fallen upon the matrons of Garadar.", objectives = "" }
WordHunterWoW_QuestEN[9917] = { title = "Do My Eyes Deceive Me", description = "Do my eyes deceive me or is there an ogre hunting party over yonder? What could ogres be doing this far from their mound? I don't like this one bit, stranger. First Murkbloods and now ogres. We just don't have the manpower to handle all of these threats to our land.\n\nCould you investigate the ogre presence to the east for us? Their forward camp is about 200 paces east of here. You'll know you're at the right place if you see the Boulderfist hunters. Kill them to find the plans!", objectives = "" }
WordHunterWoW_QuestEN[9918] = { title = "Not On My Watch!", description = "The battle plans were written up by an ogre lieutenant. His name is either Dump or Lump.\n\n<Bintook turns the parchment sideways and cocks her head.>\n\nIt could also be Billy.\n\nAnyhow, I think you should go back out there and have a word with Billy or Lump or Dumpy or whatever! Try to approach him diplomatically. If that doesn't work, try using some muscle.", objectives = "" }
WordHunterWoW_QuestEN[9919] = { title = "Sporeggar", description = "You're a kind {race}, {name}.  Not like some of the others I've met.\n\nYou should meet the rest of my people; they'll be very grateful for your help.  Take these spore sacs to my leader, Msshi'fn.  You will find him in Sporeggar, north of here.", objectives = "" }
WordHunterWoW_QuestEN[9920] = { title = "Mo'mor the Breaker", description = "You must seek out Mo'mor immediately! You will find him in the center of Telaar, by the fountain. Tell him exactly what the ogre told you.", objectives = "" }
WordHunterWoW_QuestEN[9921] = { title = "The Ruins of Burning Blade", description = "These ogre hunting parties are a precursor to invasion. We must strike at them before they have a chance to amass an army big enough to take over our town.\n\nYou're going to need to get your hands dirty, {race}.\n\nThe largest collection of Boulderfist in this region can be found at the Burning Blade Ruins, almost directly east of Telaar, near the border of Terokkar. Go there and show the Boulderfist that Telaar will not bend to their will!", objectives = "" }
WordHunterWoW_QuestEN[9922] = { title = "The Twin Clefts of Nagrand", description = "You made a strong showing, {name}. Are you ready for more?\n\nI have received reports of a large contingent of Boulderfist ogres hidden in the twin clefts of Nagrand, northwest of here in the Halaani Basin.\n\nVenture forth to the clefts and deal with the remaining Boulderfist ogres.", objectives = "" }
WordHunterWoW_QuestEN[9923] = { title = "HELP!", description = "HELP! They're gonna eat me! I just know it!\n\nFind the key, I know it has to be on one of these ogres.\n\nIf you get me out of here, my father will reward you handsomely! He's the leader of Telaar, Arechron.\n", objectives = "" }
WordHunterWoW_QuestEN[9924] = { title = "Corki's Gone Missing Again!", description = "<Arechron sighs.>\n\nThis is so embarrassing. Do you remember my boy, Corki? You rescued him from the Burning Blade Ruins recently. Well, his curiosity has gotten the best of him once more. He told me that he was going to investigate the Boulderfist menace for 'uncle' Mo'mor and ran off to the ogre mounds in the Halaani Basin, north of here.\n\nDo you think you could track him down? I would be eternally grateful.\n", objectives = "" }
WordHunterWoW_QuestEN[9925] = { title = "Matters of Security", description = "Gezhe chose to base our operations as close to Oshu'gun as possible, without any regard for the safety of our crew.  Why?  Because he projected a ten percent increase in productivity by setting up shop here instead of in the mountains to the south.\n\nNever mind the crazed voidspawn wandering all of ten feet away from us.  That would be the security officer's problem, not Gezhe's.\n\nKill some voidspawn for me and I'll pay you a tenth of our security budget.  Don't get excited, it's not much of a budget.", objectives = "" }
WordHunterWoW_QuestEN[9927] = { title = "Ruthless Cunning", description = "<Lantresor hands you a pack full of banners.>\n\nThese are Warmaul ogre banners that I recently acquired.\n\nI want you to travel to Kil'sorrow Fortress, directly south of here, and kill as many of the Kil'sorrow filth as you can find. Drive a Warmaul ogre banner through the heart of each fallen Kil'sorrow soldier. Return to me when you have completed this task and the other that this plan requires.", objectives = "" }
WordHunterWoW_QuestEN[9928] = { title = "Armaments for Deception", description = "You will need to steal Kil'sorrow armaments from Kil'sorrow Fortress if my plan is to work.\n\nSearch the fortress for crates of Kil'sorrow armaments. Bring whatever you can find to me.\n\nKil'sorrow Fortress is located directly south and a little to the west of the Burning Blade Ruins.", objectives = "" }
WordHunterWoW_QuestEN[9931] = { title = "Returning the Favor", description = "Now you must plant the seed of war in the fat, useless heads of the Warmaul. To the northwest, near the mountains, you will find the Laughing Skull Ruins.\n\n<Lantresor points into the crate of armaments you brought him.>\n\nDo you recognize those banners? They are Kil'sorrow banners. I want you to take a stack of Kil'sorrow banners and plant them on the corpses of Warmaul ogres. Remember, northwest is where you will find the ogres.", objectives = "" }
WordHunterWoW_QuestEN[9932] = { title = "Body of Evidence", description = "Your rampage through Kil'sorrow Fortress has provided us with a special opportunity. We have enough bodies to make it appear as if a great battle has taken place.\n\nTravel to the Laughing Skull Ruins and find the Laughing Skull Courtyard. There should be a blazing pyre in the courtyard. Make sure the area is secure and then use this blanket to send up smoke signals. When my ogres see the smoke, they will sneak in and plant the bodies of slain Kil'sorrow soldiers.\n\nThat should be the final straw!", objectives = "" }
WordHunterWoW_QuestEN[9933] = { title = "Message to Telaar", description = "<Lantresor points to an unmarked crate.>\n\nTake it. It is my offering to your people. You have single-handedly saved my clan from extermination.\n\nYou may tell your leader that Lantresor of the Burning Blade and his Boulderfist ogres accept the offering of peace.\n\n<Lantresor bows.>\n", objectives = "" }
WordHunterWoW_QuestEN[9934] = { title = "Message to Garadar", description = "<Lantresor points to an unmarked crate.>\n\nTake it. It is my offering to your people. You have single-handedly saved my clan from extermination.\n\nYou may tell your leader that Lantresor of the Burning Blade and his Boulderfist ogres accept the offering of peace.\n\n<Lantresor bows.>", objectives = "" }
WordHunterWoW_QuestEN[9935] = { title = "WANTED: Giselda the Crone", description = "Wanted: Dead or Alive\n\nGiselda the Crone of Kil'sorrow and her lackeys for murder, ritual sacrifice, communing with the Legion, kidnapping, and burglary.\n\nKnown to congregate at Kil'sorrow Fortress in southeastern Nagrand, near the border of Terokkar.\n\nLarge gold reward to be dispensed by Warden Bullrok at Garadar to anyone able to bring Giselda to justice.", objectives = "" }
WordHunterWoW_QuestEN[9936] = { title = "WANTED: Giselda the Crone", description = "Wanted: Dead or Alive\n\nGiselda the Crone of Kil'sorrow and her lackeys for murder, ritual sacrifice, communing with the Legion, kidnapping, and burglary.\n\nKnown to congregate at Kil'sorrow Fortress in southeastern Nagrand, near the border of Terokkar.\n\nLarge gold reward to be dispensed by Warden Moi'bff Jill at Telaar to anyone able to bring Giselda to justice.", objectives = "" }
WordHunterWoW_QuestEN[9937] = { title = "WANTED: Durn the Hungerer", description = "You have destroyed two of the biggest threats in Nagrand, {name}. Are you ready to take on the scourge of the Spirit Fields?\n\nDurn the Hungerer lords over the area surrounding Oshu'gun, decimating all in his path. Thus far, none have been able to rid Nagrand of this ferocious gronn. Venture to the Spirit Fields, far southwest of here, near Oshu'gun, and track down Durn. Slay him and I assure you rewards commensurate with the difficulty of the task at hand.\n", objectives = "" }
WordHunterWoW_QuestEN[9938] = { title = "WANTED: Durn the Hungerer", description = "You have destroyed two of the biggest threats in Nagrand, {name}. Are you ready to take on the scourge of the Spirit Fields?\n\nDurn the Hungerer lords over the area surrounding Oshu'gun, decimating all in his path. Thus far, none have been able to rid Nagrand of this ferocious gronn. Venture to the Spirit Fields, west of here, and track down Durn. Slay him and I assure you rewards commensurate with the difficulty of the task at hand.", objectives = "" }
WordHunterWoW_QuestEN[9939] = { title = "WANTED: Zorbo the Advisor", description = "Wanted: Dead or Alive\n\nZorbo the Advisor, wanted for numerous planned attacks on Garadar. Along with his reavers and shaman, Zorbo has slain countless orcs. Consider Zorbo as armed, dangerous, and merciless.\n\nZorbo makes his home in the Laughing Skull Ruins in the northern mountains of Nagrand.\n\nReward for Zorbo the Advisor's death or capture to be dispensed by Warden Bullrok at Garadar. ", objectives = "" }
WordHunterWoW_QuestEN[9940] = { title = "WANTED: Zorbo the Advisor", description = "Wanted: Dead or Alive\n\nZorbo the Advisor, wanted for numerous planned attacks on Telaar. Along with his reavers and shaman, Zorbo has slain countless Broken. Consider Zorbo as armed, dangerous, and merciless.\n\nZorbo makes his home in the Laughing Skull Ruins in the northern mountains of Nagrand.\n\nReward for Zorbo the Advisor's death or capture to be dispensed by Warden Moi'bff Jill at Telaar.", objectives = "" }
WordHunterWoW_QuestEN[9944] = { title = "Missing Mag'hari Procession", description = "Greatmother says that we must press on and serve our people. She says that we must serve as an example for Garrosh - to show that life goes on.\n\nI have so many matters to attend to here, especially with Greatmother having taken ill. Would you honor the Mag'har by helping one of their matrons?\n\nSeveral days ago we sent a funeral procession to the Ancestral Grounds and they have yet to return. Will you go search for them? They took the western road out of Garadar. Follow it around and avoid Halaa.", objectives = "" }
WordHunterWoW_QuestEN[9945] = { title = "War on the Warmaul", description = "We were en route to the Ancestral Grounds when we were ambushed by Warmaul. They came from all sides, killing several of the procession guards and many of the others. They even desecrated the remains of the elder in the wagon.\n\nAnd for what? So they could humiliate us and display their power. Not even Boulderfist would have sunk so low.\n\nI am a spiritual orc, {name}, but even I have limitations. Find the attackers at Warmaul Hill to the northwest and destroy them!", objectives = "" }
WordHunterWoW_QuestEN[9946] = { title = "Cho'war the Pillager", description = "Have you ever seen an ogre king, {race}? Few have and lived to tell the tale. Unfortunately, that is exactly what we are dealing with here.\n\nThe leader of these barbarians is an ogre named Cho'war. Rumor has it that Cho'war was the ogre responsible for forcing the gronn out of the cave. Cho'war then declared himself king and dissolved the ogre clans that served under the gronn. Thus, Warmaul was born.\n\nFind Cho'war deep in the caves of Warmaul Hill. Slay him and bring me his head.", objectives = "" }
WordHunterWoW_QuestEN[9948] = { title = "Finding the Survivors", description = "If I know anything about ogres, it's that they like their food fresh. This means that the Mag'har that they captured are more than likely being kept alive until they are ready to serve. It's a sickening thought, I know, but one that we must use to our advantage.\n\nVenture to Warmaul Hill and search for Mag'har prisoners. If you find prisoners, then you will find keys to their cages on the nearby Warmaul ogres.\n\nKill ogres for their keys and release the prisoners.", objectives = "" }
WordHunterWoW_QuestEN[9951] = { title = "It's Watching You!", description = "Quick, hide!  The eyes of Naphthal'ar are upon you... upon us all!\n\nI dare not go to the top of the tower to speak with it, but you... you look as if you might know the right words to say.  Just be careful, it doesn't like jokes and will not suffer fools easily.\n\nIf you can, convince it to come down for tea.  But, by all means, get it to stop staring at me!", objectives = "" }
WordHunterWoW_QuestEN[9954] = { title = "Corki's Ransom", description = "<Arechron shows you a grime covered letter.>\n\nI just received this letter. It's from a clan of ogres known as Warmaul that rule the northwestern lands of Nagrand. It says that they have Corki and if we don't cooperate, they're going to eat him. Admittedly, Corki is a moron, but he's still my blood. Will you rescue him, {name}?\n\nI presume that he's locked up in a cage somewhere on Warmaul Hill. That should be your first stop.", objectives = "" }
WordHunterWoW_QuestEN[9955] = { title = "Cho'war the Pillager", description = "They call him Cho'war the Pillager, {name}. He's the ogre that forced out the gronn that used to rule over these ogres. You better believe he's powerful!\n\nThe chef said that Cho'war lives in the big cave - wherever that may be... Get that key and get me out of here! If we live through this, my father will no doubt give you the big reward! As soon as I'm free, seek him out.", objectives = "" }
WordHunterWoW_QuestEN[9956] = { title = "The Ravaged Caravan", description = "I was part of a caravan taking supplies to the Orebor Harborage in Zangarmarsh. As we were nearing the border of the marsh, we were jumped by a vicious squad of Warmaul ogres. They killed the others and took me prisoner, along with all of our supplies.\n\nThankfully, they neglected to place a backing on my cage. When they fell asleep, I made my escape.\n\nIt's too late for my comrades but we could really use the supplies they stole. Warmaul Hill is in the northwestern mountains of Nagrand.", objectives = "" }
WordHunterWoW_QuestEN[9957] = { title = "What's Wrong at Cenarion Thicket?", description = "We haven't heard from the druids at the Cenarion Thicket of Terokkar Forest in quite some time.\n\n{name}, I'd like for you to go down there and check in with them to see what's happening.  There are several ways to get there, but the fastest is to head south along the path, and then take the road that branches east from Shattrath City once you're in the forest.", objectives = "" }
WordHunterWoW_QuestEN[9960] = { title = "What's Wrong at Cenarion Thicket?", description = "Hey there, {class}.  We haven't heard from the druids of the Cenarion Thicket in quite some time.\n\nI want you to go over there and check to see what's happening.  You can find it by heading northwest through the forest.", objectives = "" }
WordHunterWoW_QuestEN[9961] = { title = "What's Wrong at Cenarion Thicket?", description = "{class}, I have urgent business for you.  We haven't heard from the druids of the Cenarion Thicket in quite some time.  This is unusual as we usually hear from them at least once every few days.\n\nI want you to go up there and make sure that they're alright.  You can find the thicket by heading northwest through the forest.", objectives = "" }
WordHunterWoW_QuestEN[9962] = { title = "The Ring of Blood: Brokentoe", description = "So are you ready for your first battle? If you are, let me know and I'll get things started. All you have to do is go wait in the Ring of Blood for your opponent to arrive.\n\nThis fight is against Brokentoe, a ferocious clefthoof.\n\nGood luck! I hope you brought friends.\n\nAnd remember, the fight's over when either you or your opponent are lying face down on the arena floor.\n", objectives = "" }
WordHunterWoW_QuestEN[9967] = { title = "The Ring of Blood: The Blue Brothers", description = "This next battle involves a duo - twin brothers to be precise. They call themselves the \"Blue Brothers.\"\n\nIt's not too late to chicken out, {name}. I'd certainly understand.\n\nBut if you're ready for some action, step in the Ring of Blood and wait for the Murkblood twins to arrive.\n\nLast one standing is the winner!", objectives = "" }
WordHunterWoW_QuestEN[9968] = { title = "Strange Energy", description = "Something strange has changed the teromoths of the thicket.\n\nWhere once there was a diversity of life in there, now only the teromoths remain.  And while before they were at peace, now they are agitated and will not hesitate to attack you should you get close.\n\nI need to compare the vicious ones to the normal.  Collect for me a number of samples from both.  You'll find the unaffected teromoths both to the south and the north.\n\nI'm certain this is related to whatever killed all of the druids.", objectives = "" }
WordHunterWoW_QuestEN[9970] = { title = "The Ring of Blood: Rokdar the Sundered Lord", description = "This fight is gonna be painful, {name}. Do you have any friends that are brave enough to help you out? The ogres managed to get a giant from Blade's Edge named Rokdar! Trust me, you're gonna need friends, he seems unbeatable! He's hard as a rock - literally!\n\nIf you still want to fight him, step into the Ring of Blood and he will come.", objectives = "" }
WordHunterWoW_QuestEN[9971] = { title = "Clues in the Thicket", description = "I have no idea what killed all of the druids here.  I've been away for a couple of days on a survey of the Bone Wastes to the south.\n\nPlease, you must help me to uncover what's behind this horrible tragedy.  Go into the thicket and look for a clue that might reveal something to us.  When I was in there briefly, I could have sworn I saw a dead Broken and a strange object next to him.\n\n And don't worry about Treelos - he might have been driven insane by what happened, but I think he's mostly harmless.", objectives = "" }
WordHunterWoW_QuestEN[9972] = { title = "The Ring of Blood: Skra'gath", description = "You're murderin' 'em out there, kid! They got a ringer for the next match. They say he's a void lord or something... No way do they want you up against their champion. Did you here that palooka, Mogor, yapping at you? The bets are through the roof!\n\nGet in that ring and take this one out fast!", objectives = "" }
WordHunterWoW_QuestEN[9973] = { title = "The Ring of Blood: The Warmaul Champion", description = "They had to ship the champion in from the Blade's Edge gladiator pits. He was training on mountain giants - three at a time.\n\nIf you win this one, you become the new champion. What do you think your odds are, kid? Do you have a shot? Just give me the word and I'll bet the house on you.\n\nNow get in there and win!", objectives = "" }
WordHunterWoW_QuestEN[9977] = { title = "The Ring of Blood: The Final Challenge", description = "<Gurgthock is counting his massive pile of gold.>\n\nYou've made me a lot of money, kid. If you can defeat Mogor, I promise to make it worth your while. All that pain you suffered in the Ring of Blood is gonna end up paying off.\n\nNow get in there and show these ogres what you're made of!", objectives = "" }
WordHunterWoW_QuestEN[9978] = { title = "By Any Means Necessary", description = "I don't know what to make of all of this, but I do know how we can find more clues.\n\nEmpoor is a Broken merchant that traffics in all sorts of goods and information.  If you were to persuade him to talk, I'm sure he might have something interesting to say.\n\nHe travels the road here between Tuurem and Shattrath.  Watch out, though -- he travels with a bodyguard.", objectives = "" }
WordHunterWoW_QuestEN[9979] = { title = "Wind Trader Lathrai", description = "I was asked to pick up and deliver some boxes of goods from an ethereal in Shattrath City.\n\nLast I saw him, he was standing outside of the World's End Tavern in Lower City.  His name is Wind Trader Lathrai, and that's all that I know!\n\nWant more answers, go talk with him!", objectives = "" }
WordHunterWoW_QuestEN[9982] = { title = "He Called Himself Altruis...", description = "A being riding atop a nether drake arrived in town late last week. He introduced himself as Altruis and then proceeded to ask us several questions about Nagrand.\n\nHe claimed that he was hunting Legion. That such insanity was actually his job. Can you imagine? A person that would willingly hunt demons?\n\nBefore he left, he asked that we let the would-be heroes in town know that he will be staying in western Nagrand for awhile and that should they seek a purpose, to find him.", objectives = "" }
WordHunterWoW_QuestEN[9983] = { title = "He Called Himself Altruis...", description = "A being riding atop a nether drake arrived in town late last week. He introduced himself as Altruis and then proceeded to ask us several questions about Nagrand.\n\nHe claimed that he was hunting Legion. That such insanity was actually his job. Can you imagine? A person that would willingly hunt demons?\n\nBefore he left, he asked that we let the would-be heroes in town know that he will be staying in western Nagrand for awhile and that should they seek a purpose, to find him.", objectives = "" }
WordHunterWoW_QuestEN[9984] = { title = "Host of the Hidden City", description = "Although you cannot read the strange script on the scroll, the ornate seal at the bottom of the document implies that it was drafted by an arakkoa of high standing. Luanga may have masterminded the capture and interrogation of Deirom, but it seems he was taking orders from someone else.\n\nYou remember Thander mentioning that Andarl has studied the arakkoa. Perhaps he can decipher the scroll's contents.", objectives = "" }
WordHunterWoW_QuestEN[9985] = { title = "Host of the Hidden City", description = "Although you cannot read the strange script on the scroll, the ornate seal at the bottom of the document implies that it was drafted by an arakkoa of high standing. Luanga may have masterminded the capture and interrogation of Dugar, but it seems he was taking orders from someone else.\n\nYou remember Rokag mentioning that Kurgatok has studied the arakkoa. Perhaps he can decipher the scroll's contents.", objectives = "" }
WordHunterWoW_QuestEN[9986] = { title = "Stymying the Arakkoa", description = "We need to show the arakkoa that they cannot attack our people with impunity. If we don't stop them here, the roads will no longer be safe for our merchants, couriers, or soldiers.\n\nMy scouts have identified the leaders of each of the major arakkoa settlements in the area. Seek out Ashkaz, Ayit, and Urdak, in Veil Reskk, Veil Shienor, and Veil Skith and kill them. ", objectives = "" }
WordHunterWoW_QuestEN[9987] = { title = "Stymying the Arakkoa", description = "We need to show the arakkoa that they cannot attack our people with impunity. If we don't stop them here, the roads will no longer be safe for our merchants, couriers, or soldiers.\n\nMy scouts have identified the leaders of each of the major arakkoa settlements in the area. Seek out Ashkaz, Ayit, and Urdak, in Veil Reskk, Veil Shienor, and Veil Skith and kill them. ", objectives = "" }
WordHunterWoW_QuestEN[9988] = { title = "A Dandy's Best Friend", description = "Don't let Thander and company fool you. They may look like a band of fearsome warriors, but underneath all that steel, they're nothing more than a troop of dandies!\n\nAnd they won't be seen in public without their hats. They're extravagant affairs made from felt and fur, complete with the gaudiest feathers you've ever seen.\n\nThe most desirable feathers come from any of the arakkoa, of course, and my supply is running low. I'll gladly pay you if you'll collect them for me.", objectives = "" }
WordHunterWoW_QuestEN[9989] = { title = "Alien Spirits", description = "When I first came to Outland, and opened my ears to the voices of its spirits, I was amazed at what I heard. In time, I also came to notice which spirits I couldn't hear.\n\nFor all my attempts, I have never been able to make contact with the spirit of an arakkoa ancestor. Their magic is fundamentally different from ours, but I'm not convinced that their spirits are beyond my reach.\n\nBring me feathers from many arakkoa; perhaps having some token from them will provide the link I need.", objectives = "" }
WordHunterWoW_QuestEN[9990] = { title = "Investigate Tuurem", description = "You know, come to think of it, I do recall selling several boxes of strange and exotic engineering parts to Empoor about a month ago.  I'm not sure what they'd be used for, but I know that they were delivered to Tuurem.\n\nPerhaps one or more of those boxes is still there?", objectives = "" }
WordHunterWoW_QuestEN[9991] = { title = "Survey the Land", description = "To be my eyes will require some diligence on your part. Nethrandamus will take you through the Legion camps, but you must catalog everything that you see. Even the smallest detail that you may think to be inconsequential could be useful for our purposes.\n\nPrimarily, I want you to note what structures are in the camps and what comprises the camps' defenses.\n\nNethrandamus is ready when you are, {name}. Do not be afraid, he will keep you safe from harm.\n", objectives = "" }
WordHunterWoW_QuestEN[9992] = { title = "Olemba Seeds", description = "Aren't the trees in the forest beautiful? I've often wondered if they would survive on Azeroth.\n\nI'm hesitant to send back seedlings, though. It's a rough trip and they're much harder to transport than something like a sack of seeds. The seeds are stored in tough cones that fall from the tree's branches once they've reached maturity.\n\nIf you come upon some of those cones in your travels, would you mind bringing some of the seeds back to me?", objectives = "" }
WordHunterWoW_QuestEN[9993] = { title = "Olemba Seed Oil", description = "The oily seeds from the forest's olemba trees could prove very valuable. I'd like to gather a larger quantity of them, press them for their oil, and then see what I can do with it.\n\nJust think, there's a whole forest full of trees out there, producing a lot of seeds that go to waste. I don't care if it turns out to be cooking oil, lamp oil, or weapon oil, I won't let it go to waste!\n\nBring me any of the seeds that you happen to gather from the olemba cones. They're all over the place.", objectives = "" }
WordHunterWoW_QuestEN[9994] = { title = "What Are These Things?", description = "I don't know about you, but I have no idea what all of those things are.  I do know one thing though - they look dangerous!\n\n{name}, I think you should take this box of parts to Jenai Starwhisper at the Allerian Stronghold to the southeast.  She may have some idea of what these are.", objectives = "" }
WordHunterWoW_QuestEN[9995] = { title = "What Are These Things?", description = "I don't know about you, but I have no idea what all of those things are.  I do know one thing though - they look dangerous!\n\n{name}, I think you should take this box of parts to Tooki at Stonebreaker Hold to the southeast.  He may have some idea of what these are.", objectives = "" }
WordHunterWoW_QuestEN[9996] = { title = "Attack on Firewing Point", description = "We know that the blood elves of Firewing Point are working for Kael'thas and Illidan.  And from what you've told me, clearly they are using the Broken of Tuurem as smuggling go-betweens for the creation of some horrible weapon.\n\nWhatever they're up to out there, the most efficient thing that we can do right now is to thin out their numbers.\n\nThe Firewing blood elves need to be taken out!  Head up to Firewing Point to the north and see to it.", objectives = "" }
WordHunterWoW_QuestEN[9997] = { title = "Attack on Firewing Point", description = "We know that the blood elves of Firewing Point are working for Kael'thas and Illidan.  And from what you've told me, clearly they are using the Broken of Tuurem as smuggling go-betweens for the creation of some horrible weapon.\n\nWhatever they're up to out there, the most efficient thing that we can do right now is to thin out their numbers.\n\nThe Firewing blood elves need to be taken out!  Head over to Firewing Point to the northeast and see to it.", objectives = "" }
WordHunterWoW_QuestEN[9998] = { title = "Unruly Neighbors", description = "The recent arrival of the fel orcs at the ruins to the east both puzzles and troubles Thander. They wasted no time in starting to construct fortifications and repair the buildings.\n\nThe construction goes on day and night, {name}. I've dispatched one of my most reliable agents to keep watch, but we can ill afford to delay action. Move against their workers, then seek out Theloria Shadecloak at the Allerian Post to the north of the Bonechewer Ruins. She'll give you further instructions.", objectives = "" }
WordHunterWoW_QuestEN[9999] = { title = "Buying Time", description = "As long as the transporters stand, nothing we do to the forge camps will have any permanence. We must find a way to destroy the Legion structures.\n\nI need time to devise a plan of attack. If you can keep their engineers and tinkerers busy, it would greatly slow down their progress, buying me the time I need.", objectives = "" }
WordHunterWoW_QuestEN[10000] = { title = "An Unwelcome Presence", description = "Our forces at Thrallmar thought they had the fel orcs contained in the Hellfire Citadel area, but the recent arrivals at the ruins to the east say otherwise.\n\nWe can't permit them to gain a foothold here. Rokag has dispatched Shadowstalker Kaide to the ruins to keep an eye on them, but we have to do something to keep them from digging in.\n\nGo to the ruins, decimate their peons, and then look for Kaide in the trees to the north. He'll tell you where to go from there.", objectives = "" }
WordHunterWoW_QuestEN[10001] = { title = "The Master Planner", description = "All forge camps have a master planner. The master planner dictates what types of structures are present at a forge camp and how each structure is situated. Moreover, this information is kept on a set of blueprints that the planner carries around on their person.\n\nWe need the master planner's blueprints. Armed with such exacting information, we could persuade an acquaintance of mine to lend some assistance.\n\nFind the mo'arg master planner and take his blueprints. He will be stationed behind the forges.", objectives = "" }
WordHunterWoW_QuestEN[10002] = { title = "The Firewing Liaison", description = "Over the past couple of days, I've observed a blood elf woman traveling to and from the fel orc stronghold and conversing with the fel orc leader. From her body language, she's clearly issuing orders. But why? Whose orders is she conveying?\n\nMy curiosity got the better of my judgment and I shadowed her when she left the fel orc encampment. She headed north, to Firewing Point. I stopped before reaching the perimeter of the blood elf outpost.\n\nKill her before she leaves the fel orc camp again.\n", objectives = "" }
WordHunterWoW_QuestEN[10003] = { title = "The Firewing Liaison", description = "Over the past couple of days, I've observed a blood elf woman traveling to and from the fel orc stronghold and conversing with the fel orc leader. From her body language, she's clearly issuing orders. But why? Whose orders is she conveying?\n\nMy curiosity got the better of my judgment and I shadowed her when she left the fel orc encampment. She headed north, to Firewing Point. I stopped before reaching the perimeter of the blood elf outpost.\n\nKill her before she leaves the fel orc camp again.", objectives = "" }
WordHunterWoW_QuestEN[10004] = { title = "Patience and Understanding", description = "Take the blueprints and travel to Shattrath City in the Terokkar Forest. Once at Shattrath, go to the Lower City and look for a mo'arg by the name Sal'salabim. He'll probably be at the bar, drinking away his sorrows.\n\nBy the way, you may need to convince him to lend his assistance. Try to approach him with patience and understanding. If that does not work, use your fists.", objectives = "" }
WordHunterWoW_QuestEN[10005] = { title = "Letting Earthbinder Tavgren Know", description = "{name}, after you're done celebrating here, I think that you should go back to the Cenarion Thicket and speak with Earthbinder Tavgren.\n\nI'm certain that he'll want to know what really happened out there.", objectives = "" }
WordHunterWoW_QuestEN[10006] = { title = "Letting Earthbinder Tavgren Know", description = "{name}, I think that after you're done celebrating here, you should go back to the Cenarion Thicket and speak with Earthbinder Tavgren.\n\nI'm certain that he'll want to know what really happened out there.", objectives = "" }
WordHunterWoW_QuestEN[10007] = { title = "Thinning the Ranks", description = "Knowing Thander and Bertelm, they won't tolerate such a large buildup of hostile forces on our doorstep. Asking them to dispatch members of the garrison to participate in an attack on the camp isn't an option either. It would just leave us too vulnerable to attack.\n\nIt falls to us to do what we can to diminish the threat the fel orc buildup poses. Kill what you can of their forces and I will look for ways to stall any reinforcements.", objectives = "" }
WordHunterWoW_QuestEN[10008] = { title = "What Happens in Terokkar Stays in Terokkar", description = "If word reaches Thrallmar that they've failed to contain the fel orcs, we're going to be receiving a lot of company down here. Frankly, I'm not sure I want all that attention, so we're going to keep this little problem under wraps, got it?\n\nIf we can inflict enough casualties on the fel orcs, chances are their presence will never come to the attention of anyone outside Stonebreaker. So, let's end it now.\n\nWade in there, swing your weapon, wave your hands, or whatever it is you do - just kill fel orcs.", objectives = "" }
WordHunterWoW_QuestEN[10009] = { title = "Crackin' Some Skulls", description = "<Sal'salabim laughs.>\n\nThis Sal'salabim design.\n\n<Sal'salabim points to the architecture and formations on the blueprints.>\n\nLook at towers. Demon hunter no can see, yes? Poor, poor Altruis. He cry if he had eyes, yes?\n\nYes, Sal'salabim help but first you help Sal'salabim.\n\n<Sal'salabim gives you a ledger.>\n\nThese creatures owe Sal'salabim golds. Many golds. Go collect for Sal'salabim and come back. They no give you Sal'salabim gold easy. Have to fight, but you strong. You defeat Sal'salabim!", objectives = "" }
WordHunterWoW_QuestEN[10010] = { title = "It's Just That Easy?", description = "<Sal'salabim points to the blueprint.>\n\nYou see where fel cannons are?\n\n<Sal'salabim draws an arrow denoting a change of direction.>\n\nYou turn fel cannon around and use on structures.\n\nWait! Don't be mad! One thing you not know. Overseers have key to turn cannons. You need key first! One from each overseer!\n\nNot so easy, eh?\n\nTake information back to Altruis.\n", objectives = "" }
WordHunterWoW_QuestEN[10011] = { title = "Forge Camp: Annihilated", description = "Gather your courage, {name}. You will need it if you are to face an overseer.\n\nOnce you are ready, find and kill the overseers at each camp. Take their keys and use them to turn and fire the fel cannons upon the camps. Return to me once the camps are destroyed.", objectives = "" }
WordHunterWoW_QuestEN[10012] = { title = "Fel Orc Plans", description = "The writing on the plans is far too delicate and precise to have come from any of the fel orcs. You can't make out what the text says, but the implications are pretty clear: the fel orcs are taking orders from the blood elves at Firewing Point.\n\nWhy would the two forces be working together? Bertelm might have some insight into this odd alliance. You decide to make your way back to the Allerian Stronghold and show him the map.", objectives = "" }
WordHunterWoW_QuestEN[10013] = { title = "An Unseen Hand", description = "The writing on the plans is far too delicate and precise to have come from any of the fel orcs. You can't make out what the text says, but the implications are pretty clear: the fel orcs are taking orders from the blood elves at Firewing Point.\n\nWhy would the two forces be working together? Rokag might have some insight into this odd alliance. You decide to make your way back to Stonebreaker Hold and show him the map.", objectives = "" }
WordHunterWoW_QuestEN[10016] = { title = "Timber Worg Tails", description = "Have you come across the timber worgs in your travels? I've had the opportunity to observe them while mapping some of the northern reaches of the forest. I wouldn't recommend getting close to them unless you're prepared for combat.\n\nThey have no fear of us and won't hesitate to defend their territory.\n\nIt's fitting that such a creature would have a magnificent tail. I've been trying to collect enough of them to trim a new cloak, but the worgs have a habit of evading my snares. Will you help?", objectives = "" }
WordHunterWoW_QuestEN[10017] = { title = "Strained Supplies", description = "More and more refugees come through the gates of Shattrath City each day.  Some have sustained such injuries, it's a real wonder they made it here.\n\nI can deal with most of the conventional injuries; my training as an Aldor healer has prepared me for that.  Poison wounds are more problematic as my anti-venom supplies have begun to run low.\n\nBring me venom sacs from the local dreadfang spiders so I can produce more antidotes.  You'll find a pocket of the spiders in the southeastern region of Terokkar.", objectives = "" }
WordHunterWoW_QuestEN[10018] = { title = "Vestments of the Wolf Spirit", description = "Generations ago, when orc clans still called Terokkar Forest home, the wolf spirit played an important role in their lives. When the orcs departed, they had no longer had any need for the spirit and they left it behind.\n\nIn time, the spirit grew lonely and it too left the forest.\n\nI believe I can bring the wolf spirit back to his ancestral home, just as we orcs have returned. The ritual will require me to create vestments from the pelts of the wolves of the forest to guide the spirit back to its home.", objectives = "" }
WordHunterWoW_QuestEN[10020] = { title = "A Cure for Zahlia", description = "The woman to my right suffered a severe injury to the head.  She survived, but lost her eyesight.\n\nA traditional cure used among my people requires the blood of a very old basilisk.\n\nUnfortunately, due to poaching from various groups, Terokkar basilisks don't tend to live very long.\n\nThere is one basilisk whose name I've known since I was a youngling.  It is known only as \"Stonegazer\" and it's rumored to live east of here, near the land's edge.\n\nBring me its blood so that Zahlia may see once again.", objectives = "" }
WordHunterWoW_QuestEN[10021] = { title = "Restoring the Light", description = "Much of this region was inhabited by draenei long ago.  We Aldor were charged with the safeguarding of our holy sites and altars.  Many of them have since been destroyed or taken over by our enemies.\n\nTo the east of here there is an arakkoa outpost.  It was purposefully built on the location of three of our sacred altars. The arakkoa use their foul magic to warp and defile the innate power of our shrines.\n\nTake this to the arakkoa outpost and use it to cleanse the three altars.", objectives = "" }
WordHunterWoW_QuestEN[10022] = { title = "The Elusive Ironjaw", description = "Now that I have the fur I'll need for the trim, I've been thinking that the pelt of a particular wolf would make a good hood for my cloak. Imagine seeing your enemy clad in the pelt of the most cunning predator in the forest!\n\nI've tried trapping old Ironjaw without success. I've tried cornering him, outsmarting him, and baiting him. None of it has worked.\n\nHe stalks the northeastern reaches of the forest, and I'd gladly reward you if you could succeed where I have failed.", objectives = "" }
WordHunterWoW_QuestEN[10023] = { title = "Patriarch Ironjaw", description = "You've done well in gathering the first pelts.\n\nThe final piece of the vestments requires a pelt unlike any other. There is one particular wolf, an old and cunning one, that has earned his place as the patriarch of the forest wolves. He is known among them as Ironjaw, the mighty hunter.\n\nIn my visions, I have seen him wandering the northeastern region of the forest. Including his pelt in the vestments will surely light the wolf spirit's path.\n\nDo not mourn Ironjaw. He will be well honored.", objectives = "" }
WordHunterWoW_QuestEN[10024] = { title = "Voren'thal's Visions", description = "Our leader, Voren'thal the Seer, was once a close advisor to Kael'thas.  His prophetic visions warned him that Kael's path would lead to the destruction of our race.\n\nThe visions are usually vague and unfocused, but our alchemists have devised an elixir to help him focus his clairvoyance.  Unfortunately, this elixir calls for a rare ingredient: basilisk eyes.  My usual source, this pathetic ethereal, has failed me.\n\nSeek the dampscale basilisks in the rocky regions of Terokkar and bring me their eyes.", objectives = "" }
WordHunterWoW_QuestEN[10026] = { title = "Magical Disturbances", description = "It's embarrassing to admit this, but something has happened to me here in Terokkar Forest that hasn't occurred since my apprentice days.\n\nOccasionally, my spells will fizzle when I know I've done everything correctly. I almost drove myself crazy the first time it happened.\n\nI think I've found the cause. The forest is full of creatures called warp stalkers, demonic creatures with an affinity for magic and a habit of disturbing magical flows. The best way to deal with them is simply to kill them.", objectives = "" }
WordHunterWoW_QuestEN[10027] = { title = "Magical Disturbances", description = "There's nothing more annoying than preparing to cast a spell, only to have it interrupted by some unseen force. After the fourth time, I knew it couldn't be coincidence and I sent Keb'ezil out to investigate.\n\nI guarantee you'll never encounter an imp that talks back more than Keb.\n\nAnyway, he managed to find the source of the problem, a pesky creature known as a warp stalker. They have a habit of disturbing the magical energy wherever they blink into existence. I've had enough of their interference.", objectives = "" }
WordHunterWoW_QuestEN[10028] = { title = "Vessels of Power", description = "Amid the ruins of Tuurem are a number of vessels containing raw, magical energy. We are fortunate that the Broken who have overrun the city are ignorant to the resource in their midst, but we cannot assume they will remain so forever.\n\nWith those vessels and their power in hand, the scattered survivors of my people can resist the lure of demonic magic. Every quel'dorei we can save from our prince's folly is one more that can help us regain our lost glory. Bring me these vessels, {class}.", objectives = "" }
WordHunterWoW_QuestEN[10030] = { title = "Recover the Bones", description = "The bones of the dead draenei litter the Bone Wastes from the explosion of Auchindoun.  Their spirits are restless, and cannot move on to the next life.\n\n{class}, you must help me to recover their bones and take them to their final resting place!  Only then will they be at peace; only then will they know comfort.\n\nGather up the restless bones with care and deliver them to Ramdor the Mad at Auchindoun in the center of the Bone Wastes.  Despite his name, he will know how to care for them.", objectives = "" }
WordHunterWoW_QuestEN[10031] = { title = "Helping the Lost Find Their Way", description = "Many spirits of the draenei were corrupted by the explosion of Auchindoun.  Now they wander the wastes in torment.\n\n{name}, I beseech you to put them to rest.  Destroy the lost spirits and broken skeletons that haunt the Bone Wastes beyond Auchindoun's walls.\n\nWhat?  You think leaving them to wander in blind agony would be better?\n\nAfterward, return to Soolaveen at the Refugee Caravan and tell him of that which you have done.", objectives = "" }
WordHunterWoW_QuestEN[10032] = { title = "Artifacts from Tuurem", description = "Have you ever noticed the behavior of the Lost Ones in Tuurem? They wander the ruins, searching for surviving scraps of anything made by the draenei.\n\nTheir Broken masters know better. They've left their former lives and identities behind and become something completely different.\n\nI believe we can use the Lost Ones' compulsion to our benefit and gather old draenei relics from them. Why risk life and limb battling the Broken, when we can profit from picking our targets wisely?", objectives = "" }
WordHunterWoW_QuestEN[10033] = { title = "WANTED: Bonelashers Dead!", description = "A bounty is declared on the bonelashers of the Bone Wastes.  As known carriers of the plague, they are to be destroyed forthwith!\n\nWhile they can be found throughout the wastes, they are known to congregate at Carrion Hill in the north.\n\nReport to Taela Everstride afterward to collect your reward.", objectives = "" }
WordHunterWoW_QuestEN[10034] = { title = "WANTED: Bonelashers Dead!", description = "The bonelashers of the Bone Wastes bit Mawg and made him sick.  Now he wants all of them destroyed!\n\nWhile they can be found throughout the wastes, they are known to congregate at Carrion Hill in the north.\n\nReturn to Mawg Grimshot after you've done the deed and he'll give you a good reward.", objectives = "" }
WordHunterWoW_QuestEN[10035] = { title = "Torgos!", description = "There's a creature in the Bone Wastes so fearsome that only the dauntless dare to stalk him.\n\nI speak of Torgos, king of the bonelashers, who circles over Veil Rhaze on the western edge of the wastes.\n\nToo bad that there's an arakkoan scarecrow there, known as Torgos's Bane, which keeps him at bay.  I'd bet if you laid his mate Trachela's carcass at the foot of that scarecrow he'd come down anyway.  She can be found at Carrion Hill in the northern wastes.\n\nBring me one of Torgos's tail feathers.", objectives = "" }
WordHunterWoW_QuestEN[10036] = { title = "Torgos!", description = "I want Torgos, king of the bonelashers, dead!\n\nNot long ago, while I was out hunting at Veil Rhaze on the western edge of the wastes, he fell upon me.\n\n<Mawg taps his eyepatch.>\n\nHe took my eye, and now I would have his life!  Bring me one of his tail feathers as proof and I'll give you a worthy reward.\n\nYou'll need his mate Trachela's carcass though to call him down as he's deathly afraid of the old arakkoan scarecrow known as Torgos's Bane.\n\nFind her at Carrion Hill in the northern wastes.", objectives = "" }
WordHunterWoW_QuestEN[10037] = { title = "Rather Be Fishin'", description = "Speaking of lakes, there's a lake with real good fishin' up to the northeast. I used to go up there with my friends, but my mom won't let me go anymore.\n\nShe says it's too dangerous, but I haven't seen anything up there but a few little spiders. Like spiders can do anything to you...\n\nMy favorites were always the eels that live up there. If you're going to be up by the lake, would you think about bringing back some of the eels? They're feisty but once you subdue 'em, you can bring 'em back no problem.", objectives = "" }
WordHunterWoW_QuestEN[10038] = { title = "Speak with Private Weeks", description = "A report's just come in from one of our scouts near Grangol'var Village.  He says that a shadowy band has moved into the ruins there.\n\n{name}, I want you to speak with Private Weeks and see how you can assist him to figure out what this unknown group is up to.  Just head west past Stonebreaker Hold.  His last report puts his position near the north entrance to the village.", objectives = "" }
WordHunterWoW_QuestEN[10039] = { title = "Speak with Scout Neftis", description = "I am informed that one of our scouts near Grangol'var Village is currently observing a shadowy band that has recently moved in there.\n\n{name}, I want you to speak with Scout Neftis and see how you can assist her in figuring out what this unknown group is up to.\n\nJust head south out of here, and then due west, skirting the north of the Bone Wastes.  Her last report puts her position near the southern entrance to the village.", objectives = "" }
WordHunterWoW_QuestEN[10040] = { title = "Who Are They?", description = "I don't know who they are, but I know they're hostile!\n\nI'm going to give you a disguise, and I want you to go in there and speak with three of them that I've observed as being 'chatty'. Talk with the initiate, the laborer, and the advisor.\n\nJust watch out; there're a few hunters in there who'll be able to see through your disguise and they look tough! And whatever you do, don't leave the village -- the disguise is kind of flimsy. If you lose your disguise, come back to me and I'll give you another.", objectives = "" }
WordHunterWoW_QuestEN[10041] = { title = "Who Are They?", description = "I don't know who they are, but I know they're hostile!\n\nI'm going to give you a disguise, and I want you to go in there and speak with three of them that I've observed as being 'chatty'. Talk with the initiate, the laborer, and the advisor.\n\nJust watch out; there're a few hunters in there who'll be able to see through your disguise and they look tough! And whatever you do, don't leave the village -- the disguise is kind of flimsy. If you lose your disguise, come back to me and I'll give you another.", objectives = "" }
WordHunterWoW_QuestEN[10042] = { title = "Kill the Shadow Council!", description = "What!  Those guys are Shadow Council?!\n\n{name}, you have to go back in there and waste them!  I want you to take out their leader and as many of their executioners and summoners as you can.\n\nAfter you're done with that, report back to Lieutenant Gravelhammer at the Allerian Stronghold.\n\nGood luck, {class}!", objectives = "" }
WordHunterWoW_QuestEN[10043] = { title = "Kill the Shadow Council!", description = "What!  Those guys are Shadow Council?!\n\n{name}, you have to go back in there and waste them!  I want you to take out their leader and as many of their executioners and summoners as you can.\n\nAfter you're done with that, report back to Advisor Faila at Stonebreaker Hold.\n\nGood luck, {class}!", objectives = "" }
WordHunterWoW_QuestEN[10044] = { title = "A Visit With the Greatmother", description = "The Greatmother has asked that I seek you out and deliver a message. She wishes to speak with you at once.\n\nMy will has been sapped but make no mistake, {name}, if you anger the Greatmother, I will come down upon you with all the force that I can muster. She is in the main hall.\n\n<Garrosh points at the large building to the north.>\n\nListen to what she has to say and do as she tells you.", objectives = "" }
WordHunterWoW_QuestEN[10045] = { title = "Material Components", description = "Mother Kashur wishes to speak with you, {name}. Before this becomes possible, you must collect the herbs required to create a potion that will expand your mind, allowing you to commune with the spirits.\n\nYou must gather Olemba root from Terokkar, marshberries from Zangarmarsh, Telaari fronds from Nagrand and dragonspine from the Blade's Edge mountains. I have written down instructions on this parchment as to the cultivation of these herbs. Return to me when you have gathered the materials.", objectives = "" }
WordHunterWoW_QuestEN[10046] = { title = "Through the Dark Portal", description = "Two weeks ago, our scouts reported a heavily armed Alliance force under the command of Field Commander Romus departing Nethergarde Keep. With so many soldiers and supplies, along with such a distinguished commander, they can only have one goal: Outland.\n\nThe warchief sent an advance force through the portal, but if the Alliance believes there is a need for that many troops, perhaps we'd be wise to send our own reinforcements.\n\nJourney through the Dark Portal and report to Nazgrel at Thrallmar.", objectives = "" }
WordHunterWoW_QuestEN[10047] = { title = "The Path of Glory", description = "The 'Path of Glory,' they called it. A road leading from the heart of their gruesome fortress to the Dark Portal, paved with the bones of my people.\n\nIt wasn't enough for them to hunt us down like animals, destroy our cities, and torture those who survived. No, they had to use our bones as paving stones, denying my brethren a proper burial under the Light.\n\nThose tortured souls still wander these lands, crying out for release. I ask you, {name}, help me in this undertaking.", objectives = "" }
WordHunterWoW_QuestEN[10048] = { title = "A Handful of Magic Dust", description = "I'm going to need dust, but not just any dust.\n\nThe royal teromoths that inhabit the forest nearby have a magical dust upon their wings, which they use to pacify those that hunt them.  I can make use of that property of the dust to assuage the resistance that I am feeling from the arakkoa eyes you retrieved.  This, in turn, will allow me to use them to find Deirom.\n\nI won't need much, perhaps half a dozen handfuls, or so.", objectives = "" }
WordHunterWoW_QuestEN[10049] = { title = "A Handful of Magic Dust", description = "I'm going to need dust, but not just any dust.\n\nThe royal teromoths that inhabit the forest nearby have a magical dust upon their wings, which they use to pacify those that hunt them.  I can make use of that property of the dust to assuage the resistance that I am feeling from the arakkoa eyes you retrieved.  This, in turn, will allow me to use them to find Dugar.\n\nI won't need much, perhaps half a dozen handfuls, or so.", objectives = "" }
WordHunterWoW_QuestEN[10050] = { title = "Unyielding Souls", description = "Near the end of our invasion, the Armory to the south fell under attack by the Horde's insidious Death Knights. Those vile shades cursed the Armory's defenders - and trapped their souls between the realms of the living and the dead.\n\nThose noble souls must be set free! I beg you, {name}, end my comrades' torment, for I have not the heart to slay them myself.", objectives = "" }
WordHunterWoW_QuestEN[10051] = { title = "Escape from Firewing Point!", description = "Thank goodness for you!\n\n{class}, I need you to help me escape.  I have information vital to the security of the Allerian Stronghold and probably all of Outland!\n\nI came here from the Cenarion Expedition on a diplomatic mission, but as you can see, they weren't very friendly.  If you help me get to safety, I can assure you that you will be handsomely rewarded!", objectives = "" }
WordHunterWoW_QuestEN[10052] = { title = "Escape from Firewing Point!", description = "Thank goodness for you!\n\n{class}, I need you to help me escape.  I have information vital to the security of Stonebreaker Hold and probably all of Outland!\n\nI came here from the Cenarion Expedition on a diplomatic mission, but as you can see, they weren't very friendly.  If you help me get to safety, I can assure you that you will be handsomely rewarded!", objectives = "" }
WordHunterWoW_QuestEN[10053] = { title = "Dealing with Zeth'Gor", description = "It is imperative that we follow up on the momentum created by your defeat of Warboss Nekrogg, {name}. If we're lucky, the leadership at Zeth'Gor won't have heard about Nekrogg.\n\nThe Bonechewers at Zeth'Gor to the southeast are usually led into battle by Grillok \"Darkeye\". Seek him out in his lair, a cave cut beneath the fel orc settlement, and kill him. Once he is dead, search the cave for the fel orc battle plans. We must not be taken by surprise.", objectives = "" }
WordHunterWoW_QuestEN[10054] = { title = "Impending Doom", description = "A quick examination of the plans reveals Zeth'Gor's leader, Warlord Morkh, as the mastermind behind the attacks led by Bone Magus Warlor. There's more to the map than just Morkh's forces.\n\nThe plans indicate that the Bonechewer force is armed and marshalling for an all out attack on Honor Hold in concert with forces from Hellfire Citadel.\n\nThere's no time to bring word to Lieutenant Amadi. You must stop the Bonechewer forces before they can launch their attack!", objectives = "" }
WordHunterWoW_QuestEN[10055] = { title = "Waste Not, Want Not", description = "Reinforcements are great, but I don't see 'em haulin' any wagons loaded with ingots or timber.\n\nTake a look around, friend. Trees are in short supply, and the mines are overrun with Legion scum.\n\nI'm in a bad way fer supplies, and I'm makin' what substitutions I can, but it's time to start reusing what we can.\n\nThe southern edge of the Path o' Glory is strewn with the ruins of siege machinery. Some pieces of 'em are still usable. Feeling up to a bit o' a salvage operation?", objectives = "" }
WordHunterWoW_QuestEN[10056] = { title = "Bleeding Hollow Supplies", description = "The orcish ruins of Zeth'Gor to the southeast serve as a base for an ever-growing tide of orcs emerging from Hellfire Citadel.\n\nThe Sons of Lothar have been fighting them for some time, and the stories they tell would be nigh unbelievable if I hadn't seen these 'fel' orcs with my own eyes.\n\nSomething has changed them, augmented them in a way we've never seen before. We have to do anything we can to keep them from strengthening. Go to Zeth'Gor and destroy any supplies you find there.", objectives = "" }
WordHunterWoW_QuestEN[10057] = { title = "Looking to the Leadership", description = "The disturbances at Expedition Armory continue, despite your best efforts. No one truly knows everything that happened there, nor exactly what binds the spirits of the fallen soldiers to the ruins.\n\nPerhaps we've been approaching this the wrong way. I've always assumed that each of the ghosts had a tie to the ruins, but what if their ties were to their leaders?\n\nArch Mage Xintor and Lieutenant Commander Thalvos were particularly close to their men, so perhaps overcoming their ghosts will calm the rest.", objectives = "" }
WordHunterWoW_QuestEN[10058] = { title = "An Old Gift", description = "<The priest's gaze slowly moves from his mug to you.>\n\nDon't you know better than to bother a man in his cups?\n\nOh, what's the use? I suppose newcomers are a good sign. What would Turalyon think?\n\nI remember the eve of our departure, when I gave Mysteries of the Light to him. During the campaign and the ensuing years, he never forgot to read his daily passage to the men.\n\nWhen he left us again, he gave the book back to me. Like a fool, I believed it safe in my quarters to the south of the armory.", objectives = "" }
WordHunterWoW_QuestEN[10059] = { title = "Dealing With Zeth'Gor", description = "It is imperative that we follow up on the momentum created by your defeat of Warboss Nekrogg, {name}. If we're lucky, the leadership at Zeth'Gor won't have heard about Nekrogg.\n\nThe Bonechewers at Zeth'Gor are usually led into battle by Grillok \"Darkeye\". Seek him out in his lair, a cave cut into the rock beneath the outpost, and kill him. Once he is dead, search the cave for the fel orc battle plans. Thrallmar must not be taken by surprise.", objectives = "" }
WordHunterWoW_QuestEN[10060] = { title = "Impending Doom", description = "A quick examination of the plans reveals Zeth'Gor's leader, Warlord Morkh, as the mastermind behind the attacks led by Bone Magus Warlor. There's more to the map than just Morkh's forces.\n\nThe plans indicate that the Bonechewer force is armed and marshalling for an all out attack on Thrallmar in concert with forces from Hellfire Citadel.\n\nThere's no time to bring word back to Thrallmar. You must stop the Bonechewer forces before they can launch their attack!", objectives = "" }
WordHunterWoW_QuestEN[10061] = { title = "The Unyielding", description = "When the Bonechewer fel orcs attacked the Expedition Armory, the garrison there fell quickly.  The battle was bloody and fierce, and there were no survivors.\n\nAlthough the dead were buried, their spirits continue to haunt those ruins.  Of late, I have been receiving visions that these spirits may soon become a threat to Thrallmar.\n\nThere is only one course of action to take.  We must grant these spirits rest.  You must overcome them in battle.", objectives = "" }
WordHunterWoW_QuestEN[10062] = { title = "Looking to the Leadership", description = "The disturbances at the Expedition Armory continue, despite your best efforts. No one truly knows everything that happened there, nor exactly what binds the spirits of the fallen soldiers to the ruins.\n\nWe may be approaching this the wrong way. My visions suggested that each of the ghosts had a tie to the ruins, but what if their ties were to their leaders?\n\nArch Mage Xintor and Lieutenant Commander Thalvos were particularly close to their men, so perhaps overcoming their ghosts will calm the rest.", objectives = "" }
WordHunterWoW_QuestEN[10063] = { title = "Explorers' League, Is That Something for Gnomes?", description = "Babysitting! Would you believe it?\n\nThey pulled me out of a promising dig and sent me along with Captain Odesyus' expedition to babysit that little gnome!\n\nI'd never heard o' a gnome wanting to become a prospector before, so I asked.\n\nSeems we are takin' gnomes now, and this particular one has a fascination with murlocs!\n\nWell, he's gone off and set up shop in an old turtle shell on the northern shore of the island. Go and have a look if you don't believe me!", objectives = "" }
WordHunterWoW_QuestEN[10064] = { title = "Talk to the Hand", description = "The Hand of Argus has established a forward base at Vindicator's Rest, but they are sorely outnumbered by both the blood elves and mutated wildlife. Without backup, their outpost is in danger of falling, and we'd have no way to keep an eye on events near the Vector Coil.\n\nReport to Scout Jorli at Vindicator's Rest to the northwest and offer her your assistance, {name}.", objectives = "" }
WordHunterWoW_QuestEN[10065] = { title = "Cutting a Path", description = "During our mission to reconnoiter the Sunhawks and their portal, I sustained a serious wound. Scout Loryi has managed to staunch the bleeding and she's trying to figure out a way to evacuate me to Blood Watch.\n\nThe problem is that we'd have to abandon our position here in order to guarantee a safe return.\n\nAs soon as we leave this consecrated ground, we'll be set upon by ravagers. If you can clear some of the enraged ravagers, it might allow us to make the trip back safely.", objectives = "" }
WordHunterWoW_QuestEN[10066] = { title = "Oh, the Tangled Webs They Weave", description = "We don't dare abandon our post, or wander too far from Vindicator's Rest, {race}. The mutated creatures closest to the Vector Coil have been changed profoundly by energy leaking from the crystals.\n\nThe mutated tanglers appear to have gained a certain degree of sentience. They've learned to create, set, and conceal vicious traps that can ensnare even the most careful warrior.\n\nWe'll never be able to move against the Sunhawks if we're constantly forced to look underfoot. Attack the problem at its source, {name}.", objectives = "" }
WordHunterWoW_QuestEN[10067] = { title = "Fouled Water Spirits", description = "Most of the creatures touched by the crystals' energy have been corrupted in the same ways: strange marks on their flesh, increased aggression, and small crystal shards in their bodies. However, the fouled water spirits north of here appear to be turning entirely to crystal.\n\nI've never seen anything react to the crystals this way before, when we explored the foul pool, they were particularly dangerous. We must get rid of them before the Sunhawks can exploit them as a new source of energy.", objectives = "" }
WordHunterWoW_QuestEN[10074] = { title = "Oshu'gun Crystal Powder", description = "This base was the primary draenei research facility for the study of naaru crystals.\n\nWhat we have discovered is a veritable goldmine of research notes about the crystals from the \"diamond\" mountain, Oshu'gun. It would seem that everything in this region carries with it some residual powder of the Oshu'gun crystals. If you find any powder while adventuring in this region, return it to me and I shall reward you with a token of my appreciation which you may use to make purchases from the quartermaster.", objectives = "" }
WordHunterWoW_QuestEN[10076] = { title = "Oshu'gun Crystal Powder", description = "This base was the primary draenei research facility for the study of naaru crystals.\n\nWhat we have discovered is a veritable goldmine of research notes about the crystals from the \"diamond\" mountain, Oshu'gun. It would seem that everything in this region carries with it some residual powder of the Oshu'gun crystals. If you find any powder while adventuring in this region, return it to me and I shall reward you with a token of my appreciation which you may use to make purchases from the quartermaster.", objectives = "" }
WordHunterWoW_QuestEN[10078] = { title = "Laying Waste to the Unwanted", description = "Now that we've gotten our salvage operation off the ground, it's time to begin the second phase of the plan.\n\nAcross the Path of Glory, the Horde still has their old blade throwers trained on us. Don't let their age fool you, {name}, they're still very dangerous. Much as we're working to reclaim what we can, we can't assume the Horde is going to dismantle their weaponry.\n\nTake this torch and burn the remaining siege equipment. I'll take no chances with Honor Hold's safety.", objectives = "" }
WordHunterWoW_QuestEN[10079] = { title = "When This Mine's a-Rockin'", description = "The mine's been overrun by a plague of gan'arg misfits!\n\nNot only did they run all my workers out of the tunnels, but they're pounding away in there night and day! To make things worse, now I've got Danath on me back! He says he's going to take away me ale ration if I don't get this taken care of soon!\n\nNone of the miners'll go in there, and the guards are busy drinking themselves silly.\n\nI'm begging you, {name}, help me here. Danath can take me dignity, but he'll never take me ale!", objectives = "" }
WordHunterWoW_QuestEN[10081] = { title = "To Meet Mother Kashur", description = "Do not be alarmed by what you might see once the effect has taken hold! These spirits are all around us - always. The potion allows your mind to be able to understand and ultimately see the spirits. You will need to be under its influence if you are to speak with Mother Kashur.\n\nYou will find her a great ways to the southwest, at the Ancestral Grounds.\n", objectives = "" }
WordHunterWoW_QuestEN[10082] = { title = "The Agitated Ancestors", description = "Do you see them walking around us? The Ancestral Grounds are normally quiet and undisturbed.\n\nAs of late, the ancestral spirits have risen and are extremely agitated. Something is causing a great disturbance to the spirits. We must discover what that something could be, but first, we must put the immediate threat to rest.\n\nThese ghosts that you see walking about are not truly the ancestors but a representation of their state of being. You must destroy the agitated orc spirits. Do this and return to me.", objectives = "" }
WordHunterWoW_QuestEN[10085] = { title = "A Visit With The Ancestors", description = "I need for you to journey to the villages of the ancestors, {name}. Seek each one out and see if the ancestors remain.\n\nVisit Sunspring Post to the north, visit the Laughing Skull Ruins far to the north against the mountains, visit Garadar to the northeast, and finally, visit the Bleeding Hollow Ruins on the borders of Nagrand and the Terokkar Forest, to the east.\n\nReturn to me once you have observed the ancestors in their homes.", objectives = "" }
WordHunterWoW_QuestEN[10086] = { title = "I Work... For the Horde!", description = "Would you believe it?  These orcs hired me to help them shore up damaged fortifications and build explosives.  What a dream job!  It's too bad we're so short on materials, but a clever goblin like myself learns how to make do!\n\nCan you help me?  I need salvaged wood and metal from the ruined battlements along the Path of Glory.  Go down there and salvage, and watch out for those red-skinned orcs!\n\nWhen you're done, come back for big rewards!", objectives = "" }
WordHunterWoW_QuestEN[10087] = { title = "Burn It Up... For the Horde!", description = "I'm a lucky, lucky goblin.  I get to make explosives and killing machines, knowing they'll be used immediately on important missions!\n\nSpeaking of missions, I just got one from Thrallmar command: burn the Alliance cannons on the far side of the Path of Glory... the ones pointing dangerously close to Horde fortifications.  Take this torch and make your way to each cannon.  Fire the torch and watch the sparks fly!", objectives = "" }
WordHunterWoW_QuestEN[10093] = { title = "The Temple of Telhamat", description = "Fortunately, the Path of Glory is not the only trace of my people in these lands. To the west, a few of our holy sites survive, although some have been overrun.\n\nWhile Velen prepared for the journey that would lead him to Azeroth, those of us who would remain behind sought to reestablish a presence at our holy places.\n\nIn the western part of the Hellfire Peninsula, you will find a small group of draenei at the Temple of Telhamat, led by Amaan the Wise. I am certain he'd be interested in meeting you.", objectives = "" }
WordHunterWoW_QuestEN[10096] = { title = "Saving the Sporeloks", description = "Ikeyen's been telling me stories about what happened to him down in those caves and I think it's just awful!\n\nYou know, maybe we should do something to help out those poor sporeloks.  Ikeyen says that they live there in the Funggor Cavern, but that the marsh beasts have recently invaded.\n\nWhy don't you go down there and see if you can clear some of those marsh beasts out?  It's just to the southwest.", objectives = "" }
WordHunterWoW_QuestEN[10099] = { title = "The Mastermind", description = "Those infernal gan'arg keep scurrying into the mine! For each one you kill, two or three more seem to take its place!\n\nThere's got to be someone down there in the deepest reaches of the mine directing the incursion. You seemed to do well against them last time, and Light knows you're the only one brave enough to venture back into the mine. Find out who's responsible for this disturbance and make him pay!", objectives = "" }
WordHunterWoW_QuestEN[10101] = { title = "When Spirits Speak", description = "Oshu'gun - the diamond mountain - was once sacred to my people. It was there that the clans would gather every year to celebrate the springtime festival. It was there that our shaman communed with the honored ancestors. It was the center of our culture - until the shadows overtook us. When the clans became a horde, the spirits of Oshu'gun fell silent. The ancestors turned their backs on us.\n\nYet something now draws them from their rest. Venture to Oshu'gun and discover what could trouble the spirits so.", objectives = "" }
WordHunterWoW_QuestEN[10102] = { title = "A Secret Revealed", description = "As my energies bled away over the centuries, a void slowly grew in my place - devouring the souls of those nearby. Helplessly, I watched as generations of orc souls were drawn into the vortex. Recently, my enemies harnessed the vortex and used it to draw countless void minions into their Burning Legion.\n\nNow, the key to ending this cycle and freeing the orc spirits lies with another naaru - A'dal. I have sensed his essence within the ancient city of Shattrath in the Terokkar Forest.", objectives = "" }
WordHunterWoW_QuestEN[10103] = { title = "Report to Zurai", description = "With the arrival of Field Commander Romus and his forces, the Alliance and their draenei friends have grown bold. They're militarizing every old draenei ruin from here to Shattrath.\n\nIn response, the trolls have established a new outpost in the eastern part of Zangarmarsh, just south of the Dead Mire. Swamprat Post, they're calling it. I'm glad they have a sense of humor about living in a place like that, because I wouldn't relish it.\n\nThe post's commander has asked me to send anyone I can spare.", objectives = "" }
WordHunterWoW_QuestEN[10104] = { title = "Concerns About Tuurem", description = "The rumors from Tuurem are unsettling. Some say the town's ruins are overrun with crazed Broken and Lost Ones, while opportunistic artifact hunters steal draenei relics.\n\nIt's hard to know which are true and which aren't, but we have a responsibility to safeguard the ruins as best we can. Find Andarl at the Allerian Stronghold in Terokkar Forest. He is something of a student of magical relics. More than anyone else, he's likely to know what's going on there.", objectives = "" }
WordHunterWoW_QuestEN[10105] = { title = "News for Rakoria", description = "Now that Swamprat Post is complete, our control of the roads in and out of the marsh is much less tenuous. Our presence in Terokkar Forest is much less secure. Even so, at Stonebreaker Hold, Rakoria awaits word of our progress.\n\nShe's sharp and capable, {name}, but be careful around her. She's got a lot of goods she's eager to move along the roads, but don't assume she's got our best interests at heart. Rakoria goes where she believes there's profit to be found.", objectives = "" }
WordHunterWoW_QuestEN[10106] = { title = "Hellfire Fortifications", description = "The Hellfire Citadel wages constant battles with our forces.  We are holding our own so far, but we can't yet launch a real offensive against them.  To do that, we need forward staging areas.\n\nOur scouts identified three fortifications near Hellfire Citadel.  We want you to help secure these forts.  Capture each fort, and then report back to me.\n\nMay fortune shine upon you in the conflicts ahead, {name}, for you will no doubt clash with Horde forces eager to gain these same fortifications.", objectives = "" }
WordHunterWoW_QuestEN[10107] = { title = "Diplomatic Measures", description = "Kilrath sends news of the Boulderfist leader: He is an orc! An ancient orc that passed through the Dark Portal in the time of our fathers and has since returned to his homeland. I wish for you to track down this orc and try to convince him to pull back the Boulderfist ogres. He resides on an upper platform in the Burning Blade Ruins to the southeast near the border of Terokkar. Good luck, {name}!\n\nBe warned, he is a blademaster...", objectives = "" }
WordHunterWoW_QuestEN[10108] = { title = "Diplomatic Measures", description = "The huntress's agents send news of the Boulderfist leader: He is an orc! An ancient orc that passed through the Dark Portal in the time of our fathers and has since returned to his homeland. I wish for you to track down this orc and try to convince him to pull back the Boulderfist ogres. He resides on an upper platform in the Burning Blade Ruins to the east. Good luck, {name}!\n\nBe warned, he is a blademaster...", objectives = "" }
WordHunterWoW_QuestEN[10109] = { title = "I Must Have Them!", description = "Do you see them?? By Gazlowe's horrific halitosis, I will have those eggs! Say, you look like you might be of some use.\n\nI'll tell you what, {race}; if you gather a few items for me to make my Jump-a-tron 4000 functional, I'll give you a key that will let you operate the machine as well! What can you do with a Jump-a-tron 4000 you say? What can't you do is more like it...\n\nI'll need air elemental gas from the air elementals of Nagrand. They're all over the place so don't ask me where to find 'em!", objectives = "" }
WordHunterWoW_QuestEN[10110] = { title = "Hellfire Fortifications", description = "The fel orcs of Hellfire Citadel must be scoured from our birthland!  To attack them, we must first secure forward staging points near the Citadel.\n\nOur outrunners found three fortifications that will suit this purpose, but the Alliance has the same idea and even now sends forces to take them!\n\nWe want you to stop the Alliance and capture these forts.  Aid in the capture of each fort and then return to me.\n\nFor the Horde!", objectives = "" }
WordHunterWoW_QuestEN[10111] = { title = "Bring Me The Egg!", description = "Now that you've been initiated, I want you to get me that egg! Use the Jump-a-tron and try to hit the nest dead center. But be careful! Bodily injury or serious permanent damage may occur from a bad jump.", objectives = "" }
WordHunterWoW_QuestEN[10112] = { title = "A Personal Favor", description = "Hmmm?  A box you say?  Or was it several?  Do you know what material the box was constructed from?\n\nAnd what was the name of this merchant?  Empoor?  Are you certain that he's one of the Broken?  I don't do much business with their kind.\n\nPerhaps my memory would be jogged if you were to do me a favor?\n\nThe Skithian arakkoa - primitive casters that they are - recently stole a huge shipment of my more exotic goods.  I want it all back!\n\nYou can find Veil Skith just to the south of Shattrath City.", objectives = "" }
WordHunterWoW_QuestEN[10113] = { title = "The Nesingwary Safari", description = "\"Go out and find us some supplies,\" he said. I was nearly killed about 15 times before I found this place! These Broken might not be the most hospitable bunch but at least they're not trying to tear my skin from my bones.\n\nAnyway, I'm not going back. My days of huntin' big game are over. If you end up heading northeast towards Zangarmarsh and run into the Nesingwary Safari, let them know that \"Shotgun\" quit. \n\nHey, maybe you can take my place! Good luck, stranger.\n", objectives = "" }
WordHunterWoW_QuestEN[10114] = { title = "The Nesingwary Safari", description = "These orcs have never seen a tauren before - if you can believe such a thing. If it weren't for Captain Kroghan, they would have probably been serving me for their next meal right about now.\n\nBut where are my manners? I am Ohlorn Farstrider, hunter extraordinaire! I am part of the Nesingwary expedition that came up here from Azeroth in search of big game. If you are interested in the hunt, perhaps you should visit my crew at the Nesingwary Safari, due east of here near the border of Zangarmarsh.\n", objectives = "" }
WordHunterWoW_QuestEN[10115] = { title = "Daggerfen Deviance", description = "The Kurenai and the draenei don't always see eye to eye, particularly on the issue of the Lost Ones. We are content to help the Lost Ones who seek us out, but we won't pursue them. Some draenei are intent on 'redeeming' them all.\n\nHowever, there are times when even the Lost Ones go too far, such as the Daggerfen. In their village to the west, they dabble in poisons and deceit, arts that come unnaturally to us.\n\nWe must put an end to this before the vile Daggerfen can extend their influence.", objectives = "" }
WordHunterWoW_QuestEN[10116] = { title = "WANTED: Chieftain Mummaki", description = "Wanted: Chieftain Mummaki - leader of the foul and degenerate Lost One tribe of the Daggerfen, for his brutal attacks against the Orebor Harborage.\n\nThe chieftain and his band of assassins are responsible for the deaths of numerous Kurenai and draenei and should only be approached by seasoned combatants.\n\nTravelers are advised to avoid the Daggerfen Village area to the west of the Orebor Harborage.\n\nTo claim the bounty, present proof of the chieftain's demise to Ikuti.", objectives = "" }
WordHunterWoW_QuestEN[10117] = { title = "WANTED: Chieftain Mummaki", description = "Wanted: Chieftain Mummaki - leader of the foul and degenerate Lost One tribe of the Daggerfen, for his brutal attacks against Zabra'jin and its inhabitants.\n\nThe chieftain and his band of assassins are responsible for the deaths of numerous scouts and messengers and should only be approached by seasoned combatants.\n\nTravelers are advised to avoid the Daggerfen Village area to the northwest of Zabra'jin.\n\nTo claim the bounty, present proof of the chieftain's demise to Shadow Hunter Denjai.", objectives = "" }
WordHunterWoW_QuestEN[10118] = { title = "Message to the Daggerfen", description = "Of all the Lost One tribes in Zangarmarsh, the Daggerfen are the most cunning and most aggressive. They are highly organized and make no secret of the fact that they desire control over the other Lost Ones in the marsh.\n\nTheir attacks have already taken quite a toll on my scouts and messengers. I cannot afford to lose any more men.\n\nIf we don't act soon, they'll have complete control over the roads and Zabra'jin will effectively be surrounded.", objectives = "" }
WordHunterWoW_QuestEN[10120] = { title = "Arrival in Outland", description = "Aided by the Alliance, my forces will hold the line here, but I need you to deliver my report to General Krakork in Thrallmar. With his help, we'll be able to drive these demons back into the abyss that spawned them! Speak to Vlagga Freyfeather. She'll speed you on your way.", objectives = "" }
WordHunterWoW_QuestEN[10121] = { title = "Eradicate the Burning Legion", description = "Though this land is full of strange new enemies, the Burning Legion is still the greatest threat to our Expedition. One of my most trusted warriors, Sergeant Shatterskull, has been studying the Legion's tactics - trying to discern the demons' true purpose in this land. Seek him out at the supply caravan just outside the southern wall.\n\nAnd {name} - be wary of the Legion. Their evil cannot be underestimated.", objectives = "" }
WordHunterWoW_QuestEN[10122] = { title = "The Citadel's Reach", description = "Each day, Hellfire Citadel opens its gates, and more fel orcs pour out and into the camps they've established along the ramparts south of the fortress.\n\nI dispatched one of my most capable scouts, Private Imarion, to track their movements, preparations and numbers, but he hasn't returned to report his findings.\n\nImarion was to focus his efforts on the northernmost camp along the Southern Rampart, near where it joined the Citadel. Find him, {name}. Without his information, we're sitting ducks.", objectives = "" }
WordHunterWoW_QuestEN[10123] = { title = "Felspark Ravine", description = "Doom Lord Kazzak commands the Burning Legion in Outland. While we can't get to Kazzak - yet - we can and must get to his lieutenants that command Legion troops from the ground.\n\nThey have stationed dreadlords in Felspark Ravine, east of here. They are responsible for these infernal storms that rain down upon our heads. To take them and their minions out would be a great set back to the Burning Legion.", objectives = "" }
WordHunterWoW_QuestEN[10124] = { title = "Forward Base: Reaver's Fall", description = "Your battle prowess has been noted by high command, {class}. They want to send you to the front lines to meet up with Maimfist's crew. They're radicals, devoted to the complete extermination of the Burning Legion, so you may fit right in...\n\nHead east about 200 paces and veer south at the jutting mass of land. You'll see Reaver's Fall where an old farm used to stand. Once there, you are to report to Forward Commander To'arch.\n\nNow move out!", objectives = "" }
WordHunterWoW_QuestEN[10126] = { title = "Warboss Nekrogg's Orders", description = "The orders, signed by 'Warboss Nekrogg,' order the fel orc patrols stationed at this camp to bring their human prisoner south for interrogation.\n\nLieutenant Amadi mentioned that the Southern Rampart is dotted with fel orc camps. Perhaps the next large section of the wall to the south is where they took Private Imarion.\n\nJudging by the note's mention of interrogation, it seems the private's fel orc captors see some value in keeping him alive. Pick up the trail before they decide to change their minds.", objectives = "" }
WordHunterWoW_QuestEN[10128] = { title = "Saving Private Imarion", description = "The tracks lead south from Imarion's equipment, appearing to follow the Southern Rampart. The roughness of the shallow ruts suggests that Imarion's captors were in a hurry to move him to his next destination, but why?\n\nWas someone waiting there for him, perhaps the Warboss Nekrogg, the leader named in the orders you found further north?\n\nThe shield and the tracks raise more questions than they solve, but it seems certain that where you find Private Imarion, you're likely to find Warboss Nekrogg too.", objectives = "" }
WordHunterWoW_QuestEN[10129] = { title = "Mission: Gateways Murketh and Shaadraz", description = "We've identified the two main transporters that the Burning Legion are using to bring in reinforcements: Gateway Murketh and Gateway Shaadraz.\n\nIf you look east up the Path of Glory, you'll see them on either side of the road.  I want you to bomb them both into oblivion!\n\nHere are the bombs you'll use, specially designed by a goblin in Area 52.  Now, speak with Wing Commander Brack -- he'll put you on a wyvern.", objectives = "" }
WordHunterWoW_QuestEN[10130] = { title = "The Western Flank", description = "In addition to other instructions, the orders tell the remaining fel orcs to prepare their equipment and rations for a coming attack.\n\nAccording to the plans, Warboss Nekrogg's forces are to form the western flank of a pincer attack on Honor Hold.\n\nWith the hold's garrison concentrating on its eastern walls, an attack from the west would be devastating. Honor Hold can only hope to hold out if the western forces are kept out of the battle.", objectives = "" }
WordHunterWoW_QuestEN[10132] = { title = "Colossal Menace", description = "You see that huge red crystal to the north?  It fell from the sky not long ago, causing a massive earthquake.\n\nWhen we came out here to investigate the disturbance, we found all of these colossi wandering about that weren't previously here.\n\nThere's definitely something strange about that crystal and the energies that it's emanating, but I don't have time for that.  Those mountain giants are my immediate concern.\n\nI want you to head up to Fallen Sky Ridge and deal with them.", objectives = "" }
WordHunterWoW_QuestEN[10134] = { title = "Crimson Crystal Clue", description = "As the colossus falls under the weight of your attacks, you notice for the first time that it was holding a red crystal fragment.\n\nWhile it was small and unnoticeable in the mountain giant's hand, it's a fairly hefty piece for you to carry around.  It also suspiciously looks like it's a piece of the giant crystal in the middle of the ridge.\n\nIt's most definitely a clue as to the strangeness that is occurring here, and you're sure that the druids at the Cenarion Post to the south will want to see it.", objectives = "" }
WordHunterWoW_QuestEN[10136] = { title = "Cruel's Intentions", description = "Magister Bloodhawk finally deciphered the Legion missive you found earlier. It turned out to be attack plans sent by one of Highlord Kazzak's lieutenants - Arazzius the Cruel. Apparently, Arazzius commands the Legion ground forces in Hellfire. The time has come to terminate his command, {name}. Terminate with extreme prejudice. \n\nHead west to the Pools of Aggonar and put an end to this so-called 'Legion lord'. Today, the Horde reclaims Hellfire Peninsula. Let the Legion be damned. ", objectives = "" }
WordHunterWoW_QuestEN[10137] = { title = "Provoking the Warboss", description = "The plan succeeds or fails on how well these explosives are made...\n\nAs much as I'd hate to rely on anything made by an orc, it's my only real chance to get out of here. Take this and throw it against the banner hanging from the tower up there.\n\nOnce it explodes, Warboss Nekrogg won't be able to resist the chance to make an example of the troublemaker. Kill him, take the key, and then open my cage. Good luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[10140] = { title = "Journey to Honor Hold", description = "When you're ready, I'll arrange a flight straight to Honor Hold.\n\nFrom there, speak with Marshal Isildor and give him Duron's report.  He'll be happy to see another recruit from the homelands, and I'm sure the information in that report is important stuff!", objectives = "" }
WordHunterWoW_QuestEN[10141] = { title = "The Legion Reborn", description = "While the Burning Legion invaded Azeroth, they were also at work here, in Outland.  We have tracked their movements over the years, but this latest activity, {class} - well, this is beyond anything we've seen.\n\nSeek out Sergeant Altumus near the eastern supply caravan. She has been monitoring the invaders and may have insights into their purpose.\n\nBe swift - and take care, {name} - the Burning Legion is not to be underestimated.", objectives = "" }
WordHunterWoW_QuestEN[10142] = { title = "The Path of Anguish", description = "Doom Lord Kazzak commands the Burning Legion in Outland. While we can't get to Kazzak - yet - we can and must get to his lieutenants that command Legion troops from the ground.\n\nThey have stationed dreadlords at the Path of Anguish, east of here. They are the ones responsible for these infernal storms that rain down upon our heads. To take them and their minions out would be a great set back to the Burning Legion.", objectives = "" }
WordHunterWoW_QuestEN[10143] = { title = "Expedition Point", description = "Your battle prowess has been noted by high command, {class}. They want to send you to the front lines to meet up with Rohamus's crew. They're radicals, devoted to the complete extermination of the Burning Legion, so you may fit right in...\n\nHead east about 400 paces, across the Valley of Bones, until you run into a destroyed fel reaver. You'll see Expedition Point where a Legion base used to stand. Once there, you are to report to Forward Commander Kingston.\n\nNow move out!", objectives = "" }
WordHunterWoW_QuestEN[10144] = { title = "Disrupt Their Reinforcements", description = "You'll find the Legion front to our northeast, and spaced along it are portals used to gather reinforcements from throughout Outland. We, {name}, are going to destroy those portals!\n\nTake this primer.  Designed in Area 52, it uses the demons' own power as an explosive device!  Defeat Legion forces around Portals Grimh and Kaalez to gather demonic rune stones, use the primer to detonate the stones inside the portals... then watch the fireworks!!\n\nGo, {name}, and return to me when your mission is complete.", objectives = "" }
WordHunterWoW_QuestEN[10146] = { title = "Mission: The Murketh and Shaadraz Gateways", description = "Just west of the Dark Portal are two huge transporters: Gateway Murketh and Gateway Shaadraz.\n\nIf you look east up the Path of Glory, you'll see them on either side of the road.  I want you to bomb them both into rubble!\n\nHere are the bombs you'll use, specially designed by a goblin in Area 52.  Now, speak with Wing Commander Dabir'ee -- he'll put you on a gryphon and send you on your way.", objectives = "" }
WordHunterWoW_QuestEN[10150] = { title = "The Citadel's Reach", description = "Each day, Hellfire Citadel opens its gates, and more fel orcs pour out and into the camps they've established along the ramparts south of the fortress.\n\nI dispatched one of my most capable trackers, Scout Makha, to track their movements, preparations and numbers, but she hasn't returned to report her findings.\n\nMakha was to focus her efforts on the northernmost camp along the Northern Rampart, near where it ends in the rocks. Find her, {name}. Without her information, we're sitting ducks.", objectives = "" }
WordHunterWoW_QuestEN[10151] = { title = "Warboss Nekrogg's Orders", description = "The orders, signed by 'Warboss Nekrogg,' order the fel orc patrols stationed at this camp to bring their orcish prisoner south for interrogation.\n\nShadow Hunter Ty'jin mentioned that the Northern Rampart is dotted with fel orc camps. Perhaps the next large section of the wall to the south is where they took Scout Makha.\n\nJudging by the note's mention of interrogation, it seems the scout's fel orc captors see some value in keeping her alive. Pick up the trail before they decide to change their minds.", objectives = "" }
WordHunterWoW_QuestEN[10152] = { title = "The Western Flank", description = "In addition to other instructions, the orders tell the remaining fel orcs to prepare their equipment and rations for a coming attack.\n\nAccording to the plans, Warboss Nekrogg's forces are to form the western flank of a pincer attack on Thrallmar.\n\nWith the town's garrison concentrating on its eastern walls, an attack from the west would be devastating. Thrallmar can only hope to hold out if the western forces are kept out of the battle.", objectives = "" }
WordHunterWoW_QuestEN[10153] = { title = "Saving Scout Makha", description = "The tracks lead south from Makha's equipment, appearing to cross the Path of Glory. The roughness of the shallow ruts suggests that Makha's captors were in a hurry to move her to the next destination, but why?\n\nWas someone waiting there for her, perhaps Warboss Nekrogg, the leader named in the orders you found further north?\n\nThe shield and the tracks raise more questions than they solve, but it seems certain that where you find Scout Makha, you're likely to find Warboss Nekrogg too.", objectives = "" }
WordHunterWoW_QuestEN[10155] = { title = "Provoking the Warboss", description = "The plan succeeds or fails on how well these explosives are made...\n\nAs much as I'd hate to rely on anything made by a fel orc, it's my only real chance to get out of here. Take this and throw it against the banner hanging from the tower up there.\n\nOnce it explodes, Warboss Nekrogg won't be able to resist the chance to make an example of the troublemaker. Kill him, take the key, and then open my cage. Good luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[10158] = { title = "Bleeding Hollow Supplies", description = "The orcish ruins of Zeth'Gor to serve as a base for an ever-growing tide of orcs emerging from Hellfire Citadel.\n\nShadow Hunter Ty'jin sent me here to keep an eye on the outpost and its strange inhabitants.\n\nSomething has changed these orcs, augmented them in a way we've never seen before. We have to do anything we can to keep them from strengthening. Fight your way into Zeth'Gor and destroy any supplies you find there.", objectives = "" }
WordHunterWoW_QuestEN[10159] = { title = "Keep Thornfang Hill Clear!", description = "We've been fighting an ongoing battle to keep the pass through Thornfang Hill to the west clear of ravagers.  It would be bad if we were to become completely cut off from the refuge in Zangarmarsh.\n\nWe don't want to displace the creatures, but there seems to be little choice as their attacks on travelers through the area have become more aggressive.\n\nClear some of the ravagers out of there if you can.", objectives = "" }
WordHunterWoW_QuestEN[10160] = { title = "Know your Enemy", description = "Rumors have surfaced that some new breed of orc is on the rise. Larger, meaner - more cunning than the brutes we're familiar with.  If these rumors are true then our forces, already stretched, may be taxed beyond their limit.\n\nI have entrusted my lieutenant, Amadi, with investigating this matter. If you would help us in this dark hour, seek her out. She is stationed at the broken tower just west of the Hold.\n\nAnd {name} - be careful out there. You're heading into a dangerous new world.", objectives = "" }
WordHunterWoW_QuestEN[10161] = { title = "In Case of Emergency...", description = "In the event of an emergency, it's always the pilot's job to keep a level head, especially when the only orders your co-pilot follows come from his stomach.\n\nThe good news is that we won't need to wait days for replacement parts to be imported. The bad news is that the \"spare\" parts got scattered from here to the Valley of Bones to the east.\n\nThe other bad news? The spare parts aren't so spare. They, uh, fell off during our rapid descent. Could you help me collect enough to get us off the ground again?", objectives = "" }
WordHunterWoW_QuestEN[10162] = { title = "Mission: The Abyssal Shelf", description = "Now that you've got your wings, perhaps you'd be interested in running another bombing mission?\n\nThis time we've isolated the Legion's main production area, behind the forge camps to the north. I need you to get on a wyvern and destroy the whole damned thing!\n\nHere are your bombs - now, talk to Wing Commander Brack when you're ready for takeoff.", objectives = "" }
WordHunterWoW_QuestEN[10163] = { title = "Mission: The Abyssal Shelf", description = "Now that you've got your wings, perhaps you'd be interested in running another bombing mission?\n\nThis time we've isolated the Legion's main production area, behind the forge camps to the north. I need you to get on a gryphon and destroy the whole damned thing!\n\nHere are your bombs - now, talk to Gryphoneer Windbellow when you're ready for takeoff.\n", objectives = "" }
WordHunterWoW_QuestEN[10166] = { title = "Whitebark's Memory", description = "This pendant brings back memories of a different time.  A better time.\n\nUnfortunately, memories are the last thing I need right now.\n\nI want you to bury this by the runestone in the Scorched Grove.  It was there that I first met the treant elder.  Put my old friend's memory to rest.", objectives = "" }
WordHunterWoW_QuestEN[10167] = { title = "Auchindoun...", description = "Deep within the Auchenai Crypts is a tomb: A tomb unlike any that exists on this shattered realm. It was from this tomb, the first tomb, that the vast mausoleum of Auchindoun was born.\n\nYou must venture to the Auchenai Crypts of Auchindoun and find this tomb. Slay the guardian of the crypt to release the captive spirit within. The spirit holds the key... ", objectives = "" }
WordHunterWoW_QuestEN[10168] = { title = "What the Soul Sees", description = "For several centuries, the spirits of Auchindoun coalesced into my darkened essence. Many of the catastrophes that befell this crypt were a direct result of my weakened state.\n\nRegrettably, there is nothing that can be done to stop this cycle. It is a facet of the naaru condition - without the void, the Light cannot exist.\n\nYour only recourse is to destroy the ancient spirits of Nagrand before they transform into creatures of the void. Use the soul mirrors found throughout this crypt to free them...", objectives = "" }
WordHunterWoW_QuestEN[10169] = { title = "Losing Gracefully", description = "The Aldor have gained the favor of the Sha'tar today.  As if that should come as any sort of surprise!\n\nWatch them showing off their fancy footwork a few feet away from A'dal.  Could they possibly put any more effort into sucking up to the naaru?\n\nHarbinger Haronem's marksman regiment is so dedicated, it even brings its own cooking pot to avoid taking long breaks for lunch.  This cannot go without retribution, {name}.\n\nI want you to pour this vial into their meal.  The results should be... comical.", objectives = "" }
WordHunterWoW_QuestEN[10170] = { title = "Return to the Greatmother", description = "Return to Greatmother Geyah at Garadar with news of your victory, {name}. This will surely lift the spirits of the Mag'har. Perhaps even the young Hellscream will be lifted from his malaise.", objectives = "" }
WordHunterWoW_QuestEN[10171] = { title = "The Inconsolable Chieftain", description = "You have done so much for the Mag'har, {name}. Your accomplishments are known to all, including Garrosh. Go to him now and tell him of your latest victory. Tell him that you do what you do for him and his people. Surely he will be lifted by your words.", objectives = "" }
WordHunterWoW_QuestEN[10172] = { title = "There Is No Hope", description = "You are an honorable {race}, {name}. You have done much for the Mag'har. No one could ever deny your service to my people. Alas, the time of the Mag'har is at an end. You have shown me, more than anything, that I am unfit to lead these people. My cursed blood runs too deep. I will not... I cannot become the second Hellscream to damn the orcs.\n\nPlease, {name}, return to the Greatmother and tell her what I have told you. I am too ashamed to see her... to look into her eyes.", objectives = "" }
WordHunterWoW_QuestEN[10173] = { title = "The Archmage's Staff", description = "Allow me to introduce myself, {class}.\n\nI am Ravandwyr, apprentice to the Archmage Vargoth.\n\nMy master is... indisposed, shall we say. I am here on a matter of great importance.\n\nThe Arklon Ruins southeast of the city are a hotbed of Burning Legion activity. Their purpose in the ruins concerns neither me nor my master, but their leader, Ekkorash, possesses the archmage's staff.\n\nThis conjuring powder will allow you to draw the demon out of hiding. Sprinkle it on the brazier at the center of the ruins.", objectives = "" }
WordHunterWoW_QuestEN[10174] = { title = "Curse of the Violet Tower", description = "Now, you will be able to use the archmage's staff to contact him.\n\nHe resides in the Violet Tower, on an 'island' to the southeast. The tower is both sanctuary and prison to him, cursed as it is. Kirin Tor can neither enter nor leave, keeping me apart from my master.\n\nThe staff's magic can penetrate the tower's defenses, but only if invoked by one outside the Kirin Tor.\n\nTake the archmage's staff and use it to conjure his image. Tell him what has happened and that I have not completely failed him.", objectives = "" }
WordHunterWoW_QuestEN[10176] = { title = "Ar'kelos the Guardian", description = "Now that you've gathered all the items I'll need to break Kael'thas's curse, one thing remains to be done. When Kael'thas sealed the tower, he placed an arcane golem, known as Ar'kelos, at the bottom of the tower.\n\nYou must defeat Ar'kelos in order allow me to work magic within the tower again.\n\nWhen you enter the Violet Tower, the curse will begin to affect you.\n\nOnce you have defeated Ar'kelos, ascend the tower and assist me in making preparations for the ritual.", objectives = "" }
WordHunterWoW_QuestEN[10179] = { title = "The Custodian of Kirin'Var", description = "When it became clear that our expedition was trapped in Outland with no way to return to Azeroth, the Kirin Tor contingent traveled to the Plains of Farahlon and built Kirin'Var village. I left the administration of the town in the hands of Custodian Dieworth, but when Kael'thas and his forces sealed me in the Violet Tower, I lost contact with the custodian.\n\nSearch for him in Kirin'Var Village and help him in any way you can, {name}. I'm certain he's got his hands full in the aftermath of the attack.", objectives = "" }
WordHunterWoW_QuestEN[10180] = { title = "Can't Stay Away", description = "I tried to persuade Isfar to remain here, in the safety of Shattrath, but he would have none of it. Instead, he's decided to venture out to Auchindoun again on his own.\n\nHe was lucky enough to escape the Sethekk Halls once, but if they discover him, there won't be a second time.\n\nI admire his desire to free his sister, but he's not going to be able to do it without help.\n\nFind Isfar and have a word with him, {name}. If you can't persuade him to come back, perhaps you could help him rescue Lakka?", objectives = "" }
WordHunterWoW_QuestEN[10182] = { title = "Battle-Mage Dathric", description = "The sword is of exceptional quality, finely crafted and perfectly balanced for a battle-mage. The seal of the Kirin Tor and the name \"Dathric\" are engraved into the weapon's pommel.\n\nTurning the weapon over in your hands, you notice a sense of wrongness radiating from the metal, as if the item is torn between two worlds. Could this be the item anchoring Battle-Mage Dathric's spirit to this world?\n\nPerhaps returning it to its proper place can break the bond, freeing Dathric's spirit to rest at last.", objectives = "" }
WordHunterWoW_QuestEN[10183] = { title = "Off To Area 52", description = "I'm out here studying the nether - the ethereal currents and all that.  This is an ideal spot away from the lights and hubbub of town.  Isn't this bridge great?  If I could just keep this junk working.\n\nHey, you know, if you're looking for work there's plenty at Area 52!  It's just up the path and take a right at the fork in the road.\n\nWhy don't you deliver my latest research notes to Rocket-Chief Fuselage?  I'm sure that he'd have plenty for you to do, what with the X-52 rocket ship, and all!", objectives = "" }
WordHunterWoW_QuestEN[10184] = { title = "Malevolent Remnants", description = "Most of the spirits in the village are little more than pale remnants of Kirin Tor mages. They retain no knowledge of their former selves and wander the ruins in blind anger.\n\nIt wasn't always like this, though. In the immediate aftermath of the attack, the spirits were restless, but not spiteful. With the passage of time they have only grown more aggressive. I dare not venture into the southern part of the village, for they will not spare even me. Quiet them and let us hope it will purge their anger.", objectives = "" }
WordHunterWoW_QuestEN[10185] = { title = "A Fate Worse Than Death", description = "After the blood elves leveled Kirin'Var Village, they started the construction of a large building to the northwest. Without the expertise of the archmage, we can't say for certain what's going on there.\n\nOne thing is clear, though. The blood elf activities have unleashed a tide of ravenous mana elementals on the village. They seem drawn to the ruins of Wizard Row, wreaking further destruction. We cannot permit this to continue.", objectives = "" }
WordHunterWoW_QuestEN[10186] = { title = "You're Hired!", description = "Let me be the first to welcome you aboard, Junior Technician 3rd Grade {name}!\n\nWe're building my masterpiece out here - the X-52 Nether-Rocket!\n\nBut first we need to get all of the parts and fuel for it.  That's where you come in.\n\nTo start, I need crystals - LOTS of crystals - for the rocket's Etherlithium Engine Matrix.  The draenei had crystals coming out of their ears!\n\nSo head north to the Ruins of Enkaat and get them for me!  Nevermind all of the draenei ghosts.", objectives = "" }
WordHunterWoW_QuestEN[10187] = { title = "A Message for the Archmage", description = "Although things are grim here, it heartened us quite a bit to hear from you that the archmage has not forgotten the village's plight.\n\n<The custodian glances up at the tower.>\n\nIt's ridiculous, isn't it? Sometimes it seems all that separates us is a wall of mere stone. The wall of magic is easy enough to forget.\n\nIf you would be so kind, ascend the tower and let Archmage Vargoth know that we are making progress with the village and will soon have a plan to ward off the mana creatures.", objectives = "" }
WordHunterWoW_QuestEN[10188] = { title = "The Sigil of Krasus", description = "Before we departed Azeroth all those years ago, the Kirin Tor entrusted our expedition with a powerful artifact, the Sigil of Krasus. It was a great boon to us in our battle against the orcs and it could play a key role in helping me break the enchantment that imprisons me.\n\nHowever, when Kael'thas divested me of my possessions, he gave the sigil to Spellbinder Maryana, who remained behind with the garrison. If he truly realized what he had in his possession, he wouldn't have given it away so easily.", objectives = "" }
WordHunterWoW_QuestEN[10189] = { title = "Manaforge B'naar", description = "You may have noticed one of Kael's manaforges on your way here.  You know, the large purple buildings sucking energy from the sky?\n\nWe were sent here by the Sha'tar to investigate them.  You can help our information gathering efforts by obtaining a personnel roster.  Giving us an idea of who's there and what they do will prove to be invaluable information.\n\nWe believe Captain Arathyn, leading a ballista team just outside of Manaforge B'naar, is in possession of one such roster.  Obtain it for us.", objectives = "" }
WordHunterWoW_QuestEN[10190] = { title = "Recharging the Batteries", description = "I have the very important task of collecting the machinery inside these ruins, but I'm having a problem keeping all of my bots charged up.\n\nThe phase hunters - those wyrm-looking things - have lots of energy!  You can find them all over the edges of this island, floating in from the nether.\n\nFill the battery on this recharging blaster by using it on a phase hunter when they're very weak, and then finish it off to soak up the last of its energy.", objectives = "" }
WordHunterWoW_QuestEN[10191] = { title = "Mark V is Alive!", description = "Greetings, {race}.  I am charged up and fully functional.\n\nThere are fragile draenei machines in these ruins, which I must retrieve.  I am equipped with delicate servos in my wrist actuators, and the latest in combustion-pneumatic bump soakers.  Handling them with care will not be an issue.\n\nHowever, the ghosts that haunt these ruins will likely attack, so I will need you and your friends along for protection.", objectives = "" }
WordHunterWoW_QuestEN[10192] = { title = "Krasus's Compendium", description = "The Kirin Tor sent one other of Krasus's possessions with our expedition. It was his spellbook, called Krasus's Compendium. Containing all the spells he mastered, it lent us a much-needed advantage in the war.\n\nBefore Kael'thas and his forces laid siege to Kirin'Var, the compendium had been stolen from me by a rebellious apprentice intent on studying necromancy. The apprentice and his followers divided and studied the text in secret, locking themselves inside their houses in the southern part of town.", objectives = "" }
WordHunterWoW_QuestEN[10193] = { title = "High Value Targets", description = "Based on the roster information, we know that the brains of the manaforge operations are the warp-masters and warp-engineers.  It is they who oversee the retrieval of a so called \"warp-energy\" by the manaforge and its delivery to a remote destination via a system of underground pipes.\n\nThe only other specialists in the area are geologists.  Everyone else is either part of the military or a magister crony; both easily replaced.\n\nGet in there and kill Kael's specialists; that's what'll hurt him the most.", objectives = "" }
WordHunterWoW_QuestEN[10194] = { title = "Stealth Flight", description = "While you were gone, my men uncovered another one of these manaforges.  It is east of here and is known as Manaforge Coruu.\n\nTwo of my best spies have arranged a secret landing spot outside of the manaforge.  You are to help them infiltrate Kael's forces and obtain whatever information you can.\n\nSpeak to Veronia just outside the city walls; she's arranged for a windrider that will take you to Manaforge Coruu.  Once there, speak to Caledis Brightdawn; he will brief you on your mission.", objectives = "" }
WordHunterWoW_QuestEN[10197] = { title = "A Convincing Disguise", description = "Infiltrating the ranks of Kael's army will not be an easy task.  With my knowledge of illusionary magic I could pass you off as one of Kael's followers, but there are certain details in their uniforms I could not replicate.\n\nBring me a set of their robes, a pair of their gloves and a Sunfury guardsman medallion.  This will make the results of my magic much more convincing.", objectives = "" }
WordHunterWoW_QuestEN[10198] = { title = "Information Gathering", description = "I've prepared a uniform with the pieces you obtained.  It is magically enhanced to complete the illusion.\n\nWe spotted Commander Dawnforge going in to meet Arcanist Ardonis a few minutes ago.  He had a full retinue of guards with him, so whatever they're discussing is bound to be incredibly important; see if you can catch any of it.\n\nOh, I almost forgot.  You'll want to stay away from the arcane golems patrolling the manaforge.  They will see right through the illusion.", objectives = "" }
WordHunterWoW_QuestEN[10199] = { title = "That Little Extra Kick", description = "So, I'm just missing the one ingredient that'll give my concoction that little extra kick that it needs.\n\nThe sting of the nether rays, roaming around near the shaleskin flayers, delivers quite a punch.  Bring me some of their stingers and I'll extract the venom right out of them!\n\nI'm certain the results will be explosive!", objectives = "" }
WordHunterWoW_QuestEN[10200] = { title = "Return to Thalodien", description = "It would be best if this information got back to Thalodien as soon as possible.  I'll stay here and cover our tracks.\n\nIt wouldn't do us much good to have Kael'thas find out what we were snooping around here.  Secret information is always better if your enemy doesn't know you have it.", objectives = "" }
WordHunterWoW_QuestEN[10201] = { title = "And Now, the Moment of Truth", description = "The oil is finally ready for its first test. It seems heavy enough to serve as a high quality weapon oil.\n\nThe only way to find out is to have a professional try it out. See Grek over there by the wanted posters? Sure, he's no poet, but the orc knows his way around a weapon!\n\nTake a sample of the oil to him and ask him to use it on his weapon. After he's had a chance to test it out, let me know what he thinks of it.", objectives = "" }
WordHunterWoW_QuestEN[10202] = { title = "A Defector", description = "We've recently been contacted by a Sunfury magister who wishes to join our ranks and swears he has information we're in need of.  We've checked our informants to make sure he's not a double agent and he checks out.\n\nHe's stationed in Manaforge Ara which makes communication difficult.  Talk to him and see what he knows.  If he's half as useful as he claims to be, we'll be able to put him to good use.", objectives = "" }
WordHunterWoW_QuestEN[10203] = { title = "Invaluable Asset Zapping", description = "See the fissure running through Area 52?  We did that!  <grin>\n\nIt's yielding up all sorts of goodies for the X-52 Nether-Rocket, but we're running short on equipment.\n\nWe had an operation at the Arklon Ruins to the southeast until the Burning Legion moved in.  I need you to take this Ultra Deconsolodation Zapper to the ruins.  Use it to beam our gear back to Lead Sapper Blastfizzle down in the fissure.\n\nJunior Technician 3rd Grade {name}, this is your chance for that promotion.  Don't blow it!", objectives = "" }
WordHunterWoW_QuestEN[10204] = { title = "Bloodgem Crystals", description = "Kael's magisters have refined their usage of mana crystals to the point where they can siphon large amounts of energy in a matter of seconds.\n\nThey do this by attuning smaller bloodgem crystal shards to larger, fully charged ones.\n\nGo to Manaforge B'naar and obtain one of these shards from a Sunfury magister and use it to siphon energy from one of the larger crystals.\n\nReturn to me so that I may study the effects of the aura.  Do not worry; any side effects should be temporary.", objectives = "" }
WordHunterWoW_QuestEN[10205] = { title = "Warp-Raider Nesaad", description = "Warp-Raider Nesaad must be dealt with!  I have no idea how he survived my attack, but he cannot be allowed to continue his operation out there.\n\nGo back and take out Nesaad.  He keeps a small ethereal camp near the southwestern corner of the Heap.\n\nDon't fail like I did, {class}.", objectives = "" }
WordHunterWoW_QuestEN[10206] = { title = "Pick Your Part", description = "Those ethereal clowns are as opportunistic as us, I'll give them that.  But no one, and I mean NO ONE, moves in on a B.O.O.M. claim!\n\nThe Heap to the south is ours!\n\nIf we're to finish the X-52 Nether-Rocket, we're going to need all of the new tech that we can get our hands on.  And since the ethereals are stealing from us, I think it's only fair that we repay them in kind.\n\nWhy don't you head down there and see if you can acquire some of their technology out from under their noses!", objectives = "" }
WordHunterWoW_QuestEN[10208] = { title = "Disrupt Their Reinforcements", description = "Directly east of here is the Legion Front.  Spaced across the front are infernal portals and gateways, used to bring reinforcements to Hellfire Peninsula and throughout Outland. We're going to destroy those portals!\n\nTake these primers.  Designed in Area 52, they use the demons' own power as an explosive!  Defeat Legion forces around Portals Xilus and Kruul to gather demonic rune stones, use the primer to detonate four stones inside the portals, and watch!  Return to me when your mission is complete.", objectives = "" }
WordHunterWoW_QuestEN[10209] = { title = "Summoner Kanthin's Prize", description = "The next thing we must do is reclaim my familiar, Glacius, from the blood elf summoner who holds it captive. Summoner Kanthin was one of the most senior magisters in the force Kael'thas sent to decimate Kirin'Var. It's only natural that he would claim my familiar as a kind of trophy.\n\nI'm certain that Kanthin, fool that he is, has tried to compel Glacius to serve him. My scrying has revealed that Kanthin is now stationed at 'Manaforge Duro,' if that terminology has any meaning for you.", objectives = "" }
WordHunterWoW_QuestEN[10210] = { title = "A'dal", description = "Welcome to Shattrath City, {class}.  This might be the one place in all of Outland where you'll find any semblance of safety.\n\nA group of naaru known as the Sha'tar drove the demons away from here.\n\nIf you've never met a naaru, you ought to see A'dal inside the Terrace of Light.  The leader of the Sha'tar is an awe-inspiring sight if I ever saw one.  Sure is a change of pace from anything else in this bleak land.", objectives = "" }
WordHunterWoW_QuestEN[10211] = { title = "City of Light", description = "Do not burden A'dal with petty inquisitions, {class}.  That just might be the most powerful being you ever come face to face with.\n\nYou do not look familiar.  I suppose you want to learn about the city?\n\nYou'll have to excuse me if I don't give you a tour myself, but I'm a bit busy discussing strategy with A'dal.  Perhaps you'll find a summoned servant acceptable in my stead?  Excellent!", objectives = "" }
WordHunterWoW_QuestEN[10213] = { title = "Investigate the Crash", description = "When I was wounded in the wastes I saw a goblin zeppelin crash.  It went down to the northwest, beyond the Expedition Armory. \n\nThe zeppelin was on fire.  Shrieking, burning goblins were falling like bombs from the sky.  Of course I was in a lot of pain and I had lost a lot of blood.  I may have imagined the whole thing.\n\nIf you can find any survivors, we can offer them sanctuary here at Spinebreaker Post.  ", objectives = "" }
WordHunterWoW_QuestEN[10214] = { title = "When This Mine's a-Rockin'", description = "The mine's been overrun by a plague of gan'arg misfits, and on top of that, the peons have decided that this is a fine time for a nap! I don't know how they can sleep through all the disurbances coming from the mine, but that's the least of my problems.\n\nIf we don't get rid of those gan'arg pests soon, Thrallmar's supply of ore and other minerals will be cut off. I've already asked Watch Commander Krunk for help, but he says he can't spare the men with the town under constant attack. Will you help?", objectives = "" }
WordHunterWoW_QuestEN[10220] = { title = "Make Them Listen", description = "I was sent here to make contact with the Unyielding spirits.  These once proud Alliance soldiers were defeated long ago, and now their cursed spirits haunt the ruins to the west.  \n\nIf they would only join us we would gain a powerful ally.  Imagine, a legion of undying warriors to use against our enemies.  But these undead are mad with hatred and will not listen to me.  \n\nPerhaps they can be forced to join us.  ", objectives = "" }
WordHunterWoW_QuestEN[10221] = { title = "Dr. Boom!", description = "{name}, my former protege, Sparky Uberthruster, wouldn't wear his helmet while down here and one day transformed into the infamous Dr. Boom!\n\nAnd he stole off to the northeast with most of our sapping equipment!  He and his Boom Bots have been a menace to Area 52 ever since.\n\nI need you to go to his Camp of Boom just outside of town and put an end to him!  Use these Boom's Doom bombs to take him out.\n\nAnd make sure not to get too close to him or his Boom Bots!", objectives = "" }
WordHunterWoW_QuestEN[10222] = { title = "The Sunfury Garrison", description = "After Prince Kael'thas's forces destroyed the village and imprisoned the archmage in the Violet Tower, they withdrew to Sunfury Hold to the northeast. The very men who destroyed our village and slew our fellows toast their 'amazing victory' while we are helpless to avenge the fallen.\n\nWe must not allow these crimes to go unanswered! Be the instrument of our vengeance, {name}. Go to Sunfury Hold and claim the lives of those responsible for this crime.", objectives = "" }
WordHunterWoW_QuestEN[10223] = { title = "Down With Daellis", description = "I'll never forget the blood elf who led the attack. He wore a tabard with a device I've never seen before, over top of crimson armor.\n\nHe was ferocious and merciless, leading from the front where most other blood elf officers would never be seen. He was responsible for the deaths of many Kirin Tor mages that day, but he didn't linger long at Sunfury Hold. Kael'thas has ordered him to Manaforge Duro to aid in their attempt to control the area. Find him, {name}, and silence his bow for good.", objectives = "" }
WordHunterWoW_QuestEN[10224] = { title = "Essence for the Engines", description = "As the X-52's chief of engineering, I have to see to it that the nether-rocket's main engines are in tip-top shape.\n\nUnfortunately, I haven't built them yet.\n\n{class}, I'm in dire straits here!  I have almost all of the parts.  All that I'm missing is the engine core.\n\nLuckily for us, I think we can make use of the essence from the local mana wraiths to jump-start the engines.\n\nThey can be found near most of the glowing trenches in the northern part of the island.  Except for here in Area 52, of course.", objectives = "" }
WordHunterWoW_QuestEN[10225] = { title = "Report to Engineering", description = "{name}!  I need you to take all of these etherlithium crystals over to Chief Engineer Trep, my, uh, chief of engineering.\n\nHe should know what to do with them.  And if he doesn't, you see to it that he finds out!", objectives = "" }
WordHunterWoW_QuestEN[10226] = { title = "Elemental Power Extraction", description = "Darn it, that didn't do it!\n\nOk, I've got another idea!  I had Xyrol whip up an elemental power extractor.  I'm not certain exactly what this power will do, but I know that I can use it.\n\nThe sundered rumblers and warp aberrations on the ledge of the Crumbling Wastes to the south have just what I need for the engines!\n\nThe extractor will change the form of their power into something solid that you'll be able to gather up after you've defeated them.", objectives = "" }
WordHunterWoW_QuestEN[10227] = { title = "I See Dead Draenei", description = "I see dead draenei. They're all around us.\n\nBah, nobody believes me because I'm a child. Not even my own mommy believes me.\n\n<Ha'lei points to Ramdor.>\n\nHe believes me, though... He sees them too. Boy does he get angry about it!\n\nIt's kind of funny. I see ghosts and people just smile and pat me on the head, trying to placate me. Ramdor sees ghosts and people label him as crazy. I sure hope I never grow up!\n\nYou should probably talk to Ramdor before you go inside. He was once a death priest.", objectives = "" }
WordHunterWoW_QuestEN[10228] = { title = "Ezekiel", description = "I believe that the dead, which we have been caring for these last 500 odd years, should be left alone. Maladaar has other plans. He has retreated to the Crypt of Remembrance to start his experiments... Necromancy.\n\nI hope you weren't thinking about going in there... Not before helping me out so that these damned spirits will finally leave me alone. I know where they keep their treasures, {race}. Got your attention, eh?\n\nBring me the book of the dead, held by the Aldor, Ezekiel of Shattrath.\n", objectives = "" }
WordHunterWoW_QuestEN[10229] = { title = "Decipher the Tome", description = "This tome appears to be some sort of history written in a secret Alliance cipher.  Althen, the historian in Spinebreaker Post, has studied the Unyielding for some time; he may be able to crack the Alliance code and decipher the book.  ", objectives = "" }
WordHunterWoW_QuestEN[10230] = { title = "The Battle Horn", description = "Perhaps we have taken the wrong approach to the Unyielding? \n\nThe tome tells me the Expedition Armory was destroyed by orcs and death knights long ago.  The Unyielding remain here as vengeful spirits trapped in an eternal battle against the fel orc clans.  \n\nThey think only of revenge.  We must arrange for them to defeat their most hated enemies.  Enter the Expedition Armory once again and find Lieutenant Commander Thalvos.  He carries a battle horn that can summon the Unyielding.  Bring it to me.  ", objectives = "" }
WordHunterWoW_QuestEN[10231] = { title = "What Book? I Don't See Any Book.", description = "Ramdor? Hrm, let me think... Ramdor... Oh yes, the death priest. What does he want with the book? Well it doesn't matter. Yes I lied to you and no I don't have the book. Not anymore, anyway. It was stolen. Probably by one of those filthy refugees.\n\nBesides, Auchindoun is now defunct. We have no use for the book. If you find it, you can keep it.\n\nLike I said, I saw some of those ruffians snooping around the terrace last week. Start your search with them. They're probably playing dice in the slums.", objectives = "" }
WordHunterWoW_QuestEN[10232] = { title = "In A Scrap With The Legion", description = "The Burning Legion has moved in on our claim at the Scrap Field down the path and across the bridge to the east.\n\nThis could be a huge problem for us!  With the Legion at the Arklon Ruins, and now there, it's starting to look bad for us - and the rocket project - here at Area 52.\n\n{name}, I need you to go out there and deal with those demons!  I'd do it, but I'm a lover, not a fighter.\n\nYep, this is going to be trouble, I can feel it!", objectives = "" }
WordHunterWoW_QuestEN[10233] = { title = "Torching Sunfury Hold", description = "Ridding Sunfury Hold of its garrison is not sufficient to keep the blood elves from reoccupying it. Kael'thas's followers are zealous and tenacious. Leaving them anything to use at Sunfury is effectively an invitation to return.\n\nNo, it must all be destroyed. See to it that their tents and artillery burn to ashes!\n\n<The ghost's fists clench.>\n\nSteal torches from the Sunfury flamekeepers to accomplish your task, {name}.", objectives = "" }
WordHunterWoW_QuestEN[10234] = { title = "One Demon's Trash...", description = "You look like a capable young man!  I was wondering if you could lend me a hand?\n\nTo the east is the Scrap Field, which the Burning Legion has moved into.  It's full of huge fel reaver parts.  There're also a whole bunch of smaller parts in there that they don't seem to care about.\n\nI want you to get in there and get me a lot of those smaller fel reaver parts!", objectives = "" }
WordHunterWoW_QuestEN[10235] = { title = "Declawing Doomclaw", description = "You know what might just discourage them?  Take out their leader!\n\nIt seems to work everywhere else from what I've heard.  And when they see a grizzled {class}, such as yourself take out their leader... why, I bet they'll tuck tail and run for the hills!\n\nGet back in there and take out the big one they call Doomclaw.  I hear he keeps himself in the eastern part of the Scrap Field underneath the pipe.\n\nBring me his claw, too!  Maybe we can make use of it.", objectives = "" }
WordHunterWoW_QuestEN[10236] = { title = "Outland Sucks!", description = "I can't believe I left Booty Bay to come to Outland. My cousin Screed Luckheed promised me I would make a fortune, but instead he flew off in his zeppelin and left me here to try to scrape a living out of this mine. \n\nHow am I supposed to make a living here with helboars and demons and fel orcs attacking all the time? My shredder here was broken yesterday and the parts I need to fix it were stolen by fel orcs. They took the parts into the fissure to the southwest and may have dropped them there.", objectives = "" }
WordHunterWoW_QuestEN[10237] = { title = "Warn Area 52!", description = "{name}, you have to get word back to Area 52 immediately!  Hurry!\n\nTell the rocket-chief that the Burning Legion is after us now!", objectives = "" }
WordHunterWoW_QuestEN[10238] = { title = "How to Serve Goblins", description = "Why would fel orcs steal my shredder parts?  I hate them so much.  They just sneak into my camp here and take things all the time.  A couple of days ago they stole three of my peons!  Now the rest of my peons have run off because they are afraid they are going to be eaten by fel orcs.  \n\nI can't run a mine without peons.  If you could save the peons that I lost maybe the others would come back.  The fel orcs have their camps along the wall to the southwest.", objectives = "" }
WordHunterWoW_QuestEN[10239] = { title = "Potential Energy Source", description = "We are not the only ones battling the influx of the mana beings. The blood elves, too, are troubled by them, but I'm not sure why.\n\nWhatever they're involved in over there, they don't seem to be stopping. Instead, I've seen them employ a variety of methods to kill the creatures. The most effective involves magical defenses fueled by some sort of concentrated energy.\n\nCapture some of these energy sources and bring them to me. Don't hesitate to stymie the elves if an opportunity presents itself.", objectives = "" }
WordHunterWoW_QuestEN[10240] = { title = "Building a Perimeter", description = "We are prepared to try to construct a perimeter around the village using the energy source taken from the blood elves. I can't guarantee that it will work, but we have to attempt it.\n\nOtherwise, the mana creatures will surely continue devouring the spirits of the fallen Kirin Tor.\n\nUse this device at the small runes around the perimeter of town to release the energy there. If I've woven the field correctly, we should start noticing a difference once you've used the device at each point.", objectives = "" }
WordHunterWoW_QuestEN[10241] = { title = "Distraction at Manaforge B'naar", description = "We were sent here by the Sha'tar to investigate the manaforges that Kael'thas' army is operating here.  Unfortunately, the Scryers threaten to renege on their information-gathering duties unless we support them with military action.\n\nWe can't afford to compromise this mission over politics, so we've agreed to weaken the manaforge's defenses so that the Scryers can do their work.\n\nProve your loyalty to the Aldor and slay the Sunfury magisters and bloodwarders that guard Manaforge B'naar.", objectives = "" }
WordHunterWoW_QuestEN[10242] = { title = "Spinebreaker Post", description = "{name}, my equipment here is, unfortunately, not configured for all the tests I'd like to perform.  However, my colleague at Spinebreaker Post, Apothecary Albreck, possesses the required implements.\n\nI have acquired a sample of Bleeding Hollow blood -- gained from a past mission of Thrallmar's agents.  Take the sample to Albreck and allow him to study it.\n\nTo reach Spinebreaker Post, speak with Wing Commander Brack, near the wyverns to the south.", objectives = "" }
WordHunterWoW_QuestEN[10243] = { title = "Naaru Technology", description = "The Scryers obtained a personnel roster for Manaforge B'naar and are now having a field day picking out assassination targets.\n\nThey've missed one small bit of information, scribbled on the side of the roster.  It appeared to be a password or code like those used to access naaru-made technology like the Exodar or Tempest Keep.\n\nGo inside the manaforge and look for a control panel.  Copy its readouts on this scroll as well as you can.  We must confirm our suspicions about the origin of the technology.", objectives = "" }
WordHunterWoW_QuestEN[10245] = { title = "B'naar Console Transcription", description = "You try to transcribe the shapes as you see them flash across your eyes.  The results are less than exact, but should serve as adequate evidence to prove or disprove the Aldor's suspicions.", objectives = "" }
WordHunterWoW_QuestEN[10246] = { title = "Attack on Manaforge Coruu", description = "Your success at Manaforge B'naar was quite noteworthy.  I'm sure that Anchorite Karja will ask you for a repeat performance at Manaforge Coruu next.\n\nWe've learned of a particularly important regiment of Sunfury arcanists and researchers being deployed there and I would like you to target them.  Succeed and you will deliver a crushing blow against our enemy's forces.", objectives = "" }
WordHunterWoW_QuestEN[10247] = { title = "Doctor Vomisa, Ph.T.", description = "On the outskirts of town to the east are the Proving Grounds.  Our top experimentalist, Doctor Vomisa, has been toying with a combination of fel reaver, ethereal, and of course, goblin technologies there.\n\nThis is in no small part thanks to your gathering efforts Junior Technician 3rd Grade, {name}!\n\nGo to him; I know that he'll have a solution for saving Area 52.\n\nAnd since he's likely to use you as a test subject, if I were you, I'd bring some friends along just in case.", objectives = "" }
WordHunterWoW_QuestEN[10248] = { title = "You, Robot", description = "Doctor Vomisa, Ph.T. at your service.  Here, take this controller.  I want you to activate it and give my newly-invented Scrap Reaver X6000 a spin.\n\nJust stay nearby!  The controller is tied to my console here, and if you get too far away, the robot will cease to function.\n\nTry out everything... I'll be watching and calibrating its servos based upon your test run.", objectives = "" }
WordHunterWoW_QuestEN[10249] = { title = "Back to the Chief!", description = "I'm certain that the rocket-chief is going to want to have a word or two with you!\n\nIf I were you, I wouldn't hesitate to get back to Area 52 and speak with him!", objectives = "" }
WordHunterWoW_QuestEN[10250] = { title = "Bloody Vengeance", description = "East of here is an old destroyed Alliance siege tower.  Now scavengers loot it for old nails and bits of scrap.  Long ago, many Alliance warriors lost their lives at this tower and their banner was captured by Urtrak, a foul orc commander.\n\nBlow the Unyielding battle horn near the Alliance banner.  This will get the attention of Urtrak.  It may also summon forth warriors who fell in battle long ago.", objectives = "" }
WordHunterWoW_QuestEN[10251] = { title = "The Master's Grand Design?", description = "A couple of draenei paid us a visit last night. They'd somehow learned that we had the book in our possession and made a very generous offer to \"take it off our hands.\"\n\nWe didn't ask them what they wanted with the book but the young one kept talking about \"the master's grand design,\" whatever that means.\n\nLook, I don't ask questions when money is in play. They gave us a lot of gold and we gave them the book.\n\nHe said that they lived in Nagrand - in the old Abandoned Armory, north of Telaar.", objectives = "" }
WordHunterWoW_QuestEN[10252] = { title = "Vision of the Dead", description = "It has already begun. Levixus stands atop the ruins of Auchindoun and reads from the book of the dead. He calls the dead out by name and, through demonic ritual, binds the tortured souls to his will. He will raise all of Auchindoun if given the chance!\n\nBut... you must first prepare. You cannot do battle with that which you cannot see.\n\n<Nitrin hands you a parchment.>\n\nBring me the items I require to brew the tincture. It will open your mind and allow you to see into the spirit world.", objectives = "" }
WordHunterWoW_QuestEN[10253] = { title = "Levixus the Soul Caller", description = "Go now, {name}. You will find Levixus on the uppermost ruins of Auchindoun. Enter there from the southern reaches of the Bone Wastes. He stands amidst a storm of souls...\n\nDestroy him and take the book of the dead. Once you have the cursed book in your possession, destroy it! Destroy it so that such an atrocity can never again be made possible.", objectives = "" }
WordHunterWoW_QuestEN[10254] = { title = "Force Commander Danath", description = "<Marshal Isildor spits in the dust.>\n\nWell, time to earn your pay. Report at once to Force Commander Trollbane within the keep. He and his advisors will no doubt be heartened to see you.\n\n<Marshal Isildor salutes you stoically.>\n\nFor the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[10255] = { title = "Testing the Antidote", description = "I think there's something we can use in the blood as the base of an antidote. Don't look at me like I've lost my mind!\n\nIt's a common theme in nature. Often, the cure for something can be derived from the toxin itself. That's just what I aim to do.\n\nRidding the boars of their demonic influence would probably eliminate their aggression and give us insight into how to best attempt to help other species.", objectives = "" }
WordHunterWoW_QuestEN[10256] = { title = "Finding the Keymaster", description = "In retrospect, I suppose I should've expected Kael'thas's magic to be this robust. He's always been a talented mage, but I've never seen anything like the power he wielded during the attack on the tower.\n\nThe ward keeps me from being able to scry out the force holding it in place, but it doesn't preclude you from scrying.\n\nYou'll require a focus, though. A crystal-bearing giant named Apex roams the plains to the west of Manaforge Duro. One of its crystals would make an excellent scrying focus.", objectives = "" }
WordHunterWoW_QuestEN[10257] = { title = "Capturing the Keystone", description = "It doesn't surprise me that Kael'thas has put the key to this ward in the hands of someone like Commander Sarannis. Prince Kael'thas is a great many things, but he is no simpleton.\n\nIn order to break this curse once and for all, you must enter Tempest Keep and claim the keystone.\n\nOnly once the keystone has been destroyed will I regain my freedom.", objectives = "" }
WordHunterWoW_QuestEN[10258] = { title = "Honor the Fallen", description = "Hogarth, the commander of the Armory, is in the eastern tower.  You must report your victory over Urtrak to him.  Perhaps he will be friendly?  Of course he may try to consume your soul.  One can never tell with spirits such as these. \n\nThe Unyielding are still against us and will no doubt kill you if they can.  Be careful {name}.  ", objectives = "" }
WordHunterWoW_QuestEN[10261] = { title = "WANTED: Annihilator Servo!", description = "WANTED:  1 Annihilator Servo to replace the failing one in my Long Neck Spectrum Analyzer.\n\nYou and your friends might want to check with the blood elves at Manaforge B'naar to the west to see if they have any spares.  They seem to have a few arcane annihilators roaming about.\n\nPlease deliver the servo in pristine condition to Papa Wheeler at Area 52.", objectives = "" }
WordHunterWoW_QuestEN[10262] = { title = "A Heap of Ethereals", description = "There is something else that I want your help with.\n\nA group of ethereals, known as the Zaxxis, have cut their relationship with the Consortium and gone into business for themselves.  They've even cut deals with the Sunfury blood elves.  This will not be tolerated!\n\nI infiltrated their group at the Heap to the south.  But after I took out their leader, I had to escape here to Area 52.\n\n{class}, go down there and bring back their insignias.  Of course, not all wear them because they're cowards.", objectives = "" }
WordHunterWoW_QuestEN[10263] = { title = "Assisting the Consortium", description = "The naaru of Shattrath City have been trying to find a means to bring the Consortium over to their way of seeing things.\n\nLuck would have it that the business relationship between the ethereals and the blood elves of the Netherstorm has recently soured.\n\nThere's a Consortium representative in town named Nether-Stalker Khay'ji who recently ran into trouble with a pack of renegade ethereals.  As a representative of the Aldor, I would like for you to help him in any way that you can.", objectives = "" }
WordHunterWoW_QuestEN[10264] = { title = "Assisting the Consortium", description = "The naaru of Shattrath City have been trying to find a means to bring the Consortium over to their way of seeing things.\n\nLuck would have it that the business relationship between the ethereals and the blood elves of the Netherstorm has recently soured.\n\nThere's a Consortium representative in town named Nether-Stalker Khay'ji who recently ran into trouble with a pack of renegade ethereals.  As a representative of the Scryers, I would like for you to help him in any way that you can.", objectives = "" }
WordHunterWoW_QuestEN[10265] = { title = "Consortium Crystal Collection", description = "Our leader, Nexus-Prince Haramad, has tasked me with the acquisition of a crystal artifact from the Arklon Ruins to the southeast.\n\nThey're old draenei ruins.  Unfortunately for both myself and the goblins here, the Burning Legion has decided to move in to perform their own excavation.\n\nIf you're willing to help me, go to the ruins and take the crystal artifact from the dreadlord named Pentatharon.", objectives = "" }
WordHunterWoW_QuestEN[10266] = { title = "Request for Assistance", description = "While you were at the Arklon Ruins, I received a request for assistance from one of our representatives out in the field.  It would appear that the Consortium is having some 'difficulties' in trying to recover property from the blood elves, which they refuse to pay for.\n\nPlease head east out of Area 52 and cross the bridge to the next island over.  You'll find my associate, Gahruj, at the Midrealm Post, just inside of Eco-Dome Midrealm.", objectives = "" }
WordHunterWoW_QuestEN[10267] = { title = "Rightful Repossession", description = "Our business relations with the blood elves appear to be at an end.  A few weeks ago a large shipment of surveying equipment was delivered to them at Manaforge Duro.  They have refused to pay for it.\n\n{name}, I would ask that you pay the blood elves of Manaforge Duro to the east a visit.  They appear to be having some trouble with an infestation of mana creatures there, so take advantage of their preoccupation.\n\nI care not what happens to them, but I would very much like to see the return of our property.", objectives = "" }
WordHunterWoW_QuestEN[10268] = { title = "An Audience with the Prince", description = "Nexus-Prince Haramad has conveyed to me that he is interested in the immediate return of this property to him personally.  I would greatly appreciate if you would deliver it in my stead.\n\nIt is a great honor to gain an audience with the nexus-prince, and I am sure that he would be keenly interested in hearing the tales of your adventures here in the Netherstorm.\n\nSeek out his chamber atop the Stormspire to the north.  He is often present as a holographic image, which you may address.", objectives = "" }
WordHunterWoW_QuestEN[10269] = { title = "Triangulation Point One", description = "There is another reason for the retrieval of the surveying equipment.  There is a crystal from draenei legend of great importance to me.\n\nIt is said that the crystal bestows god-like powers to its bearer!  But it is in danger of being unearthed by others - namely the Burning Legion.\n\n{name}, take the equipment and use it to find the first triangulation point.  We know it to be somewhere to the east near Manaforge Ultris.\n\nAfterward, check-in with my agent, Dealer Hazzin, on the Manaforge Ultris island.", objectives = "" }
WordHunterWoW_QuestEN[10270] = { title = "A Not-So-Modest Proposal", description = "From the look on your face, I can tell you're a {race} who appreciates a good profit.\n\nI've built a reputation as a dealer in exotic goods, and I'm about to launch a new venture.\n\nI need a reliable subcontractor to procure the goods from the Celestial Ridge.\n\nFirst, you'll need to re-energize a teleport pad. There is a spare power pack in Access Shaft Zeon, which is on the south side of Manaforge UItris. The Protectorate is operating in there, so you may be able to follow their tracers to your goal.", objectives = "" }
WordHunterWoW_QuestEN[10271] = { title = "Getting Down to Business", description = "As you've no doubt seen, the area is teeming with nether dragons in various stages of growth. All nether dragons, young and old, contain an essence that's highly desired by K -- err, by a client of mine.\n\nMost people aren't willing to risk their lives to gather it, so we've got the place to ourselves. You can start by gathering the essence from any of the creatures out here, but it's imperative that we start building a supply right away. Return to me once you have the first batch.", objectives = "" }
WordHunterWoW_QuestEN[10272] = { title = "A Promising Start", description = "We've come here to investigate rumors of a strange breed of dragons, perhaps even descendents of Deathwing himself. These are clearly not ordinary black dragons, though.\n\nWe'll know more once we've had a chance to examine their eggs. Their hatred for my flight runs deep, so I can't get close enough to gather the eggs. Will you agree to help?", objectives = "" }
WordHunterWoW_QuestEN[10273] = { title = "Troublesome Distractions", description = "Your former employer, Wind Trader Marid, must've gotten wind that you're helping us now. Through my projection, I've seen his nether-stalkers entering the area, hoping to track us down.\n\nWe've been able to evade them so far, but Marid must be dealt with before the problem grows more severe.\n\nIf your impressions of Marid are correct, he'll do just about anything to secure the supply of his product. Return to him and tell him you're prepared to offer a deal. Lure him away and slay him.", objectives = "" }
WordHunterWoW_QuestEN[10274] = { title = "Securing the Celestial Ridge", description = "The nether dragons have the same ferocious temperament as their black dragon forbears, but there is something entirely alien about them. They hatch and mature rapidly, harnessing the strange energies that forged their kind in the destruction of Draenor.\n\nThere is so much more I need to know about them, but I believe the powers may be of use to my own flight. If we can displace the leader of these drakes, Veraku, with a show of dominance, we can cow the rest of them into submission.", objectives = "" }
WordHunterWoW_QuestEN[10275] = { title = "Triangulation Point Two", description = "I've recalibrated the triangulation device with the information that you provided from the first point.  You'll use it in exactly the same manner to discover the second.\n\nAll that I can tell you is that the second point is somewhere far to the west.\n\nOnce you've located it, speak with Wind Trader Tuluman; another of the nexus-prince's agents.  He's posing as a weapon merchant at a small trading post next to the bridge, which leads to the island that Manaforge Ara is on.", objectives = "" }
WordHunterWoW_QuestEN[10276] = { title = "Full Triangle", description = "With the data from both the first and second points, I'm now certain that the crystal is at the top of the Ruins of Farahlon to the northeast.\n\nUnfortunately, the data indicates that the crystal is moving, which means that it has already been discovered, probably by the Burning Legion!\n\nJust in case, I recommend that you take some friends along.\n\nSlay the demon that has the crystal and return it to Nexus-Prince Haramad.", objectives = "" }
WordHunterWoW_QuestEN[10277] = { title = "The Caverns of Time", description = "Greetings, {name}. Please follow the custodian. She will make things a bit more... clear.", objectives = "" }
WordHunterWoW_QuestEN[10278] = { title = "The Warp Rifts", description = "Long have I wandered through Outland, searching for the truth of the void.  Now I am old and weak.  Perhaps you will help me? \n\nI must learn the secrets of the voidwalkers.  You must find the Warp Fields to the west.  West of the Expedition Armory there is a dark place on the edge of the abyss where time and space are weak.  Use my unstable warp rift generator in the Warp Fields to create a warp rift.  You must gather warp nether from the creatures that come through.  ", objectives = "" }
WordHunterWoW_QuestEN[10279] = { title = "To The Master's Lair", description = "Ah, {name}. We have been expecting you. Please, allow one of my brothers to fly you down to the master. He awaits you below...", objectives = "" }
WordHunterWoW_QuestEN[10280] = { title = "Special Delivery to Shattrath City", description = "I am an ethereal of my word, {name}.  You have truly inspired me.\n\nI am now going to give you the ata'mal crystal to hand over to the naaru.  As it was your heroics that made this possible, I wish for you to deliver it.\n\nYou may use my personal teleporter to go directly to Shattrath City.  Simply step through it and you will be transported there.\n\nGive the crystal to the naaru known as A'dal on the Terrace of Light.  May the trade winds be at your back.", objectives = "" }
WordHunterWoW_QuestEN[10281] = { title = "Formal Introductions", description = "Greetings, {name}. Do not be alarmed. This is merely a projection of my current form. It's the only way my companion and I could keep watch without revealing ourselves.\n\nThe ethereal who approached you, Marid, is little better than a swindler in the guise of a legitimate merchant. I'd like you to consider working with me instead. My purpose out here is to find out more about the unusual dragonkin on this ridge. Meet me at the north end of the ridge and we will discuss this further.", objectives = "" }
WordHunterWoW_QuestEN[10282] = { title = "Old Hillsbrad", description = "To the west is the timeway to Hillsbrad of the past - 7 years to be exact.\n\nForces are working against the Horde warchief, Thrall, attempting to prevent him from ever escaping Durnholde Keep.\n\nIf Thrall never escapes, this world - as you know it - will cease to exist.\n\nGather a group of adventurers and take the timeway to old Hillsbrad. Two of our agents await you inside.\n\nSpeak with Erozion on the other side.", objectives = "" }
WordHunterWoW_QuestEN[10286] = { title = "Arelion's Secret", description = "Arelion's journal does not deal with any sort of scholarly studies.  It details his escapades with a young female blood elf!  How could I've been such a fool?\n\nUnfortunately, the floozy's identity is not revealed in this journal.  Aledis, a colleague of Arelion's, was his best friend and confidant.  Go question him and find out who he was having this affair with.\n\nI saw Aledis leave Falcon Watch for Zangarmarsh.  Follow the road headed north from town; it'll eventually lead west, toward Zangarmarsh.", objectives = "" }
WordHunterWoW_QuestEN[10287] = { title = "The Mistress Revealed", description = "I'm Arelion's friend, but I'm not going to take the beating of my life for him.  His mistress is Viera Sunwhisper.\n\nGo tell that harpy of a wife of his.  What's she going to do anyway?", objectives = "" }
WordHunterWoW_QuestEN[10288] = { title = "Arrival in Outland", description = "I want you to speak with Amish Wildhammer and catch the first flight to Honor Hold. When you arrive at Honor Hold, you'll be greeted by Marshal Isildor. I have prepared a report detailing our situation here.  Give him the report, and tell him you're ready for duty.\n\nYou have your orders, soldier, now move out!  And though your blood must be burning to help us against the fiends below, waste no time here.  Honor Hold needs you even more.", objectives = "" }
WordHunterWoW_QuestEN[10289] = { title = "Journey to Thrallmar", description = "When you're ready, I'll summon a wyvern to fly you to Thrallmar. Once you arrive, deliver Orion's report to General Krakork.\n\nLok'tar ogar, {name} - good luck.", objectives = "" }
WordHunterWoW_QuestEN[10290] = { title = "In Search of Farahlite", description = "To the northeast is an area called the Netherstone, a landmark not seen when this was a lush, green land. Newly-exposed crystal formations have shown us a mineral we've called farahlite in honor of this land's former identity.\n\nThe tiny amount of farahlite we've mined has already proven popular with our clients. The highest grade of the mineral comes not from static deposits, but from the giants around the Netherstone. I can offer you a cut of the profits if you'll help supply the higher grade farahlite.", objectives = "" }
WordHunterWoW_QuestEN[10291] = { title = "Report to Nazgrel", description = "Though our warriors are without peer, our hold on this wasteland is still tenuous. Report to Nazgrel inside the barracks - he has need of agents... such as you. If we can't protect our holdings here, we'll be of no use to anyone. Now go!", objectives = "" }
WordHunterWoW_QuestEN[10293] = { title = "Hitting the Motherlode", description = "Now that we've got a good baseline product, we're going to need something of higher quality. Certainly the farahlite we've gathered so far is nice, but I know there's better out there.\n\nWe'll have to get a sample directly from Cragskaar, the patriarch of the Farahlon giants! You should be able to find it among the other giants in the Netherstone area. It's got huge pieces of farahlite jutting from its back and that's exactly what we need. Fell the giant and collect a farahlite core from it.", objectives = "" }
WordHunterWoW_QuestEN[10294] = { title = "Void Ridge", description = "We have to improve my warp rift generator.  You must take it to Void Ridge.  Head east of here.  You must avoid the foul fort of Zeth'Gor.  To the east beyond Zeth'Gor is a small pass through the mountains.  Through this pass you will find Void Ridge, a terrible place on the edge of the abyss.\n\nYou must kill the walkers that you find there, and bring me shards of their souls.  With their power we will improve upon the warp rift generator and open a portal to the beyond that cannot be closed.  ", objectives = "" }
WordHunterWoW_QuestEN[10295] = { title = "From the Abyss", description = "My warp rift generator is complete. You can now use it to summon a true prince of the void, a creature whose soul shard will tell us much of what lies beyond.  \n\nGo south in Void Ridge and use my warp rift generator near the void stones.  Look for a cluster of crystals near the edge of the abyss.  A huge warp rift will form and Void Baron Galaxis will surely appear.  \n\nDestroy this creature and bring me his soul shard.  ", objectives = "" }
WordHunterWoW_QuestEN[10296] = { title = "The Black Morass", description = "The Infinite Dragonflight have abandoned all pretense of subtlety. They plot to destroy the Guardian, Medivh, and prevent the Dark Portal from ever opening. While outwardly, this may appear a boon to the forces of the Alliance, it is in actuality catastrophic and will result in your world ending.\n\nYou must venture through the timeway leading to the Black Morass. Go west and then south, past my future self, until you reach the tunnel that houses the swamp specimens. Cross over and speak with Sa'at.", objectives = "" }
WordHunterWoW_QuestEN[10297] = { title = "The Opening of the Dark Portal", description = "Beyond this timeway the Guardian, Medivh, feverishly works to open the Dark Portal.\n\nScattered across the morass, rifts will materialize. Infinite will pour out of the rifts and attempt to destroy Medivh's shields and, ultimately, Medivh.\n\nKill their rift lords and leaders! Do this until Medivh succeeds.", objectives = "" }
WordHunterWoW_QuestEN[10299] = { title = "Shutting Down Manaforge B'naar", description = "We cannot shut down the manaforges by force as we'd risk causing an explosion that would shake Outland to the core.\n\nAccording to your transcription, there is an emergency shutdown that permanently disables the technology - a safety mechanism common in naaru constructs.\n\nTo perform this procedure you will have to obtain a crystal that will allow you to communicate with the console.  This access crystal is in the possession of an overseer called Theredis according to our information.", objectives = "" }
WordHunterWoW_QuestEN[10300] = { title = "Rebuilding the Staff", description = "<Ravandwyr inspects the staff, noting that part of the headpiece seems to be missing.>\n\nSimply barbaric! Ekkorash must've taken the staff's crystalline headpiece for use in some other trinket, not realizing that it works in concert with the rest of the staff.\n\nAs long as it remains broken, the staff's power is greatly diminished. With a suitable draenei crystal, I should be able to repair it. I've heard the goblins remarking about the crystals carried by the ghosts at the Enkaat Ruins to the north.", objectives = "" }
WordHunterWoW_QuestEN[10301] = { title = "Unlocking the Compendium", description = "While I'm glad to have most of Krasus's Compendium back, it's useless without the heliotrope oculus. You see, Krasus was well aware of the sheer power of the spells recorded in the book and took steps to safeguard them from prying eyes.\n\nOnly a knowledgeable mage can use the oculus to unlock the compendium's secrets.\n\nDuring Kael'thas's attack, one of his lieutenants, Spellreaver Marathelle, looted it and took it to Sunfury Hold northeast of the tower. No doubt she thought it a pretty little bauble.", objectives = "" }
WordHunterWoW_QuestEN[10302] = { title = "Volatile Mutations", description = "The irradiated power cores from the Exodar have been wreaking havoc on the environment here. The most obvious effect has been the appearance of the strange creatures that seem to have sprung up near them.\n\nThere may be something we can do to help them, but now, their sheer numbers are becoming too much for us to handle.\n\nI'd like you to go out and cull their numbers somewhat, and perhaps I'll have another idea after giving it some thought.", objectives = "" }
WordHunterWoW_QuestEN[10303] = { title = "The Blood Elves", description = "You must eliminate... the blood elf... threat.  Find out... what they're... up to!\n\nThey're on the... ridge behind me.", objectives = "" }
WordHunterWoW_QuestEN[10304] = { title = "Vindicator Aldar", description = "With your help, we were able to find a solution to our problems faster than I could have hoped.\n\nI don't have any other work for you to do. My apprentices and I can handle the rest.\n\nYou should go speak with Vindicator Aldar on the other side of the ship.", objectives = "" }
WordHunterWoW_QuestEN[10305] = { title = "Abjurist Belmara", description = "This worn, sturdy tome is no spellbook, as you might expect a Kirin Tor mage to carry. The pages of the volume are covered with hand-copied stories, accompanied by colorful illustrations.\n\nThe tome seems to be far older than its former owner and may have even been a family heirloom. A powerful tie to the book may have been the last thread tying Belmara's spirit to the ruins of Kirin'Var. Returning it to its proper place on the bookshelf in her quarters might help appease her restless spirit.", objectives = "" }
WordHunterWoW_QuestEN[10306] = { title = "Conjurer Luminrath", description = "The cloak, undoubtedly of high elven craftsmanship, is richly tailored, even by the standards of the Kirin Tor. The symbols and characters sewn into the cloak's fabric hold no meaning for you, but clearly imbue the garment with magical properties.\n\nPerhaps this object binds the spirit of its former owner to this plane of existence. If so, returning it to the dresser in Conjurer Luminrath's quarters might break the spirit's link to this world, allowing it to rest.", objectives = "" }
WordHunterWoW_QuestEN[10307] = { title = "Cohlien Frostweaver", description = "Looking at the hat, you find yourself asking if any Kirin Tor mage would own such headgear. Judging from the hat's wear, it seems the gnome wouldn't go anywhere without it.\n\nYou try on the hat momentarily, discovering no magical properties beyond a faint urge to dance.\n\nThe treasured possession might be the source of the dead mage's bond to the village. Placing the hat in the footlocker in Cohlien's quarters might free his spirit.", objectives = "" }
WordHunterWoW_QuestEN[10309] = { title = "It's a Fel Reaver, But with Heart", description = "You see that scrapped fel reaver over there to the south?  Isn't it a thing of beauty?\n\nI want its heart!\n\nWhat?  Yes, of course it has a heart... what doesn't?\n\n<N. D. looks indignant for a moment.>\n\nGo on over there, pry it open, bring back what I want and I'll give you a nice finder's fee in return.\n\nOh, and I'd take a friend or two along if I were you.  These Zaxxis ethereals are a pretty mean bunch!\n\nTake this fel zapper to jumpstart its heart when you're ready to begin.", objectives = "" }
WordHunterWoW_QuestEN[10310] = { title = "Sabotage the Warp-Gate!", description = "With the Burning Legion nearby at the fel reaver scrap field, we must do what we can to stop the flow of demons into the area.\n\nThey have a warp-gate to the south in an area that they've cleverly named Invasion Point: Destroyer.\n\nI need you to go with me to the site and keep me safe while I sabotage it.\n\nAfterward, go to the Midrealm Post to the north inside Eco-Dome Midrealm and apprise Gahruj of our success.\n\nWe're going to need a friend or two of yours along to help with this.", objectives = "" }
WordHunterWoW_QuestEN[10311] = { title = "Drijya Needs Your Help", description = "{class}, it is good to see a helpful face around here.\n\nThe Burning Legion at the nearby fel reaver heap has become more bold, and I am beginning to fear for our safety here.  The demons are constantly receiving reinforcements from Invasion Point: Destroyer to the south.\n\nMy compatriot, Drijya, has gone down there to scout and see if he can do something about the Burning Legion's warp-gate.\n\nPlease find and assist him in any way that you can.", objectives = "" }
WordHunterWoW_QuestEN[10312] = { title = "The Annals of Kirin'Var", description = "Silencing the spirits has not bled them of their aggression as we had hoped it would. The malevolent spirits you subdued have reemerged in the streets of the town.\n\nWe must uncover what is causing this to happen. The destruction of Kirin'Var was just the beginning, or else the spirits would have been quieted by now.\n\nThe town hall in the southern section of Kirin'Var maintained a logbook of all the residents. Last I heard, it was in the keeping of Battle-Mage Dathric. Perhaps his spirit still has it.", objectives = "" }
WordHunterWoW_QuestEN[10313] = { title = "Measuring Warp Energies", description = "If our instincts are right and these manaforges have been made using technology from Tempest Keep, then all of Outland could be in grave danger.\n\nTempest Keep's energy-recharging mechanisms were never supposed to be used this close to the land.  The warp energies are capable of destroying this very land, even when contained within Kael's pipelines.\n\nTake this orb to Manaforge B'naar; it is attuned to measure warp energies.  Use it at the pipelines' ends, where they go into the earth.", objectives = "" }
WordHunterWoW_QuestEN[10314] = { title = "A Lingering Suspicion", description = "The strange magical device resembles nothing you've ever seen before. It's certainly not of blood elf manufacture.\n\nAs you sense spirits moving closer to the building, the orb glows with a greater intensity, which fades as the spirits leave. There's no question that it plays a role in the corruption of the ghosts.\n\nHow it works remains a mystery. Perhaps Custodian Dieworth will have some insight if you can provide the remains of some of the spirits along with your observations.", objectives = "" }
WordHunterWoW_QuestEN[10315] = { title = "Neutralizing the Nethermancers", description = "The blood elves are fools!  I'm glad that our trade relations with them have fallen apart.  In all of my travels throughout the cosmos, I have never encountered beings so selfish.\n\nThey continue to destroy the land around us with their manaforges, so let's see if we can put a dent in their operations across the bridge at Manaforge Ara.\n\nTheir nethermancers channel energy to and from the blood gems to stabilize the flow of power.  Go over there and wipe them out!", objectives = "" }
WordHunterWoW_QuestEN[10316] = { title = "Searching for Evidence", description = "Whoever is behind the transformation of the spirits has been very deliberate in their actions, taking care to target the most powerful mages first, but why? The kind of magic required to influence the spirits of slain Kirin Tor mages must be very powerful.\n\nWhy would a powerful mage go to all this trouble? I'm inclined to say this is another plot of Kael'thas's, designed to cause more misery here. If there are blood elves here, they're likely to be hiding in the houses across the covered bridge.", objectives = "" }
WordHunterWoW_QuestEN[10317] = { title = "Dealing with the Foreman", description = "The blood elves call the mine underneath Manaforge Ara the Trelleum Mine.  Ever since they lost the one underneath Manaforge Ultris, this is where their sole supply of material for running the forges is coming from.\n\nNeedless to say, it would be a boon for us to cripple their mining operation.  Perhaps we'd even be able to move in and take it over for ourselves?\n\nWhatever the case, I want you to go in there and deal with Foreman Sundown.  The mine is around the back of the island to the left.", objectives = "" }
WordHunterWoW_QuestEN[10318] = { title = "Dealing with the Overmaster", description = "I used to be the foreman here.  But now that I've been demoted, I've come to realize our pilgrimage from Quel'Thalas to Outland was all a lie.\n\nA lie perpetrated by Kael'thas to strengthen his forces here in the Netherstorm.\n\nI've tried to convince my brethren that we should leave, especially with the Burning Legion here, but they are all too stubborn.\n\nDo me a favor?  Kill Overmaster Grindgarr.  Then return to your ethereal and tell him that I am no longer his enemy.", objectives = "" }
WordHunterWoW_QuestEN[10319] = { title = "Capturing the Phylactery", description = "I suppose an explanation is in order. You've met one of the archmage's apprentices, Ravandwyr, but there was also another named Naberius.\n\nHe was an ardent student, but was drawn to necromancy. When Kael'thas appeared with his forces, Naberius seized the opportunity to betray the archmage, handing over the secrets to the tower's defense.\n\nNow, it seems, he has become a lich. If we are to stop him, we must capture his phylactery. Knowing him, he would've buried it somewhere out of sight in his domain.", objectives = "" }
WordHunterWoW_QuestEN[10320] = { title = "Destroy Naberius!", description = "Archmage Vargoth saw the danger in Naberius's pursuit of necromancy, but I don't think he ever anticipated that his own apprentice would wreak this much destruction upon the Kirin Tor.\n\nYou must defeat him, {name}, or else he will continue enslaving the spirits of our fallen brothers, robbing them of their rightful rest and destroying what little remains of Kirin'Var.\n\nWith his phylactery in hand, he can be confronted by two or three combatants, but who knows what his magic might do to more foes?", objectives = "" }
WordHunterWoW_QuestEN[10321] = { title = "Shutting Down Manaforge Coruu", description = "Your success at B'naar has given us a great deal of hope, {name}.\n\nWe've shared our discoveries with the Scryers and in return they've given us more information on the remaining manaforges.\n\nThree other manaforges still stand, in full control of the Sunfury army.\n\nYou will find Manaforge Coruu to the east.  Overseer Seylanna holds the access crystal there.  Obtain it and use it on the manaforge's control console to begin the emergency shutdown.\n\nWe're all counting on you, {name}.", objectives = "" }
WordHunterWoW_QuestEN[10322] = { title = "Shutting Down Manaforge Duro", description = "We've received news from one of the two manaforges that remain operational.  The Sunfury army is losing control of Manaforge Duro.\n\nDroves of errant mana creatures have been attracted to it by its increased energy production - the manaforge is in chaos.\n\nAn explosion at Duro has the potential to cause a chain reaction that would endanger all of Outland.  Overseer Athanel is in possession of the access crystal you need to safely disable the manaforge.", objectives = "" }
WordHunterWoW_QuestEN[10323] = { title = "Shutting Down Manaforge Ara", description = "One manaforge is all that keeps Tempest Keep functional.  After we bring Manaforge Ara down, Kael will have to resort to depleting whatever energy he's got stored up.\n\nTravel to Manaforge Ara, in the northwest, and deliver the final blow that we need by shutting it down.\n\nThe last access crystal is in the possession of Overseer Azarad.  Be warned that we expect heavy opposition in the last of Kael's functional manaforges.  You're likely to need the assistance of reliable friends.", objectives = "" }
WordHunterWoW_QuestEN[10324] = { title = "The Great Moongraze Hunt", description = "Well done, {name}! Well done!\n\nNow that you've cut your teeth with the moongraze stag, it's time you graduated to more formidable prey. Do not allow the casual disinterest of the moongraze bucks to fool you: when provoked, they are a fearsome foe.\n\nYou'll find the bucks north of here. Good hunting.", objectives = "" }
WordHunterWoW_QuestEN[10325] = { title = "Marks of Kil'jaeden", description = "As you probably know, {name}, the Aldor are keepers of the Light and servants of the naaru.\n\nDiametrically opposed to us are the agents of the Burning Legion - demons bent on the destruction of worlds and the corruption of the innocent.\n\nIf you wish to prove yourself to the Aldor, bring me the insignias of low-ranking Legion and their Shadow Council followers.  We know of a Shadow Council hideout in the Bone Wastes and there are many Legion outposts in Nagrand and the Blade's Edge Mountains.", objectives = "" }
WordHunterWoW_QuestEN[10328] = { title = "Sunfury Briefings", description = "Something about these manaforges has been bothering me, {name}.  Naaru technology is incredibly advanced; it should've taken Kael'thas years to even begin to understand it.\n\nInformation-gathering on the subject has been difficult as Kael's army is well disciplined and destroys all evidence of written communication.\n\nWe've been informed Manaforge Duro is under attack by mana creatures.  It is possible that those defending it have not yet destroyed their briefings.  Obtain them and bring them to me.", objectives = "" }
WordHunterWoW_QuestEN[10329] = { title = "Shutting Down Manaforge B'naar", description = "I was having a friendly discussion with the Aldor while you were gone.  Manaforges sure look like modified naaru technology from Tempest Keep.  Apparently, most naaru constructs have certain safeguards that allow them to be permanently disabled in case of emergency.\n\nThe procedure is usually initiated at a control console via an access crystal.  Lo and behold, according to the roster you secured, such a crystal is in the possession of a fellow called Overseer Theredis.  Obtain it and see what you can do.", objectives = "" }
WordHunterWoW_QuestEN[10330] = { title = "Shutting Down Manaforge Coruu", description = "Thalodien told us of your success in disabling Manaforge B'naar.  He expects a repeat performance here and asked us to keep an eye out for anyone using a crystal to access the console inside.  Overseer Seylanna holds the access crystal, we're sure of it.\n\nGo back in there and finish the operation.  No need to be stealthy anymore; get the crystal, begin the shutdown, kill the technicians trying to stop you and get out.\n\nHurry, it won't be long before Kael's lapdogs sniff us out.", objectives = "" }
WordHunterWoW_QuestEN[10331] = { title = "Indispensable Tools", description = "You haven't seen a heavy smithing hammer lying around by chance, have you? I brought it out here with me to finish the shoes for some of old man Amorlin's horses, but I can't find it.\n\nI've searched the barn no less than a half dozen times and I just can't seem to find it. Maybe one of the other apprentices retrieved it and took it back to the smithy? Would you be willing to go down there and take a look? The workshop is to the southeast of the tower in the Town Square.", objectives = "" }
WordHunterWoW_QuestEN[10332] = { title = "Master Smith Rhonsus", description = "At last, my journeyman project is complete! I can't wait to formally present it to Master Rhonsus.\n\n<The apprentice looks at you as you describe your experiences retrieving the hammer.>\n\nThey attacked you? All of them? By the Light, they've gone mad!\n\nWhat are we to do, {name}? It grieves me to say so, but it may be necessary to kill Master Rhonsus. It would leave me as the only smith in Kirin'Var, but I believe my training is sufficient to serve the town's needs.", objectives = "" }
WordHunterWoW_QuestEN[10333] = { title = "Help Mama Wheeler", description = "Say, {name}, I was wondering if you could do me another favor.\n\nMy partner out in the field could probably use a hand.  I was wondering if you could go check in on her.\n\nI'm sure that Mama Wheeler will appreciate the help.  Just don't mind her sharp tongue.\n\nShe's trying to look out for our interests to the east.  You'll find her just inside Eco-Dome Midrealm at the Midrealm Post.", objectives = "" }
WordHunterWoW_QuestEN[10334] = { title = "Needs More Cowbell", description = "Where, oh where has my Bessy gone? After the attack, I searched the fields and the Chapel Yard for her, but she was nowhere to be seen!\n\nAll I have left of her is this old cowbell. She usually comes running when she hears it, but these feeble old bones probably couldn't shake it hard enough.\n\nI'll loan you Bessy's bell if you're willing to go out to the fields and ring it as hard as you can. Perhaps all Bessy's waiting for is a little more cowbell.", objectives = "" }
WordHunterWoW_QuestEN[10335] = { title = "Surveying the Ruins", description = "I have to get over to the Ruins of Farahlon to start my excavations!  The problem is that the place has been infested by demons!\n\nMaybe you could do some preliminary work for me?\n\nThere are three locations within the ruins to the northeast where I want you to place surveying markers.  Each is near a draenei banner.\n\nReturn to me when you've managed to place all three markers.", objectives = "" }
WordHunterWoW_QuestEN[10336] = { title = "The Minions of Culuthas", description = "A few weeks ago, the Burning Legion moved into the Ruins of Farahlon, thwarting our plans to excavate the site for its artifacts.\n\nThen earlier today, I learned that one of their dreadlords, Culuthas, somehow killed off all of the other Burning Legion.  He has since summoned in demons that serve him.\n\n{class}, I want you to go up to those ruins to the northeast and rid them of their demon infestation.", objectives = "" }
WordHunterWoW_QuestEN[10337] = { title = "When the Cows Come Home", description = "Realizing that Bessy is still staring at you, you gesture toward Thadell's location. You find yourself promising to protect the cow on her way home. Upon finishing your sentence, you realize there's no possible way the cow could understand anything you've said.\n\nShrugging your shoulders, you prepare to guard the bovine on her way back to Thadell.", objectives = "" }
WordHunterWoW_QuestEN[10338] = { title = "Shutting Down Manaforge Duro", description = "So Manaforge Duro is under attack and Sunfury forces have lost control?  What a dilemma!  If Duro goes down, then Tempest Keep goes down.  Only drawback is... if Tempest Keep is destroyed, the explosion will probably take what little remains of this forsaken land with it.\n\nDead Kael'thas is good.  Dead everyone else is... not that great, I suppose.  It pains me to ask this of you, but go to Manaforge Duro and shut it down before it goes up in flames.  The access crystal is held by Overseer Athanel.", objectives = "" }
WordHunterWoW_QuestEN[10339] = { title = "The Ethereum", description = "Directly south of here you will find the Ethereum Staging Grounds. The Ethereum are there, preparing for something... Perhaps an assault on Ultris.\n\nWe can't take any chances, though, {class}. Break through their perimeter defenses and take out their training facility.\n\nOnce you've destroyed their soldiers and Captain Zovax, locate Ethereum transponder Zeta and use it to establish contact with me to get your next set of orders.", objectives = "" }
WordHunterWoW_QuestEN[10340] = { title = "Shatter Point", description = "{name}, you've done a great job here at the front, and you showed a lot of talent with that armored gryphon... I think I have another mission in mind for you.\n\nThis new mission launches from Shatter Point -- an attack base the Wildhammers set up on a floating piece of land near the Portal.  It's a little unnerving there, but you have tough guts.  You'll be fine.\n\nTalk to Wing Commander Dabir'ee and have him send you to Shatter Point.  From there, report to the gryphon master Runetog Wildhammer.", objectives = "" }
WordHunterWoW_QuestEN[10341] = { title = "Kick Them While They're Down", description = "The news you've discovered is fortunate, {name}.  Not only do you get to waltz into Manaforge Duro unfettered, this also presents a great opportunity to deal a blow to Kael's army.\n\nUse the mana creature assault to your advantage and pick off any Sunfury stragglers you run into.\n\nI do not take particular glee in the senseless slaughter of my own kin the way that Thalodien does, but the tactical advantage here is too high to pass up.", objectives = "" }
WordHunterWoW_QuestEN[10342] = { title = "Securing the Shaleskin Shale", description = "I make a good living selling drinks to the boozehounds around here.  But I want something more!\n\nThe rocket-chief is always telling me how he can't perfect the rocket fuel needed to get the X-52 off of the ground.\n\nWe can solve that little problem for him.\n\nFor starters I need to extract the oil from the shale of the local shaleskin flayers!  It'll form a concentrated, if explosive, base for the mix that I have in mind.\n\nFind the flayers, and their shale, all over the place near the purple rocks.", objectives = "" }
WordHunterWoW_QuestEN[10343] = { title = "The Unending Invasion", description = "Kael'thas's assault on Kirin'Var began with thundering noise and a bright flash of light in the officer quarters to the northwest. The destruction there was the most severe and after the withdrawal of the blood elves, a strange thing began to happen.\n\nBeings of pure mana began streaming into the village from all over the area. For now, we're containing them as we can, but with more information about the weapon Kael'thas used, I hope to cut off the flow of mana creatures entirely.", objectives = "" }
WordHunterWoW_QuestEN[10344] = { title = "Wing Commander Gryphongar", description = "Wing Commander Gryphongar runs this outfit of Wildhammers.  If this is your first time to Shatter Point, then you should report to him.\n\nYou'll find him inside what's left of that tower over yonder.", objectives = "" }
WordHunterWoW_QuestEN[10345] = { title = "The Flesh Lies...", description = "You see these corpses, {race}? Arconus is responsible for this slaughter. He's sucked them dry, leaving nothing more than a fleshy husk. But don't let the bodies fool you! Inside those corpses lie flesh beasts, waiting to pounce on the unsuspecting fool that gets too close.\n\nI've got my orders. I must remain here until backup arrives. That doesn't mean that you can't take my igniter and destroy the withered corpses that litter the mines. One way or another, the mission must be completed.", objectives = "" }
WordHunterWoW_QuestEN[10348] = { title = "New Opportunities", description = "I hear that a group of 'druids' from Azeroth has taken quite an interest in the effects of our eco-dome technology.\n\nThe Cenarion Expedition's representatives are eager to get access to the plants growing within the domes, particularly one called the ivory bell, known for its healing properties. They're found in clumps of brush around larger plants in Eco-Dome Midrealm.\n\nI'll share the profits with you if you're willing to gather the herbs for my first delivery.", objectives = "" }
WordHunterWoW_QuestEN[10349] = { title = "The Earthbinder", description = "You should take the crystal lump over to the earthbinder.  She's just like you... always needing to get to the bottom of a mystery and thinking all of the time.\n\nIf you ask me, she thinks a little too much.\n\nJust give it to her and I'm sure that she'll get you into a heap of trouble figuring out what is going on up there on the ridge.", objectives = "" }
WordHunterWoW_QuestEN[10350] = { title = "Behomat", description = "While you have learned many hard lessons from me during our time together, it is time that I entrusted you to wiser hands.\n\nBehomat, who trained me when I was as green as grass, will be your new teacher. I have told him that you will be seeking him out, and he is expecting you.\n\nYou will find him at the center of the Warriors' Terrace, at the highest point of the Traders Tier of the Exodar.", objectives = "" }
WordHunterWoW_QuestEN[10351] = { title = "Natural Remedies", description = "It must be that the evil emanations from that giant crystal are summoning the mountain giants and driving them insane.\n\nIt's too big to move, and beyond our ability to destroy, but I know a way to quell its power.\n\nI've summoned a circle at the northwest corner of the crystal on the ridge.  Take this seed to the circle and channel its powers to heal the land through the natural forces of rain, growth and insect repopulation.\n\nBeware, {name}, I sense an external force at play here... this is not natural!", objectives = "" }
WordHunterWoW_QuestEN[10353] = { title = "Arconus the Insatiable", description = "Araxes and I were deployed to Ultris 2 days ago. Our mission: Find and terminate the void lord Arconus. We tracked him to this mine and discovered that he'd been feeding off the energies of the creatures in the area.\n\nA fire-fight broke out which resulted in Araxes and I separating. Now I'm stuck here, badly injured. The mission is in shambles!\n\nIf you can take out Arconus, high command would be grateful. Should you accept this mission, I will assist by providing a reflection of myself as a guardian.", objectives = "" }
WordHunterWoW_QuestEN[10355] = { title = "Withered Flesh", description = "We must determine how far the damage has spread. The basidium you brought me comes from a bog giant. Their larger, hardier cousins, the bog lords, should prove more resistant to the degeneration that's struck the giants.\n\nIt would be good to know how the changes in the Dead Mire have affected the other creatures out there, too.\n\nReturn to the Dead Mire and see if you can get samples from the bog lords and the hydra in the area.", objectives = "" }
WordHunterWoW_QuestEN[10365] = { title = "Shutting Down Manaforge Ara", description = "You've done much better than any of us anticipated.  Manaforge Ara is the last of Kael's working manaforges.  You'll find it northwest of here, though you're likely to have to do some circumnavigating to get to it.  We want you to shut it down.\n\nThe last access crystal is in the possession of Overseer Azarad.  This is Kael's very last source of energy as far as we know, so expect heavy opposition.  I'd bring a couple of friends along if I were you.\n\nHmm... Azarad.  What an odd name for a sin'dorei.", objectives = "" }
WordHunterWoW_QuestEN[10367] = { title = "A Traitor Among Us", description = "Anywhere you see a tribe of enslaved Broken you will also find a traitor.  A despicable being who sold his brothers for promises of power.\n\nThere is a hut at the top of the stairs in the center of the ruins.  That's the turncoat's hut.\n\nHe's not there right now, so you will be able to sneak in if you're patient.  Inside you will find a coffer with a key inside of it.  That key unlocks the chains that keep the Dreghood elders prisoner.  Bring it to me.\n\nBeware, Arzeth the Merciless wanders nearby.", objectives = "" }
WordHunterWoW_QuestEN[10368] = { title = "The Dreghood Elders", description = "The Dreghood spirit is broken because our elders are imprisoned.  Take this key and go downstairs to free them.\n\nThey are Morod the Windstirrer, Akoru the Firecaller and Aylaan the Waterwaker.  Once they are free, the spirits will return to the Dreghood tribe.", objectives = "" }
WordHunterWoW_QuestEN[10369] = { title = "Arzeth's Demise", description = "Yes, the elemental spirits have returned to us!  We are not as strong as we once were, but a little magic can go a long way in the right hands.\n\nArzeth has great powers bestowed upon him by his dark lord.  Take this staff.  It was once a great symbol of our tribe.  Use it against Arzeth and his powers will be temporarily removed from him.  Defeat him then, so that my people may finally be free!", objectives = "" }
WordHunterWoW_QuestEN[10375] = { title = "Obsidian Warbeads", description = "You've proven yourself to our people, {name}.  Now is time for you to show us that you're willing to stand by us, even in the face of the strongest enemy.\n\nThe ogres of Outland are ", objectives = "" }
WordHunterWoW_QuestEN[10380] = { title = "A Dark Pact", description = "We've been so blind, {name}, that the alliance of two of our most dangerous enemies went completely unnoticed.\n\nI wouldn't be surprised if the Scryers had something to do with hiding this information from us, but we must now face the reality.  The Burning Legion and Kael'thas' Sunfury army serve under the same banner.\n\nThese demons are the only reason Kael'thas was ever able to utilize the technology in Tempest Keep.  Under Orelis's orders I must command you to destroy them.", objectives = "" }
WordHunterWoW_QuestEN[10381] = { title = "Aldor No More", description = "My mission here is finished.  I did what Orelis ordered me to - I've never failed to.\n\nNo more.  I foresee a great carnage - a crusade, they'll call it - following the news of this alliance between Kael'thas and the Burning Legion.\n\nFirst they give our holiest city away to our enemies and then they ask us to die fighting their enemies.  Go back to Orelis; tell him the naaru can fight their own fights from now on.", objectives = "" }
WordHunterWoW_QuestEN[10382] = { title = "Go to the Front", description = "Well, {name}, I hope you're prepared for the next phase of our operation. The Legion never rests - and neither shall we! Take a gryphon and fly over to Honor Point - it's a small post near the Legion Front. \n\nSpeak with Field Marshal Brock. He'll have instructions for you when you arrive. Oh, and tell that pasty-faced shield-kisser I said 'hello'.  \n", objectives = "" }
WordHunterWoW_QuestEN[10384] = { title = "Ethereum Data", description = "Look around you, fleshling. Very close to this transponder should be an Ethereum data cell. Locate that data cell, open it, and retrieve the contents.\n\nBring it back to this transponder at once!", objectives = "" }
WordHunterWoW_QuestEN[10385] = { title = "Potential for Brain Damage = High", description = "They're using relays to transfer information around the staging grounds.\n\nThere is only one way for you to see these relays and extract the information they hold. Unfortunately, doing so may cause you irreparable brain damage.\n\nIf you're still interested, you'll need to slay Ethereum here at the staging grounds and take their essences. Once you have an essence, drink it down. It will temporarily allow you to see an Ethereum relay, giving you enough time to destroy a relay and extract its information.", objectives = "" }
WordHunterWoW_QuestEN[10388] = { title = "Return to Thrallmar", description = "Hope you enjoyed your flight, friend. A messenger arrived while you were away - seems Nazgrel's got a new use for you. You'd best head back to Thrallmar and check in with him. I have a feeling the Legion's just getting warmed up. \n", objectives = "" }
WordHunterWoW_QuestEN[10389] = { title = "The Agony and the Darkness", description = "Greetings, {name}. I've deciphered the Legion missive and uncovered the demons' strategic plans for this Peninsula. Apparently, there is a large group of hellish terrorfiends gathering near the Pools of Aggonar in the west. We cannot allow such a force to go unchallenged. You must go there and decimate their cursed numbers. ", objectives = "" }
WordHunterWoW_QuestEN[10390] = { title = "Forge Camp: Mageddon", description = "{name}, we have reason to believe that the easternmost forge camp is not yet complete. The Legion's gan'arg servants are working 'round the clock to get the facility up and running. We can't allow that to happen. \n\nHead east to Forge Camp: Mageddon and slay 10 gan'arg. Bring me the head of their master - Razorsaw - and the Legion's fel reaver production will grind to a halt!   \n\n", objectives = "" }
WordHunterWoW_QuestEN[10391] = { title = "Cannons of Rage", description = "There is a second production facility, Forge Camp: Rage, that lies to the immediate northeast of Thrallmar. The demons have positioned a number of their fel cannons along the ridge - and they're aimed straight at us! You must enter the camp and destroy these fel cannons. \n\n{name}, you must be sure to detonate them all - or nothing will stop the Legion from raining fiery hell down upon our heads!  \n", objectives = "" }
WordHunterWoW_QuestEN[10392] = { title = "Doorway to the Abyss", description = "You are an honor to us, {name}. But now we must strike before the Legion recovers! To the north of Thrallmar lies Invasion Point: Annihilator. It houses a warp-portal through which the Legion draws its reinforcements. \n\nYou must overload that portal - and blast it back to the abyss it came from. The portal's activation key will be held by the Point's commander - Warbringer Arix'Amal. Slay him. Take the key. Use it on the portal and do what must be done. May the warchief's blessings be with you.   ", objectives = "" }
WordHunterWoW_QuestEN[10393] = { title = "Vile Plans", description = "The text on the note is written in some dark, indecipherable scrawl. The more you stare at them, the more the symbols seem to twist and burn before your eyes. There is only one in Thrallmar that can transcribe such vile script - the blood elf Magister Bloodhawk. \n\n", objectives = "" }
WordHunterWoW_QuestEN[10394] = { title = "Disruption - Forge Camp: Mageddon", description = "Pay close attention, {name}. We've been surveying the Legion camps that lie along the ridge ahead. We have reason to believe that these so-called 'Forge Camps' are where the demons are constructing those blasted Fel Reavers. \n\nYou can see the closest target, Forge Camp: Mageddon, to the west. Our intelligence suggests that it's still under construction. If you can slay the Gan'arg Servants and their master - Razorsaw - we can bring the Legion's Fel Reaver production to a grinding halt!   \n\n", objectives = "" }
WordHunterWoW_QuestEN[10395] = { title = "The Dark Missive", description = "The text on the note is written in some dark, indecipherable scrawl. The more you stare at them, the more the symbols seem to twist and burn before your eyes. There is only one at Honor Hold who can decipher such archaic script - the draenei mystic, Kryv. \n\nTake the Burning Legion Missive to Warp-Scryer Kryv who resides within the War-Room at Honor Hold.\n", objectives = "" }
WordHunterWoW_QuestEN[10396] = { title = "Enemy of my Enemy...", description = "Now we focus on the second target - Forge Camp: Rage. It lies just west of Mageddon. Trouble is, the demons have a number of fel cannons aimed straight at the Horde's outpost of Thrallmar! Though I can scarcely believe it, we actually need the Horde to help us hold the line at the Dark Portal. We can't afford to let Thrallmar fall.  You've got to destroy these cannons before the Legion pulverizes our allies! ", objectives = "" }
WordHunterWoW_QuestEN[10397] = { title = "Invasion Point: Annihilator", description = "Well, we've located the Legion's final base on the ridge - Invasion Point: Annihilator. It lies northwest of Forge Camp: Rage - and it houses a warp-portal through which the Legion has been drawing its reinforcements! \n\nYou've got to close that portal to prevent any more demons from coming through. The Point's overlord, Warbringer Arix'Amal, holds the portal's activation key. Take it from him and shut that blasted gateway down!  \n", objectives = "" }
WordHunterWoW_QuestEN[10399] = { title = "The Heart of Darkness", description = "It is just as I feared. Arix'Amal - the demon you killed earlier, was working for a secret Legionlord - Arazzius the Cruel. It appears this new villain has amassed a force of hellish terrorfiends near the Pools of Aggonar. \n\nYou must journey there and slay the terrorfiends before they strike against us. But be wary, friend - the Pools of Aggonar lie within a tortured, poisonous valley. You can find the cursed pools to the northwest of here, beyond Hellfire Citadel. \n\nLight be with you, {name}.  \n", objectives = "" }
WordHunterWoW_QuestEN[10400] = { title = "Overlord", description = "The honorable Warp-Scryer has told me of your perils, {name} - and of the new foe you've discovered. If Kryv is to be believed, this 'Arazzius the Cruel' is as powerful and evil as any foe the Sons of Lothar have ever faced. \n\nWill you stand for us now, {name}? Will you face this Legionlord and deliver the Light's justice upon him? If so, you will find him at the Pools of Aggonar. If not, his evil will most certainly find you. \n", objectives = "" }
WordHunterWoW_QuestEN[10403] = { title = "Naladu", description = "Perhaps not all hope is lost for the Dreghood.  I am one of four elders that guided this tribe before we were enslaved by the Illidari.  I thought the others were dead, but I've slowly learned that at least two others are alive - chained down and powerless just as I am.\n\nI've not yet been able to find Naladu and fear for the worst.  There are more huts in the ruins upstairs; perhaps you could look for him.  It would be a great boon for our tribe if all our elders were alive.", objectives = "" }
WordHunterWoW_QuestEN[10405] = { title = "S-A-B-O-T-A-G-E", description = "We must destroy the machinery that is making these nexus-stalker aberrations possible. To strike at their proto-accelerator would be futile as it is an ethereal creation. We must instead destroy the manaforge energy tube that they are using as a conduit.\n\nI have all that I need to create a device to overload the conduit save for one item. I need a wrapping from an archon or overlord that might be transforming soon in order to calibrate the device.", objectives = "" }
WordHunterWoW_QuestEN[10406] = { title = "Delivering the Message", description = "I'm sending one of my demolitionists out to place the disruption device. Just make sure no harm comes to him as he's placing the disruptor.\n\nKeep him protected! He will not fight back if enemies attack him, as he is only a holographic image, but the image can be destroyed!\n\nReturn to me once the job is done.", objectives = "" }
WordHunterWoW_QuestEN[10407] = { title = "Socrethar's Shadow", description = "The infamous eredar, Socrethar, leads the Burning Legion in Netherstorm.  Mentioning his name is enough to make most draenei shudder.  He gives orders from an island in the northwest that only his most trusted lieutenants can access.\n\nTo get there you will need to obtain a teleportation stone, which won't be an easy task.  The first half of the stone is in the possession of Forgemaster Morug at Forge Base: Oblivion.  The second half is held by Silroth at Forge Base: Gehenna.", objectives = "" }
WordHunterWoW_QuestEN[10408] = { title = "Nexus-King Salhadaar", description = "I have in my possession another disruptor--one capable of destroying the three conduits that surround Salhadaar. Once the conduits are destroyed, Salhadaar's protective force fields will be down. For this act, he will strike at you with a ferocity you have never before witnessed, {name}.\n\nIf you are willing to rid the world of Salhadaar, I will give you the disruptor.", objectives = "" }
WordHunterWoW_QuestEN[10409] = { title = "Deathblow to the Legion", description = "When facing eredar of great power, large armies are useless for the most part.  Their corruptive powers over mortal souls are such that only the strongest-willed can even stand face to face with them.\n\nTake this stone to the Invasion Point: Overlord, between Forge Base: Oblivion and Gehenna and bring your closest, strongest friends with you.  Orelis and Karja will meet you at Socrethar's Seat; I will send Adyen along with them.\n\nMay the Light prevail today, {name}.  May Socrethar meet his end.", objectives = "" }
WordHunterWoW_QuestEN[10410] = { title = "Ishanah's Help", description = "The time has come to face Socrethar, {name}.  Confronting an eredar leader isn't something that's taken lightly among us.  A single mistake is likely to cost us our lives if we're ill-prepared.\n\nTake Socrethar's teleportation stone to High Priestess Ishanah at the Shrine of Unending Light in Shattrath City.  She will determine how we need to handle the situation.", objectives = "" }
WordHunterWoW_QuestEN[10411] = { title = "Electro-Shock Goodness!", description = "Around the ruined manaforge you will find the run-off of Dimensius's handy work. Seeping sludge occupies the pools that surround Ultris. Directly below those pools, where the Ethereum Staging Grounds now stand, you will find even more run-off in the form of void waste.\n\nThe best method of disposal is to use electro-shock to break slimes down to globules. Use this elixir to augment your attacks with electricity. The resultant discharge will break the slimes up into their raw form. Destroy the globules!", objectives = "" }
WordHunterWoW_QuestEN[10412] = { title = "Firewing Signets", description = "It is no secret that Kael'thas Sunstrider perceives us as a great threat.  Let's face it - not many sin'dorei, fresh from Silvermoon, are willing to join the sort of company that Kael keeps.\n\nIt's also no secret that this is not just a war of words.  Scryers and the armies that serve Kael'thas attack each other on sight.  The only way to prove you're with us, {name}, is to do your share of fighting.\n\nKael's lower ranking followers wear Firewing signets to indicate their rank.  Bring them to me.", objectives = "" }
WordHunterWoW_QuestEN[10413] = { title = "The Horrors of Pollution", description = "You carefully fill a vial with the fallen void horror's ooze.\n\nResearcher Navuud at the Protectorate Watch Post would be quite interested in such a find! Take it to him at once!", objectives = "" }
WordHunterWoW_QuestEN[10416] = { title = "Synthesis of Power", description = "Arcane tomes are not ordinary books that happen to deal with arcane matters.  There is intrinsic power in them - a power I've learned to synthesize into a single arcane rune.\n\nShould you find an arcane tome in your travels I will give you one such rune.  Only the most powerful wielders of magic carry the books I need.  In Outland this usually means Kael's blood elves - but you'd be surprised by where such tomes often turn up.", objectives = "" }
WordHunterWoW_QuestEN[10417] = { title = "Run a Diagnostic!", description = "Wherever the Consortium establishes a presence, we bring our eco-dome technology. The fields allow us to work in a controlled and life-sustaining atmosphere since we often find ourselves in hostile environments.\n\nNetherstorm's volatile conditions and creatures have begun to destroy the equipment that sustains our domes, especially the generator east of here. I've started a diagnostic there in hopes of understanding what can be done to combat the damage. Would you collect the results and bring them to me?", objectives = "" }
WordHunterWoW_QuestEN[10418] = { title = "Deal With the Saboteurs", description = "In searching the area for clues about the damage to our equipment, I've seen pieces of the shield generators at the bottom of the small lake to the north. I'm not sure why the crocolisks have taken an interest in the equipment, but we have to put a stop to this problem.\n\nThe Consortium is quite clear on this matter. If it comes down to a choice between the equipment and crocolisks, the animals will have to go. I'll make it worth your while to deal with them.", objectives = "" }
WordHunterWoW_QuestEN[10420] = { title = "A Cleansing Light", description = "This temple is one of the holiest places in all of Outland.  The power of the Light here is so strong, that even items with the strongest fel taint can be cleansed of a worldly item.\n\nShould you run into any fel armaments in your confrontations with demonic enemies, bring them to me and I will demonstrate the cleansing power of the Light.", objectives = "" }
WordHunterWoW_QuestEN[10422] = { title = "Captain Tyralius", description = "Captain Tyralius took a platoon of soldiers south towards the Ethereum Staging Grounds 10 days ago. We haven't heard from him or his crew since.\n\nChances are good that they were ambushed and killed but I'm getting a curious reading from my instruments.\n\nI think it's a distress signal but these things have been wrong before. If Tyralius is still alive, they're keeping him in one of their prisons. You'll have to locate the prison and open it with a key, probably found on the warden.", objectives = "" }
WordHunterWoW_QuestEN[10423] = { title = "To the Stormspire", description = "Master Engineer Ghabar will want to know about the results of the diagnostics. If anything, they caution us to keep a close eye on the workings of our dome generators. As the fields become more and more unstable, their effects will become harder to control. It could spell disaster for our expedition and anything else housed within the domes.\n\nYou'll find Ghabar at the Stormspire. Just follow the road north from this eco-dome and across the bridge. It'll lead you to the elevator at the base of the spire.", objectives = "" }
WordHunterWoW_QuestEN[10424] = { title = "Diagnosis: Critical", description = "If Mehrdad's results are correct -- and I have no reason to believe they're faulty -- then the rest of the domes could be in trouble.\n\nI do think Mehrdad has failed to identify the underlying cause of the failures. From time to time, creatures damage the generators, but never this severely.\n\nTo be on the safe side, I'd like for you to run a set of diagnostics at the Stormspire's main dome generator, located in Eco-Dome Sutheron at the very eastern edge of the dome.", objectives = "" }
WordHunterWoW_QuestEN[10425] = { title = "Escape from the Staging Grounds", description = "Thank K'aresh! He would have torn me apart!\n\nI'm a Protectorate soldier, fleshling. My platoon was sent on a recon mission about 10 days ago. As we were moving across the upper ledges of this island, a group of Ethereum jumped us. At least I think it was Ethereum. They had the same energy color but their wrappings looked void.\n\nOnly Tyralius was spared. I think they put him in a prison cell.\n\nI've got to get back to the Protectorate Watch Post! Can you escort me back?\n", objectives = "" }
WordHunterWoW_QuestEN[10426] = { title = "Flora of the Eco-Domes", description = "Just look around you, {class}! Isn't it amazing? Of course, this incredible resurgence of life is a byproduct of the ethereal domes, but imagine what it could do in the hands of the expedition.\n\nI'm preparing to negotiate with the ethereals for access to their technology, but I'd like to get a better idea of its effects on plant-based life.\n\nI've built a device to concentrate the dome's energies on the lashers in this area. Would you be so kind as to test it for me and share the results?", objectives = "" }
WordHunterWoW_QuestEN[10427] = { title = "Creatures of the Eco-Domes", description = "Your work with the lashers turned up some astounding information, but I wonder if it holds true for animals as well.\n\nGathering information on the talbuks that live underneath this dome is going to be trickier than studying the lashers, I'm afraid.\n\nUsing this tagging device, you can put a weakened talbuk to sleep and apply a tag that I'll use to track the animal as it matures. The tagging mechanism won't work unless the talbuk has expended most of its energy.", objectives = "" }
WordHunterWoW_QuestEN[10428] = { title = "The Missing Fisherman", description = "In the fevered dreams of our injured guest, she spoke of a fisherman, Cowlen, who was in some distress at Silvermyst Isle, to the southwest, off the coast of Azuremyst.\n\nWith all that has been happening, no one has had the opportunity to look into it, but I do feel a bit of worry. Perhaps there's something you can do, {name}?", objectives = "" }
WordHunterWoW_QuestEN[10429] = { title = "When Nature Goes Too Far", description = "The dome technology possesses such power! Certainly, there are bounds beyond which we dare not go, {name}.\n\nCreatures allowed to grow too large or too fast could be just as bad as a barren landscape.\n\nI have heard rumors of just such a creature in the pool to the east. I've heard the ethereal merchants conspiring to catch the overgrown hydra for sport, but I have another purpose in mind for the giant. Bring me the creature's heart so I may study it.", objectives = "" }
WordHunterWoW_QuestEN[10430] = { title = "Testing the Prototype", description = "I've been working on a portable generator repair kit for use in some of the harsher climates that the Consortium operates in. Granted, it wasn't designed for Netherstorm, but we shouldn't have any problems with it.\n\nI had already scheduled a test with one of my best techs up at Eco-Dome Farfield beyond the Netherstone to the northeast. Take this prototype to Tashar. He'll know what to do with it. If it works, we can use it to reinforce the shield generators at the larger domes.", objectives = "" }
WordHunterWoW_QuestEN[10431] = { title = "Outside Assistance", description = "The Sunfury briefings support the theory that Kael'thas has been receiving outside help in constructing and running these manaforges.  Who this is remains a bit of a mystery, though we're likely to find out in Manaforge Ara.\n\nI've sent a group of my men to scout the surrounding area.  Go to Tuluman's Landing, north of here, and speak to Kaylaan.  See what he's discovered at Manaforge Ara.  Find out who is assisting the Sunfury army and take care of them. ", objectives = "" }
WordHunterWoW_QuestEN[10432] = { title = "Damning Evidence", description = "As you may have noticed, there are servants of the Burning Legion all over Manaforge Ara.  Kael'thas has entered an alliance with the Burning Legion.  He must've caught wind of Illidan's descent into insanity and switched paymasters accordingly.\n\nIf the Scryers get definite proof of this, it will give them a considerable political advantage.  I know for a fact that the Legion forces at this manaforge have orders that bear Kael's seal.\n\nGet these orders and bring them to Thalodien.", objectives = "" }
WordHunterWoW_QuestEN[10433] = { title = "Keeping Up Appearances", description = "The ethereals are clever and very observant, so it's no accident that I'm here posing as a simple furrier. In fact, I've been sent from Area 52 to appraise the technology the ethereals use to generate their eco-domes.\n\nI'd like to enlist your help, {class}. We've been asked to use non-goblin agents whenever possible.\n\nWhat I want you to do is bring me a number of ripfang lynx pelts in the guise of a hunter. You can find the lynxes all over Eco-Dome Midrealm.", objectives = "" }
WordHunterWoW_QuestEN[10434] = { title = "The Dynamic Duo", description = "Excellent job.\n\n<Shauly winks at you.>\n\nI think they're buying it. Now, when I send you up to speak with my associates at the Stormspire, there won't be any suspicion at all.\n\nYou'll want to look for Action Jaxon and Audi the Needle up there. They'll tell you everything you need to know. Tell 'em Shauly sent you.", objectives = "" }
WordHunterWoW_QuestEN[10435] = { title = "Retrieving the Goods", description = "<Audi looks around and then lowers her voice.>\n\nI'm sure Shauly told you a bit about our work here. When Jaxon and I are out in the field 'hunting,' we've been collecting pieces of the ethereal eco-dome generators and hiding them in the nests of our prey, the raptors in Eco-Dome Farfield.\n\nIt's a remote area to the northeast of the Stormspire, close to the Netherstone. I don't anticipate you'll run into many ethereals there, but would you be willing to help us collect the dome generator pieces?", objectives = "" }
WordHunterWoW_QuestEN[10436] = { title = "All Clear!", description = "Before we can begin the test, we have to make certain the area is clear of anything that might interfere. In our case, that means these overgrown lizards.\n\n<Tashar gestures toward the scythetooth raptors.>\n\nThere's no telling what might happen if one of those decides to take a nice bite out of the generator while it's charging. I've seen a lot of strange things in all my years as a technician, including more than a few abominations that had their beginnings as humble animals.", objectives = "" }
WordHunterWoW_QuestEN[10437] = { title = "Recipe for Destruction", description = "Atop Manaforge Ultris lies the tear in the nether that Void Lord Dimensius came through. That tear provides Dimensius with a link to the Void, rendering him immune to physical harm. If we can get a lock on the conduit that Dimensius is using to keep himself phased out of this plane of existence, we can destroy it and then destroy Dimensius.\n\nTo do this, we're going to first need you to collect fragments of Dimensius from the void creatures that he sends out to do his dirty work.", objectives = "" }
WordHunterWoW_QuestEN[10438] = { title = "On Nethery Wings", description = "Here it is, {name}. Take this phase disruptor and mount up! The Protectorate nether drake will fly you close enough to Ultris so that you can drop the disruptor on top of the void conduit.\n\nDrop as many disruptor charges as possible to ensure complete annihilation!\n\nWhen you are ready, speak with the nether drake and he'll take you up.\n\nIf you miss the mark you will have to get more bombs from me before you can go up again.", objectives = "" }
WordHunterWoW_QuestEN[10439] = { title = "Dimensius the All-Devouring", description = "Your brave actions have forced Ameer to react! He has deployed Captain Saeed and the Avengers!\n\nNow all that is left to do is destroy Dimensius.\n\nWhen you are ready, I will call for Saeed. If he is not currently fighting another battle, he will be awaiting orders from you directly east of here.\n\nLet him know when you are ready to fight and he will put his troops in motion!\n\nI wish you luck, fleshling! We have hunted Dimensius for a thousand years!", objectives = "" }
WordHunterWoW_QuestEN[10440] = { title = "Success!", description = "The test was a resounding success! We can certainly use this device to start repairing the domes.\n\nCarry word of the test results to the Stormspire and let Ghabar know that I've also found a pattern in the damage to the shield generators. Key pieces of generator units have gone missing from a number of sites. This is no accident, {name}, no technological failure. We're being stolen from. ", objectives = "" }
WordHunterWoW_QuestEN[10441] = { title = "Peddling the Goods", description = "<Audi lowers her voice again.>\n\nNow that we have the goods, I'll be sending most of the parts on to Area 52. There's enough here for more than one generator, presenting us with a perfect business opportunity.\n\nI've seen the Cenarion Expdedition's representative trying to negotiate. I want you to let her know that we can provide what she seeks at a very reasonable price. There's no reason for her to continue dealing with those two-timing ethereals.", objectives = "" }
WordHunterWoW_QuestEN[10442] = { title = "Helping the Cenarion Post", description = "{class}, there's some tauren by the name of Thiah Redmane that keeps pestering us for assistance.  She's with the Cenarion Expedition, and they've setup a little post just to the west on the south side of the road leading to Zangarmarsh.\n\nIf you hit Thornfang Hill, you've gone too far.\n\nDo you think you might head over there and see what she needs?  I don't want to have to bother Ranger Captain Venn'ren with such trivialities.", objectives = "" }
WordHunterWoW_QuestEN[10443] = { title = "Helping the Cenarion Post", description = "The Cenarion Circle has sent an expedition to Outland and, as I understand it, they are here to study what has happened and to help reverse any damage that they can.\n\nThey've setup a little post just to the west on the south side of the road leading to Zangarmarsh.\n\nIf you hit Thornfang Hill, you've gone too far.\n\nWould you please go and see how you might help them?  Speak with Thiah Redmane as she is the one that sent the request to us for assistance.", objectives = "" }
WordHunterWoW_QuestEN[10444] = { title = "Report to the Allerian Post", description = "This calls for immediate action!\n\nWe have someone out in the field closer to Firewing Point that I want you to speak with.  He'll have a better idea of what our next step should be.\n\nReport to Lieutenant Meridian out at the Allerian Post and apprise him of the situation.  You'll find the post to the northeast on the southern bank of the river just south of Firewing Point.\n\nGodspeed, {name}.", objectives = "" }
WordHunterWoW_QuestEN[10445] = { title = "The Vials of Eternity", description = "Seven vials were drawn from the Well of Eternity by Illidan.  He poured three into the lake on top of Mount Hyjal and a second Well of Eternity was created.  For years the rest were believed lost.\n\nWith the opening of the Dark Portal, we've come to know that he gave one each to his lieutenants Kael'thas and Vashj.  Retrieve what remains of them; we will need them as foci to open a gateway to any events tied to Mount Hyjal, recent or ancient.  The outcome of the Battle of Mount Hyjal must be preserved.", objectives = "" }
WordHunterWoW_QuestEN[10446] = { title = "The Final Code", description = "They're building a second mana bomb in the courtyard.  My intel suggests that the final code for the bomb is being held by Sharth Voldoun, the overseer of the project at Firewing Point.\n\n{name}, you have to go back in there and retrieve the final code from him.  He keeps himself to the top of the highest spire.\n\nTake the final code to the mana bomb that they're working on in the central courtyard and set it off.\n\nOnly then will we be certain that the Allerian Stronghold is safe.", objectives = "" }
WordHunterWoW_QuestEN[10447] = { title = "The Final Code", description = "They're building a second mana bomb in the courtyard.  My intel suggests that the final code for the bomb is being held by Sharth Voldoun, the overseer of the project at Firewing Point.\n\n{name}, you have to go back in there and retrieve the final code from him.  He keeps himself to the top of the highest spire.\n\nTake the final code to the mana bomb that they're working on in the central courtyard and set it off.\n\nOnly then will we be certain that Stonebreaker Hold is safe.", objectives = "" }
WordHunterWoW_QuestEN[10448] = { title = "Report to Stonebreaker Camp", description = "This calls for immediate action!\n\nWe have someone out in the field closer to Firewing Point that I want you to speak with.  She'll have a better idea of what our next step should be.\n\nReport to Sergeant Chawni out at Stonebreaker Camp and apprise her of the situation.\n\nTake the road north out of the hold.  From the middle of Tuurem, follow the road to the east.  You'll find the camp on the bank of the river that lies just southwest of Firewing Point.\n\nGood luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[10449] = { title = "Apothecary Zelana", description = "Apethecary Zelana has been studying the beasts of Hellfire Peninsula in the field.  She wants a sample of the blood you gathered; with luck, she might discover what turned those Bonechewer freaks' skins red!\n\nZelana is at Reaver's Fall, southeast of Thrallmar.  Follow the road east and when you see a destroyed, green-glowing hunk of metal, you're there.  She has a camp set up behind the wyverns.", objectives = "" }
WordHunterWoW_QuestEN[10450] = { title = "Bonechewer Blood", description = "Bonechewers!  They should all die!  The sight of their red skin and depravity makes my blood boil!\n\nI have a mission for you, {name}.  Kill Bonechewer orcs and collect their vile blood.  There is an apothecary who needs the blood for her tests, so we can discover how these orcs fell to the demon taint, a taint from which we so recently freed ourselves.\n\nBonechewers scavenge near the ruined battlements along the Path of Glory, to the south.  Return to me when your mission is complete.", objectives = "" }
WordHunterWoW_QuestEN[10451] = { title = "Escape from Coilskar Cistern", description = "Thank the Earthmother! I parted ways with the others several days ago. I was intent on discovering the source of the disturbance that the spirits of water were feeling. My search led me to Coilskar where I discovered that the naga were befouling the water supply of Shadowmoon Valley.\n\nUnfortunately, I was discovered and taken prisoner. There's no telling what ghastly things they had in store for me.\n\nWe must leave this place! Help me escape and then seek out Torlok at the Altar of Damnation.\n", objectives = "" }
WordHunterWoW_QuestEN[10455] = { title = "The Encroaching Wilderness", description = "We've been growing the Living Grove at an accelerated rate, but somehow the lynxes there have become lost to our control.\n\nWhere once their population was stable, the grovestalker lynxes are now beginning to encroach upon Sylvanaar, and there have been a number of unpleasant incidents of late.\n\nI suspect that the arakkoa of Veil Lashh are somehow behind it, but the immediate issue is with the lynxes themselves.\n\nI would be most grateful if you would help us to deal with this situation.", objectives = "" }
WordHunterWoW_QuestEN[10456] = { title = "Marauding Wolves", description = "The filthy races of the Horde have taken over a settlement to the east.  They've brought with them a large pack of the dire wolves that they prefer to use as mounts and sentries.\n\nThese sentries have been marauding across the bridge that separates us.  They've been stalking our fey drakes, which are critical to the pollination of the Living Grove.\n\nUse the east exit to traverse the bridge over Bloodmaul Ravine that leads to the Jagged Ridge to the east, and bring me their tails as proof!", objectives = "" }
WordHunterWoW_QuestEN[10457] = { title = "Protecting Our Own", description = "Though you've done a great deal of good work in defense of our new home here, I still feel that the Living Grove needs more protection.\n\nPlease, take this small tree bough that I have imbued with the force of nature.  When used upon the seedlings that I have planted out in the grove, it will call down a storm to accelerate the growth of a treant defender.\n\nThese treants are critical to the defense of the grove, especially if you choose not to make Sylvanaar your home for long.", objectives = "" }
WordHunterWoW_QuestEN[10458] = { title = "Enraged Spirits of Fire and Earth", description = "We must try and make amends. We must commune with the elements of this region and see if anything can be done!\n\nI grant you the totem of spirits, {race}. If you slay an enraged elemental spirit in close proximity of the totem, it will consume the elemental's soul. You must use the totem to consume many souls before you may return to me.\n\nDo this for the spirits of fire and earth first. Return to me when the totem is full.", objectives = "" }
WordHunterWoW_QuestEN[10459] = { title = "Revered Among the Cenarion Expedition", description = "We've taken notice of your accomplishments, {name}.  What you've done for us goes beyond what we expect from our allies.\n\nI've a special request to ask of you, but I must test your dedication first.", objectives = "" }
WordHunterWoW_QuestEN[10460] = { title = "Defender's Pledge", description = "", objectives = "" }
WordHunterWoW_QuestEN[10461] = { title = "Restorer's Pledge", description = "", objectives = "" }
WordHunterWoW_QuestEN[10462] = { title = "Champion's Pledge", description = "", objectives = "" }
WordHunterWoW_QuestEN[10463] = { title = "Sage's Pledge", description = "", objectives = "" }
WordHunterWoW_QuestEN[10464] = { title = "Sage's Vow", description = "You've made your pledge, {class}.  Now it is up to you to see it through.\n\nServe the Scale of the Sands well and you will be rewarded.\n\nFail and the timeline as we know it will be unravelled!", objectives = "" }
WordHunterWoW_QuestEN[10465] = { title = "Restorer's Vow", description = "You've made your pledge, {class}.  Now it is up to you to see it through.\n\nServe the Scale of the Sands well and you will be rewarded.  Fail and the timeline as we know it will be unravelled!", objectives = "" }
WordHunterWoW_QuestEN[10466] = { title = "Champion's Vow", description = "You've made your pledge, {class}.  Now it is up to you to see it through.\n\nServe the Scale of the Sands well and you will be rewarded.  Fail and the timeline as we know it will be unravelled!", objectives = "" }
WordHunterWoW_QuestEN[10467] = { title = "Defender's Vow", description = "You've made your pledge, {class}.  Now it is up to you to see it through.\n\nServe the Scale of the Sands well and you will be rewarded.  Fail and the timeline as we know it will be unravelled!", objectives = "" }
WordHunterWoW_QuestEN[10468] = { title = "Sage's Oath", description = "You've carried out the promise you made to us, {name}.  And for that you've gained the recognition you deserve.\n\nAs you continue to become attuned with past events surrounding mount Hyjal, I can continue to tap into the power contained in your ring.  It won't be long until it has reached its full potential.", objectives = "" }
WordHunterWoW_QuestEN[10469] = { title = "Restorer's Oath", description = "You've carried out the promise you made to us, {name}.  And for that you've gained the recognition you deserve.\n\nAs you continue to become attuned with past events surrounding mount Hyjal, I can continue to tap into the power contained in your ring.  It won't be long until it has reached its full potential.", objectives = "" }
WordHunterWoW_QuestEN[10470] = { title = "Champion's Oath", description = "You've carried out the promise you made to us, {name}.  And for that you've gained the recognition you deserve.\n\nAs you continue to become attuned with past events surrounding mount Hyjal, I can continue to tap into the power contained in your ring.  It won't be long until it has reached its full potential.", objectives = "" }
WordHunterWoW_QuestEN[10471] = { title = "Defender's Oath", description = "You've carried out the promise you made to us, {name}.  And for that you've gained the recognition you deserve.\n\nAs you continue to become attuned with past events surrounding mount Hyjal, I can continue to tap into the power contained in your ring.  It won't be long until it has reached its full potential.", objectives = "" }
WordHunterWoW_QuestEN[10472] = { title = "Sage's Covenant", description = "Your accomplishments have gone beyond my greatest expectations, {name}.\n\nYou step in and out of time as comfortably as any bronze dragon I've known.  You are destined for great power and I am more than pleased to help you on your way there.\n\nContinue to serve the Scale of the Sands and I will unleash your gift's full potential.", objectives = "" }
WordHunterWoW_QuestEN[10473] = { title = "Restorer's Covenant", description = "Your accomplishments have gone beyond my greatest expectations, {name}.\n\nYou step in and out of time as comfortably as any bronze dragon I've known.  You are destined for great power and I am more than pleased to help you on your way there.\n\nContinue to serve the Scale of the Sands and I will unleash your gift's full potential.", objectives = "" }
WordHunterWoW_QuestEN[10474] = { title = "Champion's Covenant", description = "Your accomplishments have gone beyond my greatest expectations, {name}.\n\nYou step in and out of time as comfortably as any bronze dragon I've known.  You are destined for great power and I am more than pleased to help you on your way there.\n\nContinue to serve the Scale of the Sands and I will unleash your gift's full potential.", objectives = "" }
WordHunterWoW_QuestEN[10475] = { title = "Defender's Covenant", description = "Your accomplishments have gone beyond my greatest expectations, {name}.\n\nYou step in and out of time as comfortably as any bronze dragon I've known.  You are destined for great power and I am more than pleased to help you on your way there.\n\nContinue to serve the Scale of the Sands and I will unleash your gift's full potential.", objectives = "" }
WordHunterWoW_QuestEN[10476] = { title = "Fierce Enemies", description = "If you seek to prove your loyalty to us, there is no better way than to fight against our enemies.\n\nOf these, there are none that can match the ogres in strength and fierceness.  Bring me the warbeads they wear around their necks as proof of their demise and I'll let the others know of your prowess.", objectives = "" }
WordHunterWoW_QuestEN[10479] = { title = "Proving Your Strength", description = "Though we seek a peaceful life, our enemies are many.  Of these, none match the ogres in sheer brute power.\n\nIf you seek to prove your prowess to us, bring me the warbeads they wear around their necks.  I will tell others of your accomplishments.", objectives = "" }
WordHunterWoW_QuestEN[10480] = { title = "Enraged Spirits of Water", description = "The Illidari naga of the region have taken control of the only clean water supply that exists in Shadowmoon Valley.\n\nDirectly north of here you will find the lair of the naga: Coilskar. Around Coilskar are pockets of agitated water that howl to the land in anguish. It is at those pockets that the enraged spirits of water now wander.\n\nTravel to Coilskar and use the totem of spirits to capture watery souls. You will find the largest concentration of these spirits near Coilskar Cistern.\n", objectives = "" }
WordHunterWoW_QuestEN[10481] = { title = "Enraged Spirits of Air", description = "Venture southeast, hero. When you see fields of gigantic blue crystals jutting out from the land, you will have reached your destination. It is there, at the Netherwing Fields, that you will find the enraged spirits of air. They roam the cliffs and mountain bases that surround the fields.\n\nDestroy their tortured forms and capture their souls with the totem of spirits. Return to me when this is done.", objectives = "" }
WordHunterWoW_QuestEN[10482] = { title = "Fel Orc Scavengers", description = "Scavengers, orcs of the Bonechewer clan, skulk about the ruined battlements overlooking the Path of Glory. We must assume that these fel orcs are gathering war machine parts for their masters within Hellfire Citadel--they must be stopped!\n\nFind Bonechewer orcs to the north, {name}. Find them and slay them! But use caution, for although these orcs are the lesser of the fel clans, their strength is the match of any orc we've faced thus far.", objectives = "" }
WordHunterWoW_QuestEN[10483] = { title = "Ill Omens", description = "{name}, in our battles with the Bleeding Hollow clan of fel orcs, we have found upon them foreboding trinkets.  These orcs have collected the insignias of fallen Honor Hold soldiers and created cursed talismans from them.  We fear the dark magic of the Bleeding Hollow orcs have transformed our insignias into evil charms with powers against us!\n\nFind such a talisman from the Bleeding Hollow orcs of Zeth'Gor, to the east, and bring it to Corporal Ironridge at Expedition Point, northeast of Zeth'Gor.", objectives = "" }
WordHunterWoW_QuestEN[10484] = { title = "Cursed Talismans", description = "{name}, we cannot allow the Bleeding Hollow orcs to possess their cursed talismans!  You must acquire them for us so they may be disposed of, and so the soldiers who owned them may be honored for their sacrifices.\n\nGo to Zeth'Gor, the cursed abode of the Bleeding Hollow, and perform your grim task... return to me when you have collected the talismans.", objectives = "" }
WordHunterWoW_QuestEN[10485] = { title = "Warlord of the Bleeding Hollow", description = "You have shown great strength and fortune, for you have delved into Zeth'Gor and lived!  Now, let us hope your fortune holds, for I have a dire task to ask of you...\n\nWarlord Morkh sits within the barracks of Zeth'Gor, commanding his fel troops against us.  His tactics are as clever as they are cruel, and I must admit that his successes against us have cut deep.  And so, {name}, I ask you to remove Morkh from his seat.  Bring me his armor so that we might display it for our soldiers and bolster them.", objectives = "" }
WordHunterWoW_QuestEN[10486] = { title = "The Encroaching Wilderness", description = "The Thunderlord were once a proud orc clan before they were transformed into fel orcs through the blood of Mannoroth.\n\nRecently we recovered this orc stronghold from the ogres that infest the ravine below.  They had moved in when the Thunderlord clan abandoned it.\n\nWe will keep this place and I will have your help doing so.\n\nIn the Jagged Ridge to the south and the west, there are bloodletters that have become like a plague upon us.  They eat and breed incessantly.\n\nKill them and then return to me.", objectives = "" }
WordHunterWoW_QuestEN[10487] = { title = "Dust from the Drakes", description = "The Alliance has recently moved in to the west, using their elven magics to grow a town and grove in a short matter of time.  We must keep their defenses weak so that they do not also grow a spine.\n\nI have a plan that will do that and more.  I want you to traverse the bridge to the southwest, which crosses over Bloodmaul Ravine and leads into the Living Grove.\n\nAttack their fey drake defenses in the Living Grove and bring back the magical dust that sometimes can be found upon their wings.", objectives = "" }
WordHunterWoW_QuestEN[10488] = { title = "Protecting Our Own", description = "With the magical dust you recovered, I have fashioned a magic ointment that will aid in our own defenses.\n\nOur dire wolves are the perfect combination of mount, sentry and friend, but the Alliance scum have been poaching them in the Jagged Ridge.\n\n{name}, I want you to take this ointment and apply it to our dire wolf friends.  The Alliance will get a rude surprise the next time that they send one of their hunting parties.\n\nBe aware though that some of the wolves may not like this, and will turn on you.", objectives = "" }
WordHunterWoW_QuestEN[10489] = { title = "Felling an Ancient Tree", description = "WANTED!\n\nStronglimb Deeproot, ancient of war and chief defender of the Living Grove south of Sylvanaar.\n\nFind him by heading west across the bridge that traverses the Bloodmaul Ravine.\n\nReturn his hewn trunk to Tor'chunk Twoclaws.", objectives = "" }
WordHunterWoW_QuestEN[10502] = { title = "The Bloodmaul Ogres", description = "There is a threat to Sylvanaar far deadlier than the Horde at Thunderlord Stronghold.\n\nI'm speaking of the native ogres of these mountains.  Just to the south and east, down in the ravine, lives the Bloodmaul clan.  While they aren't the only group of ogres that threaten us here, they are the closest.\n\nI would have you head south through the Living Grove, and then go down the path to the east, which leads to their outpost.  Slay as many of the Bloodmaul ogres at Bloodmaul Outpost as you can.", objectives = "" }
WordHunterWoW_QuestEN[10503] = { title = "The Bladespire Threat", description = "There is a threat to Thunderlord Stronghold worse than the Alliance at Sylvanaar.\n\nI speak of the ogres of these mountains.  Just to the west, down in the ravine, lies the Bladespire clan.  While they aren't the only ogres, they are the closest and they're the ones that we defeated to take this place.\n\nHead north through the Jagged Ridge, and then down the path, which leads to their hold.  Slay as many of the Bladespire ogres and their raptors as you can at Bladespire Hold and the Bladespire Grounds.", objectives = "" }
WordHunterWoW_QuestEN[10504] = { title = "The Bladespire Ogres", description = "To the north of the Bloodmaul clan lies a threat more grave:  Bladespire Hold.\n\nThe Bladespire ogres are the strongest clan in the mountains, having the favor of the gronn known as Gruul the Dragonkiller, and his seven sons.\n\nNow that we've dealt with winnowing the Bloodmaul, it is time to turn our eye upon their rivals.\n\nFrom Bloodmaul Hold head north through the ravine until you come to Bladespire Hold and the Bladespire Grounds.  Slay as many of the Bladespire ogres therein as you can.", objectives = "" }
WordHunterWoW_QuestEN[10505] = { title = "The Bloodmaul Ogres", description = "To the south of the Bladespire clan lies yet another threat:  Bloodmaul Outpost.\n\nWhile the Bloodmaul ogres are not the strongest clan in the mountains, not having the favor of the gronn known as Gruul the Dragonkiller, they run a close second.\n\nNow that we've dealt with winnowing the Bladespire, it is time to turn our eye upon their rivals.\n\nFrom Bladespire Hold head south through the ravine until you come to Bloodmaul Outpost.  Slay as many of the Bloodmaul ogres in the vicinity as you can.", objectives = "" }
WordHunterWoW_QuestEN[10506] = { title = "A Dire Situation", description = "With their wolf pack reduced, the Horde is looking for replacements.  Unfortunately there's another source nearby.\n\nThe Bloodmaul ogres in the ravine below to the east keep a strong pack as their own sentries.  I hated sending you to kill the Thunderlord wolves, so why don't we do something different this time?\n\nI've derived a magic powder from the dust that naturally falls off the wings of our fey drakes.  Sprinkle it on the Bloodmaul dire wolves to make them undesirable to the Horde.", objectives = "" }
WordHunterWoW_QuestEN[10507] = { title = "Turning Point", description = "This is the chance we've been waiting for, {name}.  Not only have we uncovered the evidence we need to show our people who Kael'thas is really working for, but we can prove our strength by defeating his new masters.\n\nMy frail health prevents me from aiding you in person with this endeavor, but I will offer you an object that will allow me to project my powers across the continent.  ", objectives = "" }
WordHunterWoW_QuestEN[10508] = { title = "A Gift for Voren'thal", description = "I don't want to send you to Voren'thal empty-handed.  It's not in my style to be underwhelming.\n\nTo gain access to Socrethar's Seat in the north, we'll need to use his own teleporters - locked by Socrethar's teleportation stone.  The first half of the stone is in the possession of Forgemaster Morug at Forge Base Oblivion.  The second half is held by the demon Silroth at Forge Base: Gehenna.\n\nObtain these and Voren'thal will be impressed beyond words.", objectives = "" }
WordHunterWoW_QuestEN[10509] = { title = "Bound for Glory", description = "Now I can properly send you back to Shattrath City.  You've uncovered evidence of Kael'thas making pacts with the Burning Legion and you've got the key to the overlord's back door.\n\nMake sure Voren'thal doesn't topple over with excitement from the news - the old man's getting a bit fragile, if you know what I mean.  You'll find him inside the Seer's Library at the Scryer's Tier.", objectives = "" }
WordHunterWoW_QuestEN[10510] = { title = "Into the Draenethyst Mine", description = "Well it's good to see someone who's willing to help out around here!\n\nBorgrim and I are part of the Explorers' League, and we're here to learn what we can of these mountains.  We've heard all sorts of tales, and I can't wait to get settled in and started.\n\nOne thing in particular has caught my attention.  The night elves speak of a place down in the ravine to the east known as the Draenethyst Mine.  It's at the south end of Bloodmaul Outpost.  I'd like some of the crystals that grow naturally therein.", objectives = "" }
WordHunterWoW_QuestEN[10511] = { title = "Strange Brew", description = "If I'm going to start this vacation out right, then I'm going to need more brew.  Unfortunately, the elves know nothing of the fine art of fermentation.\n\nI overheard that the Bloodmaul ogres down in the ravine have plenty.  I'm willing to give it a try.\n\nDo me a favor?  Head south through the Living Grove and then down the ramp to the east into Bloodmaul Outpost and procure me some?  I hear they have big barrels of it laying around and that their brewmasters carry it around to all the other ogres.", objectives = "" }
WordHunterWoW_QuestEN[10512] = { title = "Getting the Bladespire Tanked", description = "I'll not take another sip of that ill-smelling muck!  But it does give me an idea.\n\n<Borgrim gets a twinkle in his eye.>\n\nSo here's the plan.  We know that the Bloodmaul practically live off of this swill.  But I wonder what their enemies, the Bladespire ogres, think of it?\n\n{name}, I want you to take the rest of this rubbish and see if you can get the Bladespire ogres tanked.  You can find them by heading north from Bloodmaul Outpost through the ravine.", objectives = "" }
WordHunterWoW_QuestEN[10513] = { title = "Oronok Torn-heart", description = "I do not know how we can acquire the spell that the spirits mentioned, {name}. Truth be told, I don't even know where we would start such a search.\n\n<Torlok stares off in the distance, lost in thought.>\n\nHrm... It is a long shot but it might be our only chance. There is an orc that I have seen visit this area before. I spoke to him briefly once. He is a hermit that claims to live above Coilskar Cistern to the northeast. Seek out this orc, Oronok Torn-heart.\n\nAs I said, it is a long shot.", objectives = "" }
WordHunterWoW_QuestEN[10514] = { title = "I Was A Lot Of Things...", description = "I've been a lot of things, stranger, but what I once was isn't what's important. What I am now is what matters and what I am now is a farmer.\n\nI use trained felboars to dig up tubers from the hardened earth of the Shattered Plains. Recently, though, flayers from a nest to the northeast have been attacking my animals, preventing me from gathering tubers.\n\nWould you go to the area north of here and gather tubers for me? Use this whistle while standing on a tuber mound and a boar will come dig one up!", objectives = "" }
WordHunterWoW_QuestEN[10515] = { title = "A Lesson Learned", description = "We need to show those flayers what happens when you mess with Oronok's business!\n\nI want you to go back to the Shattered Plains and destroy every flayer egg that you see. They'll be deep in flayer territory so keep your guard up.", objectives = "" }
WordHunterWoW_QuestEN[10516] = { title = "The Trappings of a Vindicator", description = "I know it's strange, but I do want to stay in this cage.  It gives me the perfect opportunity to do what I came here for; to gather information on the Bladespire.\n\nI can leave at any time, but I would like to have my sword and shield back.\n\nTwo of their leaders have my trappings.  Droggam has my sword and Mugdorg has my shield.\n\nIf you have need, obtain and use the brew from Bloodmaul Outpost to the south to thin out their help and entice those two, but beware their sober guards who don't drink!", objectives = "" }
WordHunterWoW_QuestEN[10517] = { title = "Gorr'Dim, Your Time Has Come...", description = "The leader of Bladespire Hold is known as Gorr'Dim.  Trust me... the name is appropriate.\n\nStill, I wouldn't underestimate him.  He's crafty enough to have elevated his clan to be the favorite of Gruul the Dragonkiller and they now dominate these mountains.  And Gorr'Dim keeps an entourage about him at all times, including defenders who are sworn not to drink the Bloodmaul brew.\n\nFor the safety of Sylvanaar, I'm asking that you go back in there and deal with him.", objectives = "" }
WordHunterWoW_QuestEN[10518] = { title = "Planting the Banner", description = "I want you to steal the Bladespire banner from one of their champions and take it south to Bloodmaul Outpost.  Plant it atop their Northmaul Tower.\n\nThis will infuriate the Bloodmaul and they will attack you relentlessly.  But it will also keep their hatred focused on Bladespire Hold, and away from Sylvanaar.\n\nYou will know you have accomplished the deed when you have defeated Gurn Grubnosh and taken his helm.  Return it to Sylvanaar.\n\n{name}, this isn't going to be easy.  Take a  friend or two with you.", objectives = "" }
WordHunterWoW_QuestEN[10519] = { title = "The Cipher of Damnation - Truth and History", description = "<Oronok adjusts his posture and stands to his full height.>\n\nI had to be sure, {name}. And to be sure, I had to test you. Please excuse the little masquerade. I am as much a farmer as you are a felboar. Which is to say, not at all.\n\nIf you are to recover the Cipher of Damnation, you will need to listen to what I have to tell you. When you are ready, let me know and I will tell you the story.", objectives = "" }
WordHunterWoW_QuestEN[10521] = { title = "Grom'tor, Son of Oronok", description = "My first born, Grom'tor, left to search Coilskar Point - directly southwest of here.\n\nHe's the warrior in the family - ill-tempered and blood-thirsty... Traits he inherited from his mother. Search along the outskirts of Coilskar Point. If you see naga corpses, Grom'tor is sure to be close.\n\nWhen you find him, tell him this: \"We spill blood for just cause.\" It will let him know that you are a friend to Torn-heart and prevent your premature death.", objectives = "" }
WordHunterWoW_QuestEN[10522] = { title = "The Cipher of Damnation - Grom'tor's Charge", description = "This naga filth is the sixth one I've interrogated today. He's got the fancy armor so I figured he knew something. Those other ones were useless.\n\n<Grom'tor points to the corpses of the naga around him.>\n\nI only had to beat him once and he told me everything.\n\nThe first part of the cipher is hidden in a naga chest at Coilskar Point or Coilskar Cistern, east of here. He says naga carry the keys. Kill 'em, take their keys and use them to open the Coilskar chests. Return to me when you find the cipher.", objectives = "" }
WordHunterWoW_QuestEN[10523] = { title = "The Cipher of Damnation - The First Fragment Recovered", description = "<Grom'tor wraps the documents up and places them in a lockbox.>\n\nTake this box to father. He awaits your return at the farm, northeast of here.\n\nTell him that I will be home soon. As soon as I am done having my fun...", objectives = "" }
WordHunterWoW_QuestEN[10524] = { title = "Thunderlord Clan Artifacts", description = "The artifact bears markings that indicate its origins as being created by the Thunderlord clan orcs.  These orcs used to live at Thunderlord Stronghold before they were changed into fel orcs.\n\nFor a time the Bladespire ogres inhabited the stronghold until recently when the Horde pushed them out.\n\nYou've heard of other artifacts that were lost.  A drum, an arrow and a tablet come to mind as objects that you know are being sought after.\n\nFind them in Bladespire Hold and return them to Rokgar Bloodgrip.", objectives = "" }
WordHunterWoW_QuestEN[10525] = { title = "Vision Guide", description = "{race} fool.  You almost destroyed the drum!\n\nI've worked too hard to get here, and my hands have been empty up until now.  At least you were able to succeed where the others only met with failure, or worse.\n\nIt is time to evoke a vision that will lead you to the last relic that I have been seeking.\n\nTake this fiery fragment of my soul.  Use it to transform your body into flame and denature your spirit into a vision guide that will shoot forth to reveal the location of the final Thunderlord relic.", objectives = "" }
WordHunterWoW_QuestEN[10526] = { title = "The Thunderspike", description = "If the vision that I granted you is true, then you must travel down into the ravine and to the south end of Bloodmaul Ravine.  There you will find the Draenethyst Mine.\n\nJourney to the back of the mine, and retrieve the Thunderspike.  Ignore everything else!  I have no interest in the crystals of the mine, nor the ogres therein.\n\nAs soon as you have the spear return it to me here!\n\nAnd, {name}, be very careful with it... I would hate to think what would happen to you should you break it.", objectives = "" }
WordHunterWoW_QuestEN[10527] = { title = "Ar'tor, Son of Oronok", description = "My youngest son, Ar'tor, left to search Illidari Point - far to the southwest, nestled between Legion Hold and Wildhammer Stronghold.\n\nWhile Ar'tor is a hunter of remarkable skill and an expert tracker, I fear that he may be in over his head this time. Illidari Point is the proving grounds for Illidan's demons. These are demons that left the Burning Legion to join the Betrayer!\n\nTravel to Illidari Point and find Ar'tor, {name}.", objectives = "" }
WordHunterWoW_QuestEN[10528] = { title = "Demonic Crystal Prisons", description = "From assessing the scene, you note that Ar'tor is being held in place by energy beams emanating from the crystals hovering around the rune. Try as you might, Ar'tor is unmovable.\n\nYou note that the crystals have an empty slot at their base - perhaps for a key. It also seems as if succubi periodically perform some sort of ritual at the site.\n\nSearch Illidari Point for their leader. Perhaps she holds the key to releasing Ar'tor.", objectives = "" }
WordHunterWoW_QuestEN[10537] = { title = "Lohn'goron, Bow of the Torn-heart", description = "It is a sign, {name}. Even in death, I cannot be stopped. Recovering a part of the Cipher of Damnation is my destiny. With your help, that destiny will be fulfilled.\n\nBefore we embark on that journey, I must have my longbow, Lohn'goron. It is a family heirloom that has been handed down from Torn-heart to Torn-heart for generations.\n\nMy instinct tells me that a demon stole it from my corpse. Kill the demons here until you find my bow. ", objectives = "" }
WordHunterWoW_QuestEN[10538] = { title = "Boiling Blood", description = "That last experiment was not a complete loss -- I did save a small bit of the blood you brought me.  Now boiled down, it should be free of whatever curses the Bleeding Hollow witches placed on their people's blood.\n\nI need more for study.  Go gather Bleeding Hollow blood from the orcs in Zeth'Gor.  When you've gathered the blood, bring it to their cursed cauldron and boil it.  Bring me the boiled blood.", objectives = "" }
WordHunterWoW_QuestEN[10540] = { title = "The Cipher of Damnation - Ar'tor's Charge", description = "At last, we are ready. I will bestow a piece of my spirit upon you, hero. It will guard you and help you in your battle against evil.\n\nYou must then travel south of here towards the back of Illidari Point. Hidden in the ether is a vile creature known as Veneratus the Many. My spirit hunter will call him out when he is near.\n\nDestroy Veneratus and take from his corpse the second part of the Cipher of Damnation.", objectives = "" }
WordHunterWoW_QuestEN[10541] = { title = "The Cipher of Damnation - The Second Fragment Recovered", description = "I thank you, hero. For without you, my spirit would forever remain in this cursed place.\n\n<Ar'tor hands you a spectral lockbox.>\n\nTake it and deliver it to my father at the farm, far to the northeast, above Coilskar Cistern... Inside are Lohn'goron and the second part of the cipher.\n\nHe will be sad to hear news of my death. Promise me that you will assure him that I died a free soul. Tell him that I see the hunting grounds and they are glorious. Tell him that I wait for him there...", objectives = "" }
WordHunterWoW_QuestEN[10542] = { title = "They Stole Me Hookah and Me Brews!", description = "T'chali used to be a pretty friendly troll.  Me come down here to teach the Bloodmaul how to brew their beer.  But once me do that, the Bloodmaul bury T'chali and leave him here to rot!\n\nThe worst part of it was that they stole me hookah!\n\nSo, you want to help T'chali?  You bring me hookah back.  T'chali think the ogres that stole it headed southwest over by the mine.\n\nAnd while you're in there, pick up some brews, too!", objectives = "" }
WordHunterWoW_QuestEN[10543] = { title = "Grimnok and Korgaah, I Am For You!", description = "T'chali has been waiting for his revenge!\n\nThe day they bury T'chali and leave him to die, it was Grimnok Battleborn that led them.  And the next day it was Korgaah that come south to raid and kick T'chali in the head.\n\nI want them dead!\n\nYou will find Grimnok atop the Southmaul Tower in Bloodmaul Outpost.  You will find Korgaah in the top of a building at the north end of Bladespire Hold.  Korgaah has sober defenders, so use the brew to distract him away from them, because they won't drink.", objectives = "" }
WordHunterWoW_QuestEN[10544] = { title = "A Curse Upon Both of Your Clans!", description = "T'chali wants revenge on all of the ogres!\n\nT'chali was a powerful witch doctor in life.  If you reach into me grave you will find a wicked strong fetish.\n\nInvoke the fetish's magic at the entrances to the buildings and towers of both Bladespire Hold and Bloodmaul Outpost.  The voodoo you work will summon an evil spirit that you must defeat.  This in turn will curse that building.\n\nBeware, if you attempt to curse a building that is already cursed, you will call down another cursed spirit!", objectives = "" }
WordHunterWoW_QuestEN[10545] = { title = "Bladespire Kegger", description = "As T'chali was saying, he helped out his Bloodmaul friends to make their brew.  But what T'chali did not say was why.\n\nThe Bloodmaul are in dire straits.  The Bladespire clan be crushing them, and they needed a new weapon to help out with their fight.\n\nThat's when T'chali came up with a great idea.  Why not make the perfect brew, one that strengthens you and weakens your enemy?  Only thing is, T'chali does not know if it works.\n\nSo, you gonna take this brew up to Bladespire Hold and see if it works!", objectives = "" }
WordHunterWoW_QuestEN[10546] = { title = "Borak, Son of Oronok", description = "While Ar'tor was off hunting and Grom'tor was off fighting, Borak studied. Eventually he took up a vocation as a scholar and left for the wilds of Draenor. He returned home a few years ago a changed orc.\n\nHis heightened sense of awareness and mental acuity had forged a silent assassin.\n\nNow a confident and powerful orc, he has taken to recovering the most guarded piece of the cipher.\n\nFind Borak hiding near Eclipse Point, far to the south. He watches from the shadows of the bridge.", objectives = "" }
WordHunterWoW_QuestEN[10547] = { title = "Of Thistleheads and Eggs...", description = "I'd have given up had I not noticed... He's a Thistlehead. I couldn't place it at first but the signs are all there...\n\nNow if we could get our hands on some bloodthistle, we'd be in business.\n\nIn my travels, I met a shady Broken in Shattrath named Tobias.\n\nTobias made a business of trading bloodthistle to blood elves for rotten arakkoa eggs.\n\nDirectly west of here are arakkoa ruins. Search them for an egg and head to the lower city of Shattrath. That's where you'll find Tobias.", objectives = "" }
WordHunterWoW_QuestEN[10550] = { title = "The Bundle of Bloodthistle", description = "I wasn't lying. That egg was incredible. Where did you get it from?\n\nWell, if you ever need more bloodthistle, you know where I am and what I need.\n\nHere's a bundle of the stuff. Take it back to your benefactor.", objectives = "" }
WordHunterWoW_QuestEN[10551] = { title = "Allegiance to the Aldor", description = "", objectives = "" }
WordHunterWoW_QuestEN[10552] = { title = "Allegiance to the Scryers", description = "", objectives = "" }
WordHunterWoW_QuestEN[10553] = { title = "Voren'thal the Seer", description = "Now that you've chosen a side, {name}, you should meet the Scryers' leader.\n\nYou will find Voren'thal the Seer inside the Seer's Library at the Scryer's Tier.\n\nSee if you can be of assistance to him.  He will be glad to hear you've decided to lend them a hand.", objectives = "" }
WordHunterWoW_QuestEN[10554] = { title = "Ishanah", description = "Now that you've decided to side with the Aldor, you'd do well to introduce yourself to their leader.  You will find High Priestess Ishanah inside the Shrine of Unending Light.", objectives = "" }
WordHunterWoW_QuestEN[10555] = { title = "Malaise", description = "The magic practiced by the Lashh'an arakkoa is unnatural. They rip out handfuls-clawfuls?-of their own feathers as reagents!\n\nThat doesn't sound like good magic to me. I've come here to learn more about their spells. Unfortunately getting close is too much for me.\n\nYou could succeed: cast one of their spells on yourself, then return to me. You'll have to find one of their spellbooks, high up in the trees of Veil Lashh.\n\nAnd unless you've grown feathers I can't see, you'll need to get some of those.\n", objectives = "" }
WordHunterWoW_QuestEN[10556] = { title = "Scratches", description = "The pictograms indicate using feathers to cast the spell at one of the circles of power in Veil Lashh.\n\nConfusing iconography seems to show an arakkoa being suffused with the spirit of a kaliri.", objectives = "" }
WordHunterWoW_QuestEN[10557] = { title = "Test Flight: The Zephyrium Capacitorium", description = "I built an amazing device, the Zephyrium Capacitorium, and I'm sure it'll work perfectly, but... do you want to help me test it?\n\nThere's plenty of hazard pay!\n\nSpeak with my twin over there, Rally. Good luck, {name}. Come back after your experiment.  Or... if that's not possible due to sustained injuries, your next of kin can report to collect your pay.", objectives = "" }
WordHunterWoW_QuestEN[10558] = { title = "Revered Among Honor Hold", description = "You've proven your worth to our cause, {name}.  One such as yourself could one day become a great leader.\n\nContinue to fight our enemies in the Shattered Halls and gain renown among my men.  If you live up to my expectations I will have greater tasks to ask of you.", objectives = "" }
WordHunterWoW_QuestEN[10559] = { title = "Revered Among Thrallmar", description = "You've proven yourself time and again, {class}.  Yet more trials await you.\n\nContinue to fight the Fel Horde inside the Shattered Halls of Hellfire Citadel and your name will be known to all of Thrall's followers in this land.", objectives = "" }
WordHunterWoW_QuestEN[10560] = { title = "Revered Among the Sha'tar", description = "<The calming melodic tones projected by A'dal become more hushed and somber.>\n\n<You are shown the large naaru structure known as Tempest Keep.  It is now inhabited by the forces of Kael'thas and its power used for nefarious ends.  A'dal promises you greater tasks once you've done your part to take back Tempest Keep.>", objectives = "" }
WordHunterWoW_QuestEN[10561] = { title = "Revered Among the Keepers of Time", description = "You've proven yourself to us, {race}.  The timeline is not yet safe, however.\n\nWe're in need of true champions and you may prove to be one.\n\nContinue to defend the events of the past from intruders and you'll get the renown you deserve.", objectives = "" }
WordHunterWoW_QuestEN[10562] = { title = "Besieged!", description = "Don't let your guard down, {race}. We're under constant assault from the Burning Legion.\n\nFrom their base of Legion Hold to the northwest, the demons rain down a ceaseless stream of infernals. As quickly as we can kill them, the new meteors impact and begin a new wave of attacks.\n\nMy men are ragged and exhausted. I don't know how much longer they'll hold out. Please, {name}, lend your help to our defenses. Take your place on the line and halt the advance of the infernals!", objectives = "" }
WordHunterWoW_QuestEN[10563] = { title = "To Legion Hold", description = "The fortress of Legion Hold is nigh impregnable, and to be completely honest, I can't spare the forces for an assault. Our hopes are riding on you, {name}.\n\nWhat little information we've been able to gather indicates that the Legion stocks and prepares its infernals at the hold. With the help of a disguise I'll give you, you must sneak into Legion Hold and learn about their plans. Your best hope is to intercept or overhear communication between their commanders. Good luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[10564] = { title = "Blast the Infernals!", description = "The device we've assembled won't win any beauty contests, but it should be capable of destroying the infernals amassed at Legion Hold. Judging from what the fel reaver power core's energy did to the Fetid Pool, it holds a respectable amount of explosive power.\n\nIf you set the device off in the middle of the green glyph at the hold, it should be in range to hit all of the infernals.", objectives = "" }
WordHunterWoW_QuestEN[10565] = { title = "The Stones of Vekh'nir", description = "The arakkoa of Vekh'nir have been a thorn in our sides for many years. Some strange religion guides them, a religion which has the arakkoa in a frenzy of activity. They carry these crystals with them now, which they have turned to some dark purpose.\n\nI know something of their rituals. They take the crystals to their spell circles to infuse them. We at the village would like to know more. Waylay a few of the arakkoa until you find a crystal, charge it, then return it to me.", objectives = "" }
WordHunterWoW_QuestEN[10566] = { title = "Trial and Error", description = "I've fashioned four wands that I believe will enhance the power of the arakkoa's crystals. Take these wands to Trogma's Claim, and try them on the ogre slaves.\n\nYou'll need to find an infused crystal off of the arakkoa in the area.\n\nWhen you figure out which is best, come back to me.", objectives = "" }
WordHunterWoW_QuestEN[10567] = { title = "Creating the Pendant", description = "The arakkoa of Ruaan Weald elevate from their flock the Harbingers of the Raven, the heralds of their god.\n\nThey believe that the Harbingers watch over them from the sky, where they receive the teachings of the Raven, and descend to pass this message along.\n\nThe Harbingers hold a powerful sway over the souls of the arakkoa. They use magical pendants, which we need.\n\nAttract one of the Harbingers by slaying its flock and taking their claws. Place the claws upon the altar to get his attention.", objectives = "" }
WordHunterWoW_QuestEN[10568] = { title = "Tablets of Baa'ri", description = "Years ago, the dreaded warlock known as Gul'dan raised the volcano in the middle of Shadowmoon.  The draenei village of Baa'ri, to the southwest, was buried under the lava along with its inhabitants and artifacts of religious importance.\n\nThe treacherous tribe of Broken known as the Ashtongue has been ordered by Illidan to excavate the area.  We must use this opportunity to recover the Tablets of Baa'ri, an ancient text rumored to hold the secrets of the Temple of Karabor, now known as the Black Temple.", objectives = "" }
WordHunterWoW_QuestEN[10569] = { title = "The Sketh'lon Wreckage", description = "Our scouts have brought back disturbing reports from the ruined arakkoa encampments in the area.\n\nThe ghosts of powerful arakkoa magicians wield powers we never thought they possessed. They seem to be organizing, as though preparing for something, but our knowledge is limited. We cannot afford to remain ignorant!\n\nTravel north to the Sketh'lon Wreckage, to the northwest of the Deathforge and search for signs of their motives.", objectives = "" }
WordHunterWoW_QuestEN[10570] = { title = "To Catch A Thistlehead", description = "<Borak takes the bundle of bloodthistle from you and places it to his nose.>\n\nPungent...\n\nNow, take this bundle and place it at the other end of this bridge. When the envoy makes his daily rounds, he will be compelled to pick it up - without his bodyguard. You see, blood elves look down upon bloodthistle addicts. If any of his compatriots ever found out...\n\nAll you need to do is lie in wait for him to dismiss his bodyguard. When he is alone, make your strike! Kill him and take the missive.", objectives = "" }
WordHunterWoW_QuestEN[10571] = { title = "Oronu the Elder", description = "According to the tablets, an artifact known as a Medallion of Karabor was kept at Baa'ri.  Only the highest-ranking draenei priests were granted these, as they allowed unfettered access into the Temple of Karabor.\n\nWe must find out whether the Ashtongue have recovered the medallion that was kept at Baa'ri yet.  Its power would provide great aid in our fight against Illidan.\n\nAkama's lieutenant at Baa'ri, Oronu the Elder, receives written orders from him daily.  Obtain them and bring them to me.", objectives = "" }
WordHunterWoW_QuestEN[10572] = { title = "Setting Up the Bomb", description = "We cannot permit the Legion to carry out its plan to destroy Wildhammer Stronghold on their march to the Black Temple.\n\nThere's only one way to stop them, {name}. You must create an explosive large enough to destroy the Legion's entire stockpile of infernals at the hold.\n\nThe Fetid Pool near Legion Hold holds an old fel reaver power core you could use as the base of your device. Search the other wreckage near the fel reaver for armor plating we might be able to make a casing from.", objectives = "" }
WordHunterWoW_QuestEN[10573] = { title = "The Deathforge", description = "From your findings at Legion Hold, we know that the Legion's Shadow Council allies are producing infernals in the Deathforge. I've dispatched a small scouting party to keep watch over the area, but they're not able to accomplish everything we need.\n\nIf the Deathforge is left alone to operate, they'll rebuild the infernal stockpile that you destroyed at Legion Hold.\n\nI want you to meet up with Stormer Ewan Wildwing, at the Deathforge Tower, to the northwest, overlooking the Deathforge itself.", objectives = "" }
WordHunterWoW_QuestEN[10574] = { title = "The Ashtongue Corruptors", description = "According to Akama's letter, four fragments of the medallion were unearthed and given to the Ashtongue Corruptors.  These dreaded Broken were once powerful shaman who now defile the very elements they revered.\n\nHaalum, Corruptor of Air, can be found at Netherwing Pass.  Eykenen and Uylaru, Corruptors of Earth and Fire, were last seen at the Fel Pits near the Hand of Gul'dan.  Lakaan, Corruptor of Water, is rumored to be near Coilskar Point.\n\nFind them and obtain the medallion fragments.", objectives = "" }
WordHunterWoW_QuestEN[10575] = { title = "The Warden's Cage", description = "The fragments you obtained are only half of the medallion.  The Ashtongue leader, Akama, must have kept the other half.\n\nI dread to ask this of you, as Akama is both evil and cunning.\n\nHe and the Ashtongue Deathsworn - the vilest and most brutal of the tribe - are rumored to run a torture chamber inside the Warden's Cage.\n\nI want you to find that dreaded prison,  and find the whereabouts of Akama.  His second in command at the location is a Broken known as Sanoru - interrogate him if you have to.", objectives = "" }
WordHunterWoW_QuestEN[10576] = { title = "The Shadowmoon Shuffle", description = "<Borak looks you up and down.>\n\nThis is going to be tricky, but I think I can make it work.\n\nI can disguise you as one of these Illidari blood elves, {name}. What I need first, though, are several pieces of their armor. It is imperative that the armor be clean. No blood stains! We want to avoid suspicion.\n\nBring me the gear and I'll take care of the rest of the disguise.\n\nOnce the disguise is assembled, you're going to deliver the message to the Grand Commander - in person.", objectives = "" }
WordHunterWoW_QuestEN[10577] = { title = "What Illidan Wants, Illidan Gets...", description = "Take this disguise and enter Eclipse Point. Once inside, use the disguise to cloak yourself. The Eclipsion blood elves will be unable to see through the disguise, thereby granting you safe passage to Grand Commander Ruusk.\n\nOnce you find Ruusk, tell him where next to move the cipher. You're going to have to act your heart out, {name}. Play it off as if you are his superior, delivering a message from his lord. That should do it!\n\nOh - watch out for the dragonhawks as they see through the disguise.", objectives = "" }
WordHunterWoW_QuestEN[10578] = { title = "The Cipher of Damnation - Borak's Charge", description = "That Cipher fragment will never reach Zuluhed. You're going to ambush Ruul the Darkener and his transport before it has a chance to make the delivery.\n\nThe Dragonmaw Fortress is directly east of here, across the Netherwing Fields. Somewhere between Dragonmaw Fortress and the Sanctum of the Stars is where you'll find Ruul. Strike hard and strike fast! And {name}, from the sound of it, this Ruul is going to be tough. Keep your guard up.\n\nReturn the Cipher to me should you succeed.\n", objectives = "" }
WordHunterWoW_QuestEN[10579] = { title = "The Cipher of Damnation - The Third Fragment Recovered", description = "Take this box to my father. He still resides at Oronok's Farm, far to the north, above Coilskar Cistern. When all three fragments are pieced together, the ancient words will be known once more.\n\nGood luck, {name}. Tell my father that I will be home soon.", objectives = "" }
WordHunterWoW_QuestEN[10580] = { title = "Where Did Those Darn Gnomes Go?", description = "Despite the good that we've done here, I feel bad about one thing: driving Toshley and his gnome friends away.\n\nWe had no choice; they were making a mess of our efforts in the grove with all of their technology and experimentation.\n\nI would appreciate it if you would find out what became of them.  Last we heard, they headed east across the bridge.  I'm certain that they must have turned south, away from Thunderlord Stronghold.\n\nLook for a clue as to their whereabouts in the southern Jagged Ridge.", objectives = "" }
WordHunterWoW_QuestEN[10581] = { title = "Follow the Breadcrumbs", description = "VERY WELL, I AM HEREBY WARNING YOU THAT YOU WILL FIND NOTHING UP ON THE RIDGE.\n\nDO NOT FOLLOW THE TRAIL OF SPARE PARTS THAT LEAD TO TOSHLEY'S STATION!  YOU WILL NOT FIND TOSHLEY, NOR ANY OTHER GNOME THERE.", objectives = "" }
WordHunterWoW_QuestEN[10582] = { title = "Minions of the Shadow Council", description = "<Ewan listens to you recount the events at Legion Hold, nodding.>\n\nThat puts our observations into perspective. We've caught glimpses of them launching infernals in the direction of the hold, but haven't been able to find much more than that.\n\nThe Shadow Council has the Deathforge sealed tighter than a new keg o' thunderbrew. The first thing you'll need to do is crack some skulls so you can get in there and poke around. Start eliminating the Shadow Council guarding the entrance to the Deathforge!", objectives = "" }
WordHunterWoW_QuestEN[10583] = { title = "The Fate of Flanis", description = "Wing Commander Nuainn originally sent three of us out here to keep watch over the Deathforge and to gather information. Flanis Swiftwing volunteered to try to infiltrate the Deathforge, but we haven't heard anything from him in days.\n\nI fear the worst, {name}. Flanis is a skilled scout, but if he's gotten in over his head, we have no way of knowing. Search the Deathforge for him and recover any information or items he might have collected.", objectives = "" }
WordHunterWoW_QuestEN[10584] = { title = "Picking Up Some Power Converters", description = "Those dumb ogres at the Bladespire Outpost to the north have been raiding our power converters!  And you're going to get them back for me, sort of.\n\nNo doubt, with their big, clumsy hands, the ogres have damaged the converters.  So, what I want you to do is release the energy from them and then use this protovoltaic magneto collector on the resultant electromental to encase it.\n\nIt'll likely be sore with you, so you'll need to 'kill' it while it's contained in the magneto sphere.", objectives = "" }
WordHunterWoW_QuestEN[10585] = { title = "The Summoning Chamber", description = "In order for the Shadow Council to construct infernals as quickly as they're being used, they must have an area dedicated to summoning the corrupted elementals that serve as the souls of the creatures.\n\nThe summoning chamber is likely to be found below ground, near a pool of fouled water or lava. Locate the summoning chamber within the Deathforge and find a way to end their summoning ritual. The mo'arg involved in making the infernals may carry a tool that will help disrupt the summoner's magics.", objectives = "" }
WordHunterWoW_QuestEN[10586] = { title = "Bring Down the Warbringer!", description = "We've made a lot of progress against the Shadow Council's operations at the Deathforge, but if we're to truly be triumphant, we'll need to defeat the Legion's overseer there.\n\nI found a key among the items in Flanis's pack. I'm certain it will prove useful in tracking down this Warbringer Razuun you observed at Legion Hold.\n\nAfter you've hunted down and dealt with Warbringer Razuun, report directly to Wing Commander Nuainn. He'll want to know immediately!", objectives = "" }
WordHunterWoW_QuestEN[10587] = { title = "Karabor Training Grounds", description = "Our scouts have reported a massive influx of Sunfury blood elf recruits heading to the Ruins of Karabor.  Normally this would represent a purely military threat, however we believe something else is amiss.\n\nDescriptions of their attire and fighting style are suspiciously close to that of Illidan himself.  I do not want to become alarmed without good reason, so I would like you to go there and bring me back their weapons.  We will then determine whether my fears are unfounded or not.", objectives = "" }
WordHunterWoW_QuestEN[10588] = { title = "The Cipher of Damnation", description = "How many times has this spell been used in the history of our worlds? Undoubtedly, its power for destruction is unparalleled.\n\nWhat you must do now is take the cipher, now made whole, and read from it at the Altar of Damnation - where the memory of Gul'dan stands.\n\nWhat you will see once the words are uttered are the memories left imprinted upon the land. Stand your ground and await the coming of Cyrukh.\n\nYou must be victorious, {name}. This land cannot withstand another shattering.", objectives = "" }
WordHunterWoW_QuestEN[10589] = { title = "Gaining Access", description = "According to Razuun's orders, the massive infernal staging area is called Invasion Point: Cataclysm and it's nestled in the northern mountains. The only way to reach it is by using a teleporter located at Legion Hold.\n\nCertain members of the Legion host carry devices allowing them to activate the teleporters. You must capture one of these devices to win access to the teleporter. Slaughter all of the demons if you must, but you can't afford to return empty-handed.", objectives = "" }
WordHunterWoW_QuestEN[10594] = { title = "Gauging the Resonant Frequency", description = "Take these scanners to the Singing Ridge.  By dropping them in a pattern on the ground, you will create overlapping fields that will read the amplitude of the crystals.  Stand amidst them in such a way that you're in five oscillation fields and I'll have the information that I need!\n\nYour scanners will even work with those that others drop.\n\nOh, and it's likely that a rift will be formed!  I have no idea what, if anything, will come out of it, but be prepared for the worst.", objectives = "" }
WordHunterWoW_QuestEN[10595] = { title = "Besieged!", description = "<Gulmok looks to the sky.>\n\nOur scouts are putting up a good fight, but the infernals keep coming!\n\nFrom their base of Legion Hold to the southwest, the demons bombard us with impunity! Even the elite Kor'kron guard cannot hold them off forever.\n\nI'm drafting every able-bodied {race} to do their part in defense of Shadowmoon Village. This is no game, {class}. The survival of the village is at stake. Do your duty to the Horde, and join the fray!", objectives = "" }
WordHunterWoW_QuestEN[10596] = { title = "To Legion Hold", description = "The fortress of Legion Hold is your target. You'll have no reinforcements, so a frontal attack is out of the question.\n\nWhat little information we have shows that the Legion stocks and prepares its infernals at the hold. With the help of a disguise I'll give you, you must sneak into Legion Hold and discover their plans.\n\nYour best hope is to intercept or overhear communication between their commanders. ", objectives = "" }
WordHunterWoW_QuestEN[10597] = { title = "Setting Up the Bomb", description = "We can't allow the Legion to trample us on their march to Black Temple.\n\nFind a way to destroy the infernals they intend to use against us. That's not a request, {name}; it's an order.\n\nThe Fetid Pool near Legion Hold holds an old fel reaver power core you could use as the basis for a kind of fel bomb. Search the other wreckage near the fel reaver for a section of armor plating. You should be able to make a bomb powerful enough to take out those infernals and give the hold a nice shake!", objectives = "" }
WordHunterWoW_QuestEN[10598] = { title = "Blast the Infernals!", description = "The device we've assembled won't win any beauty contests, but it should be capable of destroying the infernals amassed at Legion Hold. Judging from what the fel reaver power core's energy did to the Fetid Pool, it holds a respectable amount of explosive power.\n\nIf you set the device off in the middle of the green glyph at the hold, it should be in range to hit all of the infernals.", objectives = "" }
WordHunterWoW_QuestEN[10599] = { title = "The Deathforge", description = "While you were taking care of the infernals at Legion Hold, I've been going over your reports. We've got no reason to believe the Legion lied about what's going on at the Deathforge. They're really cranking out infernals down there, so I've dispatched a scouting party to keep watch over it.\n\nIf we don't shut down the Deathforge, they'll rebuild the infernal stockpile that you destroyed at Legion Hold.\n\nReport to Scout Zagran atop Slag Watch, to the southeast of here and overlooking the Deathforge.", objectives = "" }
WordHunterWoW_QuestEN[10600] = { title = "Minions of the Shadow Council", description = "<Zagran listens to you recount the events at Legion Hold, nodding.>\n\nThat fills in the gaps we've seen. We've caught glimpses of them launching infernals in the direction of the hold, but haven't been able to find much more than that.\n\nThe Shadow Council has the forge pretty much locked down. Looks like you're going to need to fight your way in. Start eliminating the Shadow Council guarding the entrance to the Deathforge!", objectives = "" }
WordHunterWoW_QuestEN[10601] = { title = "The Fate of Kagrosh", description = "The scouting party originally had three members. Unfortunately, Kagrosh decided he wanted to be a hero.\n\nHe descended into the Deathforge and we haven't heard from him since.\n\nIn all likelihood, the fool's gone and gotten himself killed. The Shadow Council members aren't idiots and Kagrosh wasn't exactly strong in the subtlety department, if you know what I mean. Keep an eye out for him in the Deathforge and recover any information or items he might have collected.", objectives = "" }
WordHunterWoW_QuestEN[10602] = { title = "The Summoning Chamber", description = "In order to churn out infernals as quickly as the Deathforge seems to, they must have an area dedicated to summoning the elementals that form the core of the infernals.\n\nThe summoning chamber is likely to be found below ground, near a pool of fouled water or lava. Locate the summoning chamber within the Deathforge and find a way to end their summoning ritual. The mo'arg involved in making the infernals may carry a tool that will help disrupt the summoner's magics.", objectives = "" }
WordHunterWoW_QuestEN[10603] = { title = "Bring Down the Warbringer!", description = "We've made a lot of progress against the Shadow Council here at the Deathforge, but now it's time to finish the job.\n\nI found a key among the items in Kagrosh's pack. At least he accomplished something before they got to him.\n\nThe key should help you to track down this Warbringer Razuun you observed at Legion Hold.\n\nAfter you've hunted down and dealt with Warbringer Razuun, report directly to Blood Guard Gulmok. We must not keep him waiting.", objectives = "" }
WordHunterWoW_QuestEN[10604] = { title = "Gaining Access", description = "According to Razuun's orders, the massive infernal staging area is called Invasion Point: Cataclysm and it's located in the mountains behind our village! The only way to reach it is by using a teleporter at Legion Hold.\n\nCertain Legion minions carry a device allowing them to use the teleporter. You must capture one of these devices to win access to the teleporter. Slaughter all of the demons if you must, but you can't afford to return empty-handed. Do not delay; the enemy is perilously close.", objectives = "" }
WordHunterWoW_QuestEN[10606] = { title = "The Art of Fel Reaver Maintenance", description = "The best way to destroy the rest of the Legion's supplies is to use their own weapons against them. I've been working on a rig that will let you take control of one of those Fel Reaver Sentinels below.\n\nThere are a couple things I need to work out, yet. For that, I'll need the manual that Doctor Gutrick keeps locked in a chest at the bottom of the ramp. He probably won't give up the key without a fight, so you'll need to capture it. Bring the fel reaver manual back to me and I'll do the rest!", objectives = "" }
WordHunterWoW_QuestEN[10607] = { title = "Whispers of the Raven God", description = "At Grishnath, totems left by the Oracles of the Raven enable the arakkoa to hear the Word of the Raven. Unfortunately, the language of the arakkoa is indecipherable to us.\n\nUsing the Harbinger's pendant, we can understand it. You will be able to take the souls of the arakkoa to understand their language. While you are suffused with the arakkoa's spirit, you can visit the totems and understand their message.\n\nDiscover this for us, {name}.", objectives = "" }
WordHunterWoW_QuestEN[10608] = { title = "Crystal Clear", description = "The damned rock flayers are keeping me from my research down in the Singing Ridge!  By digging at the crystals there, with every scratch they are ruining my chances of studying the harmonics of the singing crystals.\n\nYou look like someone who can help me deal with this problem.  Head south and clear those crystal flayers out.", objectives = "" }
WordHunterWoW_QuestEN[10609] = { title = "What Came First, the Drake or the Egg?", description = "I'm researching the applications of drake essences to my work as a physician.  I think they could be a panacea for a host of maladies!\n\nI need someone to go south to the Singing Ridge and get me some.\n\nWilling to take my temporal phase modulator and use it on the nether whelps that hatch from the nether drake eggs?  Retrieve the essences from whatever they turn into.\n\nWhich, I might add, I'm not certain of what that will be as we're using some pretty dicey, time  and space modifying tech here.", objectives = "" }
WordHunterWoW_QuestEN[10610] = { title = "Prospecting Basics", description = "", objectives = "" }
WordHunterWoW_QuestEN[10611] = { title = "The Art of Fel Reaver Maintenance", description = "The best way to destroy the rest of the Legion's supplies is to use their own weapons against them. I've been working on a rig that will let you take control of one of those Fel Reaver Sentinels below.\n\nThere are a couple things I need to work out, yet. For that, I'll need the manual that Doctor Maleficus keeps locked in a chest near the bottom of the ramp. He probably won't give up the key without a fight, so you'll need to capture it. Bring the fel reaver manual back to me and I'll do the rest.", objectives = "" }
WordHunterWoW_QuestEN[10612] = { title = "The Fel and the Furious", description = "<Plexi leafs through the manual.>\n\nWell, this has everything we need, but there's just one problem. Fel Reavers aren't really built to respond to remote control.\n\nWe can modify one for you to use for a short time, but you'll have to work fast, or there's no telling what might happen! I wouldn't be surprised if your little stunt with the fel reaver catches the attention of the Legion's lackeys, either. Keep an eye out, and whatever you do, don't forget to destroy as much as you can!", objectives = "" }
WordHunterWoW_QuestEN[10613] = { title = "The Fel and the Furious", description = "<Nakansi leafs through the manual.>\n\nAll the information is here, but be warned. These things weren't built to be controlled remotely.\n\nWe can modify one for you to use for a short time, but you'll have to work fast, or there's no telling what might happen! I wouldn't be surprised if your little stunt with the fel reaver catches the attention of the Legion scum, either. Try to keep yourself safe, but remember, the mission and the safety of Shadowmoon Village come first!", objectives = "" }
WordHunterWoW_QuestEN[10614] = { title = "Whispers on the Wind", description = "I have chased rumors of the Mok'Nathal across Outland with nothing to show for it. Finally, we may have found their home.\n\nBut now that the moment is here, I am filled with unease. Unease that has kept me awake deep into the nights during my search. Will they accept me?\n\nI... know their leader's name: Leoroxx. Seek him out. You must be my eyes in this.", objectives = "" }
WordHunterWoW_QuestEN[10615] = { title = "Ruuan Weald", description = "The information you have helped me reveal about the nature of the arakkoa here will be of great interest to another.\n\nWe were visited by members of the Cenarion Expedition, who have also become concerned with the arakkoa's intentions here in the Blade's Edge Mountains.\n\nYou should seek him out. His name is Timeon, and you will find him at Evergrove in Ruuan Weald. Follow the road west from here, then north when it forks in Razor Ridge. Finally, follow the road west when it splits in the Bladed Gulch.", objectives = "" }
WordHunterWoW_QuestEN[10617] = { title = "Silkwing Cocoons", description = "The silk from the cocoons of the silkwings are used for all manner of things in the village. We can never get enough, and we never have enough.\n\nIt is difficult to harvest the cocoons from the larva once they begin the process of metamorphosis.\n\nOur warriors are occupied with the assault on our village. If you could gather these for us, that would be helpful.", objectives = "" }
WordHunterWoW_QuestEN[10618] = { title = "The Softest Wings", description = "Hunting silkwing larva is a difficult challenge for our young warriors, but luckily, even if they fail to harvest the cocoon from the larva, we can still use the wings of hatched silkwings.\n\nIn fact, we use the wings for much more than the cocoons, and we can never have too many.\n\nIf you'll be out there, it would be a great help if you could bring me some.", objectives = "" }
WordHunterWoW_QuestEN[10619] = { title = "The Ashtongue Tribe", description = "The Ashtongue tribe is feared among all Broken.  It consists of the most vicious and bloodthirsty individuals, handpicked by Akama himself.  They are as fierce and ruthless as any naga, demon or blood elf in Illidan's army and they have been deployed in large numbers at the Ruins of Baa'ri, southwest of here.  Go there and put a dent in their numbers before they get a chance to mount an attack on us.", objectives = "" }
WordHunterWoW_QuestEN[10620] = { title = "Ridgespine Menace", description = "We hired on to help Toshley when he decided to move to Outland, and we've been on the move ever since.\n\nNow it looks like we've finally put down some roots.  All of the crazy scientists have their projects going, and us Roughriders are here to protect them.\n\nWhat we need right now is for you to go north into Razor Ridge, or east to the Scalewing Shelf, and keep them clear by killing the stalkers.  They're stealthy spiders that live amongst the rock outcroppings, and jump unsuspecting passersby.", objectives = "" }
WordHunterWoW_QuestEN[10621] = { title = "Illidari-Bane Shard", description = "The shard appears to be a piece of a larger weapon. Sharp-looking runes etched into the metal glow with a menacing light.\n\nThe weapon's intended purpose isn't clear to you, but it's hard to ignore. Most of the mo'arg at Legion Hold seem to be working with fragments of the same metal you hold in your hand. Perhaps one of the weaponsmiths at Wildhammer Stronghold might be able to tell you more about it.", objectives = "" }
WordHunterWoW_QuestEN[10622] = { title = "Proof of Allegiance", description = "Akama has been tracking your progress quite closely, {name}.\n\nThe Ashtongue you've slain at the Ruins of Baa'ri are amongst the most evil Broken known among us... carefully hand-picked by Akama himself to maintain the facade we need to present to Illidan.  The Deathsworn, however, know of Akama's true intentions.\n\nFirst things first.  We need to know that you are not with Illidan.  A Satyr known as Zandras watches over us from above the prison walls on his behalf.  Slay him as proof of your allegiance.", objectives = "" }
WordHunterWoW_QuestEN[10623] = { title = "Illidari-Bane Shard", description = "The shard appears to be a piece of a larger weapon. Sharp-looking runes etched into the metal glow with a menacing light.\n\nThe weapon's intended purpose isn't clear to you, but it's hard to ignore. Most of the mo'arg at Legion Hold seem to be working with fragments of the same metal you hold in your hand. Perhaps one of the weaponsmiths at Shadowmoon Village might be able to tell you more about it.", objectives = "" }
WordHunterWoW_QuestEN[10624] = { title = "A Haunted History", description = "Have you felt the cold chill? Perhaps what you thought was a hand on your shoulder? That was not your mind playing tricks on you, {race}. The land is haunted. Ghosts litter the landscape, stuck here for all eternity.\n\nWould you like to see them? Are you sure about that? These types of things tend to change a person - and not for the better.\n\nVery well, I will need you to collect for me the ever-burning ash that is found near any of the fel lava pools of western Shadowmoon. Anywhere near green lava...\n", objectives = "" }
WordHunterWoW_QuestEN[10625] = { title = "Spectrecles", description = "I call them \"Spectrecles.\" Clever, no? When you equip these goggles, you will be able to see the spirits of Shadowmoon Valley.\n\nBefore I let you have them, though, you must promise me that you will help us clear out the ghosts at the village.\n\nTake the goggles and destroy any and all spirits that you see wandering about Shadowmoon Village. Hopefully, destroying these spirits will force any that remain to move elsewhere.", objectives = "" }
WordHunterWoW_QuestEN[10626] = { title = "Capture the Weapons", description = "With a larger supply of this material, we might be able to forge a weapon for you to use.\n\nThe two pit lords at Legion Hold, Makazradon and Morgroron, have already been equipped with these anti-demon weapons. We have no way of knowing how many more the Legion intends to produce, but if we can capture these prototypes, there should be enough for our project.\n\n<Ordinn grins.>\n\nThere's a certain amount of satisfaction in using the Legion's own 'secret weapons' against them, don't you think?", objectives = "" }
WordHunterWoW_QuestEN[10627] = { title = "Capture the Weapons", description = "With a larger supply of this material, I can forge a weapon suitable for you.\n\nThe two pit lords at Legion Hold, Makazradon and Morgroron, have already been equipped with these anti-demon weapons. Capturing those two weapons should provide us with enough material to make your weapon, and then some.\n\nI can't wait to bring the battle to the enemy using these weapons. That'll teach the Legion to trifle with anti-demon magics.", objectives = "" }
WordHunterWoW_QuestEN[10628] = { title = "Akama", description = "You've proven what side you're on.  I will reveal to you our leader's hideout.\n\nFollow the halls beyond; there will be an underground passage hidden by stagnant water on your right.\n\nI must warn you, {name}.  You are not to speak to anyone of what you see there.", objectives = "" }
WordHunterWoW_QuestEN[10629] = { title = "Shizz Work", description = "I finally got my shredder working but I seem to have lost the keys. I keep a pack of felhounds to protect my camp. They don't do a very good job and they like to bite me a lot. They also like shiny things. I think this one felhound I have may have eaten my shredder keys. I'll pay you if you'll take my felhound on a walk. Kill some helboars and let him eat. He'll do his business. When he's done, see if you can't find the keys in his \"leavings.\"", objectives = "" }
WordHunterWoW_QuestEN[10630] = { title = "Beneath Thrallmar", description = "I'm almost back in business.  Problem is all these gan'arg are in my mine.  I can't send my peons in and even once I fix this shredder I wouldn't want to risk it in combat. Deep down in the mine the gan'arg have a leader.  If you kill him maybe the gan'arg will leave.  Then I could make some money and buy my way out of here. ", objectives = "" }
WordHunterWoW_QuestEN[10632] = { title = "Cutting Your Teeth", description = "It's nice that you've been helping out Toshley and his scientists.  I, however, do not have the luxury of indulging in my 'personal' interests.\n\nIf you want to make a difference around here, you'll do what I ask of you, and right now, I need weapons.\n\nOur guns are effective at range, but when the bugs get in close, we need to have powerful melee weapons as a backup.\n\nThe teeth of the daggermaw lashtails in the northern part of the Razor Ridge make for great vibro-weapon blades.  Scare me up some.", objectives = "" }
WordHunterWoW_QuestEN[10633] = { title = "Teron Gorefiend - Lore and Legend", description = "Stories abound about the life of Teron Gorefiend, but most are just that - stories. We do not know what happened to Gorefiend after he returned to Draenor.\n\nThe only thing we are certain of is that he has already died once.\n\nI have heard the scouts here speaking of an ancient orc spirit that resides at the Altar of Shadows, far to the southeast, across the Netherwing Fields and through Netherwing Pass. Take the Spectrecles and track this orc down. He will surely have more information on Gorefiend.", objectives = "" }
WordHunterWoW_QuestEN[10634] = { title = "Divination: Gorefiend's Armor", description = "In life, Gorefiend was a monster, but in death, Gorefiend was an unmitigated terror.\n\nTo the southeast you will find Netherwing Ledge. What was once part of the mainland of Shadowmoon is now a floating island in the sky.\n\nVhel'kur, spawn of Deathwing, once called it his home, but now knows it as his grave. He flies an endless circle above the island, seething at his defeat to Gorefiend.\n\nIf you are to recover the Gorefiend's armor, it is Vhel'kur that you must defeat.", objectives = "" }
WordHunterWoW_QuestEN[10635] = { title = "Divination: Gorefiend's Cloak", description = "Many a cruel act he committed but none so cold as the slaughter of the clerics of Karabor.\n\nAfter Gul'dan's Horde defeated the draenei of Karabor, the surviving clerics of Karabor were marched out, told that they were to be taken to Hellfire Citadel as prisoners of war.\n\nGorefiend, not yet a death knight, murdered each and every last one of them in cold blood. They now roam in front of the Black Temple with vengeance in their hearts.\n\nIt is the clerics of Karabor that hold the cloak of Gorefiend.", objectives = "" }
WordHunterWoW_QuestEN[10636] = { title = "Divination: Gorefiend's Truncheon", description = "One by one they knelt before him, offering their lives as a show of allegiance. Gorefiend hoisted his sickle and cut clean their heads. Shortly after this slaughter, Gorefiend took his own life.\n\nBut this was no act of contrition! No, Gorefiend sought immortality! From the corpses of the fallen death knights rose the Ghostriders of Karabor.\n\nThey now ride the roads encircling the Hand of Guldan, awaiting the day that their master returns. It is they who hold the truncheon of Gorefiend. Retrieve it...", objectives = "" }
WordHunterWoW_QuestEN[10637] = { title = "A Necessary Distraction", description = "The weapons are authentic, as we feared.  Illidan is training demon hunters at the Ruins of Karabor and we must put an end to it.\n\nDo not be fooled by their name, {name}, their power will be used against us as often as against any demon.\n\nTheir warlocks summon and subdue demons to be used as part of the initiates' training.  A pit lord named Azaloth has proven too strong to be used in training and is kept banished.  Find a way to let him loose on his captors.  That should buy us the time we need.", objectives = "" }
WordHunterWoW_QuestEN[10639] = { title = "Teron Gorefiend, I am...", description = "With Gorefiend's items restored, there is but one last piece to this puzzle: A host.\n\n<The ancient shadowmoon spirit's lips curl up  to form a wicked grin.>\n\nSurely you did not believe the fairy tale that I told you. The Altar of Shadows is my prison. Without your help, I would have been stuck here for all eternity. Now, I will take over your body and you will destroy my captors and break these bonds. Refuse and we will both be stuck here forever.\n\nTeron Gorefiend will be free!", objectives = "" }
WordHunterWoW_QuestEN[10640] = { title = "Altruis", description = "It is rare in this day and age to hear of those who follow the path of the demon hunter.  It is rarer still to find someone who does and has no allegiance to Illidan.\n\nThere are rumors of one such individual here in Outland.  One name is said to be feared in the Legion fields of Nagrand more than any army of Aldor vindicators.  That name is Altruis.\n\nGo to western Nagrand and find him.  He might be willing to shed some light on these new demon hunter training grounds.", objectives = "" }
WordHunterWoW_QuestEN[10641] = { title = "Against the Legion", description = "The Burning Legion has proven its capacity to corrupt mortal souls time and again.  If I'm to entrust you with the knowledge you seek, I must have proof of your allegiance.\n\nA demoness known as Sathal has eluded me for a long time as she's gifted with an incorporeal form.\n\nShe watches over the wrath priestesses as they do her bidding at Forge Base: Gehenna.  Slay one of her minions and spill her blood on the ground.  This affront should cause Sathal to materialize temporarily.  Slay her while you can.", objectives = "" }
WordHunterWoW_QuestEN[10642] = { title = "A Ghost in the Machine", description = "I fear that these dwarves do not understand what they have built upon. This area was once the ancestral grounds for the Shadowmoon orcs. I speak of spirits, {race}.\n\nFor nearly twenty years they have laid dormant beneath the Wildhammer Stronghold, but recently, something has riled them up.\n\nVenture beyond the gates of Wildhammer and seek out the pools and rivers of fel lava found across this land. Near the lava will be ever-burning ash. Bring me this ash so that I may craft something that will help us.\n", objectives = "" }
WordHunterWoW_QuestEN[10643] = { title = "Harbingers of Shadowmoon", description = "Let it be known that Zorus does have a sense of humor.\n\nEnough small talk. Don the Spectrecles so that you are able to see the Shadowmoon orc spirits that wander this stronghold. Do not be frightened as we are truly the invaders here. Alas, they must be destroyed, for their time has long since passed.\n\nDestroy the Shadowmoon harbingers infesting Wildhammer Stronghold and return to me.", objectives = "" }
WordHunterWoW_QuestEN[10644] = { title = "Teron Gorefiend - Lore and Legend", description = "Stories abound about the life of Teron Gorefiend, but most are just that - stories. We do not know what happened to Gorefiend after he returned to Draenor.\n\nThe only thing we are certain of is that he has already died once.\n\nI have heard the scouts here speaking of an ancient orc spirit that resides at the Altar of Shadows, far to the east, across the Netherwing Fields and through Netherwing Pass. Take the Spectrecles and track this orc down. He will surely have more information on Gorefiend.", objectives = "" }
WordHunterWoW_QuestEN[10645] = { title = "Teron Gorefiend, I am...", description = "With Gorefiend's items restored, there is but one last piece to this puzzle: A host.\n\n<The ancient shadowmoon spirit's lips curl up  to form a wicked grin.>\n\nSurely you did not believe the fairy tale that I told you. The Altar of Shadows is my prison. Without your help, I would have been stuck here for all eternity. Now, I will take over your body and you will destroy my captors and break these bonds. Refuse and we will both be stuck here forever.\n\nTeron Gorefiend will be free!", objectives = "" }
WordHunterWoW_QuestEN[10646] = { title = "Illidan's Pupil", description = "You've proven your allegiance, {name}.  You must forgive my caution, but in this world things are not what they appear.\n\nI will tell you about Varedis when you're ready.", objectives = "" }
WordHunterWoW_QuestEN[10647] = { title = "WANTED: Uvuros, Scourge of Shadowmoon", description = "Wanted - DEAD:\n\nUvuros, scourge of Shadowmoon Valley.\n\nBy order of Overlord Or'barokh, the fel beast, Uvuros, is to be killed on sight and his mane stripped from his carcass as proof of deed. Return the fiery mane of the beast to Warcaller Sardon Truslice should you succeed.\n\nUvuros was last seen at the Hand of Gul'dan, located in the heart of Shadowmoon Valley - east of Shadowmoon Village.", objectives = "" }
WordHunterWoW_QuestEN[10648] = { title = "WANTED: Uvuros, Scourge of Shadowmoon", description = "Wanted - DEAD:\n\nUvuros, scourge of Shadowmoon Valley.\n\nBy order of Thane Yoregar, the fel beast, Uvuros, is to be killed on sight and his mane stripped from his carcass as proof of deed. Return the fiery mane of the beast to Warcaller Beersnout should you succeed.\n\nUvuros was last seen at the Hand of Gul'dan, located in the heart of Shadowmoon Valley - northeast of Wildhammer Stronghold.", objectives = "" }
WordHunterWoW_QuestEN[10649] = { title = "The Book of Fel Names", description = "I sympathize with your intentions of stopping Varedis and his followers, but you won't stand a chance against him.  That is, unless you find the artifact that gave him his power.\n\nThe Book of Fel Names is rumored to be in the possession of Blackheart the Inciter inside the Shadow Labyrinth in Auchindoun.  Obtaining it will be your only hope against Varedis.", objectives = "" }
WordHunterWoW_QuestEN[10650] = { title = "Return to the Aldor", description = "This book... I could use it to increase my power tenfold...  No!  It would end up corrupting my very soul, this I am sure of.  Return to those who sent you here, {name}.\n\nYou now have the means to stop Varedis.  Wait until he manifests his demonic form through metamorphosis, at that point you will need to burn the book in his presence.  That will be the only way you can deprive him of his power.", objectives = "" }
WordHunterWoW_QuestEN[10651] = { title = "Varedis Must Be Stopped", description = "We must dispose of this foul artifact, but not before we use it to dispose of Varedis's powers.\n\nWe need to permanently shut down the Ruins of Karabor training grounds, which will mean killing not only Varedis but also the three night elf masters that assist him: Alandien, Theras and Netharel.\n\nGather a suitable force and return to the Ruins of Karabor.  Follow Altruis's instructions for defeating Varedis.  For all of our sakes, I hope they work.", objectives = "" }
WordHunterWoW_QuestEN[10652] = { title = "Behind Enemy Lines", description = "All arrangements have been made to take you to where our spies are hiding.  Just come see me when you're ready and we'll get you on your way.", objectives = "" }
WordHunterWoW_QuestEN[10653] = { title = "Marks of Sargeras", description = "By now it should be clear to you why we oppose the Burning Legion and those who serve them.\n\nIf you wish to prove yourself to the Aldor, bring me the insignias of high-ranking Legion and their Shadow Council followers.  The highest-ranking Legion can be found in Netherstorm and Shadowmoon Valley.", objectives = "" }
WordHunterWoW_QuestEN[10656] = { title = "Sunfury Signets", description = "As you might know, the Scryers and the armies of Kael'thas are at war.  Kael sees us as a threat to his influence over other blood elves and has tried to crush us time and again.\n\nIf you wish to aid us in our battle against Kael'thas, there are plenty of targets for you to go after.  Kael's highest ranking soldiers wear Sunfury signets to mark their ranks.  You will find them all over Netherstorm and Shadowmoon Valley.", objectives = "" }
WordHunterWoW_QuestEN[10657] = { title = "Ride the Lightning", description = "We haven't kept the use of the Zephyrium Capacitorium under budget.  But, it occurs to me that the serpents of the Scalewing Shelf to the east have a lightning breath and glands that we can make use of.\n\nI've repolarized the magneto collector to absorb lightning strikes and I want you to head up there, activate it on yourself, and get us some cheap fuel from those serpents.", objectives = "" }
WordHunterWoW_QuestEN[10660] = { title = "What Strange Creatures...", description = "I am interested in learning more about the strange reptiles that mill about the lava flows of Shadowmoon Valley. Never have I seen beasts able to withstand the searing heat of molten lava!\n\nOutside of Shadowmoon Village, where the ground has ruptured and lava flows through the cracks, you will find felfire diemetradons. Slay them and bring me their spleens. From their spleens I will be able to begin preliminary analysis of their resistance to heat.\n\nBegin your search to the southeast.\n", objectives = "" }
WordHunterWoW_QuestEN[10661] = { title = "Spleendid!", description = "Have you ever heard of food that cooks itself and stays hot forever? Dare to dream, I say!\n\nBut maybe it's not a dream at all! Outside the fortress, near the lava pools and streams, you can find beasts that thrive in the sizzling heat. They're called felfire diemetradons.\n\nThe dwarves around here tell me that those diemetradons have the tastiest spleens ever and that the spleens practically come pre-cooked! Bring me those spleens and I'll give you some coin.\n\nStart your search directly east of here.", objectives = "" }
WordHunterWoW_QuestEN[10662] = { title = "The Hermit Smith", description = "<Ordinn examines the results from his attempt at smithing the metal and shakes his head.>\n\nThis is beyond my ability, but that's not to say the weapon can't be recreated for your use.\n\nThere was a talented smith who accompanied the Sons of Lothar to Draenor, David Wayne. He was a remarkable blacksmith, but chose to leave the expedition. These days, he lives in a small camp on a peninsula east of Firewing Point in Terokkar Forest. Take the ingots to him and see if he can help you with the weapon.", objectives = "" }
WordHunterWoW_QuestEN[10663] = { title = "The Hermit Smith", description = "<The orc shakes his head at his failure.>\n\nThis is beyond my ability, but that's not to say the weapon can't be recreated.\n\nIt pains me to suggest this, but your only hope may be a human smith by the name of David Wayne. It's true he was once a member of the Alliance's expedition, but that was a long time ago and he has since left the Sons of Lothar. These days, he lives in a small camp on a peninsula east of Firewing Point in Terokkar Forest. Take the ingots to him and see if he can help you.", objectives = "" }
WordHunterWoW_QuestEN[10664] = { title = "Additional Materials", description = "The ingots that you brought contain most of the metal I'll need to forge the sword's blade, but I'll need a variety of things to create other parts of the weapon.\n\nLet's see, among the things I don't have here are an adamantite frame, some heavy knothide leather, and a demon warding totem. Skilled crafters should be able to produce the first two, but the third is only sold by the reagent vendor in Shattrath's Lower City, Fantei. You'll find him with the other tradesmen.", objectives = "" }
WordHunterWoW_QuestEN[10665] = { title = "Fresh from the Mechanar", description = "Working with the ingots you brought is going to require a lot of heat -- rather more than a conventional forge can supply.\n\nI'm going to need a supplemental heat source for the forge and there are very few things in Outland that can supply that kind of power.\n\nThe Mechanar area of Tempest Keep turns out manacells containing an incredible amount of power. Find one of the overcharged manacells from the stacks around Mechano-Lord Capacitus and bring it back here.", objectives = "" }
WordHunterWoW_QuestEN[10666] = { title = "The Lexicon Demonica", description = "Recreating the enchantments on the blade requires several spells to be spoken in demonic.\n\nIt's not something I was taught during my training as an apprentice, but there's no way around it. There's a book, called the Lexicon Demonica, that will provide most of the words I need, but it's in the hands of a powerful Shadow Council warlock.\n\nDeep in the halls of Auchindoun's Shadow Labyrinth, it is held by Grandmaster Vorpil. Do whatever you must to secure the book and bring it to me. ", objectives = "" }
WordHunterWoW_QuestEN[10667] = { title = "Underworld Loam", description = "The frame that you brought me earlier will not be sufficient to hold molten metal without reinforcement. A rare kind of earth can be used to cool and imbue the frame, giving the adamantite an unnatural strength.\n\nUnderworld loam, as the earth is known, is accorded great value among the naga. Few enough of them possess it, and in Outland, I know of only one naga who uses it -- Hydromancer Thespia, who resides in the Steamvault of Coilfang Reservoir.", objectives = "" }
WordHunterWoW_QuestEN[10668] = { title = "Against the Illidari", description = "I still have respect for Illidan.  Without him I would not have found my path.\n\nHe is not who he once was, however.  His soul has been corrupted by power, his mind has been twisted by defeat.  He has become what I am sworn to destroy and his pet servants, the Illidari, are as much of an abomination as any demon of the Burning Legion.\n\nHis grasp on Outland is slipping yet his reach is still vast.  Prove you're not with him by slaying his lieutenant Lothros at Illidari Point in Shadowmoon Valley.", objectives = "" }
WordHunterWoW_QuestEN[10669] = { title = "Against All Odds", description = "Some demons pledge allegiance to no one but themselves.  A true enemy of demons finds and destroys his prey regardless of affiliation, however.\n\nThe demon Xeleth - a Legion defector - was once worshipped as a god by primitive swamp creatures in Zangarmarsh.  When Draenor was nearly destroyed, he retreated into a slumber deep beneath Marshlight Lake.  Find the portal at the lake and plant this spear into the ground.\n\nXeleth will awake - be ready to slay him and prove you're an enemy to all demons.", objectives = "" }
WordHunterWoW_QuestEN[10670] = { title = "Tear of the Earthmother", description = "The sword's enchantments must be contained within a powerful focus, such as a gem. I know of a gem that we can use for this purpose, for there are few that can play host to such powerful magics without shattering.\n\nThe gem we need is called the tear of the earthmother. It's a powerful artifact in the hands of the ogres who created it, and Warbringer O'mrogg, who currently holds the gem, has many powerful allies in Hellfire Citadel's Shattered Halls. Take care in retrieving the tear, {name}.", objectives = "" }
WordHunterWoW_QuestEN[10671] = { title = "More than a Pound of Flesh", description = "{name}, I've got something else for you to do.  One of the eggheads wants to study the fiendling flesh beasts that can be found at Razaan's Landing, north of the Razor Ridge.\n\nMore to the point, they want to study the flesh of the flesh beasts that are there.\n\n<Dizzy makes a disgusted face.>\n\nBut, of course, they aren't willing to get their hands dirty, and they only want the ether-energized flesh, which it's not likely that all of them have.\n\nI say, beggars can't be choosers, but what can you do?", objectives = "" }
WordHunterWoW_QuestEN[10672] = { title = "Frankly, It Makes No Sense...", description = "We must study these creatures further.\n\nFar to the east - near the huge lava flow beneath the ruins of Baa'ri - you will find arcano control units. These controllers were crafted by a genius named Gnomus for the sole purpose of exploring lava via mechanical scorpion.\n\nHe has long since lost his mind and is now only interested in eating the hottest food known to gnome-kind.\n\n<Tiorus gives you a funny look.>\n\nI want you to use the control and tag the diemetradons of the lava flow for further study.\n", objectives = "" }
WordHunterWoW_QuestEN[10673] = { title = "Felspine the Greater", description = "Gnomus knows about the massive diemetradon and plans to eat it! He must have been able to see what I could see through the eyes of his arcano-scorp. Look, there's no time to explain. He's crazy and that craziness is going to cost us the closest thing we've got to a fireproof jumpsuit.\n\nGet back to the lava flow near Baa'ri and track down Felspine the Greater. Once you find it, kill it and bring me back its hide.\n\nDon't try and reason with me, {name}. I'm well past that point.", objectives = "" }
WordHunterWoW_QuestEN[10674] = { title = "Trapping the Light Fantastic", description = "The Razaani ethereals have been playing with some interesting technology at Razaan's Landing to the north.\n\nI'm sure they won't mind if you use this trap to take a few samples of their little pink floating light orbs?  They're probably only for decoration anyway.\n\nThe trap has a special property to it that when opened should attract one of the floating balls towards it.  Of course, it'll probably also alert the Razaani to your presence.", objectives = "" }
WordHunterWoW_QuestEN[10675] = { title = "Show Them Gnome Mercy!", description = "<The blood drains out of Toshley's face.>\n\nThese orbs are made up of both nether energy and souls, some of them gnome souls!\n\nHow dare they!  Were they the ones killing our people that traveled north?!\n\n{name}, you must put a stop to this, and the only way to do that is to finish off their leader, Nexus-Prince Razaan.\n\nYou'll have to coax him out of hiding though.  I'm guessing that you can do that by killing a lot of his Razaani ethereal.\n\nBring me the collection of souls that he no doubt has.", objectives = "" }
WordHunterWoW_QuestEN[10676] = { title = "Bane of the Illidari", description = "<David gathers his smithing supplies.>\n\nYou've done well in getting everything we'll need to reforge the anti-demon blade. Your hard work and dedication is about to be repaid.\n\nThe time has come to forge the sword.", objectives = "" }
WordHunterWoW_QuestEN[10677] = { title = "The Second Course...", description = "I remember seeing larger diemetradons east of the Hand of Gul'dan, near the lava flows around the Ruins of Baa'ri. What I want you to get for me now is one overdeveloped felfire gizzard from the beasts around that area. You might have to kill several to find a gizzard like the one I described. Keep at it! One of them is bound to have my next meal.", objectives = "" }
WordHunterWoW_QuestEN[10678] = { title = "The Main Course!", description = "Long story short, I used to work with a blood elf named Tiorus. My partnership with Tiorus dissolved once I got into gourmet living. He decided to take it upon himself to continue our research using MY inventions. Anyhow, he had some of his Horde goons using my arcano-scorp probes at the Ruins of Baa'ri lava flow and discovered the mother of all diemetradons!\n\nI need you to get there before he does and kill the diemetradon, Felspine, and bring his hide back to me.\n\nHurry up!", objectives = "" }
WordHunterWoW_QuestEN[10679] = { title = "Quenching the Blade", description = "The blade is nearly finished!\n\nYou can almost feel the magic beginning to coalesce inside the steel, but one thing remains to be done.\n\nYou must take the forged blade to the Scalding Pools near the top of the Hand of Gul'dan in Shadowmoon Valley and plunge it into the lava pools to quench the sword. When you have quenched the sword, return.", objectives = "" }
WordHunterWoW_QuestEN[10680] = { title = "The Hand of Gul'dan", description = "The elements need your help, {race}! Shadowmoon Valley has been subject to unspeakable evils. The spirits remain tortured to this day. Many are enraged and unwilling to commune with the Earthen Ring.\n\nHelp this world heal, friend.\n\nDirectly northeast of Wildhammer Stronghold you will find an area known as the Altar of Damnation. Make your way there and speak with Earthmender Torlok.", objectives = "" }
WordHunterWoW_QuestEN[10681] = { title = "The Hand of Gul'dan", description = "The elements need your help, {race}! Shadowmoon Valley has been subject to unspeakable evils. The spirits remain tortured to this day. Many are enraged and unwilling to commune with the Earthen Ring.\n\nHelp this world heal, friend.\n\nSoutheast of Shadowmoon Village - in the heart of Shadowmoon Valley - you will find an area known as the Altar of Damnation. Make your way there and speak with Earthmender Torlok.", objectives = "" }
WordHunterWoW_QuestEN[10682] = { title = "A Time for Negotiation...", description = "When we arrived in the Ruuan Weald, the wyrm cultists were keeping themselves to Blackwing Coven, through the tunnel to the west.  But now, they are encroaching upon us here.\n\nI need you to find the wyrmcultists' overseer.  He's known to make a regular patrol between their various camps in the Ruuan Weald.\n\nNegotiate with him.  Let him know that there's room for compromise, but that we will not condone or allow the wholesale slaughter of the wildlife, nor the felling of all of the trees.", objectives = "" }
WordHunterWoW_QuestEN[10683] = { title = "Tablets of Baa'ri", description = "The Ashtongue Broken have been ordered by Illidan to excavate the Ruins of Baa'ri, to the far north.  They're in search of draenei artifacts, no doubt - Baa'ri was home to many Baa'ri relics before Gul'dan buried the town under a volcanic explosion.  We must use this opportunity to recover the Tablets of Baa'ri, an ancient text rumored to hold the secrets of the Temple of Karabor... a place you might know as the Black Temple.", objectives = "" }
WordHunterWoW_QuestEN[10684] = { title = "Oronu the Elder", description = "According to the tablets, an artifact known as a Medallion of Karabor was kept at Baa'ri.  Only the highest-ranking draenei priests were granted these, as they allowed unfettered access into the Temple of Karabor.\n\nWe must find out whether the Ashtongue have recovered the medallion that was kept at Baa'ri yet.  Its power would provide great aid in our fight against Illidan.\n\nAkama's lieutenant at Baa'ri, Oronu the Elder, receives written orders from him daily.  Obtain them and bring them to me.", objectives = "" }
WordHunterWoW_QuestEN[10685] = { title = "The Ashtongue Corruptors", description = "According to Akama's letter, four fragments of the medallion were unearthed and given to the Ashtongue Corruptors.  These dreaded Broken were once powerful shaman who now defile the very elements they revered.\n\nHaalum, Corruptor of Air, can be found at Netherwing Pass.  Eykenen and Uylaru, Corruptors of Earth and Fire, were last seen at the Fel Pits near the Hand of Gul'dan.  Lakaan, Corruptor of Water, is rumored to be near Coilskar Point.\n\nFind them and obtain the medallion fragments.", objectives = "" }
WordHunterWoW_QuestEN[10686] = { title = "The Warden's Cage", description = "The fragments you obtained are only half of the medallion.  The Ashtongue leader, Akama, must have kept the other half.\n\nI dread to ask this of you, as Akama is both evil and cunning.\n\nHe and the Ashtongue Deathsworn - the vilest and most brutal of the tribe - are rumored to run a torture chamber inside the Warden's Cage.\n\nI want you to find that dreaded prison,  and find the whereabouts of Akama.  His second in command at the location is a Broken known as Sanoru - interrogate him if you have to.", objectives = "" }
WordHunterWoW_QuestEN[10687] = { title = "Karabor Training Grounds", description = "Our scouts have reported a massive influx of Sunfury blood elf recruits heading to the Ruins of Karabor.  Normally this would represent a purely military threat, however we believe something else is amiss.\n\nDescriptions of their attire and fighting style are suspiciously close to that of Illidan himself.  I do not want to become alarmed without good reason, so I would like you to go there and bring me back their weapons.  We will then determine whether my fears are unfounded or not.", objectives = "" }
WordHunterWoW_QuestEN[10688] = { title = "A Necessary Distraction", description = "The weapons are authentic, as we feared.  Illidan is training demon hunters at the Ruins of Karabor and we must put an end to it.\n\nDo not be fooled by their name, {name}, their power will be used against us as often as against any demon.\n\nTheir warlocks summon and subdue demons to be used as part of the initiates' training.  A pit lord named Azaloth has proven too strong to be used in training and is kept banished.  Find a way to let him loose on his captors.  That should buy us the time we need.", objectives = "" }
WordHunterWoW_QuestEN[10689] = { title = "Altruis", description = "You don't see many demon hunters nowadays.  They're viewed with suspicion by their own people and it's very rare to find one that doesn't have some sort of allegiance to Illidan.\n\nThere are rumors of one such demon hunter out in Nagrand.  His name is Altruis.  He hates all demons with a passion and will help us if you can convince him that you share his goals.\n\nGo to western Nagrand and find him.  He might be willing to shed some light on these new demon hunter training grounds.", objectives = "" }
WordHunterWoW_QuestEN[10690] = { title = "The Den Mother", description = "WANTED!\n\nRema, the den mother and primary defender of the Jagged Ridge south of Thunderlord Stronghold.\n\nFind her by heading east out of town and across the bridge that traverses the Bloodmaul Ravine.  She keeps herself secluded in the tunnel at the southern edge of the ridge.\n\nReturn with news of her demise to Commander Skyshadow of Sylvanaar.", objectives = "" }
WordHunterWoW_QuestEN[10691] = { title = "Return to the Scryers", description = "This book... I could use it to increase my power tenfold...  No!  It would end up corrupting my very soul, this I am sure of.  Return to those who sent you here, {name}.\n\nYou now have the means to stop Varedis.  Wait until he manifests his demonic form through metamorphosis, at that point you will need to burn the book in his presence.  That will be the only way you can deprive him of his power.", objectives = "" }
WordHunterWoW_QuestEN[10692] = { title = "Varedis Must Be Stopped", description = "Of course we must destroy this book, but not before we use it to destroy Varedis.\n\nIf we're to shut down this academy of Illidan imitators, we'll have to deal not just with Varedis but also the three night elf masters that assist him: Alandien, Theras and Netharel.\n\nGather a suitable force and return to the Ruins of Karabor.  Follow Altruis's instructions for defeating Varedis.  Hopefully his plan will work - otherwise... it'll have been a pleasure working with you.", objectives = "" }
WordHunterWoW_QuestEN[10701] = { title = "Breaking Down Netherock", description = "To whomever cares about the timely construction of the X-52 Nether-Rocket --\n\nThe king of the local mountain giants, Netherock, has been terrorizing the Crumbling Wastes.  He's been interfering with operations all along the south ledge of the island!\n\nTake your friends and deal with him!  Then, return to me here in Area 52.\n\nRocket-Chief Fuselage", objectives = "" }
WordHunterWoW_QuestEN[10702] = { title = "A Grunt's Work...", description = "All Horde forces in this region have been dispatched to handle the attacks from the Burning Legion. This means that we are short-handed for grunt work.\n\nOur supply caravans are in constant danger from the wildlife of the region. We can't veer 15 feet off the road without running into a chimaera, felboar, or abnormally large scorpion.\n\nGet out there and clear Shadowmoon Valley of its sadistic wildlife! Just kill 'em all!", objectives = "" }
WordHunterWoW_QuestEN[10703] = { title = "Put On Yer Kneepads...", description = "It's time to get down in the muck and get dirty. What were you expectin'? You gotta learn to walk before you can crawl, right? Er, reverse that...\n\nAnyway, we got all hands on deck fer killin' the garbage being thrown at us by the Burning Legion. That leaves you with the honor of cleaning up the crazed wildlife of Shadowmoon Valley.\n\nGrab a sword, staff, whatever it is that makes you happy, and kill as much of the wildlife as you can see. That'll clear a way out for our supply caravans!", objectives = "" }
WordHunterWoW_QuestEN[10704] = { title = "How to Break Into the Arcatraz", description = "A message was embedded in the ata'mal crystal that you recovered.  Nexus-Prince Haramad has given us information vital to our campaign against Tempest Keep.\n\nHe tells us that there are two pieces, shards to a key, which, when combined, will unlock the keep's Arcatraz satellite.\n\nOne half is possessed by an ancient in the Botanica known as Warp Splinter.  The other is held by Pathaleon the Calculator inside the Mechanar.\n\nBring both shards to me and I will combine them into the Arcatraz key.", objectives = "" }
WordHunterWoW_QuestEN[10705] = { title = "Seer Udalo", description = "I hope you're not shocked when I reveal to you that the pieces of the Medallion of Karabor you obtained from my minions are mere replicas.\n\n<Akama shows you an identical medallion in his open palm.>\n\nMy Deathsworn and I have kept the secret from Illidan for as long as possible.   We are however, still missing the final piece.\n\nUdalo came to me in dreams  to announce he had found it.  Unfortunately he is held by Kael'thas inside the Arcatraz in Tempest Keep.  Find him and see what he knows.", objectives = "" }
WordHunterWoW_QuestEN[10706] = { title = "A Mysterious Portent", description = "Before he died, Udalo appears to have written a single word on the floor beneath him.  The writing is barely legible but you recognize the word Atam'al.\n\nPerhaps Akama will understand the meaning of his brethren's message.", objectives = "" }
WordHunterWoW_QuestEN[10707] = { title = "The Ata'mal Terrace", description = "It has been known to us that the fel orcs, under Illidan's command, have guarded an Ata'mal crystal known as the Heart of Fury at the Ata'mal Terrace.  They cloud its presence with dark magic, to keep it from the Sha'tar.\n\nFight your way to the Ata'mal Terrace outside the Black Temple and turn your eyes to the sky.  Shadowlord Deathwail will circle the terrace, beyond your reach.  You will have to slay him and his warlocks before you can obtain the crystal.\n\nIt won't be easy, {name}.  I wish you luck.", objectives = "" }
WordHunterWoW_QuestEN[10708] = { title = "Akama's Promise", description = "<Akama inserts the crystal into the medallion in his hand.>\n\nI am not as strong as I once was, {name}.  Being so close to evil itself all these years - I do not know if I can trust myself with an artifact as powerful as this.\n\nTake this as my promise to you that when the time comes and you face Illidan, I will be on your side.  Take it to the one being we know we can trust with its power.  Take the medallion to A'dal in Shattrath City.", objectives = "" }
WordHunterWoW_QuestEN[10709] = { title = "Reunion", description = "So you come from the world beyond the Portal? And you know of Rexxar. Oh yes, I am quite familiar with him.\n\nYou see, he is my son.\n\nBut he made his choice a lifetime ago. He is not one of us, and he is not welcome here. We have enough troubles with the Bloodmaul ogres.\n\nKnow this: being born a half-breed does not make you Mok'Nathal.", objectives = "" }
WordHunterWoW_QuestEN[10710] = { title = "Test Flight: The Singing Ridge", description = "I've been fiddling with the Zephyrium Capicitorium and I'm ready to perform another test!  Do you want to help?\n\nThis next flight should be short, but fast!\n\nUm... and although I'm sure there's no danger... I have this, uh, waiver that I'd like  you to sign.  It's just a formality, I assure you!\n\nBest of luck!  Talk to Rally to launch yourself, and come back to me after the experiment is over!", objectives = "" }
WordHunterWoW_QuestEN[10711] = { title = "Test Flight: Razaan's Landing", description = "{name}, I raised the efficiency of the Zephyrium Capacitorium by 30 percent.  That will launch a test subject of your weight and wind drag ratio to new heights!  Want to test my theory?  This experiment ought to send you near Razaan's Landing.\n\nSpeak with Rally... he'll get you prepared for launch.", objectives = "" }
WordHunterWoW_QuestEN[10712] = { title = "Test Flight: Ruuan Weald", description = "Hey, {name}.  I'm glad I caught you!  I have a very important mission!\n\nHere is a nether-weather vane.  I need you to take some in flight readings for me and deliver them to my cousin in Ruuan Weald.\n\nSpeak with Rally and take a Zephyrium Capacitorium flight to Ruuan Weald.  While you're flying, spin the vane!\n\nAfter you land, bring the spinning vane to O'Mally Zabnabber.\n\nGood luck, {name}.  And don't delay!", objectives = "" }
WordHunterWoW_QuestEN[10713] = { title = "...and a Time for Action", description = "We will not stand idly by while they decimate the Ruuan Weald around us.  Our first priority must be to the trees.\n\n{class}, I want you to go back out into the Weald and deliver a very different message for us.  I want you to slay every one of their hewers that you come into contact with!\n\nIf they will not listen to reason, perhaps they will listen to a more assertive method of persuasion!", objectives = "" }
WordHunterWoW_QuestEN[10714] = { title = "On Spirit's Wings", description = "If the Mok'Nathal are tormented by the Bloodmaul ogres, then I will stop them and their followers. Ogres are simple creatures, and there is little profit they could gain from harassing the Mok'Nathal.\n\nThere must be something more to this. {name}, take Spirit, my hawk, and spy upon the conversations of the Bloodmaul's leaders. He may go undetected where we cannot.", objectives = "" }
WordHunterWoW_QuestEN[10715] = { title = "Into the Churning Gulch", description = "So, your Rexxar would have me fashion a poison for him? I'll give him what he desires, but there will be a price. Even for friends, there must be a price. Free things destroy friendships.\n\nFirst, you must venture a short distance to the southwest to the Churning Gulch.\n\nTherein mill some of the most poisonous creatures in all of Outland, or anywhere. I speak of the crust bursters, and this poison will require gathering their glands for me.", objectives = "" }
WordHunterWoW_QuestEN[10717] = { title = "Poaching from Poachers", description = "Pardon me, but I couldn't help but overhear your conversation with Chawn.  I'd like to help.\n\nI'm studying the Blackwing Coven, and helping the druids in their dealings with them.\n\nI am very interested in acquiring a few of their dragon whelps; it would help us to gauge exactly what we're up against by understanding that which they revere.\n\nBut first, we're going to need to acquire some nets.  I noticed that the wyrmcult poachers out in the Ruuan Weald have an abundance of them.", objectives = "" }
WordHunterWoW_QuestEN[10718] = { title = "The Spirits Have Voices", description = "{name}, now that you can see me, there is something you must tell Rexxar. I know that he seeks his people, and I know where they are.\n\nThe Mok'Nathal, as they are known, have a village to the east beyond the Razor Ridge.\n\nGo, give Rexxar this news. His people are in danger, and I know that he will want to come to their aid.", objectives = "" }
WordHunterWoW_QuestEN[10719] = { title = "Did You Get The Note?", description = "The cultist dropped this note, which apparently was to be delivered to Overseer Nuaar.  It is signed by someone named Kolphis Darkscale.\n\nIt is likely that Tree Warden Chawn will be interested in looking at this.", objectives = "" }
WordHunterWoW_QuestEN[10720] = { title = "The Smallest Creatures", description = "The ogres, simple as they are, would notice you dispersing this poison throughout their camp. Thus, I will teach you how to enlist the help of one of nature's smallest creatures to do this task.\n\nBy playing a simple rhythm on this drum, you can coax a marmot to follow your commands.\n\nThere is a den of marmots near the Bloodmaul camp, to the north, down in the Daggermaw Canyon past the Circle of Blood.\n\nOnce you have a marmot's aid, use it to disperse the poison to the Bloodmaul's kegs.", objectives = "" }
WordHunterWoW_QuestEN[10721] = { title = "A Boaring Time for Grulloc", description = "{name}, I have a pet boar named Huffer. He wants to help you to have some fun with one of the nearby sons of Gruul.\n\nGrulloc inhabits a place known as the Cursed Hollow. When you get there, let Huffer loose. The gronn will have a fine time chasing him around, and you will retrieve the bag that he guards and deliver it to Baron Sablemane.\n\nTo get to the Cursed Hollow, head down the northern ramp and east through Dragons' End. The hollow is on the eastern edge.", objectives = "" }
WordHunterWoW_QuestEN[10722] = { title = "Meeting at the Blackwing Coven", description = "I know what must be done!  {name}, you must pose as Overseer Nuaar and attend that meeting!\n\nThe wyrmcultists at the coven all have a standard outfit that they wear, so go collect scraps from them, and when you have enough, put together a disguise.\n\nPose as Overseer Nuuar and speak with Kolphis Darkscale to see what he has to say, and then return to Tree Warden Chawn.\n\nYou'll find the coven by heading through the Wyrmskull Tunnel and following the path past the Raven's Wood and Grishnath to its end.", objectives = "" }
WordHunterWoW_QuestEN[10723] = { title = "Gorgrom the Dragon-Eater", description = "The gronn we seek is Gorgrom the Dragon-Eater. With Sablemane's trap, you will make short work of the gronn. You will find him accepting sacrifices from the ogres of Boulder'mok.\n\nFollow the road north from the Circle of Blood, then west at Ruuan Weald. Go northwest through the tunnel.\n\nFirst, kill the ogres for their heads. We will send a message. Set the trap at his altar. When he is dead, plant the grisly totems near him - none can mistake that message.\n\nTake the bear.\n\n<Misha growls.>", objectives = "" }
WordHunterWoW_QuestEN[10724] = { title = "Prisoner of the Bladespire", description = "Shortly after my arrival in the mountains, I came under attack by a group of Bladespire ogres.\n\nThough I fought free of them, and slew many, they took my wyvern, Leokk, captive. Spirit has found him, locked in a cage in the heart of the Bladespire encampment outside of Gruul's lair.\n\nOne of the ogres must carry his key. Find it and Spirit can use it to unlock Leokk's cage.\n\nYou will find the encampment at the north end of the Daggermaw Canyon down below.", objectives = "" }
WordHunterWoW_QuestEN[10742] = { title = "Showdown", description = "Now it comes to this. We will bring Goc forth from his lair, and we will destroy him. With Goc dead, the Bladespire ogres will threaten the Mok'Nathal no longer. Go to Goc's altar outside Gruul's Lair, then blow my horn. I will come, and we will face the son of Gruul together.", objectives = "" }
WordHunterWoW_QuestEN[10744] = { title = "News of Victory", description = "You must bring word of our success to Kurdran Wildhammer immediately! His men, under Wing Commander Nuainn, have fought nonstop to keep Wildhammer Stronghold safe and your return will surely bolster their spirits. With the threat from the Legion out of the way, Kurdran can finally turn his attention to dealing with the forces of Illidan. Our place here is far from secure, but we've won a major victory this day.", objectives = "" }
WordHunterWoW_QuestEN[10745] = { title = "News of Victory", description = "You must bring word of our success to Overlord Or'barokh immediately! Now that we've crushed the Legion and obliterated their presence in Shadowmoon Valley, the overlord can turn his attention to our other foes.\n\nAlthough the Kor'kron guard will never admit it, they'll be glad we're no longer fighting on two fronts.", objectives = "" }
WordHunterWoW_QuestEN[10747] = { title = "Whelps of the Wyrmcult", description = "I need to examine the whelps that they are raising at the Blackwing Coven.\n\nThere should be an abundance of them flying around inside their cavernous base, as well as a number of eggs, which if you get close to them will likely hatch.\n\nPlease, {name}, take the net and capture a handful of them alive for me.\n\nFind them by heading west across the Wyrmskull Bridge and heading through the Wyrmskull Tunnel.  Follow the path to its end past Grishnath and the Raven's Wood.", objectives = "" }
WordHunterWoW_QuestEN[10748] = { title = "Maxnar Must Die!", description = "They've left us no choice, {name}.  It's time to put an end to the threat from the Blackwing Coven by taking out their leader, Maxnar the Ashmaw.\n\nI don't know if you caught a glimpse of him while you were in there, but he's one of the dragonkin, half-man, half-dragon.  And he's tough, so don't underestimate him!\n\nFinish it quickly and with any luck you'll secure the safety of Evergrove and the Ruuan Weald.", objectives = "" }
WordHunterWoW_QuestEN[10749] = { title = "Baron Sablemane's Poison", description = "Here, take this to your master. I'm sure that whatever the reason, Rexxar will put it to good use.\n\nOh, and do be certain to remind him that he owes me.\n\nHe knows what I want, and I'm certain that however he intends to obtain it for me, I'll be seeing you again sooner than you think.\n\nNow, do be a good little boy and run this up to Rexxar.", objectives = "" }
WordHunterWoW_QuestEN[10750] = { title = "The Path of Conquest", description = "Word has come from my wind riders, {name}. The Eclipsion blood elves are planning something big. They have begun forming their armies at the Path of Conquest, far to the southeast - adjacent to Eclipse Point.\n\nI want you to travel to the Path of Conquest and assess the situation. Once you have done so, use this flare gun to signal a wind rider. One will swoop down from the sky to meet you. Inform them of what you have discovered and they will give you your next set of orders.", objectives = "" }
WordHunterWoW_QuestEN[10751] = { title = "Breaching the Path", description = "We're going to need more time, {race}. I'm going to fly further ahead with some of the other wind riders. Hopefully, we can gather some more information. What I need from you now is to clear a path and more importantly, keep their arrows pointed away from us!\n\nCall for a wind rider with the Kor'kron flare gun once you have thinned their numbers.", objectives = "" }
WordHunterWoW_QuestEN[10753] = { title = "Culling the Wild", description = "The number of atrocities committed by the Burning Legion is countless. Even as we speak, they send their legion forces against the creatures of this land. Helpless to defend against their power, they fall one by one. {name}, help me stop these crimes of nature destroy all which they corrupt. \n\nOver the hill, east of here, you will see the corruption spreading across Bladed Gulch. Kill the ones causing the crime, the Fel Corrupters, and as many Felsworn as you can.", objectives = "" }
WordHunterWoW_QuestEN[10755] = { title = "Entry Into the Citadel", description = "This freshly cast mold was to be used to create a key of some sort.  From the image engraved on its back, it appears to be related to Hellfire Citadel.\n\nMaybe this could prove to interest to Nazgrel, the leader of the Horde's forces in Thrallmar.", objectives = "" }
WordHunterWoW_QuestEN[10756] = { title = "Grand Master Rohok", description = "The symbol on the key's handle... it is hard to make it out inside the mold, but I recognize it as the Shattered Hand's own.\n\nThere is a good chance this key will allow you to enter the Shattered Halls.\n\nSpeak to Rohok, our resident blacksmith.  If anyone can forge this key it is he.", objectives = "" }
WordHunterWoW_QuestEN[10757] = { title = "Rohok's Request", description = "Fel orc blacksmiths may not be the most skilled in the world, but there is some craftsmanship to their trade.  Only fel iron can be used with this mold if we want to end up with a working key - anything else would probably end up breaking it.\n\nBring me some fel iron bars, a bit of arcane dust and motes of fire.  I'll try my hand at it, but I make no promises.", objectives = "" }
WordHunterWoW_QuestEN[10758] = { title = "Hotter than Hell", description = "It's no good, {name}!  No matter how many coals I put to the fire, it's just not enough heat.\n\nThere's only one thing I can think of that is hot enough to temper this key and it is the insides of the Legion's fel reavers.\n\nI've only ever seen one downed once.  I remember seeing its insides fuming, shooting fire and steam as it fell.  Take this mold and plunge it into a fallen fel reaver.  I recommend you get yourself some friends if you plan to take one down.", objectives = "" }
WordHunterWoW_QuestEN[10759] = { title = "Find the Deserter", description = "I get the feeling that all the pieces are here, but I just can't put them together in a way that makes sense.\n\nI think our best lead is to attempt to locate this deserter. If he left his comrades at the camp, there's a chance you might be able to persuade him to help us understand what the dark conclave arakkoa are planning.\n\nStart your search for him along the road in Magma Fields to the northwest. It seems a likely place for him to take refuge.", objectives = "" }
WordHunterWoW_QuestEN[10760] = { title = "The Sketh'lon Wreckage", description = "The Sketh'lon Wreckage, just to the east, is an eerie place. The peons are convinced that it's cursed.\n\nThere are few trees here, so the peons have no choice but to venture into the arakkoa ruins to chop wood. The arakkoa spirits prey on the work groups, draining their life and using it to fuel their foul magics.\n\nWe must find out what is driving the dark conclave and stop them before their influence expands. Search the Sketh'lon Wreckage for evidence of their plans.", objectives = "" }
WordHunterWoW_QuestEN[10761] = { title = "Find the Deserter", description = "There's nothing here that would explain why the spirits of these arakkoa have remained in this world or how they came into thirst for the blood of orcs.\n\nI think our best lead is to try to find the deserter mentioned in the journal. If he left his comrades at the camp, there's a chance you might be able to persuade him to help us understand what the dark conclave arakkoa are planning.\n\nStart your search for him on the road through the Magma Fields to the southeast.", objectives = "" }
WordHunterWoW_QuestEN[10762] = { title = "Grand Master Dumphry", description = "The symbol on the key's handle... it is hard to make it out inside the mold, but I recognize it at the Shattered Hand's own.\n\nThere is a good chance this key will allow you to enter the Shattered Halls.\n\nSpeak to Dumphry.  He is a master of his craft.  If he can't craft this key for you, no one can.", objectives = "" }
WordHunterWoW_QuestEN[10763] = { title = "Dumphry's Request", description = "Fel orcs might be complete barbarians but their smithing is not as primitive as you might think.  Only fel iron can be used with this mold if we want to end up with a working key - anything else would probably end up breaking it.\n\nBring me some fel iron bars, a bit of arcane dust and motes of fire.  I'll try my hand at it, but I make no promises.", objectives = "" }
WordHunterWoW_QuestEN[10764] = { title = "Hotter than Hell", description = "It's not working, lad.  I cannot give it enough heat... the materials will not be properly tempered.\n\nYou know, the fel reavers used by the Burning Legion are powered by a scalding core of fel fire - it burns much hotter than normal fire.\n\nIf you could find enough people to take one down, you could heat the mold in the insides of the fallen reaver.  Beware, {class}, those fel reavers pack quite a punch.", objectives = "" }
WordHunterWoW_QuestEN[10765] = { title = "When Worlds Collide...", description = "At the southern end of the Path of Conquest, near a stationary caravan, I discovered what looked like a meeting between a giant and a blood elf chancellor. You've probably already noticed the smaller giants on the path as well. Something is just not right about all of this, grunt.\n\nI want you to fight your way to this meeting and break up the party. Recover whatever you can from the scene and then call for one of us with the flare gun.", objectives = "" }
WordHunterWoW_QuestEN[10766] = { title = "Invasion Point: Cataclysm", description = "Now that we have access to the Legion's base at Invasion Point: Cataclysm, we need to figure out a way to shut down their operations there. Wildhammer Stronghold won't be safe until the Legion's presence is erased from Shadowmoon Valley.\n\nI've sent an advance party up to the invasion point to help you formulate a plan to destroy the Legion's supplies. Go back to Legion Hold and step into the teleporter with the green crystals above it. Plexi will meet you at your destination.", objectives = "" }
WordHunterWoW_QuestEN[10767] = { title = "Invasion Point: Cataclysm", description = "Now that we have access to the Legion's base at Invasion Point: Cataclysm, we need to figure out a way to shut down their operations there. Shadowmoon Village won't be safe until the Legion's presence is erased from the valley.\n\nI've sent an advance party up to the invasion point to help you formulate a plan to destroy the Legion's supplies. Go back to Legion Hold and step into the teleporter with the green crystals above it. Nakansi will meet you at your destination.", objectives = "" }
WordHunterWoW_QuestEN[10768] = { title = "Tabards of the Illidari", description = "The wind riders must return to Shadowmoon Village to prepare for the next phase of our assault. What I need from you now are the tabards that these blood elves wear.\n\nWhen you have collected enough tabards, call for a wind rider using the Kor'kron flare gun. Prepare yourself for a bit of espionage, {race}!", objectives = "" }
WordHunterWoW_QuestEN[10769] = { title = "Dissension Amongst the Ranks...", description = "Researcher Tiorus was kind enough to put this concoction together for the final strike. I merely pour it upon this tabard that you have provided for me and the item is imbued with the essence of the Illidari filth.\n\nTake the enchanted tabard and travel to the Eclipsion Fields, southwest of Eclipse Point. Once there, use the tabard to transform into an agent of Illidan. While in disguise, slay the crazed colossi that wander the field. They will think it an attack by the Eclipsion and sever all ties!", objectives = "" }
WordHunterWoW_QuestEN[10770] = { title = "Little Embers", description = "Northeast of here, on the plateau above us lies the burnt ashes of my ancient home. A great wood flourished there before the Burning Legion sent their imps to burn us away. So many died that even centuries later my tired old heart hungers for revenge. There are too many of them for us to ever reclaim the land, but you could make them afraid.\n\nSurely you will help me?", objectives = "" }
WordHunterWoW_QuestEN[10771] = { title = "From the Ashes", description = "If you follow the road east and up the side of the mountain, then turn north, you will come to my long lost home.\n\nOnce there was a wood there. Its name is forgotten. Long ago the Burning Legion summoned scorched imps and other creatures of flame. My home was destroyed and my people fled. Now only I remain. \n\nI have saved some ironroot seeds that could be planted in fertile volcanic soil. Their magic is strong. Do this for me and I will share with you the treasures of a forgotten age.", objectives = "" }
WordHunterWoW_QuestEN[10772] = { title = "The Path of Conquest", description = "My gryphon riders have come back with a bit of news! The Eclipsion blood elves are planning something big. They've begun forming their armies at the Path of Conquest, located east of here - adjacent to Eclipse Point.\n\nI want you to travel to the Path of Conquest and assess the situation. Once you've done so, use this flare gun to signal a gryphon rider. One will swoop down from the sky to meet you. Tell 'em what you've discovered and they'll give you the next set of orders.", objectives = "" }
WordHunterWoW_QuestEN[10773] = { title = "Breaching the Path", description = "We're going to need more time, {race}. I'm going to fly further ahead with some of the other gryphon riders. Hopefully, we can gather some more information. What I need from you now is to clear a path and more importantly, keep their arrows pointed away from us!\n\nCall for a gryphon rider with the Wildhammer flare gun once you have thinned their numbers.", objectives = "" }
WordHunterWoW_QuestEN[10774] = { title = "Blood Elf + Giant = ???", description = "At the southern end of the Path of Conquest, near a stationary caravan, I discovered what looked like a meeting between a giant and a blood elf chancellor. What are giants even doing here? Something is just not right about all of this, grunt.\n\nI want you to fight your way to this meeting and break up the party. Recover whatever you can from the scene and then call for one of us with the flare gun.", objectives = "" }
WordHunterWoW_QuestEN[10775] = { title = "Tabards of the Illidari", description = "The gryphon riders must return to Wildhammer Stronghold to prepare for the next phase of our assault. What I need from you now are the tabards that these blood elves wear.\n\nWhen you have collected enough tabards, call for a gryphon rider using the Wildhammer flare gun. Prepare yourself for a bit of espionage, {race}!", objectives = "" }
WordHunterWoW_QuestEN[10776] = { title = "Dissension Amongst the Ranks...", description = "Gnomus was kind enough to put this concoction together for the final strike. I merely pour it upon this tabard that you have provided for me and the item is imbued with the essence of the Illidari filth.\n\nTake the enchanted tabard and travel to the Eclipsion Fields, southwest of Eclipse Point. Once there, use the tabard to transform into an agent of Illidan. While in disguise, slay the crazed colossi that wander the field. They will think it an attack by the Eclipsion and sever all ties!", objectives = "" }
WordHunterWoW_QuestEN[10777] = { title = "Asghar's Totem", description = "What you read in the commander's journal is true. While the orcish Horde massed under Gul'dan, my people sought to defend ourselves from the threat by striking against him. Gul'dan learned of their intentions and cast a mighty spell that destroyed our camps and twisted the spirits of my brothers.\n\nThey must be stopped before they unleash a greater evil. In the Sketh'lon Wreckage to the north, seek out Asghar and bring me the totem he carries. With it, we can begin to thwart the dark conclave's plans.", objectives = "" }
WordHunterWoW_QuestEN[10778] = { title = "The Rod of Lianthe", description = "The totem alone is not strong enough to counteract the sinister magics of the dark conclave.\n\nWe can combine it with other objects of power, forming a staff to focus the energies. We cannot rescue my brethren from the depths of their depravity, but we can stop them.\n\nOne of the items I need for the staff is the Rod of Lianthe, held by the blood elves at Eclipse Point to the southeast. It is kept in a pavilion on the top tier of the ruins and will be heavily guarded. Use caution, {name}.", objectives = "" }
WordHunterWoW_QuestEN[10780] = { title = "Sketh'lon Feathers", description = "There is one last element missing from the staff. We must direct the staff's power toward the Dark Conclave spirits.\n\nWe can do that by gathering feathers scattered on the ground at the Sketh'lon Base Camp and using them in the staff. The base camp is to the south, east of Wildhammer Stronghold.\n\nGul'dan's magic utterly destroyed my brethren, leaving only their spirits, but it did not stop there. The magic fed on the spell the arakkoa were preparing, forging a sinister force that engulfed the spirits.", objectives = "" }
WordHunterWoW_QuestEN[10781] = { title = "Battle of the Crimson Watch", description = "They are probably searching for you on the Path of Conquest as we speak. You must make your escape, {race}!\n\nLeave me, I'm done for... They... I think I hear them coming. It's now or never! Get out! If you choose to stay, you will have to fight!\n\nIf you fight and somehow manage to survive, take what you have learned here and deliver that knowledge to A'dal in Shattrath City.", objectives = "" }
WordHunterWoW_QuestEN[10782] = { title = "Imbuing the Headpiece", description = "The staff is nearly finished!\n\nAll that remains is to imbue the headpiece with power flowing from the echoes of Gul'dan in this accursed place. To the east, near the Fel Pits and south of the Deathforge, is the Altar of Damnation.\n\nThere, fragments of Gul'dan's past are trapped. When you carry the unfinished headpiece of the staff into the area around the altar, don't be surprised if some of the entities react to it. You will be carrying a dangerous object with strong connections to the cataclysm.", objectives = "" }
WordHunterWoW_QuestEN[10783] = { title = "Baron Sablemane", description = "Here is my plan. We will poison the ogres and then destroy their gronn master.\n\nDuring my travels in these mountains, I met a man named Baron Sablemane. He is a master of the alchemical arts, and may be convinced to assist us.\n\nYou will find him at the Circle of Blood, down in the canyon to the north of here. Whatever price he requires, I will leave it to your discretion to accept.", objectives = "" }
WordHunterWoW_QuestEN[10784] = { title = "Crush the Bloodmaul Camp", description = "<Tor'chunk leans in close to whisper.>\n\n{name}, you've done us more than proud in the fight against the ogres so far.  And while I have every confidence in what Rexxar has planned, I would still ask that you crush the ogres at Bloodmaul Camp before returning.\n\nThat way we'll be doubly certain of the outcome.\n\nTo get there, head north down the ramp out of Thunderlord.  Then, at the base of the ramp, head west across Dragons' End and north through the Churning Gulch and Daggermaw Canyon.", objectives = "" }
WordHunterWoW_QuestEN[10785] = { title = "It's a Trap!", description = "There's is no cause of fury greater in this world than that of Gruul and his sons. They slaughtered my people - my children - and now I will have revenge.\n\nI have fashioned a trap from dragon fire, and if you're clever enough, you can use it to kill even a gronn.\n\nJust hurry, take the trap to Rexxar. My thirst for revenge must be quenched.", objectives = "" }
WordHunterWoW_QuestEN[10786] = { title = "Slaughter at Boulder'mok", description = "I know that Rexxar has plans for you to head to Boulder'mok.  I have something that I want you to do while you are there.\n\nWe must take any chance we can get to strike down the ogres of these mountains, or they will overrun us, and all that we have bled and died for will be for nothing!\n\nBoulder'mok lies far to the northwest.  Travel north to Ruuan Weald, and from there head west through the tunnel and past the Raven's Wood.\n\n{name}, I want you to kill the Bladespire ogres of Boulder'mok.  Wipe them out!", objectives = "" }
WordHunterWoW_QuestEN[10791] = { title = "Welcoming the Wolf Spirit", description = "I've nearly completed the vestments that I'll wear during the ceremony. As I add the finishing touches, I'd like you to set this incense by the candles near the runestone to my left.\n\nI believe it will help us to attract the wolf spirit's attention, since it was made in the days of the orcish clans. I can almost imagine my ancestors using it in a ceremony paying tribute to the wolf spirit after a successful hunt.\n\nOnce you've placed the incense, I'll begin the ceremony.", objectives = "" }
WordHunterWoW_QuestEN[10792] = { title = "Zeth'Gor Must Burn!", description = "The Bleeding Hollow clan have betrayed their noble heritage!  We, the orcs who fought and died to save ourselves from the fel taint of Mannoroth, look upon our vile cousins and see only weakness and ignobility... and for that, they must burn!\n\nEnter Zeth'Gor, their bastion to the east, and burn their buildings.  Kill peons for their torches, ignite them at their forge, and hurl the burning torches at their hovels, their stable and their barracks.  Burn them all, and then return to me!\n\nFor the Horde!", objectives = "" }
WordHunterWoW_QuestEN[10793] = { title = "The Journal of Val'zareq: Portends of War", description = "This journal documents the recent activities of Illidan's armies. It also explains why Val'zareq was parading around the Path of Conquest. He was personally responsible for the capture of a high general of the Sha'tar.\n\nThis general is being held at a post known as Crimson Watch, located at the southern end of the Path of Conquest. A mysterious faction, calling itself the Crimson Sigil, is charged with his incarceration. If you choose to investigate, it would be wise to bring allies.", objectives = "" }
WordHunterWoW_QuestEN[10795] = { title = "A Date with Dorgok", description = "Good, I've seen you around and I've been meaning to speak to you about a matter of some importance.\n\nThere are reports coming in that for some reason the Bloodmaul ogres are planning an offensive against Sylvanaar and Ruuan Weald.  We don't know who or what is pushing them to do this, but I intend to nip their plan in the bud!\n\nBloodmaul Camp is where the attacks are to be staged from.  Head northwest down the ramp out of the Ruuan Weald and you will find it.  I want you to kill their leader, Dorgok!", objectives = "" }
WordHunterWoW_QuestEN[10796] = { title = "Crush the Bloodmaul Camp!", description = "I've heard that you've done us more than proud in the fight against the ogres thus far.  Now, I would ask that you face them again.  I want you to crush the ogres at Bloodmaul Camp!\n\nTo get down there, head northwest down the ramp out of the Ruuan Weald.  You'll find them at the base of the ramp.\n\nGood luck, {class}!", objectives = "" }
WordHunterWoW_QuestEN[10797] = { title = "Favor of the Gronn", description = "A token in the form of a small statuette falls from Dorgok's dead clutch.  It bears a striking resemblance to one of the gronn.\n\nSurely, Commander Haephus Stonewall at Evergrove in the Ruuan Weald, up the ramp to the east, would be interested in this!", objectives = "" }
WordHunterWoW_QuestEN[10798] = { title = "Pay the Baron a Visit", description = "This is bad news.  Gorgrom the Dragon-Eater is behind the recent Bloodmaul plans against Sylvanaar!\n\nWhy he's manipulating them, and not just using the Bladespire, I don't know.  But if we're to deal with a gronn, we're going to need help.\n\nI know a man who is wise in the ways of all sorts of exotic magics.  Baron Sablemane is his name, and you can find him at the Circle of Blood, back down the ramp to the northwest, and then southwest through the canyon.\n\nAsk him to fashion us a trap for the gronn.", objectives = "" }
WordHunterWoW_QuestEN[10799] = { title = "Into the Churning Gulch", description = "Very well, I'll create this trap, but first I want something in return.\n\nThere happens to be a nearby gronn that is in possession of an item that I want, but you can't face him, not yet anyway.\n\nSo, you and I are going to fashion a sleeping powder from the poison of the nearby crust bursters.\n\nYou'll find them in the Churning Gulch to the southwest.  Bring me a number of their glands, and be quick about it!", objectives = "" }
WordHunterWoW_QuestEN[10800] = { title = "Goodnight, Gronn", description = "I've outdone myself again.  I've fashioned a sleeping powder for you to use on Grulloc, the gronn I spoke of who is guarding what I want.\n\nGrulloc keeps himself at the Cursed Hollow, an area at the eastern edge of Dragons' End on the other side of the Circle of Blood.\n\nIf I were you, I wouldn't tarry long once you have his sack.  The effects of the dust won't last long.", objectives = "" }
WordHunterWoW_QuestEN[10801] = { title = "It's a Trap!", description = "There's nothing more that I hate in this world than the sons of Gruul and their father!  They slaughtered my people, and my children, and now I will have a taste of revenge!\n\nI have fashioned a trap from some dragon fire, and if you're clever enough, you might just be able to use it to kill a gronn.\n\nI'm sure that you have a particular gronn in mind; it matters not to me which one you kill.  Just hurry, take the trap to your Commander Stonewall.\n\nMy thirst for revenge must be quenched!", objectives = "" }
WordHunterWoW_QuestEN[10802] = { title = "Gorgrom the Dragon-Eater", description = "We must show the ogres that we are not to be trifled with. We must send a message.\n\nTravel to Boulder'mok and kill the ogres there. Make sure you keep their heads.\n\nThen go to Gorgrom's altar and place the trap there for him. Gorgrom will appear, and you must lure him into the trap. When he is dead, mount your grisly totems near his corpse, so that the ogres may look at their fallen master and their fallen brothers, and know the price for seeking to destroy us.", objectives = "" }
WordHunterWoW_QuestEN[10803] = { title = "Slaughter at Boulder'mok", description = "I know that we have plans for you to head to Boulder'mok. I have something that I want you to do while you are there.\n\nWe must take any chance we can get to strike down the ogres of these mountains, or they will overrun us, and all that we have bled and died for will be for nothing!\n\nBoulder'mok lies to the west. Travel southwest, cross the bridge and head through the tunnel. On the west side of the Raven's Wood you will find them.\n\n{name}, I want you to wipe out the Bladespire ogres of Boulder'mok.", objectives = "" }
WordHunterWoW_QuestEN[10804] = { title = "Kindness", description = "Something has them spooked, {race}.\n\n<Mordenai points to the nether drakes flying overhead.>\n\nThey won't even come down to feed. I have seen several fall to the earth, dead from exhaustion before their bodies hit the ground.\n\nWe must save them! The Rocknail flayers that are found near the crystals are their natural prey. Kill flayers and take their carcasses. Place a carcass in the field and stand extremely still. As long as you do not make any aggressive motions, they will not attack you.", objectives = "" }
WordHunterWoW_QuestEN[10805] = { title = "Massacre at Gruul's Lair", description = "You've proven yourself resourceful, and now I think I'm going to put you to personal use in my own fight against Gruul and his sons.\n\nThe Bladespire clan are the favored of the gronn, and while you may have thinned out their numbers elsewhere, you haven't yet dealt with their strongest.\n\nGruul protects the exterior of his lair with only the toughest of ogres, and it is those that you must kill.  Head north through the Daggermaw Canyon and you will find Gruul's Lair at the end.", objectives = "" }
WordHunterWoW_QuestEN[10806] = { title = "Showdown", description = "The time has come for us to face Goc, the master of the Bladespire ogres. It is also time that I take a hand in events, to see the last of the gronn's life.\n\nTake my signet ring. When you come to the Altar of Goc, use it, and I will come to join you.\n\nTogether we will destroy Goc.", objectives = "" }
WordHunterWoW_QuestEN[10807] = { title = "The Ashtongue Broken", description = "The Ashtongue tribe is feared among all Broken.  It consists of the most vicious and bloodthirsty individuals, handpicked by Akama himself.  They are as fierce and ruthless as any naga, demon or blood elf in Illidan's army and they have been deployed in large numbers at the Ruins of Baa'ri, to the north.  Go there and put a dent in their numbers before they get a chance to mount an attack on us.", objectives = "" }
WordHunterWoW_QuestEN[10808] = { title = "Thwart the Dark Conclave", description = "The spirits of the dark conclave seek to summon an ancient and powerful evil through a ritual conducted at the lava pits to the south of the Sketh'lon Base Camp.\n\nGul'dan's magic mingled with their own, empowering them to aid this creature in manifesting in our world! We must not allow this to happen, {name}. The death and destruction it would bring are unimaginable!\n\nCarry the staff with you to the site of the summoning and use its magics to stop the dark conclave once and for all!", objectives = "" }
WordHunterWoW_QuestEN[10809] = { title = "WANTED: Worg Master Kruush", description = "The poster reads:\n\n\"Worg Master Kruush leads the worg riders of the Bleeding Hollow clan.  A price has been placed on his head, for his riders exact heavy tolls on supply trains to Spinebreaker Post.\"\n\n\"Scouts report him within Zeth'Gor, and the hero able to bring the severed head of this villain to me will earn the thanks of the Horde, and a large bounty.\"\n\n\"-Captain Darkhowl\"", objectives = "" }
WordHunterWoW_QuestEN[10810] = { title = "Damaged Mask", description = "As you examine the damaged mask, you hear strange sounds coming from within. If the mask wasn't damaged you might be able to hear the sounds more clearly.\n\nO'Mally Zapnabber in Ruuan Weald might be able to fix the mask.", objectives = "" }
WordHunterWoW_QuestEN[10811] = { title = "Seek Out Neltharaku", description = "Their patron soars high above, {name}. Perhaps the kindness that you showed his children has moved his heart. Seek Neltharaku out and enlist his aid. Together, you may be able to solve the plight of the Netherwing drakes.\n\n<Mordenai points to the sky.>\n\nFly high, friend...", objectives = "" }
WordHunterWoW_QuestEN[10812] = { title = "Mystery Mask", description = "Ok, it should work now. What is it, you ask? Why, it's a communication device - it allows those blockheads to communicate with each other. You know, the Burning Legion! I would suggest that you hand this mask to Wildlord Antelarion. He's over there pacing around. Always moving, he is.\n\nWell get moving, he's been trying to get his hands on one of these for sometime now.", objectives = "" }
WordHunterWoW_QuestEN[10813] = { title = "The Eyes of Grillok", description = "{name}, you have braved the lair of the Bleeding Hollow orcs, dreaded Zeth'Gor, and survived!  Perhaps you have the strength to aid me, for I aim to gaze into the mind of its darkest witch, Grillok!\n\nTake this shard.  Use it to ensorcel an Eye of Grillok and bind it to yourself.  Return here and approach my cauldron... and it will pull the eye from you.\n\nGo, {name}.  And use care -- An Eye of Grillok will betray you to our enemies if given the slightest opening!", objectives = "" }
WordHunterWoW_QuestEN[10814] = { title = "Neltharaku's Tale", description = "I have information that you may find useful. Please listen to what I have to tell you, {race}.", objectives = "" }
WordHunterWoW_QuestEN[10815] = { title = "The Journal of Val'zareq: Portends of War", description = "This journal documents the recent activities of Illidan's armies. It also explains why Val'zareq was parading around the Path of Conquest. He was personally responsible for the capture of a high general of the Sha'tar.\n\nThis general is being held at a post known as Crimson Watch, located at the southern end of the Path of Conquest. A mysterious faction, calling itself the Crimson Sigil, is charged with his incarceration. If you choose to investigate, it would be wise to bring allies.", objectives = "" }
WordHunterWoW_QuestEN[10816] = { title = "Reclaiming Holy Grounds", description = "You did well against the Broken in Baa'ri, {name}.  Let's see how well you do against Illidan's most feared army.\n\nThe fel orcs of the Shadowmoon Clan occupy the Ata'mal Terrace, once a very holy site where ata'mal crystals were used in spiritual ceremonies.\n\nWe had reason to believe they were hiding an actual ata'mal crystal in the vicinity, but our scrying has revealed nothing.  Nevertheless, the fel orcs are on draenei holy ground and their presence must be dealt with.", objectives = "" }
WordHunterWoW_QuestEN[10817] = { title = "The Great Retribution", description = "You did well against the Ashtongue Broken, {name}.  I have another challenge for you, should you be up to it.\n\nNot too long ago, the Sanctum of the Stars suffered a tremendous attack by Illidan's fel orcs.\n\nWe've determined it was perpetrated by the Shadowmoon orcs who occupy the Ata'mal Terrace.\n\nShow them that the Scryers are not to be trifled with.", objectives = "" }
WordHunterWoW_QuestEN[10818] = { title = "Baron Sablemane Has Requested Your Presence", description = "{name}, while you were out being one hell of a {class}, Baron Sablemane sent his pet dragon up here with a message.\n\nHe's asked for you personally.  From what I understand, he wants you to head up his own fight against the gronn.\n\nI guess you're the most qualified person in all of Outland to help him, but if I were you, I'd get in contact with a couple of friends first and ask them to join you at the Circle of Blood.", objectives = "" }
WordHunterWoW_QuestEN[10819] = { title = "Felsworn Gas Mask", description = "I have a very special mission for you, {name}. I need you to infiltrate Forge Camp: Anger east of here. When you enter the camp you will need to wear the Felsworn gas mask and locate the Legion communicator. Once you have located the communication device speak with whomever is on the other side of the device.\n\nIf all works out you can trick the demon into something devious! Try telling the demon that Camp Anger has revolted.\n\nGood luck to you {class}.", objectives = "" }
WordHunterWoW_QuestEN[10820] = { title = "Deceive thy Enemy", description = "For every moment I hear silence, you draw closer to your death! SPEAK!\n\nWhat? The camp has revolted? This cannot possibly be true! My minions would not dare undermine my authority.\n\nWell then, every last one of them will pay for this treachery, they will pay dearly. Silence them all and be done with it! Report back to me once you have carried out my order or you shall be dealt with.", objectives = "" }
WordHunterWoW_QuestEN[10821] = { title = "You're Fired!", description = "Doomcryer did nothing to stop the revolt? How dare she! She has been trying to undermine my authority for some time. However, this time will be her last. You must summon her and deal with her personally.\n\nHer anger guards hold the keys that summon her to Forge Camp: Anger. Retrieve the five keys and activate the five Legion obelisks. The obelisks have a short duration, so make sure they are all activated at the same time. Remember, the anger guards carry more keys.", objectives = "" }
WordHunterWoW_QuestEN[10824] = { title = "Sunfury Signets", description = "The survival of the Scryers hinges on outrecruiting Kael'thas.  Every pilgrim from Quel'Thalas that joins his side brings him closer to victory.  The opposite is true for us.\n\nSoon, however, we will run out of recruits and it will come down to what side can kill the other quicker.  Prove your worth to the Scryers by bringing me Sunfury signets worn by  high-ranking blood elves allied with Kael'thas and Illidan.  You'll find them at Eclipse Point to the west and the Ruins of Karabor, to the northeast.", objectives = "" }
WordHunterWoW_QuestEN[10825] = { title = "The Truth Unorbed", description = "This strange, magical orb drops from beneath the contour feathers of the arakkoa.\n\nSuffused with an eerie, purple glow, the orb pulses to an unheard beat.  Holding it makes you mildly uncomfortable, and so you quickly place it within your pack.\n\nPerhaps Tree Warden Chawn at Ruuan Weald to the west, through the tunnel and across the Wyrmskull Bridge, would be interested in examining it?", objectives = "" }
WordHunterWoW_QuestEN[10826] = { title = "Marks of Sargeras", description = "By now it should be clear to you why we oppose the Burning Legion and those who serve them.\n\nIf you wish to prove yourself to the Aldor, bring me the insignias of high-ranking Legion and their Shadow Council followers.  Here in Shadowmoon you will find a strong Legion presence to the far west in Legion Hold and the Deathforge.", objectives = "" }
WordHunterWoW_QuestEN[10829] = { title = "Treebole Must Know", description = "This is troubling!  The arakkoa are causing the ancients and protectors to become possessed by evil spirits!\n\nBut, there is one ancient that could not possibly have been affected.  His name is Treebole, and you must go to him at once if we're to save the trees of the Raven's Wood!\n\nGo back to the Raven's Wood.  You will find him at the fork in the path just past Grishnath.", objectives = "" }
WordHunterWoW_QuestEN[10830] = { title = "Exorcising the Trees", description = "The Grishna have caused the leafbeards and stonebarks to be inhabited by evil koi-koi spirits.\n\nWe must save the trees or soon all of the Raven's Wood will be lost forever!\n\nCombine the magic of a Grishnath orb, found throughout Grishnath, with a dire pinfeather from a dire raven.\n\nUse the resultant exorcism feather to draw out and slay the koi-koi spirit as quickly as possible.  The stonebarks are too powerful for this ritual, but if enough leafbeards are saved, they will be freed as well.", objectives = "" }
WordHunterWoW_QuestEN[10834] = { title = "Grillok \"Darkeye\"", description = "Grillok Darkeye has wagered a piece of himself to dark powers, and gained great magic for it.  His lost eye burns deep in some hellish pit, now a demon's trinket... and the patch that covers his betrayal holds its own dark secrets.\n\nBring me Grillok's eyepatch, {name}, and I will reward you greatly for your service...", objectives = "" }
WordHunterWoW_QuestEN[10835] = { title = "Apothecary Antonivich", description = "{name}, I have prepared a preliminary report of my findings regarding the Bleeding Hollow orcs.  My colleague in Thrallmar, Apothecary Antonivich, will be happy to receive them.  He too studies the phenomenon of fel orcs... in hopes of preventing such a tragedy from again befalling our orcish allies.\n\nTake him this report, and I will continue my study of the blood you brought me.  If fortune is with us, we will isolate the cause of the fel orc affliction.", objectives = "" }
WordHunterWoW_QuestEN[10836] = { title = "Infiltrating Dragonmaw Fortress", description = "I require time so that I may devise a plan to save my children and mate. You will buy me this time, mortal.\n\nVenture into Dragonmaw Fortress, located on the eastern edge of the Netherwing Fields, and lay waste to all Dragonmaw orcs that you find. The ensuing chaos and confusion should have a considerable impact on their plans.\n\nBe warned, some of my kin are too far gone - their minds corrupted by the Dragonmaw. For them, the only resolution is death. You have my permission to end their lives as well.", objectives = "" }
WordHunterWoW_QuestEN[10837] = { title = "To Netherwing Ledge!", description = "I believe that I can imbue nethervine crystals with my own essence. The power contained within these imbued crystals should be sufficient to free enslaved drakes of their masters' grasps.\n\nTravel to Netherwing Ledge, an island located off the broken shelf of Shadowmoon Valley, to the southeast. It is on Netherwing Ledge that you will find nethervine crystals. Return to me when you have collected enough crystals to fill your packs.\n\nAnd {name}, Beware the Dragonmaw that now inhabit the island.", objectives = "" }
WordHunterWoW_QuestEN[10838] = { title = "The Demoniac Scryer", description = "The Demoniac Scryer is now ready.  Take it behind Hellfire Citadel, to Hellfire Basin, and summon it upon the ground.  It will then begin to attune itself to Hellfire Citadel.  After its attunement, speak to the Scryer and transcribe what it tells you.  Bring that transcription to me...\n\nGo, {name}, but only when you are ready.  There is no doubt that Hellfire Citadel will detect the Scryer and send wardens to destroy it!", objectives = "" }
WordHunterWoW_QuestEN[10839] = { title = "Veil Skith: Darkstone of Terokk", description = "Veil Skith lies to the northwest of the caravan and to the south of Shattrath in a secluded grove of the forest. It is rumored that the colony of Skettis has constructed a maligned altar of worship. This Darkstone of Terokk must be purified if the arakkoa of Skith are ever to be redeemed.\n\nTake this Rod of Purification and cast it upon the Darkstone. Blessed by A'dal, the rod's purity might be enough to bring clarity to the Darkstone. Go now and may the light shine upon thee.", objectives = "" }
WordHunterWoW_QuestEN[10840] = { title = "The Tomb of Lights", description = "To the east, buried under the charred sand, is the Tomb of Lights, a lost resting place of the dead.  Before our caravan was ambushed I was going to journey to the tomb and cleanse it of evil spirits.  \n\nLittle did I know it was already infested with another kind of evil.  Even now the ethereals plunder the bodies of the fallen for trinkets and keepsakes that were given to the dead centuries ago.  \n\nThere is little I can do while our caravan struggles to survive.  ", objectives = "" }
WordHunterWoW_QuestEN[10842] = { title = "Vengeful Souls", description = "The Tomb of Lights has become corrupted by the Shadow Council and the draenei dead have become cursed spirits, angry and confused with a burning hatred for the living.\n\nEnter the tomb and seek out these tragic victims. Give them the rest that they deserve.", objectives = "" }
WordHunterWoW_QuestEN[10843] = { title = "Since Time Forgotten...", description = "Since time forgotten we have fought with the Bladespire ogres.\n\nWe have managed to push them back so that now they only hold a tenuous grip at Bladespire Outpost.  It's back the way that you came, on the southwestern edge of the Razor Ridge.\n\nProve your worth to me by killing their leader, Gnosh Brognat.\n\nLet us see what stuff you are made of when fighting the ogres.", objectives = "" }
WordHunterWoW_QuestEN[10845] = { title = "Slay the Brood Mother", description = "My hunters have just returned from a scouting mission to the Singing Ridge.  It seems that the nether drakes, which infest the crystals there, have increased greatly in number, and threaten to spill out into our laps.\n\nSince you have proven yourself a competent slayer, let us see if your {class} skills are the match of an adult drake.\n\nFind the Singing Ridge by heading south through the Scalewing Shelf.  Enter and slay their brood mother, Dreadwing.", objectives = "" }
WordHunterWoW_QuestEN[10846] = { title = "Understanding the Mok'Nathal", description = "<Leoroxx looks you in the eye with the kind of stare that chills your soul.>\n\nYou come to the Mok'Nathal, but you do not understand us.  You do not understand our struggle to survive.\n\nIf you would understand us, then you will have to endure a taste of that struggle.\n\nTo the south are the Vekh'nir arakkoa.  They have enslaved a group of ogres in the caverns known as Trogma's Claim and their leader, Vekh is in there.\n\nSlay him!", objectives = "" }
WordHunterWoW_QuestEN[10847] = { title = "The Eyes of Skettis", description = "Doom harkens from the cliffs of Skettis.\n\nMy people, the arakkoa, face a fate shrouded in unspeakable evil. Too often have we abused dark magic for wrongdoing. Through A'dal I have learned of the Light and of redemption.\n\nTerokk watches his colonies from Skettis through orbs enchanted by the black art. Steal these Eyes from Veil Reskk and Veil Shienor in northern Terokkar. Let me see what Terokk sees. Let me look through the eyes of Skettis.", objectives = "" }
WordHunterWoW_QuestEN[10848] = { title = "Veil Rhaze: Unliving Evil", description = "Veil Rhaze was a particularly wicked colony of Skettis.\n\nDespite the village's eradication by the Auchindoun disaster, Terokk's influence remained in the maligned spirits there. Travel west to Veil Rhaze and slay those murderous wretches. You'll find them to the west of the Shadow Tomb, on the border of Bone Wastes and Terokkar Forest.\n\nThis will be our first blow against Terokk and the guardians of Skettis.", objectives = "" }
WordHunterWoW_QuestEN[10849] = { title = "Seek Out Kirrik", description = "Other arakkoa took part in the betrayal of Terokk.\n\nKirrik recognized Terokk as a charlatan, not a prophet. The only prophecy Terokk envisioned was the doom borne of his own bidding.\n\nIt was Kirrik who led us bravely from Skettis. After our pilgrimage to Shattrath, Kirrik traveled to the colonies in search of others.\n\nThis missive tells of what the Eyes have seen. Kirrik must be told! Follow the road south out of Shattrath to the Bone Wastes and look for the caravan.", objectives = "" }
WordHunterWoW_QuestEN[10851] = { title = "The Totems of My Enemy", description = "There is the right way to honor one's ancestors, and there is the wrong way.\n\nThe Bladespire ogres carry totems with them, but they do not use them to show their respect.  Instead, they seek to use them to manipulate and control.\n\nWe should steal their totems because they are unworthy!  We will then put them to better use.\n\nGo to the Bladespire Outpost to the west, just southwest of the Razor Ridge.  Slay the Bladespire mystics and crushers, and take their totems from them!", objectives = "" }
WordHunterWoW_QuestEN[10852] = { title = "Missing Friends", description = "We broke down here because some guys came in the night and made a lot of noise.  It was scary.  I don't know when we are going to get moving again.  \n\nSome of my friends are missing though.  I don't know where they are.  I think those scary bird men took them away to the northwest.  They probably are all locked up in cages and stuff.  If you find them that would be great.  I'm kind of worried about them.", objectives = "" }
WordHunterWoW_QuestEN[10853] = { title = "Spirit Calling", description = "The spirits of the nether drakes in the Singing Ridge are in need of liberation.\n\nThe nether drakes were not always nether drakes.  They used to be black drakes.\n\nBut then, with the destruction of this world, a wave of nether energy washed over everything and had the side-effect of changing the drakeling eggs.\n\nNow they are all twisted versions of their former selves.  We must help them to find peace.\n\nDo this by slaying a drake near to the spirit calling totem, and then take its spirit from it.", objectives = "" }
WordHunterWoW_QuestEN[10854] = { title = "The Force of Neltharaku", description = "Take this enchanted nethervine crystal and make your way back to Dragonmaw Fortress. Once there, seek out the enslaved drakes and invoke the magic of the nethervine crystal. My own energies will pour forth, causing the drakes to break free from the bond of their captors. When you see that the drake has broken free, help it defeat its captor! It will most assuredly be weak from the imprisonment.\n\nRelease all that you can find and return to me, {name}.", objectives = "" }
WordHunterWoW_QuestEN[10855] = { title = "Fel Reavers, No Thanks!", description = "Ah, yes - the fel reaver!  Certainly the Legion's most terrible mechanical creation.  There are no less than three of these abominations aimed at the Stormspire.\n\nFortunately for us, they are not active yet.  This affords us the possibility of dealing with them through sabotage instead of brute force.\n\nObtain condensed nether gas from the gan'arg at Forge Base: Oblivion and fill a nearby fel reaver's fuel tank with it.  I've a feeling its engine won't handle it too well.", objectives = "" }
WordHunterWoW_QuestEN[10856] = { title = "The Best Defense", description = "Brave acts of industrial sabotage will only get us so far, {name}.  Just as Forge Base: Oblivion serves as an assembly site for Fel Reavers, Forge Base: Gehenna serves as a staging ground for their army as it is where the majority of the Legion's teleportation devices are located.\n\nI want you to go in there and put a dent in their numbers.  They must have a full regiment of wrathbringers by now and we just can't allow that.", objectives = "" }
WordHunterWoW_QuestEN[10857] = { title = "Teleport This!", description = "As fun as killing demons might be, it does us little good when the Legion can keep using its teleporters to replace anything we kill.\n\nUnfortunately, I don't have any high-powered explosives handy... but the mo'arg that maintain the teleporters do.\n\nTake this rod... I've tuned its powers to interfere with mo'arg brain frequencies.  Return to Forge Base: Gehenna and use it on any mo'arg you see.  You won't have long, but you'll be able to use their demolition charges on the nearby teleporters.", objectives = "" }
WordHunterWoW_QuestEN[10858] = { title = "Karynaku", description = "It shames me to ask for your assistance once more, {name}, but you are my flight's only hope. Without my mate, the netherwing brood may die out completely.\n\nMake your way to the top of Dragonmaw Fortress and find Karynaku.\n\nWe will be flying overhead. Should a break appear in their defenses, the might of the netherwing will swoop down to assist you.\n", objectives = "" }
WordHunterWoW_QuestEN[10859] = { title = "Gather the Orbs", description = "The Razaani ethereals have strange devices that emit small, pink floating light orbs.  They remind me of souls.\n\nThey are not to be confused with the large yellow balls that break free of the ethereal when they die, these are something else entirely.\n\nI'd like for you to head north to Razaan's Landing and drop some totems, which will attract the pink light orbs.\n\nBring them back to me so that I might determine exactly what they are.", objectives = "" }
WordHunterWoW_QuestEN[10860] = { title = "Mok'Nathal Treats", description = "Hungry, {race}?  The Great Spirit helps those that help themselves.  If you want to earn a meal, I suggest that you listen up, because Braagor there isn't going to give you anything for free, nor as tasty!\n\nThe raptors and scalewings of Razor Ridge and the Scalewing Shelf have everything that's needed for two of the most delicious dishes you'll ever taste.  Bring me their raptor ribs and serpent flesh, and I'll make some of each for you.\n\nI may even teach you how to cook them up for yourself, if you hurry.", objectives = "" }
WordHunterWoW_QuestEN[10861] = { title = "Veil Lithic: Preemptive Strike", description = "In the wretched colony to the southwest known as Veil Lithic, Terokk's minions are attempting to befoul their avian brethren before they hatch. The dark sorcerers of Lithic encase eggs in a shadowy curse. When the hatchlings emerge, they mindlessly serve Terrok.\n\nTravel to Veil Lithic and prematurely break the eggs before the curse has time to seep in. Even if you are too late, you can put down the tainted ones.\n\nRemember, the Light shines brightest in the darkness.", objectives = "" }
WordHunterWoW_QuestEN[10862] = { title = "Surrender to the Horde", description = "The cowardly arakkoa attack us daily.  They ambush our hunters and sometimes even raid inside our walls.  We kill them when we can, but their magic is strong and they often escape our warbands.  \n\nI have learned that some arakkoa claim to be friendly with the Horde.  They live in Shattrath City to the northwest.  Rilak the Redeemed is their leader.  Search for him in the Lower City, and when you find him, demand his surrender.", objectives = "" }
WordHunterWoW_QuestEN[10863] = { title = "Secrets of the Arakkoa", description = "Out here on the frontier we have to deal with the arakkoa every day.  They strike at us when they please, raiding our supply lines and killing our scouts.  \n\nYet we know very little about these enigmatic creatures.  I have received news that northwest of here in Shattrath City there are arakkoa who are not hostile.  They might be willing to share the secrets of their race.  \n\nRilak the Redeemed is their leader.  He resides in the northern part of the Lower City.", objectives = "" }
WordHunterWoW_QuestEN[10864] = { title = "A Burden of Souls", description = "I have a device, the Demoniac Scryer, that can analyze fel magic.  I would have you use the Scryer, but first... you must appease it.  The Scryer, you see, has trapped within it a creature of vast intelligence and its needs are, shall we say, quite eccentric.\n\nTo appease the Scryer, you must kill orcs.  Specifically, they must be Shattered Hand orcs -- the Scryer demands their souls.\n\nReturn to me when the souls are reaped.  You will find the orcs north, and south, and surrounding... Hellfire Citadel.", objectives = "" }
WordHunterWoW_QuestEN[10865] = { title = "Inform Leoroxx!", description = "Quickly, you must inform Leoroxx of what is transpiring up at Razaan's Landing!\n\nThose orbs were comprised of souls, some of them Mok'Nathal!", objectives = "" }
WordHunterWoW_QuestEN[10866] = { title = "Zuluhed the Whacked", description = "He hides in my thoughts, mortal. He waits for me to break... for me to bend to his will.\n\nAnd this will be his undoing. I will call for him. I will tell him that I will do as he asks. When he appears, kill him and take the key!\n\nKnow this: Zuluhed is an ancient orc with unknown powers. He has surely been empowered further by Illidan. You risk your life for me in doing as I ask. Are you certain you wish to make such a sacrifice?", objectives = "" }
WordHunterWoW_QuestEN[10867] = { title = "There Can Be Only One Response", description = "There can be only one response to this... this, DEFILEMENT of the souls of our ancestors!\n\n{name}, if you would aid us to restore the souls of our honored dead to their rightful place, go back to Razaan's Landing.\n\nGo back up there and kill the razaani until their leader, Nexus-Prince Razaan shows his cowardly face.  Kill him and get those souls back, and then give them over to Spiritcaller Dohgar!", objectives = "" }
WordHunterWoW_QuestEN[10868] = { title = "Arakkoa War Path", description = "The arakkoa have attacked us again, this time striking in the night and then using their dark magic to escape before we could charge out to meet them in numbers. They use their summoning circles to rescue their warriors from certain death, but they cannot run from us if we attack their homes. Veil Reskk and Veil Shienor lie to the north and northeast.\n\nFind these arakkoa nests and kill as many as you can.", objectives = "" }
WordHunterWoW_QuestEN[10869] = { title = "Thin the Flock", description = "The arakkoa have attacked us again, this time striking in the night and then using their dark magic to escape before we could marshal our soldiers.  \n\nVeil Reskk and Veil Shienor lie to the north and northwest.  Find these arakkoa nests and kill as many as you can.  They may not fear us, but at least we can thin their numbers.", objectives = "" }
WordHunterWoW_QuestEN[10870] = { title = "Ally of the Netherwing", description = "Allow me to return you to Mordenai. I am certain that he wishes to see you once more.", objectives = "" }
WordHunterWoW_QuestEN[10871] = { title = "Ally of the Netherwing", description = "Allow me to return you to Mordenai. I am certain that he wishes to see you once more.", objectives = "" }
WordHunterWoW_QuestEN[10872] = { title = "Zuluhed the Whacked", description = "He hides in my thoughts, mortal. He waits for me to break... for me to bend to his will.\n\nAnd this will be his undoing. I will call for him. I will tell him that I will do as he asks. When he appears, kill him and take the key!\n\nKnow this: Zuluhed is an ancient orc with unknown powers. He has surely been empowered further by Illidan. You risk your life for me in doing as I ask. Are you certain you wish to make such a sacrifice?", objectives = "" }
WordHunterWoW_QuestEN[10873] = { title = "Taken in the Night", description = "Our small outpost is under constant attack. Several nights ago, we were raided by the spiders of Netherweb Ridge, on the southeastern edge of the Bone Wastes. They poisoned many of our people, wrapped them in webs and carried them away. Some of our warriors took up arms and with little preparation pursued the spiders.\n\nWe have not seen the captives or our hunting parties since. We hope that some may still be alive, perhaps imprisoned by the spiders.  Our numbers are few. Will you search for our people?\n", objectives = "" }
WordHunterWoW_QuestEN[10874] = { title = "Veil Shalas: Signal Fires", description = "Terokk's perch, Skettis, looms above the Bone Wastes to the east. At the base of Skettis lies Veil Shalas, the most formidable of Terokk's colonies. It is through the stronghold of Veil Shalas that Terokk's forward sages wage war against the Light.\n\nThe evil-doers of Shalas communicate with their master using a complex system of magical signal fires. Travel to the east, {race}, and extinguish the fires. Once Veil Shalas is silenced, we can begin to plot the fall of Skettis.\n\nBut I get ahead of myself.", objectives = "" }
WordHunterWoW_QuestEN[10875] = { title = "Report to Nazgrel", description = "{name}, during your foray with the Demoniac Scryer, I sent word of your exploits against the fel orcs.  Nazgrel, our illustrious leader in Thrallmar, wishes to speak with you.  I believe he has a bloody mission in mind...", objectives = "" }
WordHunterWoW_QuestEN[10876] = { title = "The Foot of the Citadel", description = "Force-Commander Gorax is training Shattered Hand captains at the base of Hellfire Citadel, honing them to a bloody razor's edge.  You must kill him, {name}, for his loss would be a mighty blow to the fel orcs.\n\nHowever, that is not all you must do.\n\nTake this banner.  Place it atop Gorax's corpse.  Gorax's commander, the Hand of Kargath, must answer your challenge if he has even a drop of true orc blood within him!\n\nHis head, the head of the hand of Kargath, is what I seek.", objectives = "" }
WordHunterWoW_QuestEN[10877] = { title = "The Dread Relic", description = "Long ago a caravan went to Auchindoun with a mission to take a Dread Relic from the ancient tombs beneath the necropolis. They fled, but the relic was their undoing.  The relic is evil and it summons evil when touched.   Their caravan was destroyed somewhere to the east. \n\nThis dark artifact is the key to a terrible plan to defeat Teribus the Cursed, a creature that flies over the Bone Wastes.  Help me if you wish, but your life and even your soul will be at risk.", objectives = "" }
WordHunterWoW_QuestEN[10878] = { title = "Before Darkness Falls", description = "After our caravan fell prey to an attack by Shadow Council cabal cultists, scouts were sent to Shattrath to call for help.  The guards think we're safe for now, but they underestimate these madmen.\n\nI, for one, am not looking forward to having my throat slit by some cabal initiate in the middle of the night.  Do us all a favor and take the fight to them, before they come to us.\n\nYou will find our attackers south of here, at Auchindoun's northern entrance.", objectives = "" }
WordHunterWoW_QuestEN[10879] = { title = "The Skettis Offensive", description = "Skettis has waged war on us! Have you gathered enough strength to help with Shattrath's defense?\n\nHold off the attackers!", objectives = "" }
WordHunterWoW_QuestEN[10880] = { title = "Cabal Orders", description = "This message bears a dark seal and though the language seems somewhat familiar, it appears to be encoded.\n\nPerhaps someone at the Refugee Caravan will know something about it.", objectives = "" }
WordHunterWoW_QuestEN[10881] = { title = "The Shadow Tomb", description = "Many believe it was the Shadow Council that caused the explosion that tore Auchindoun apart.  It is rumored they awoke a great evil inside.\n\nIf that is true, then that evil must have turned against them.  According to these orders, part of the Shadow Council is fleeing Auchindoun.  They are using the Shadow Tomb to store powerful artifacts from Auchindoun.\n\nThree of these are sacred, for they belonged to the powerful patriarchs Arunen, K'alen and Atalor.  I must ask you to retrieve them.", objectives = "" }
WordHunterWoW_QuestEN[10883] = { title = "The Tempest Key", description = "You have proven yourself capable of great feats, {name}. Your discovery of the Cipher of Damnation and Kael'Thas' involvement is most important to our cause. Should Kael use the cipher, what little is left of this world may collapse.\n\nA'dal is convinced that Kael must be stopped and now seeks adventurers willing to undergo trials. Those that prove their strength will be granted favor by the naaru.\n\n<Khadgar nods.>\n\nA'dal awaits...\n", objectives = "" }
WordHunterWoW_QuestEN[10884] = { title = "Trial of the Naaru: Mercy", description = "Four trials you must pass before you are deemed worthy by the naaru.\n\nWithin the Shattered Halls of Hellfire Citadel are three of your people. They are held there by the merciless one, Kargath Bladefist. He seeks to execute them as a sign of his virility and power. You must save these prisoners before such an atrocity can come to pass. As proof of deed, bring me the unused axe of the executioner. It must not have a drop of blood on its blade!\n", objectives = "" }
WordHunterWoW_QuestEN[10885] = { title = "Trial of the Naaru: Strength", description = "Four trials you must pass before you are deemed worthy by the naaru.\n\nThe trial of strength is divided in two. You must destroy the leader of the Coilfang Steamvaults, Warlord Kalithresh, and bring me his trident. Slay the extra-planar being known as Murmur, in the Shadow Labyrinth of Auchindoun, and bring me his essence.\n\nDo this and you will have passed the trial of strength.", objectives = "" }
WordHunterWoW_QuestEN[10886] = { title = "Trial of the Naaru: Tenacity", description = "Four trials you must pass before you are deemed worthy by the naaru.\n\nIn our travels we have encountered many dangerous beings. Some of these beings we incarcerated and placed in what is now known as the Arcatraz of Tempest Keep.\n\nThere is one prisoner, however, that is a victim of circumstance. A stowaway who was in the wrong naaru vessel at the wrong time.\n\nVenture to the Arcatraz and rescue the gnome, Millhouse Manastorm. Ensure his survival.", objectives = "" }
WordHunterWoW_QuestEN[10887] = { title = "Escaping the Tomb", description = "I appreciate your help, {name}.  I was certain I was going to be killed.\n\nLet's get out of here with a hurry.  It won't be long before more cultists come after us.", objectives = "" }
WordHunterWoW_QuestEN[10888] = { title = "Trial of the Naaru: Magtheridon", description = "Four trials you must pass before you are deemed worthy by the naaru.\n\nOnly one obstacle remains, mortal. Gather an army and travel to the lair of Magtheridon, deep inside Hellfire Citadel. Battle your way to the heart of the chamber and destroy the foul corrupter!", objectives = "" }
WordHunterWoW_QuestEN[10889] = { title = "Return to Shattrath", description = "Your actions, while brave, will surely rouse a vindictive response from Terokk.\n\nHurry to Shattrath. Send word to Rilak!", objectives = "" }
WordHunterWoW_QuestEN[10893] = { title = "Longtail is the Lynchpin", description = "With the Blackwing wyrmcultists massing in the tunnel, we're hard pressed to deal with the situation.  Quite frankly, they have the numbers.\n\nAnd while we've been able to take care of any of their people that get too close, the fact remains that if they attack in earnest, we're going to be overrun.\n\nThe situation calls for someone to get through to the other end of the tunnel, and take out their leader, Draaca Longtail.  Up for some fun?", objectives = "" }
WordHunterWoW_QuestEN[10894] = { title = "Wyrmskull Watcher", description = "Hmm, I'm not certain what we should do.  I'm not much of a military planner.\n\nWatcher Moonshade will know what to do.  He's heading up our defensive efforts at the Wyrmskull Tunnel to the west at the end of Wyrmskull Bridge.  We have a force out there just in case the cultists try anything funny.\n\nPlease, take the note to him with all due haste.", objectives = "" }
WordHunterWoW_QuestEN[10895] = { title = "Zeth'Gor Must Burn!", description = "It's time to strike Zeth'Gor from the air!  Our gryphon riders are ready for a sortie, {name}.  But they need someone on the ground to direct their fire.  Are you ready for a covert mission?\n\nTake these smoke beacons into Zeth'Gor, the Bleeding Hollow stronghold to the west.  They have four guard towers: one near their northern wall, one near their southern wall, one near their forge and another nestled in their foothills.  Place a beacon underneath each of the towers and we'll fly in and bomb them!", objectives = "" }
WordHunterWoW_QuestEN[10896] = { title = "The Infested Protectors", description = "The trees of this land are ravaged by the power that was unleashed from Auchindoun.  The foul magic that was unleashed blasted the land into the wastes you see all around.  The trees that survived are now infested with wretched wood mites that crawl under their bark and gnaw at their flesh.  \n\nRotting forest-ragers and infested root-walkers are breeding grounds for the mites.  They are found along the edge of the wood to the east.  Destroy these creatures and then kill the mites that flee their husks.", objectives = "" }
WordHunterWoW_QuestEN[10898] = { title = "Skywing", description = "Skywing flutters around you.\n\nYou get the feeling he wants you to follow him.", objectives = "" }
WordHunterWoW_QuestEN[10900] = { title = "The Mark of Vashj", description = "", objectives = "" }
WordHunterWoW_QuestEN[10901] = { title = "The Cudgel of Kar'desh", description = "Bring me the elemental signets that the cudgel requires!\n\nThe earthen signet is held by Gruul the Dragonkiller. Gruul can be found inside his lair in the Blade's Edge Mountains.\n\nThe second signet is the blazing heart of a creature known as Nightbane. This mythical beast is said to reside in the hallowed halls of the prophet, Medivh.\n\nMake haste!\n", objectives = "" }
WordHunterWoW_QuestEN[10903] = { title = "Return to Honor Hold", description = "{name}, while you were on your mission in Zeth'Gor, I received news of my commanding officer, Colonel Jules.  He was stricken with a demonic corruption while fighting near the Gor'gaz Outpost, and his situation has grown very bad.\n\nYou have made such great gains for us against the fel orcs.  Your strength in battle is without question... is your spirit just as strong?\n\nPlease, return to Honor Hold and speak with Klatu, in an upper room at the Honor Hold inn.", objectives = "" }
WordHunterWoW_QuestEN[10904] = { title = "Harvesting the Fel Ammunition", description = "We must shut down the Burning Legion's access to Death's Door, but first you're going to destroy their two warp-gates!\n\nThe problem is, we can't even scratch one of those things, so you're going to need to use their own weapons against them.\n\nThe death's might, death's watch, deathforge over-smiths and deathforge technicians carry the ammunition for the fel cannons.\n\nNormally it wouldn't affect any of them, but if you bring the cannonballs to me, I will imbue them with Nature's unbridled wrath!", objectives = "" }
WordHunterWoW_QuestEN[10908] = { title = "Speak with Rilak the Redeemed", description = "You look surprised to be talking to me. I do not blame you. My people, the arakkoa, deserve to be feared.\n\nSpeak with Rilak the Redeemed in Shattrath City if you wish to know more. He can be found in the northern part of the Lower City, with the other outcasts of Skettis.\n\nAnd, {name}, we will speak again.", objectives = "" }
WordHunterWoW_QuestEN[10909] = { title = "Fel Spirits", description = "Colonel Jules was cursed in a battle near the Gor'gaz Outpost, a haunt for Shattered Hand fel orcs.  My master, Barada, works feverishly to cure the poor human, but he needs help.  The Colonel's tormented spirit seeks peace, and his path to peace is, I fear, a path of vengeance.\n\nTake this anchorite relic to Gor'gaz Outpost.  Place it upon the ground near Shattered Hand orcs and defeat them.  This will release their fel spirits -- you must slay those fel spirits for Jules' own spirit's recovery.", objectives = "" }
WordHunterWoW_QuestEN[10910] = { title = "Death's Door", description = "Now there is an even greater threat from the Burning Legion.  To the south is a portal known as Death's Door, which opens upon the horrific world where the Legion breeds its deadly hounds.\n\nTo get there, exit Evergrove by heading east up the ramp.  Follow the path south, through the Bladed Gulch, Razaan's Landing, Razor Ridge and the Scalewing Shelf.  Then, take the ramp down into the Vekhaar Stand and enter Death's Door through the tunnel, south of Mok'Nathal.\n\nOnce there, use this druid signal.", objectives = "" }
WordHunterWoW_QuestEN[10911] = { title = "Fire At Will!", description = "Now that the ammunition can affect the Burning Legion, it's time for you to use it.\n\nThere are two warp-gates, which are used for teleportation and enhancement of the void terrors.  One is in the south and the other in the north, and each is within range of a fel cannon.\n\nUse the naturalized ammunition to take control of each fel cannon and destroy the warp-gates.\n\nAttack the gate with artillery to begin, and be prepared to kill its defenders to keep the cannon alive if necessary.", objectives = "" }
WordHunterWoW_QuestEN[10912] = { title = "The Hound-Master", description = "Baelmon the Hound-Master must die!  He maintains the ritual that keeps the portal functioning.\n\nThe Death's Door portal is located at the north end of the canyon.  When you find it, you will find Baelmon.\n\nYou're going to need help on this one, so take this wand.  When you battle the Hound-Master, use it and a couple of my friends will come to your aid.\n\nAfter you have defeated Baelmon, return to Wildlord Antelarion.\n\nAnd, {name}, thank you for all that you've gone through for us here.", objectives = "" }
WordHunterWoW_QuestEN[10913] = { title = "An Improper Burial", description = "Is there nothing that can be done to stem the tide of corruption? My soldiers have been battling the Auchenai for days now with no end in sight. Each casualty, whether Auchenai or Sha'tar, is snatched from the battlefield - their souls lifted and taken to parts unknown.\n\nI will not have it! A proper burial is out of the question but those fiends will not have their souls! Take this torch and travel to the field of battle, directly east of here. Burn every corpse you see! We will not fuel their rituals.", objectives = "" }
WordHunterWoW_QuestEN[10914] = { title = "A Hero Is Needed", description = "It is not enough. A hero is needed. Our forces are overwhelmed as the Auchenai continue to grow in number.\n\n<Commander Ra'vaj looks at you.>\n\nWill you be the hero? Return to the field of battle and strike at their soldiers. Keep them occupied so that my scouts can get behind their lines and see what they are creating.", objectives = "" }
WordHunterWoW_QuestEN[10915] = { title = "The Fallen Exarch", description = "They are feeding the souls they steal to a coffin that they have dragged out from the Auchenai Crypts. My scouts believe the contents of the coffin to contain the first exarch of the crypts. They seek to resurrect the ancient one!\n\nYou must battle your way to the western side of Auchindoun and disturb the contents of that coffin before they feed it enough souls. Should you lose your way, follow the walking souls.\n\nDestroy whatever is inside that coffin!", objectives = "" }
WordHunterWoW_QuestEN[10916] = { title = "Digging for Prayer Beads", description = "Anchorite Barada plans to exorcise the corruption from Colonel Jules, and will require an assistant for the task.  Such an assistant must be prepared...\n\nI am ashamed to admit that my prayer beads were lost in Honor Hold's courtyard.  I believe the dog Fei Fei stole them and buried them, but I do not know where.  If you speak with his master, Warrant Officer Tracy Proudwell, perhaps she will know where Fei Fei hides his stolen treasures.", objectives = "" }
WordHunterWoW_QuestEN[10917] = { title = "The Outcast's Plight", description = "As an outcast, I am marked for death by arakkoa loyal to the city of Skettis.  I cannot leave these walls for fear of my life, but that doesn't mean I cannot strike at them in retaliation.\n\nI have a small cache of treasure that I'm willing to part with, should you help me strike back at my would-be assassins.  Bring me feathers from the denizens of the various Veils of Terokkar as proof of their demise.", objectives = "" }
WordHunterWoW_QuestEN[10920] = { title = "For the Fallen", description = "When the dreadfang widows attacked our outpost we heard the voice of the naaru calling us to battle.  We pursued the creatures into the night.  Some of our people we found dead in the dark, others we could hear struggling against their captors. \n\nBy morning we had come to this place and we fought a fierce battle but we were beaten.  Dreadfang poison will soon take my companions and I cannot last long.  Before I die I must know that the dreadfang widows were beaten.", objectives = "" }
WordHunterWoW_QuestEN[10921] = { title = "Terokkarantula", description = "You have slain many of the dreadfang widows but they will continue to spawn and soon they will strike at us again.  Deep within Netherweb Ridge is the lair of the Terokkarantula, the brood-mother of these gruesome creatures.  If we are to be safe, she must die.  ", objectives = "" }
WordHunterWoW_QuestEN[10922] = { title = "Digging Through Bones", description = "Oy! You look like you can take care of yerself, {race}. Me and the crew here are looking for a bodyguard to watch over us while we hit a dig site to the north. The pay is pretty good and all you gotta do is make sure no nasty creatures kill me or any of my employees.\n\nIf you successfully make it back without any casualties, Dwarfowitz over there will pay ya.", objectives = "" }
WordHunterWoW_QuestEN[10923] = { title = "Evil Draws Near", description = "Now you must use the Dread Relic in a foul necromantic ritual if you wish to challenge Teribus the Cursed.  To the northeast, beyond Auchindoun, is the Writhing Mound, a place where necromancers gather.  \n\nThe auchenai death-speakers and doomsayers carry doom skulls that are laced with powerful necro-enchantments.  If you collect enough skulls you can use their power along with the power of the Dread Relic to command Teribus to face you.", objectives = "" }
WordHunterWoW_QuestEN[10924] = { title = "Bloody Imp-ossible!", description = "The blood of the warp chasers in this area is a powerful and rare reagent. It's one of my biggest sellers.\n\nNormally, I take my imp, Zeppit, out to help me gather it. Warp chaser blood is simply too caustic to be handled safely by you or I, but it doesn't bother Zeppit.\n\nThings are getting busier here at the shop, so if I send Zeppit with you, will you help gather the blood? Zeppit's attention tends to wander, so you'll need to be close to the chaser when it dies for Zeppit to do his work.", objectives = "" }
WordHunterWoW_QuestEN[10926] = { title = "Return to Sha'tari Base Camp", description = "We will not make it back on our own.  The dreadfang poison is too strong. You must return to Sha'tari Base Camp for us.  Scout Navrin will send a rescue party out to find us.", objectives = "" }
WordHunterWoW_QuestEN[10927] = { title = "Killing the Crawlers", description = "Commander Skyshadow wants this tunnel cleared out so we can expedite trade with the Harborage. I must not leave my post here so I am leaving the task in your hands. Clear the tunnel and report to Commander Skyshadow at once!\n", objectives = "" }
WordHunterWoW_QuestEN[10928] = { title = "Killing the Crawlers", description = "Tor'chunk Twoclaws wants this tunnel cleared out so we can expedite trade with Swamp Rat. I must not leave my post here so I am leaving the task in your hands. Clear the tunnel and report to Tor'chunk Twoclaws at once!\n", objectives = "" }
WordHunterWoW_QuestEN[10929] = { title = "Fumping", description = "How would you like to do a little more work for the Explorers' League? These bone worms have us all quite intrigued.\n\nI've got a drum right here that you can use out in the Bone Wastes. Just bang on the damned thing and see what you get. If it's a worm, kill it and bring back the carcass for us to study. We'll need a good lot of carcasses to get a valid testing sample.", objectives = "" }
WordHunterWoW_QuestEN[10930] = { title = "The Big Bone Worm", description = "I was right! These carcasses you brought me belong to maturing worms. Do you know what that means? It means that somewhere out there is a big one! I think we can get it to come out if we can provide the right kind of food. Let's see... something big! Yes!\n\nI remember seeing clefthooves east of here on the other side of the Bone Wastes. Get out there and kill a clefthoof. Once it's dead, use the drums. Hopefully the big one will come up to feed. If you manage to kill it, bring me its organs!", objectives = "" }
WordHunterWoW_QuestEN[10935] = { title = "The Exorcism of Colonel Jules", description = "{name}, it is time to save Colonel Jules.  His condition has worsened and Barada fears that, if we do not cleanse him of his corruption,  he will be lost to us.\n\nTake the prayer beads you found and speak with Anchorite Barada to begin the ritual.  Let no disruptions stop the ritual... and if all goes well, Colonel Jules will be saved.  Speak with Jules when he is saved, then return to me.", objectives = "" }
WordHunterWoW_QuestEN[10936] = { title = "Trollbane is Looking for You", description = "While we were busy, a messenger was waiting out in the hall.  I suppose he grew tired, or perhaps he simply ran away at the sight of Jules floating around the room.\n\nEither way, Force Commander Danath is looking for you.  I suggest that you seek an audience with him inside the barracks as quickly as possible!", objectives = "" }
WordHunterWoW_QuestEN[10937] = { title = "Drill the Drillmaster", description = "I'm receiving reports that the Shattered Hand fel orcs, out in front of Hellfire Citadel, are organizing for what looks like an all-out assault.  No doubt, they're not happy about your successes against all of the clans.\n\nGet to the base of the citadel, where the Path of Glory ends.  You'll find the fel orcs busy with their preparations, but you're going to catch them with their pants down.\n\nEliminate the one that's in charge of that force.  Kill Drillmaster Zurok!", objectives = "" }
WordHunterWoW_QuestEN[10942] = { title = "Children's Week", description = "One special little girl is going to be very happy to have you as a friend, even if it is for a short while.\n\nTake this whistle.  With it, you will be able to call for the child that you have agreed to sponsor.  It will only last for a limited time - not much longer than Children's Week itself, in fact.\n\nPlease, {name}, call upon your orphan.  I know that she will be more than excited to meet you and have the opportunity to venture out of the city!", objectives = "" }
WordHunterWoW_QuestEN[10943] = { title = "Children's Week", description = "One special little girl is going to be very happy to have you as a friend, even if it is for a short while.\n\nTake this whistle.  With it, you will be able to call for the child that you have agreed to sponsor.  It will only last for a limited time - not much longer than Children's Week itself, in fact.\n\nPlease, {name}, call upon your orphan.  I know that she will be more than excited to meet you and have the opportunity to venture out of the city!", objectives = "" }
WordHunterWoW_QuestEN[10944] = { title = "The Secret Compromised", description = "Thanks again, {name}.  I recognize your name.  Akama has entrusted you with his plans and so I will trust you as well.\n\nThe naga discovered I was working against Illidan and tried to get me to speak by torturing me.  I did not tell them a thing - Akama himself taught me to master pain through meditation.\n\nIllidan asked the naga to bring me to him.  He would have seen right through my flesh and into my soul's deepest secrets.\n\nAkama must be warned.  Our plans are in jeopardy!", objectives = "" }
WordHunterWoW_QuestEN[10945] = { title = "Hch'uu and the Mushroom People", description = "I had a friend named Hch'uu.  She told me that she ended up in the orphanage because she had to run away from an evil fungal giant and got lost.\n\nWe had great fun until her people came and took her away last year.  I think she said she was going to live at a place called Sporeggar.\n\nI'd like to go to see her and have a look at her mushroom village.  The orphan matron told me that it is on the west side of Zangarmarsh, between the Sporewind and Marshlight lakes.\n\nCan we go?  Can we go?  Please?!", objectives = "" }
WordHunterWoW_QuestEN[10946] = { title = "Ruse of the Ashtongue", description = "Olum's sacrifice was tremendous.  I would never have asked him to give up his life myself.  But it is done.\n\nIf we're to lure Illidan back into a false sense of security, we need to do his bidding - at least for now.\n\nI command a vast army of Ashtongue, but - aside from the Deathsworn - none can be trusted.\n\nYou are to perform the deed that Illidan demands.  Take this cowl; it is magical in nature.  You will appear to be one of my men to any who see you slaying Kael's phoenix, Al'ar.", objectives = "" }
WordHunterWoW_QuestEN[10947] = { title = "An Artifact From the Past", description = "Illidan's attention is now on Kael'thas, thanks to you.  The time has come to make our move.\n\nI've had a vision of an artifact that will aid us in our final struggle - the phylactery of a lich known as Winterchill.  Unfortunately its power was lost forever after his defeat in the Battle of Mount Hyjal.\n\nThere might be a way to retrieve this artifact, however.  Legend speaks of a place in Azeroth guarded by bronze dragons...  a place where past and present meet.  It is there you will find what we seek.", objectives = "" }
WordHunterWoW_QuestEN[10948] = { title = "The Hostage Soul", description = "You might wonder why I go to such lengths to hide my intentions.  Why not throw my lot in openly with the naaru?\n\nMy very essence - my soul - is held prisoner inside the Black Temple.  Illidan could destroy me any moment... until now!  This phylactery will allow me to regain control of my soul.\n\nThe time has come, {name}.  I'll lead Maiev and my Deathsworn to Illidan's doorstep.\n\nSpeak to A'dal and and tell him of our plan.  If we strike together we'll break through Illidan's defenses.", objectives = "" }
WordHunterWoW_QuestEN[10949] = { title = "Entry Into the Black Temple", description = "<A'dal shows you an image of a naaru outside of the Black Temple, fighting alongside draenei vindicators and blood elf magisters.  You immediately understand that this is the distraction Akama is waiting for.>", objectives = "" }
WordHunterWoW_QuestEN[10950] = { title = "Auchindoun and the Ring of Observance", description = "One of the priests that comes to visit told a story about a place nearby.  It's called Auchindoun, and it's supposed to be very important to the draenei.\n\nHe said it used to be the place where the bodies of the draenei were taken when they died.  But some time ago, something bad blew it up.\n\nI'd like to see its Ring of Observance.  The orphan matron told me that it is in the middle of the Bone Wastes, on the south side of the Terokkar Forest.\n\nPlease, Mr. {name}, can we go?", objectives = "" }
WordHunterWoW_QuestEN[10951] = { title = "A Trip to the Dark Portal", description = "How can we look at all of these interesting places and not see the Dark Portal?!\n\nThe grown-ups are always trying to tell us scary stories about it and how it's so dangerous, with lots of demons, and stuff.\n\n<Salandria rolls her eyes.>\n\nBut you're here, so it can't be too bad, right?\n\nI want to see for myself.  You remember where it is on the east edge of Hellfire Peninsula?", objectives = "" }
WordHunterWoW_QuestEN[10952] = { title = "A Trip to the Dark Portal", description = "There's one place that if we don't go anywhere else, we have to go to: the Dark Portal!\n\nThe orphan matrons are always trying to scare us with stories about how dangerous it is, with lots of demons, and people like you coming through it.\n\n<Dornaa rolls her eyes.>\n\nBut you're here, and nice, so it can't be too bad, right?\n\nI want to see it for myself.  You remember where it is on the eastern edge of Hellfire Peninsula?", objectives = "" }
WordHunterWoW_QuestEN[10953] = { title = "Visit the Throne of the Elements", description = "Have you heard of the Throne of the Elements?  It's supposed to be this place in Nagrand where there are these powerful elementals.\n\nOne day soon, I'm going to be a powerful mage, or maybe a warlock.  I'm gonna have to learn about some of the elemental forces!\n\nDo you think maybe that we could go there?\n\n<Salandria looks at you slyly.>\n\nYa know, it would be educational to go there.  It's supposedly just north of Garadar, on the other side of Skysong Lake.", objectives = "" }
WordHunterWoW_QuestEN[10954] = { title = "Jheel is at Aeris Landing!", description = "I miss my brother, Jheel.  He's a couple of years older than me, so they let him start an apprenticeship with the ethereal in Nagrand.\n\nIt sure would be nice to go visit him.  He loves geology and stuff, so I bet he's having a great time.\n\nThe orphan matron told me that he's training at a place called Aeris Landing in Nagrand.  It's supposed to be along the road, far to the west of Telaar, and northwest of the great mountain, Oshu'gun.", objectives = "" }
WordHunterWoW_QuestEN[10956] = { title = "The Seat of the Naaru", description = "Do you know anything about the naaru?  They're these angelic beings that have been helping the draenei for a really long time.  I've seen a bunch around Shattrath.\n\nThey say that one naaru, O'ros, was with the Exodar when it traveled to your homeworld.  I should like to see for myself.\n\nCan you take me there?  I bet we could get there fast by using one of the portals inside the Temple of the Moon in Darnassus!  When we get there, if you get lost, we could always just look at your map.", objectives = "" }
WordHunterWoW_QuestEN[10957] = { title = "Redemption of the Ashtongue", description = "When Illidan obtained the Broken's allegiance, Akama was our wisest.  He knew that openly opposing the Betrayer would lead to the extinction of our race.\n\nInstead he has plotted and schemed for this very moment under utmost secrecy.  Failure would be catastrophic... not just for Akama, not just for the Broken, but for all of Outland.  No one this close to Illidan has ever been able to deliver such a terrible blow to him.\n\nHelp Akama free his soul and he will grant you access to Illidan's sanctum.", objectives = "" }
WordHunterWoW_QuestEN[10958] = { title = "Seek Out the Ashtongue", description = "<As you look up at Xi'ri, your mind becomes focused and your will determined.  Your work here is not done; you must go inside the Black Temple and find Akama's followers.>\n\n<Much depends on Akama's success.>", objectives = "" }
WordHunterWoW_QuestEN[10959] = { title = "The Fall of the Betrayer", description = "With Illidan's lieutenants defeated, Akama will be able to force open the doors to Illidan's sanctum.  Be ready to bring your force inside as soon as Akama does.\n\nWe still do not know what has become of Maiev, but we must make our move without her.\n\nI hope your force is up to the task.  Illidan will not be pleased to see Akama.", objectives = "" }
WordHunterWoW_QuestEN[10960] = { title = "When I Grow Up...", description = "When you were my age did you know that you wanted to be a {class} when you grew up?\n\nI'm not sure what I want to be.  Maybe a mage or a warlock, like I said before?  Or maybe a paladin Blood Knight?  Yeah, definitely a Blood Knight!\n\nThey say that the true ones are trained in Silvermoon City on your world.  Could you take me there?  The stories that I've heard say that the paladin trainers reside in the Farstriders' Square in that city.\n\nPlease take me there.  Please!", objectives = "" }
WordHunterWoW_QuestEN[10962] = { title = "Time to Visit the Caverns", description = "In the orphanage, the old priest that comes by told us stories about the Caverns of Time.  He said that it sits in the middle of time, and is really important for keeping things straight.\n\nI don't know what that means, but he said that there were dragons there that were helping to save the world!  I want to see a dragon!\n\nDo you think that we could go there?  He said that the entrance was on the eastern edge of a great desert named Tanaris.\n\nMaybe you could buy me a souvenir while we're there?", objectives = "" }
WordHunterWoW_QuestEN[10963] = { title = "Time to Visit the Caverns", description = "In the orphanage, the old stinky priest that comes by told us stories about the Caverns of Time.  He said that it sits in the middle of time, and is really important for keeping things straight.\n\nI don't know what that means, but he said that there were dragons there that were helping to save the world!  I want to see a dragon!\n\nI think we should go there.  He said that the entrance was on the eastern edge of a great desert named Tanaris.\n\nYou could buy me a souvenir while we're there!", objectives = "" }
WordHunterWoW_QuestEN[10966] = { title = "Back to the Orphanage", description = "Darn it all!  I guess it's time to go back to the orphanage at Shattrath City.\n\nI've had such a great time.  You're the best person in all of the worlds, {name}!  You're my big brother now!\n\n<Dornaa's eyes begin to well up with tears.>\n\nI'm going to miss you so much!  When I grow up, I'm going to be just like you!!!", objectives = "" }
WordHunterWoW_QuestEN[10967] = { title = "Back to the Orphanage", description = "Darn it all!  I guess it's time to go back to the orphanage at Shattrath City.\n\nI've had such a great time.  You're the best person in all of the worlds, {name}!  You're my big brother now!\n\n<Salandria's eyes begin to well up with tears.>\n\nI'm going to miss you so much!!!", objectives = "" }
WordHunterWoW_QuestEN[10968] = { title = "Call on the Farseer", description = "I am sensing something very special about this child indeed.\n\nYou should take her to visit Farseer Nobundo, here in the Exodar.  I believe that he has been expecting the two of you.\n\nLook for Nobundo upon the highest terrace in the Crystal Hall.", objectives = "" }
WordHunterWoW_QuestEN[10969] = { title = "Seek Out Ameer", description = "It would seem that an outside force has taken an interest in the business practices of the Consortium. Five Consortium dealers have gone missing in the past two days. We have reason to believe the Ethereum are involved. If you are interested in assisting, seek out Commander Ameer at the Protectorate Watch Post.\n\nYou will find the Protectorate Watch Post directly east of here on the next island. \n", objectives = "" }
WordHunterWoW_QuestEN[10970] = { title = "A Mission of Mercy", description = "We salvaged this prison orb on our last scouting mission into Ethereum territory. We'd have never found it had it not been for the distress signal that it was faintly emitting.\n\nWe think one of our own might be locked up in there but we have no way of opening the orb up without harming whatever is inside.\n\nWhat we know about the Ethereum is that any of their members could - at any given time - be carrying a key to unlock an orb. Retrieve one and return so that we may uncover the mysteries of this orb.", objectives = "" }
WordHunterWoW_QuestEN[10971] = { title = "Ethereum Secrets", description = "<Ameer holds up a tag.>\n\nI found this prisoner I.D. tag with the remains of the fallen vanguard. I can only assume that all of their prisoners are tagged in the same manner.\n\nI'm going to start cataloguing the tags in hopes of making sense of their penal system. If in your adventures you find more Ethereum prison keys, you can use them to open the Ethereum prisons at the Ethereum Staging Grounds - directly south of here. Bring me back any and all I.D. tags that you find.", objectives = "" }
WordHunterWoW_QuestEN[10973] = { title = "A Thousand Worlds", description = "I have cracked the code! Each tag is broken up into several segments. The front side of the tag is always the same and states: \"A Thousand Worlds...\" I am unsure as to the meaning of this phrase but it sounds insidious.\n\nOn the back side of the tag are the vital statistics. The first set of runes indicates location and the second indicates prisoner type. Furthermore, it would seem that the keys can be combined to form a special key that accesses another prison type. Now I just need more keys...", objectives = "" }
WordHunterWoW_QuestEN[10974] = { title = "Stasis Chambers of Bash'ir", description = "The Ethereum have a settlement on the northernmost shelf of Blade's Edge Mountains known as Bash'ir's Landing. According to the key tablet, much larger versions of the prisons are kept at Bash'ir's. It should also be noted that the Ethereum refer to those prisons as stasis chambers.\n\nThe key tablet grants access to a very specific stasis chamber at the landing known as Stasis Chamber Alpha. Take the key and investigate.\n\nMy image will be awaiting your return at Bash'ir's Landing. Speak to me there.", objectives = "" }
WordHunterWoW_QuestEN[10976] = { title = "The Mark of the Nexus-King", description = "What I must now know is what the Ethereum have held inside the Mana-Tombs of Auchindoun.\n\nIn your battles against the beasts of the stasis chambers of Bash'ir you may run across an item known as the Mark of the Nexus-King. Should you find such an item, return it to me immediately! It is the final piece in crafting a key that will allow access to the stasis chamber inside the Mana-Tombs.", objectives = "" }
WordHunterWoW_QuestEN[10977] = { title = "Stasis Chambers of the Mana-Tombs", description = "The Mark of the Nexus-King that you recovered has allowed me to forge a new key for the stasis chambers found inside the Mana-Tombs.\n\nAccording to the glyphs on the mark, two exist: one near the front and one near Nexus-Prince Shaffar. This key that I am about to give you will open the stasis chamber near the front.\n\nI want you to go to the Mana-Tombs of Auchindoun and open the Mana-Tombs Stasis Chamber.", objectives = "" }
WordHunterWoW_QuestEN[10982] = { title = "The Eye of Haramad", description = "", objectives = "" }
WordHunterWoW_QuestEN[10983] = { title = "Mog'dorg the Wizened", description = "Mog'dorg wise!  Him send Grok to city, look for help.  Bloodmaul clan need help.\n\nMog'dorg say, send powerful little ones to him at Blade's Edge Mountains.  Him stand on tower at Circle of Blood.  Mog'dorg wise!", objectives = "" }
WordHunterWoW_QuestEN[10984] = { title = "Speak with the Ogre", description = "<V'eru's voice fills your mind with crystalline tone and clarity.>\n\nThere is an ogre down in the Lower City, pleading for the assistance of passersby.  They have all turned a deaf ear upon his plight.\n\nDo you think you might aid him?\n\nHis name is Grok, and he is sitting near the merchants to the southeast.\n\nThank you, {name}.", objectives = "" }
WordHunterWoW_QuestEN[10985] = { title = "A Distraction for Akama", description = "<Xi'ri pulses with lights as the Aldor and Scryer forces around him respond to his orders.  Xi'ri's army is ready to push Illidan's forces back and create a distraction for Akama.  The naaru awaits your request to begin the attack.>", objectives = "" }
WordHunterWoW_QuestEN[10989] = { title = "Mog'dorg the Wizened", description = "Mog'dorg the Wizened waits for you at top of da tower.  He tells me to look for a {race} {class} just like you.  You go speak with him about smart things.\n\nGo now, but don't tell no one.  It's a secret!", objectives = "" }
WordHunterWoW_QuestEN[10995] = { title = "Grulloc Has Two Skulls", description = "To the east, at the terminus of Dragons' End, is the Cursed Hollow.  Therein, Grulloc, son of Gruul, plots his dimwitted schemes.\n\nI heard that one of his possessions was stolen from him through trickery.  Was that you?  Unfortunate that he was not slain in the process.\n\nIf we are to regain our freedom, I would have you take his most prized possession, a dragon skull from when he rejoiced in his father's slaying of the black dragonflight.  The only way you'll get the skull is to vanquish him.", objectives = "" }
WordHunterWoW_QuestEN[10996] = { title = "Maggoc's Treasure Chest", description = "On the Razor Ridge, above and to the southeast, Maggoc patrols.  His father assigned him as the warden of the eastern mountain range, and he revels in terrorizing any creature that gets in his way.\n\nAs a son of Gruul, he must be done away with if my clan is to survive.  That's where you come in.\n\nMaggoc carries a treasure chest with him at all times.  Prove to me that he has been slain by bringing me his precious chest.  Feel free to keep whatever you find within it.", objectives = "" }
WordHunterWoW_QuestEN[10997] = { title = "Even Gronn Have Standards", description = "Are you familiar with Shattrath City, {class}?  Above it to the northwest is a place called the Barrier Hills, which you can only get to upon a flying mount.\n\nOne of Gruul's sons, Slaag, exiled himself and took control of the Gordunni ogres that reside there.  Even at such a distance, we cannot afford to leave him in peace, lest he return when the rest of his brothers have been slain.\n\n{name}, you must travel there, and bring back his standard as proof that he has been dealt with.", objectives = "" }
WordHunterWoW_QuestEN[10998] = { title = "Grim(oire) Business", description = "There is one more gronn to be slain: Skulloc Soulgrinder. He keeps himself hidden away, but there is a way to coax him forth.\n\nHe was trained by an ogre warlock known as Vim'gol the Vile, whose grimoire you must retrieve!\n\nVim'gol must be summoned by standing within a fire ring at his circle. Find Vim'gol's Circle in the mountains, to the northeast, near the Broken Wilds.", objectives = "" }
WordHunterWoW_QuestEN[11000] = { title = "Into the Soulgrinder", description = "The grimoire is the key to Skulloc's downfall.\n\nRead aloud from the book at Soulgrinder's Barrow to initiate the ritual.  An object known as the Soulgrinder will appear, as well as Skulloc's ghostly victims, who will try to destroy it.  You must keep them from doing so long enough to force Skulloc fully into the world.\n\nFind the barrow by heading north through the Daggermaw Canyon on the other side of the Circle of Blood.  It is on the right side before Gruul's Lair.\n\nBring back Skulloc's soul.", objectives = "" }
WordHunterWoW_QuestEN[11002] = { title = "The Fall of Magtheridon", description = "The source of Illidan Stormrage's fel orc army has been vanquished. The manufactory halts production of its grim product - at least for now. All that remains are a few trinkets and this severed head - a fitting trophy for a hero of the Alliance.\n\nReturn Magtheridon's head to Danath Trollbane at Honor Hold.\n", objectives = "" }
WordHunterWoW_QuestEN[11003] = { title = "The Fall of Magtheridon", description = "The source of Illidan Stormrage's fel orc army has been vanquished. The manufactory halts production of its grim product - at least for now. All that remains are a few trinkets and this severed head - a fitting trophy for a hero of the Horde.\n\nReturn Magtheridon's head to Nazgrel at Thrallmar.\n", objectives = "" }
WordHunterWoW_QuestEN[11004] = { title = "World of Shadows", description = "Sky Commander Adaris was seriously injured during a Skettis incursion.  He's been in and out of consciousness since.\n\nI fear he has succumbed to a feverish delirium.  During brief lucid moments he demands that I prepare an elixir made from shadow dust carried by the arakkoa.  He seems to believe it will allow him to see into a \"world of shadows\" where the arakkoa's true leaders dwell.\n\nI do not believe this nonsense for a second, but I fear he won't rest until I obtain such an elixir.  Will you help?", objectives = "" }
WordHunterWoW_QuestEN[11005] = { title = "Secrets of the Talonpriests", description = "Thank you for paying heed to my fevered rants.  All along we had been trying to identify and destroy the Skettis chain of command; we had learned of three clerics known as the talonpriests, but we'd never seen them with our own two eyes.  Now we know why.\n\nTalk to Severin to obtain more of the elixir he discovered.  Use the elixir to find and kill the three talonpriests: Ishaal, Skizzik and Zellek.  They're rumored to dwell in Veil Ala'rak, near the eastern shore of Blackwind Lake.", objectives = "" }
WordHunterWoW_QuestEN[11007] = { title = "Kael'thas and the Verdant Sphere", description = "The air around you hums - a gentle hum. The naaru are aware of your victory. Perhaps they are the reason you were compelled to pick up this sphere from the still-twitching remains of Kael'thas Sunstrider. What secrets could it hold?\n\nPerhaps A'dal in Shattrath City could make sense of the item.", objectives = "" }
WordHunterWoW_QuestEN[11008] = { title = "Fires Over Skettis", description = "You think you have what it takes to be part of the Skyguard?  We'll have to see how you handle yerself in the air.\n\nThe arakkoa are breeding a gargantuan variety of their attack pets and are using it against our scouts.  I want you to take these blasting charges and use them to destroy hatcheries above the arakkoa's dwellings.  Avoid the monstrous kaliri guarding the hatcheries.  They'll knock you off your mount before you know what hit you.", objectives = "" }
WordHunterWoW_QuestEN[11009] = { title = "Ogre Heaven", description = "Now that you have delivered us from bondage, we can begin the process of reunifying the clans.  This will take some time; old grudges are difficult to overcome.\n\nBut more pressing, you must go to Ogri'la in the heavens above to the west.  You must defend it, and us, from those forces above that the gronn used to protect us from: ethereals, demons, and worst of all, the black dragonflight.\n\nWhen you find ogre heaven, seek out the wisdom of Chu'a'lor on how best to proceed.", objectives = "" }
WordHunterWoW_QuestEN[11010] = { title = "Bombing Run", description = "You have a flying mount... so what!  You think you have what it takes to use it properly?\n\nForge Camp: Wrath and Forge Camp: Terror, to the north and south, are a major pain in my backside, as well as being a threat to peaceful Ogri'la.  With all of those fel cannons shooting down the Skyguard left and right, we can't get through there to take care of business.\n\nYou want to prove yourself?  Take these bombs and knock out their ammo stacks.  Just don't let them shoot you down, too!", objectives = "" }
WordHunterWoW_QuestEN[11012] = { title = "Blood Oath of the Netherwing", description = "", objectives = "" }
WordHunterWoW_QuestEN[11013] = { title = "In Service of the Illidari", description = "Netherwing Ledge... What was once a bastion of sanctuary for the Netherwing is now home to the Dragonmaw. While the orcs may have control of our territory, our magic there is still strong. Strong enough to cloak your true identity and allow you to infiltrate the ranks of Dragonmaw.\n\nI have prepared this letter for you to present to their leader, Overlord Mor'ghor. Fly headlong into the maw of our enemy and seek out Dragonmaw Base Camp to start your new life as a fel orc of Illidan Stormrage.", objectives = "" }
WordHunterWoW_QuestEN[11014] = { title = "Enter the Taskmaster", description = "<Mor'ghor crumples up the service letter and tosses it aside.>\n\nAlright grunt, first things first. If you're gonna join my beloved Dragonmaw army, you'll need to work. Everyone works up here on the ledge. Get a job and don't screw it up and I'll see if there might be something more interesting for you to do later.\n\nGo talk to Taskmaster Varkule Dragonbreath. He's standin' in the middle of town. He'll assess your skills and assign work as he sees fit.\n\nNow get out of my face!", objectives = "" }
WordHunterWoW_QuestEN[11015] = { title = "Netherwing Crystals", description = "No good at nothin'? That's fine. Even lunkheads like you can be used around here. Just find creatures on the ledge and kill 'em. Sometimes they'll have nether crystals on their carcasses. Gather those and bring 'em back to me and I'll consider your work order for the day complete.\n", objectives = "" }
WordHunterWoW_QuestEN[11016] = { title = "Nethermine Flayer Hide", description = "A skinner, eh? Well you'll find plenty to skin here! You gotta search for flayers around crystal formations. Take 'em down and take their hides. Sometimes they'll have a hide worth keepin'. Bring those to me.", objectives = "" }
WordHunterWoW_QuestEN[11017] = { title = "Netherdust Pollen", description = "A flower picker?! Hilarious... Unfortunately, our mages and shaman need your services. The netherdust bushes that grow on this ledge have special pollen that is apparently very useful in their magical dealings. Bring me that stuff and I'll consider your work order complete.", objectives = "" }
WordHunterWoW_QuestEN[11018] = { title = "Nethercite Ore", description = "A miner!\n\n<Varkule salutes.>\n\nAn orc after my own heart! That's how Varkule got his start - minin'! There ain't nothin' better than getting down and dirty in the mines, is there?\n\nNow get out there and find those nethercite deposits. Strip 'em for all their worth and bring me back the ore.", objectives = "" }
WordHunterWoW_QuestEN[11019] = { title = "Your Friend On The Inside", description = "", objectives = "" }
WordHunterWoW_QuestEN[11020] = { title = "A Slow Death", description = "The Dragonmaw have peons stationed at nearly every crystal formation up here. While the outright slaying of them would draw far too much unwanted attention to you, there is a way that we can thin their numbers and remain below the suspicious eyes of Mor'ghor.\n\nVenture into the wilds of Shadowmoon Valley and slay the tainted wildlife. Take from them their corrupt fel glands. Use those fel glands with this mutton that I'll give you near the peons. They'll take one bite and fall deathly ill!", objectives = "" }
WordHunterWoW_QuestEN[11021] = { title = "Ishaal's Almanac", description = "This mysterious tome was on Talonpriest Ishaal's body.  It contains arcane symbols and charts of celestial bodies beyond your comprehension.\n\nAll writing is in a language you don't understand; likely an ancient version of the arakkoa written tongue.  Perhaps you should bring this to Sky Commander Adaris.", objectives = "" }
WordHunterWoW_QuestEN[11022] = { title = "Speak with Mog'dorg", description = "King {name}!  You speak with Mog'dorg the Wizened before you leave and go to Ogri'la!", objectives = "" }
WordHunterWoW_QuestEN[11023] = { title = "Bomb Them Again!", description = "We're still having problems with those flak cannons, {name}.\n\nDon't get me wrong -- I think that you did an outstanding job the last time out -- but, that doesn't change the fact that those damned demons seem to be replenishing their ammo supplies faster than we can knock them out.  And that means we're having a hell of a time getting our people through there, not to mention the risk those demons pose to Ogri'la.\n\nWhat do you say?  Want to take another shot at it?", objectives = "" }
WordHunterWoW_QuestEN[11024] = { title = "An Ally in Lower City", description = "There is an arakkoa in Lower City by the name of Rilak...  He can be trusted.  Take the book... to him.\n\n<Adaris drifts into unconsciousness as he returns the book to you.>", objectives = "" }
WordHunterWoW_QuestEN[11025] = { title = "The Crystals", description = "When prepared correctly, the crystals of the mountains exhibit strange powers, such as the clarity of mind that we have found here in Ogri'la.\n\nAll of the creatures atop the mountains covet the crystal shards and use them to further their own goals.  An economy has even sprung up around them.\n\nTo assist us, you must first learn about the Apexis shards.  Bring me some.  In addition to the creatures here having them, they can sometimes be found where the flayers dig at the larger crystals.", objectives = "" }
WordHunterWoW_QuestEN[11026] = { title = "Banish the Demons", description = "You've arrived at the perfect time, friend!  We are in need of assistance.  In return, you will receive something very rare, which will help us both in the end.\n\nWe're not a violent ogre any longer, but the demons nearby threaten to overrun us and the Skyguard.  The problem with demons is that, once killed, they come right back in new bodies!\n\nBut, if you use this crystal to summon a banishing portal, when they die near it, their essences will be drawn in and banished back from whence they came!", objectives = "" }
WordHunterWoW_QuestEN[11028] = { title = "Countdown to Doom", description = "This almanac presages the return of Terokk, the most powerful and terrible Skettis king in arakkoa history.\n\nI always believed this to be the mere legend, {name}.  The return of the talonpriests and your recovery of this tome indicate otherwise.\n\nWith each day, Terokk comes closer to returning to full strength.  Your only chance is to bring him to our world prematurely.  Return to Skettis and speak to Adaris about this.  Let us hope he has the wisdom to do the right thing.", objectives = "" }
WordHunterWoW_QuestEN[11029] = { title = "A Shabby Disguise", description = "Open the package, {name}.  It is a disguise.  It doesn't look very convincing, does it?\n\nI craft them for ethereal smugglers in search of rare books.  There is an arakkoa scribe who dwells in the central island in Skettis, Terokk's Rest; his name is Sahaak.  He is old and nearly blind.\n\nUse the disguise to speak with him and obtain the book known as the Adversarial Bloodlines.  Be careful, {name}.  The disguise won't fool the other arakkoa.", objectives = "" }
WordHunterWoW_QuestEN[11030] = { title = "Our Boy Wants To Be A Skyguard Ranger", description = "{class}, we've got a problem -- we have lots of sons.  And ever since the Skyguard moved in nearby, all our sons ever talk about is joining their ranks.\n\nAs a proud father, we want them to have every advantage for when they apply.  So, would you go to the fel crystalforge at either forge camp to the north or south, and procure a magic flask for our sons?  You can't miss their green smoke.\n\nWe think that they take ten apexis shards to make.  We'd give you the shards, but we don't have any at the moment.", objectives = "" }
WordHunterWoW_QuestEN[11035] = { title = "The Not-So-Friendly Skies...", description = "On the northeast edge of this island exists a dock used for the packaging and transport of Netherwing crystals and relics. Dragonmaw Transporters transport the goods from the dock to Dragonmaw Fortress while Dragonmaw Ascendants guard the ground from any would-be attackers.\n\nThis leaves one opening for you to make a strike at the Dragonmaw: The Dragonmaw Skyway.\n\nFly to the shattered islands of the Dragonmaw Skyway and ambush the transporters that use the route. Recover our stolen relics!", objectives = "" }
WordHunterWoW_QuestEN[11036] = { title = "Out of This World Produce!", description = "I'll be the first to admit I'm not quite sure what this order is for, but Rocket-Chief Fuselage's instructions were very specific -- only the very best fruit, preserved to survive a long voyage and sealed against the elements.\n\nThere were other specifications, zero-gravity this and low pressure that. I don't pretend to understand it, but the price is right, so he'll get his superfood. Bring this crate to him up at Area 52. After crossing into Netherstorm, keep following the road until you see the town.", objectives = "" }
WordHunterWoW_QuestEN[11037] = { title = "A Strange Vision", description = "I've had a most unusual vision, {name}, and I don't know quite what to make of it. I've seen an arrow, an immense arrow, riding into the sky on a trail of fire. Such a feat is trivial for a skilled mage, but somehow I know the arrow I saw is not the product of magic.\n\nIt will be unlike anything the people of Azeroth have ever achieved. You must seek out the people working on this, {name}. Lend them your help, for without it, their efforts may yet fail.", objectives = "" }
WordHunterWoW_QuestEN[11038] = { title = "Assist Exarch Orelis", description = "Not long ago, High Priestess Ishanah sent a small group of anchorites to Netherstorm, under the command of Exarch Orelis. They were to investigate the activities of Kael'thas and his minions, but we haven't received any reports of their findings yet.\n\nI worry that our presence in the area might not be strong enough to carry out the mission. I'm certain that the exarch could benefit from your knowledge and experience. Are you willing to travel to Area 52 and assist him?", objectives = "" }
WordHunterWoW_QuestEN[11039] = { title = "Report to Spymaster Thalodien", description = "Some time ago, Voren'thal dispatched a small team to Netherstorm to investigate the activities of Kael'thas. Our leader has the utmost confidence in Spymaster Thalodien and his compatriots, and has decided to honor his request for reinforcements.\n\nThalodien's report was brief, but clear that he's encountered something of great importance. Report to him at Area 52 and assist him in any way possible, {name}.", objectives = "" }
WordHunterWoW_QuestEN[11040] = { title = "Parts for the Rocket-Chief", description = "You can count on one hand the number of times I've collaborated with a goblin. We're far more likely to be in competition with them, but when I received Rocket-Chief Fuselage's request, I just couldn't refuse him.\n\nThis crate is full of parts I'm not using here, but that the rocket-chief might be able to put to use on his project. Would you be kind enough to deliver them if you're on your way to Area 52?\n\nWho knows, maybe some fine gnomish parts could keep his creation from exploding!", objectives = "" }
WordHunterWoW_QuestEN[11041] = { title = "A Job Unfinished...", description = "In the name of our great master... For the glory of Illidan!\n\nBy order of Overlord Mor'ghor, the great plateau of Netherwing Ledge is to be secured. With all Netherwing drakes captured or forced off of the land, rock flayers are running rampant and threatening crystal harvesting operations.\n\nDestroy them all, their den mother and her consort, Arvoar.\n\nMor'ghor commands it!\n\n<It would appear that this orc failed to take the plateau. It is time to prove your worth to Mor'ghor!>", objectives = "" }
WordHunterWoW_QuestEN[11042] = { title = "A Mystifying Vision", description = "A strange vision haunts me, {name}. I see a continuous cloud of smoke ascending toward the sky, left in the wake of a giant fire moving ever faster away. It is not a natural phenomenon, nor a creation of evil; that much I know.\n\nI have no knowledge of what it looks like, save that it is the product of the labor of many. Yet, without more hands, it may never come to be.\n\nTravel to Netherstorm, {class}. Locate those responsible for this creation and offer them your aid.", objectives = "" }
WordHunterWoW_QuestEN[11043] = { title = "Building a Better Gryphon", description = "I've heard that the Wildhammer dwarves maintain a gryphon roost at their fortress down in southern Shadowmoon Valley. If you're going down there, would you speak to them on my behalf? I have some ideas on how to improve their gryphons!\n\nWhy stop at armoring them when you could attach an altimeter, a rear view mirror, and rocket? Imagine how fast you could go with one of those babies strapped to your gryphon's back! I'll call it the TurboGryphon 8000!", objectives = "" }
WordHunterWoW_QuestEN[11044] = { title = "Visions of Destruction", description = "A vision of cataclysm often disturbs my rest -- a rain of green fire falling to the earth, felling the valiant defenders of a mighty fortress. It has haunted me for weeks now, although I have only recently come to understand its meaning.\n\nTo the far east, in Shadowmoon Valley, the Wildhammer dwarves endure constant attacks from the Burning Legion and numerous other foes. They fight bravely, but without relief, their enemies will triumph. Go to their side, {name}. Help them in their fight.", objectives = "" }
WordHunterWoW_QuestEN[11045] = { title = "Zorus the Judicator", description = "The history of Shadowmoon Valley is a long and troubled one. Few delve into it for fear of breathing new life into the unspeakable atrocities that took place there.\n\nNot all are so timid, though. Zorus the Judicator searches for the truth about the ghosts of Shadowmoon's past. It is a staggering undertaking, one with which he would welcome help, I'm sure.\n\nIf you should venture into the valley, look for Zorus at Wildhammer Stronghold, in the central portion of the valley's southern region.", objectives = "" }
WordHunterWoW_QuestEN[11046] = { title = "Chief Apothecary Hildagard", description = "The history of Shadowmoon Valley is a long and troubled one. Few study it for fear of breathing new life into the unspeakable atrocities that took place there.\n\nNot all are so timid, though. Chief Apothecary Hildagard's research delves into the ghosts of Shadowmoon's past. It is a staggering undertaking, one with which she would welcome help, I'm sure.\n\nIf your travels bring you there, seek Hildagard at Shadowmoon Village, in the northwestern reaches of the valley.", objectives = "" }
WordHunterWoW_QuestEN[11047] = { title = "The Apprentice's Request", description = "As an apprentice wind rider master, one of my tasks is to care for the beasts when they're not flying. The problem is that we have so few here, there's very little downtime for any of them.\n\nI'm afraid we'll work them all to death if we don't receive any replacements. There's a large stable down in Shadowmoon Village, in western Shadowmoon Valley. Dama Wildmane oversees the wind rider care and training there.\n\nWould you speak with her on our behalf and let her know about our situation?", objectives = "" }
WordHunterWoW_QuestEN[11048] = { title = "Kroghan's Report", description = "My original orders were to remain in Garadar for a short time, then continue on and report to Blood Guard Gulmok at Shadowmoon Village. What I've seen in my time here is that Garadar could benefit from a long term Horde liaison.\n\nI know that Blood Guard Gulmok needs all the troops he can get, but I know he'll understand that my mission here isn't yet complete. Travel to Shadowmoon Village, in northwestern Shadowmoon Valley, and inform Blood Guard Gulmok of my delayed arrival.", objectives = "" }
WordHunterWoW_QuestEN[11049] = { title = "The Great Netherwing Egg Hunt", description = "Should you discover any Netherwing eggs while exploring, bring them to me.\n\nBe warned, a Netherwing egg is a rare discovery. Do not become frustrated if you cannot locate one. These Dragonmaw have been very thorough in collecting most of them and shipping them off to parts unknown.\n\nEggs might be found on creatures of the island, near crystal formations, in the mines, or even inside a nethercite node or netherdust bush.\n\nKeep a low profile. We don't need Mor'ghor catching wind of your actions.", objectives = "" }
WordHunterWoW_QuestEN[11051] = { title = "Banish More Demons", description = "If we know the demons, and we do because we've studied them extensively, they're fast at work repairing any damage that has been done to their precious transporter.\n\nSo, if you want a chance at another darkrune, take our banishing crystal back out there and eliminate more demons.  Besides, you want to help us to lessen the threat that the demons pose, yes?\n\nWe said \"chance\" because the process we use yields mixed results.  You might get a darkrune, or you might get something else entirely.", objectives = "" }
WordHunterWoW_QuestEN[11052] = { title = "Akama's Promise", description = "<Akama inserts the crystal into the medallion in his hand.>\n\nI am not as strong as I once was, {name}.  Being so close to evil itself all these years - I do not know if I can trust myself with an artifact as powerful as this.\n\nTake this as my promise to you that when the time comes and you face Illidan, I will be on your side.  Take it to the one being we know we can trust with its power.  Take the medallion to A'dal in Shattrath City.", objectives = "" }
WordHunterWoW_QuestEN[11053] = { title = "Rise, Overseer!", description = "Rare it is that a peon survives for as long as you have. Rarer still is when a peon rises from the dregs to attain a new rank.\n\n<Varkule claps.>\n\nThe Overlord has called for you, grunt. A new rank awaits, no doubt.", objectives = "" }
WordHunterWoW_QuestEN[11054] = { title = "Overseeing and You: Making the Right Choices", description = "So you're the new overseer, eh? Well there's one thing any good overseer needs and that's the proper disciplinary weapon. Before you can go out there and knock some sense into these peons you need to have your \"piece.\" Each overseer has to gather the materials required to make their own \"piece\" and you'll be no different.\n\nI'll need knothide leather and the hardened hide of Tyrantus. You'll find Tyrantus in Eco-Dome Farfield, located in the northern reaches of Netherstorm.", objectives = "" }
WordHunterWoW_QuestEN[11055] = { title = "The Booterang: A Cure For The Common Worthless Peon", description = "This is your booterang. There are many like it but this one is yours.\n\nAs an overseer you will use this booterang to sow terror into the hearts of defiant peons. Proper use of the booterang will instill obedience and ensure subservience.\n\nVenture forth to the crystal fields and discipline any peons that you see slacking off. Show them the might of the booterang!\n", objectives = "" }
WordHunterWoW_QuestEN[11056] = { title = "Hazzik's Bargain", description = "Do not draw attention to our conversation.  Adaris would not approve.\n\nI belong to the lowest caste of arakkoa, {name}.  During Terokk's rule I would've been sacrificed to the dark powers worshipped by his talonpriests.  If what you say is true and the talonpriests are seeking Terokk's return, then you must prevent them from succeeding - regardless of what your leader says!\n\nI've something to offer you that you'll find useful.  There is a package at my old dwelling in Upper Veil Shil'ak.  Bring it to me!", objectives = "" }
WordHunterWoW_QuestEN[11057] = { title = "The Trouble Below", description = "We commend your zeal in wanting to help out here in Ogri'la, {class}.  However, we have a favor to ask of you before we can accept your assistance.\n\nDown below our brethren are enslaved to the Sons of Gruul.  Please, speak with Mog'dorg the Wizened, who is leading an ogre resistance against their gronn masters.\n\nSeek him out atop the tower on the eastern side of the Circle of Blood arena.", objectives = "" }
WordHunterWoW_QuestEN[11058] = { title = "An Apexis Relic", description = "Long ago a now-extinct sect of the arakkoa known as the Apexis lived here.  Remnants of their civilization are still present.  We call them apexis relics.\n\nWhat we know about them is that, when properly used, they grant a boon.  Each relic presents a colored sequence which, when the crystals are pressed in the correct order, leads through a series of levels, each harder than the last.\n\nAn apexis shard is needed to power the relic.  Return when you have attained the insight of the apexis vibration.", objectives = "" }
WordHunterWoW_QuestEN[11059] = { title = "Guardian of the Monument", description = "You've figured out how to use the single-person relics, but as you may have seen, there are bigger ones, which they surround.\n\nThese larger apexis monuments function in much the same way, but they take 35 apexis shards to activate.\n\nOf greater concern to us are the guardians that are summoned through their use.  These crystal constructs turned on their arakkoan masters long ago, and now endanger Ogri'la.\n\nWe would ask that you destroy one and bring us proof.", objectives = "" }
WordHunterWoW_QuestEN[11061] = { title = "A Father's Duty", description = "As to that other magical flask, it can only be obtained from one spot: Bash'ir Landing.  It's an ethereal base, and they aren't too friendly with outsiders, so it might be a little dangerous to obtain.\n\nWhere's Bash'ir Landing, you ask?  Well, if you get on your flying steed and head north by northeast, well past Forge Camp: Wrath, you'll eventually spot it.  The Bash'ir crystalforge itself is at the northeast corner of the landing.\n\nThank you for doing this, {name}.  It'll mean the world to our sons!", objectives = "" }
WordHunterWoW_QuestEN[11062] = { title = "The Skyguard Outpost", description = "{name}, we were wondering if you might be willing to visit our friends just to the north at the Skyguard Outpost?\n\nSky Commander Keller and his Skyguard are here running missions for our mutual protection, and he's asked us to send along anyone that we feel would excel at helping out.\n\nThat would be you!\n\nHead up there as soon as you can, and please, give him our regards.", objectives = "" }
WordHunterWoW_QuestEN[11063] = { title = "Earning Your Wings...", description = "", objectives = "" }
WordHunterWoW_QuestEN[11064] = { title = "Dragonmaw Race: The Ballad of Oldie McOld", description = "Don't let the gray hair fool you, grunt. I'm still ten times the rider that you are! And don't go thinking that this old dog doesn't have any tricks up his sleeve.\n\nNow all you gotta do is follow me and try not to get knocked down off your mount. If you can do that, Oldie will admit defeat.\n\nWe'll lift off as soon as you're ready.\n", objectives = "" }
WordHunterWoW_QuestEN[11065] = { title = "Wrangle Some Aether Rays!", description = "Wanna help the Skyguard and Ogri'la?\n\nJust hear me out before you walk away, hot stuff.  We're in need of remounts!  The bombing runs and missions to Bash'ir Landing have taken a toll on our mounts.\n\nThe aether rays that fly around Vortex Summit, and the Crystal Spine to the northeast, look like they'd do just fine.  You don't even have to bring them back here, though that would be nice.  Just break and rope them, and we'll track them down later.\n\nThink you can wrangle me up some?", objectives = "" }
WordHunterWoW_QuestEN[11066] = { title = "Wrangle More Aether Rays!", description = "So, I hope that you're up to helping us wrangle up even more aether rays!  From what I can see, you're a natural with the rope!  And it's for a good cause, because not only do we get fresh mounts, but it helps us to protect Ogri'la, which the ogres appreciate.\n\nRemember, the aether rays fly around Vortex Summit, and the Crystal Spine to the northeast.\n\nThink you can wrangle me up some more?", objectives = "" }
WordHunterWoW_QuestEN[11067] = { title = "Dragonmaw Race: Trope the Filth-Belcher", description = "Dragonmaw treat you right, {name}. Even a worn out cursed being like me is given a chance. Now if you want to prove your worth to the Skybreakers, you will have to defeat me.\n\nI'm going to shake you off my tail like a bad case of fleas...\n\nWe'll lift off when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[11068] = { title = "Dragonmaw Race: Corlok the Vet", description = "You are challenging ME? Don't make me laugh!\n\nYou're serious? Very well then! All you need to do is not die. You can manage to not die, right?? Even if I'm hurling skulls at you and flying circles around your pathetic riding skills?\n\nJust let me know when you're ready and we'll lift off.", objectives = "" }
WordHunterWoW_QuestEN[11069] = { title = "Dragonmaw Race: Wing Commander Ichman", description = "Three years I spent in that hell hole. Three years a prisoner of war to the damnable Frostwolf Clan. Made to sit in their tower and listen to them endlessly whine about the bridge to Dun Baldar. About how it's \"unfair\" that blah, blah, blah, blah... War isn't fair! To hell with 'em all!\n\nThe minute I was freed I left that place forever and came here to start a new life. Now Mulv and I are vying for the top orc spot. If you want it, you're gonna have to go through me, scrub.\n\nWe go when you're ready.\n", objectives = "" }
WordHunterWoW_QuestEN[11070] = { title = "Dragonmaw Race: Wing Commander Mulverick", description = "Three years of blood, sweat and tears. Mostly tears... The amount of crying that a hardened soldier does when it comes down to all-out war is amazing!\n\n\"They're jumping into our tower with their horses!\" \"Why is their base so well defended?\" \"They're taking our relief hut, I'm going A.W.O.L.!\"\n\nWimps...\n\nI took the first train out of \"cry-town\" the minute the Dark Portal opened. Now I'm a top gun for the Dragonmaw. If you want to be top orc, you'll have to defeat me.\n\nWe go when you are ready.\n", objectives = "" }
WordHunterWoW_QuestEN[11071] = { title = "Dragonmaw Race: Captain Skyshatter", description = "You dare challenge Skyshatter? The world around you will fall into darkness as the heavens are torn asunder by my meteors.\n\nYou stand no chance, soldier. Yet it is your desire to die...\n\nI will entertain this morbid obsession if only to prove a point to any that might foolishly dream of making the same mistake.\n\nWe ride when you are ready!", objectives = "" }
WordHunterWoW_QuestEN[11072] = { title = "Adversarial Blood", description = "The descendants held prisoner by the Skettis talonpriests are listed in this book: Gezzarak the Huntress, Karrog the crystal giant, the heretic known as Darkscreecher Akkarai and Vakkiz the Windrager.  They will all need to be slain before Terokk returns to this world.\n\nYou will need the scrolls carried by the time-lost arakkoa to call them forth at the summoning circles in Skettis.  Bring me a token from each one.  These are powerful beings you will be facing; you would do well to bring friends.", objectives = "" }
WordHunterWoW_QuestEN[11073] = { title = "Terokk's Downfall", description = "I... I've turned a blind eye to your dealings with the arakkoa prisoner, {name}.  It looks like your instincts to cooperate with him were right.\n\nYou must understand... I would've faced a mutiny in my current state if I endorsed your efforts to bring Terokk to this world.\n\nTake the items that Hazzik prepared for you and go ahead with your plan.  I will command my men to back you up when the time comes.  I recommend that you bring a force of your own as well.  I fear you'll only get one chance at this.", objectives = "" }
WordHunterWoW_QuestEN[11075] = { title = "The Netherwing Mines", description = "Your help is required at the Netherwing Mines, overseer {name}.\n\nTwo days ago our mining operations came to a grinding halt when we made a grim discovery. A miner was working in the depths of the mine and struck his pick upon an unusual crystal formation. Unfortunately, this crystal formation was attached to a very angry nether dragon. The beast woke from its slumber and annihilated all of our workers.\n\nReport to the Mistress of the Mines. They await you at the mouth of the mines, southwest of here.", objectives = "" }
WordHunterWoW_QuestEN[11076] = { title = "Picking Up The Pieces...", description = "Much of our hard work lies scattered about in these mines. Carts full of cargo are littered across every inch of this mine! We just can't get to any of it with the current infestation.\n\nThat's where you come in, {name}. Your daily duty here at this mine is to collect the cargo left behind by the miners and deep mine workers.\n\nGather the nethermine cargo and return it to me or my sister.", objectives = "" }
WordHunterWoW_QuestEN[11077] = { title = "Dragons are the Least of Our Problems", description = "That dragon waking up riled up a host of other nasty creatures in these mines. Two types are proving to be a thorn in the side of the Dragonmaw: Nethermine flayers and Nethermine ravagers. You must help us by killing them off. All I ask is your involvement once per day.\n\nGet in there and kill as many as you can!", objectives = "" }
WordHunterWoW_QuestEN[11078] = { title = "To Rule The Skies", description = "As ye've flown around, ye must have noticed the dragons above.  I trust ye haven't fallen victim ta their rage.  Help us put an end ta it, {name}!\n\nRivendark and Obsidia lord over this terrace, while Insidion and Furywing rule the skies over yon terrace ta the northeast.  Each has a perch on their respective domains.  I be wondering if ye and yer friends will go ta one, lad, break open an egg with 35 apexis shards and attract the dragon down.\n\nBring me some teeth as proof.", objectives = "" }
WordHunterWoW_QuestEN[11079] = { title = "A Fel Whip For Gahk", description = "Gahk think being smart is dumb sometimes.  Gahk not want to think.  Me want little {race} to smash big demons!\n\nDey have some chiefs, and da chiefs all have whips to hurt da little demons.  You bring Gahk a whip!\n\nYou challenge demon chief in forge camps at burning, green, fel crystal prism.  Use 35 apexis shards to get dem to come.  Dey called Galvanoth, Braxxus, Zarcsin and da Mo'arg Incinerator.", objectives = "" }
WordHunterWoW_QuestEN[11080] = { title = "The Relic's Emanation", description = "Now that you have felt the enlightening vibrations of the apexis relics, it is time for you to further your understanding of their workings.  We are very eager to benefit from your observations!\n\nAs you progress in your ability to attune to the relics, you will gain a higher level of knowledge.  This recognition will come in the form of an emanation from the relic.\n\nReturn to us when you have attained such an emanation.", objectives = "" }
WordHunterWoW_QuestEN[11081] = { title = "The Great Murkblood Revolt", description = "This document outlines a revolt planned by the Murkblood broken. It seems that the dragon was to be used as a diversion to draw attention away from their escape. Looking at all of the corpses littering the mine, it would be safe to assume that their plans failed.\n\nReturn the escape plans to the Mistress of the Mines.", objectives = "" }
WordHunterWoW_QuestEN[11082] = { title = "Seeker of Truth", description = "These miners are far too stupid to concoct any type of escape plan. We must find and punish the source. Venture into the depths of the mine and seek out the Murkblood overseers. If they have not been overcome by the denizens of the mine, they will undoubtedly be hiding.\n\nOnce you locate one, interrogate him until he reveals the true mastermind behind the escape. Return to me with the identity of this traitor and the hand of the overseer.", objectives = "" }
WordHunterWoW_QuestEN[11083] = { title = "Crazed and Confused", description = "Don't worry about this dragon, {name}. We've got plans for it...\n\nDeeper in this mine is a band of crazed Murkblood. After the dragon broke out, they were cut off from the exit. Somehow, after a mere 2 days of isolation, they've lost all sense of decency.\n\nThey've resorted to cannibalism and the promotion of mayhem. We don't need that kind of madness in this place. Find 'em and kill 'em. All of 'em.", objectives = "" }
WordHunterWoW_QuestEN[11084] = { title = "Stand Tall, Captain!", description = "Well, well, well... still alive I see. That's good, because Mor'ghor has requested your presence in his tower at once. Get a move on!", objectives = "" }
WordHunterWoW_QuestEN[11085] = { title = "Escape from Skettis", description = "Hail, {name}.  I thank you for coming to my aid.\n\nThe arakkoa's monstrous birds knocked me from my nether ray while on a scouting mission.\n\nLet's get out of here, while we can.", objectives = "" }
WordHunterWoW_QuestEN[11086] = { title = "Disrupting the Twilight Portal", description = "One of your responsibilities as a captain of Dragonmaw is to snuff out Burning Legion activity in Outland. It is your duty to silence those that defy Lord Illidan!\n\nThe demons foolishly attempt to stabilize the portal found on the Twilight Ridge of western Nagrand. They must pay for their treachery, and you will be the orc that collects on their debt.\n\nTravel to the Twilight Ridge and lay waste to its inhabitants. You will be responsible for making at least one attack per day on their fortifications.", objectives = "" }
WordHunterWoW_QuestEN[11089] = { title = "The Soul Cannon of Reth'hedron", description = "Reth'hedron now lords over the Twilight Ridge of Nagrand. An eredar of such power being loosed upon this world does not bode well for the Illidari. Alas, we do not have the resources required to slay Reth'hedron. Not with the war the Sha'tar have brought to the Black Temple. No... I have a better plan.\n\nYou will subdue Reth'hedron, banishing him back through the Twilight Portal. For this a soul cannon must be fashioned.\n\nReturn to me with the materials on this list.", objectives = "" }
WordHunterWoW_QuestEN[11090] = { title = "Subdue the Subduer", description = "<Balthas holds up an alien looking device.>\n\nThis is a soul cannon. Its effects are devastating when attuned. This one is attuned to my blood. The same blood flowing through the veins of Reth'hedron - my brother. Aye, his misplaced allegiance will be the end of him.\n\nTake the cannon and fly to the Twilight Ridge in western Nagrand. Locate Reth'hedron and fire! You must stay on your mount and within range for the effects to take hold. Stand your ground against him and he will have no choice but to flee!", objectives = "" }
WordHunterWoW_QuestEN[11091] = { title = "A Special Thank You", description = "You honor us with your efforts on our behalf.  And now there is someone that we would like for you to meet.\n\nJho'nass is our most trusted quartermaster.  He maintains a stock of goods that we provide for sale to only the most dedicated of friends to Ogri'la.\n\nYou are one such friend, {name}.\n\nWhen you find the time, go and speak with him.  As we understand it, he has prepared a little something for you as a token of our appreciation.", objectives = "" }
WordHunterWoW_QuestEN[11092] = { title = "Hail, Commander!", description = "Captain {name}!\n\n<Taskmaster Varkule salutes you.>\n\nOverlord Mor'ghor has asked to see you in his chambers at once!", objectives = "" }
WordHunterWoW_QuestEN[11093] = { title = "Hungry Nether Rays", description = "Nether rays are surprisingly loyal and obedient once properly trained.  Unfortunately the war on Skettis is taking a toll on them.\n\nWe have dozens of sorties a day - the poor fellows rarely get a break.  And with recent shortages on feed, if those blasted birdmen don't kill them on a mission then starvation will.\n\nIf you can lend a hand, take one of our rays to the woods in the south.  They don't mind warp chaser meat as long as it's a fresh kill.", objectives = "" }
WordHunterWoW_QuestEN[11094] = { title = "Kill Them All!", description = "Commander {name}, stand at attention! You are to take a battalion of Skybreakers and sack the Scryers' outpost located at the foot of the Netherwing Fields. With the Sanctum of the Stars destroyed, our lines of communication to our posts at Eclipse Point and Illidari Point will once more be open.\n\nGo now! Use this flare gun to signal the Skybreakers for the attack!", objectives = "" }
WordHunterWoW_QuestEN[11095] = { title = "Commander Hobb", description = "The Dragonmaw only dare attack us when our guard is down. They would face certain defeat if they were to attack us while we were prepared.\n\nI want you to let them come, {name}.\n\n<Thelis nods.>\n\nYes... a trap. Take this flare that their overlord gave you and deliver it to Commander Hobb. He is standing guard right outside this building.", objectives = "" }
WordHunterWoW_QuestEN[11096] = { title = "Threat from Above", description = "So you want to join the Skyguard?  Well, I know you can fly... but can you fight?\n\nThe Skyguard is sworn to protect Shattrath from the dangers that loom above us, both near and far.  The Gordunni ogres who dwell in the Barrier Hills to the north are an immediate threat to us.\n\nReaching the ogres has been problematic for Shattrath's ground units.  That's where we come in.  See what you can do to help contain them.", objectives = "" }
WordHunterWoW_QuestEN[11097] = { title = "The Deadliest Trap Ever Laid", description = "Take these Scryer medals. Mor'ghor will need proof of \"victory\" once this is over. He will recognize them as coming from the corpses of fallen Scryer soldiers.\n\nNow all that remains is to use the signal flare to alert the Dragonmaw raiders. We will crush them when you are ready. Just give me the word.", objectives = "" }
WordHunterWoW_QuestEN[11098] = { title = "To Skettis!", description = "The Barrier Hills are only one of the fronts where we've been deployed.  A less immediate but far more dangerous threat looms from beyond the Skethyl Mountains, from within the arakkoa city of Skettis.\n\nA few months ago our scouts detected a huge increase in arakkoa activity there.  Several attacks against Shattrath followed.  We've stationed forces outside of their city since.\n\nTake these explosives to Sergeant Doryn at Blackwind Landing, just outside Skettis.  Tell him you're a new recruit.", objectives = "" }
WordHunterWoW_QuestEN[11099] = { title = "Kill Them All!", description = "Commander {name}, stand at attention! You are to take a battalion of Skybreakers and sack the Aldor outpost located northwest of our beloved Black Temple. With the Altar of Sha'tar destroyed, our lines of communication to our posts at Coilskar will once more be open.\n\nGo now! Use this flare gun to signal the Skybreakers for the attack!", objectives = "" }
WordHunterWoW_QuestEN[11100] = { title = "Commander Arcus", description = "The Dragonmaw only dare attack us when our guard is down. They would face certain defeat if they were to attack us while we were prepared.\n\nI want you to let them come, {name}.\n\n<Ceyla nods.>\n\nYes... a trap. Take this flare that their overlord gave you and deliver it to Commander Arcus. He is standing guard right outside this building.\n", objectives = "" }
WordHunterWoW_QuestEN[11101] = { title = "The Deadliest Trap Ever Laid", description = "Take these Aldor medals. Mor'ghor will need proof of \"victory\" once this is over. He will recognize them as coming from the corpses of fallen Aldor soldiers.\n\nNow all that remains is to use the signal flare to alert the Dragonmaw raiders. We will crush them when you are ready. Just give me the word.", objectives = "" }
WordHunterWoW_QuestEN[11102] = { title = "Bombing Run", description = "You can fly around as a crow... so what!  Ever annihilate something on the ground while you were flying?  Want to?\n\nForge Camp: Wrath and Forge Camp: Terror, to the north and south, are a major pain in my backside, as well as being a threat to peaceful Ogri'la.  With all of those fel cannons shooting down the Skyguard left and right, we can't get through there to take care of business.\n\nWant to prove yourself?  Take these bombs and knock out their ammo stacks.  Just don't let them shoot you down, too!", objectives = "" }
WordHunterWoW_QuestEN[11107] = { title = "Bow to the Highlord", description = "I am unworthy to even carry a message directed at you, sir. Please forgive me for this indulgence. Overlord Mor'ghor has requested your presence in his chambers at once!", objectives = "" }
WordHunterWoW_QuestEN[11108] = { title = "Lord Illidan Stormrage", description = "Come, highlord {name}. Illidan himself awaits us!", objectives = "" }
WordHunterWoW_QuestEN[11109] = { title = "Jorus the Cobalt Netherwing Drake", description = "", objectives = "" }
WordHunterWoW_QuestEN[11110] = { title = "Malfas the Purple Netherwing Drake", description = "", objectives = "" }
WordHunterWoW_QuestEN[11111] = { title = "Onyxien the Onyx Netherwing Drake", description = "", objectives = "" }
WordHunterWoW_QuestEN[11112] = { title = "Suraku the Azure Netherwing Drake", description = "", objectives = "" }
WordHunterWoW_QuestEN[11113] = { title = "Voranaku the Violet Netherwing Drake", description = "", objectives = "" }
WordHunterWoW_QuestEN[11114] = { title = "Zoya the Veridian Netherwing Drake", description = "", objectives = "" }
WordHunterWoW_QuestEN[11117] = { title = "Catch the Wild Wolpertinger!", description = "Here now. Ye hear that? There be sounds in them hills. Those're the wolpertingers! Wily beasts, they are, attracted by the smells o' Brewfest. I've a mind to catch me some, but I knocked me shin and can't outrun the buggers. Ye can help me, though!\n\nTake this net and cast it over the little blighters. Bring me a good five of 'em and I'll make it worth yer while!\n\nOne more thing - ye gotta use Synthebrew Goggles to spot 'em! Let me know if ya need a pair.", objectives = "" }
WordHunterWoW_QuestEN[11118] = { title = "Pink Elekks On Parade", description = "Getting drunk is a time-honored tradition at Brewfest -- it's damn near required! Thing is, I'm getting reports across Azeroth saying the celebration's plagued by hallucinations!  We can't have that!\n\nThese elekks can't be harmed by normal weapons -- they pass right through 'em -- so take this fabulous piece of gnomish machinery, visit one of the other beer gardens, and zap 'em to oblivion.\n\nRemember, you have to be wearing Synthebrew Goggles to see 'em! Talk to me if you need a pair.", objectives = "" }
WordHunterWoW_QuestEN[11119] = { title = "Assault on Bash'ir Landing!", description = "Heya, boyo!  Up fer some fun are ye?\n\nEvery couple o' hours, me aether-techs launch an assault on Bash'ir Landing, far ta the northeast in the Blade's Edge Mountains.  They say that they're there 'studying' the Bash'ir crystalforge, but it's an assault; there be no two ways about it.  We use the crystalforge to resupply, and there's always extra to be sold.\n\nGo on down ta the landin' pad and speak with the aether-tech apprentice.  He'll tell ye when the next mission is ta launch.", objectives = "" }
WordHunterWoW_QuestEN[11120] = { title = "Pink Elekks On Parade", description = "Brewfest is a time-honored celebration of food and drink. But sometimes drink gets the better of you! Excessive brew drinking can lead to many side effects... and we're getting many reports on hallucinations!\n\nFolks have been talking about seeing pink elekks, and I need you to take care of them. Take this goblin-engineered ray gun to one of the beer gardens and zap the elekks away. To keep yourself safe, I recommend wearing Synthebrew Goggles to see your targets while still keeping your wits about you.", objectives = "" }
WordHunterWoW_QuestEN[11122] = { title = "There and Back Again", description = "So you want to help out at Brewfest? I've got the perfect task for ya. I'll put you on one of my racing rams and you head down to Kharanos. I've got some kegs I need to pick up. \n\nFlynn Firebrew is waiting on a hill near a stack of kegs. He'll toss you a keg when you get near, then you run the keg back here and toss the keg to Pol Amberstill. You can only carry one at a time. \n\nReady?", objectives = "" }
WordHunterWoW_QuestEN[11129] = { title = "Kyle's Gone Missing!", description = "Help, {name}! My prized puppy, Kyle, has run away! I just know he's running around Bloodhoof Village, lost and hungry.\n\nWill you find him and feed him? Once he eats he will settle down and come home.\n\nTo feed him you will need to find food. His favorite meal is tender strider meat. Just venture east and you should find plenty of striders. Hunt one down and take its succulent meat to Kyle. When you see Kyle in town, put the meat down and he is sure to come to you.", objectives = "" }
WordHunterWoW_QuestEN[11131] = { title = "Stop the Fires!", description = "You must help us!  The Headless Horseman is attacking the village.  Fires are everywhere!  The children aren't safe!\n\nPlease, {name}, join the fire brigade.  Grab a bucket and toss it on the fires, or pass it to a friend who's closer to the blaze.  Put out all the fires and we may yet be saved!", objectives = "" }
WordHunterWoW_QuestEN[11135] = { title = "The Headless Horseman", description = "The Headless Horseman is driven away, but he will return as long as Hallow's End looms.  {name}, end our misery, and the insane lament of the Horseman.  Face him when he is joined with his head, and destroy it!\n\nHe rests in the Forlorn Cloister of the Scarlet Monastery, in Tirisfal Glades.  Find his pumpkin shrine and say this:\n\n  Horseman, rise\n  Your time is nigh\n  You felt death once\n  Now, know demise!\n\nGo, {name}.  And may the Light go with you.", objectives = "" }
WordHunterWoW_QuestEN[11153] = { title = "Break the Blockade", description = "All of our ships are sunk! We need your help to break the pirate blockade below in the Shattered Straits!\n\nTake these cluster bombs and hitch a ride on the zeppelin that Harrowmeiser has 'loaned' to us.  He'll fly you over the decks of those pirate scoundrels, and you make sure to give it to them good!\n\nIf you can't bomb them to smithereens, I'm afraid we'll never be able to break the blockade.", objectives = "" }
WordHunterWoW_QuestEN[11154] = { title = "Scare the Guano Out of Them!", description = "You, yes you... I need your help!\n\nPetrov sent me up here to get bat guano for the cluster bombs he's making back at the keep. He sent me to my doom!\n\nThe darkclaw bats hang out in the Rivenwood to the north, but I'm not taking a step off of this platform unless it's to go home!\n\nBut you... you could get it for me! Yes? Pretty please?!!!\n\nHere, take these firecrackers. My thinking is that if you drop 'em underneath the bats, the guano will be scared right out of them!", objectives = "" }
WordHunterWoW_QuestEN[11155] = { title = "Shoveltusk Soup Again?", description = "With all of the strange disappearances of our livestock, we better resupply in a hurry, or the beasties around these parts will be the least of our worries!\n\nSeeing as I'm in charge of feeding this lot, I'm going to need you to head east and get me some meat. More to the point, I'm looking to cook us up some tender shoveltusk meat.\n\nJust beware the stags... they're mean!", objectives = "" }
WordHunterWoW_QuestEN[11157] = { title = "The Clutches of Evil", description = "{name}, I don't trust anyone but you to take care of this.  I need the proto-drake eggs and proto-whelps in the burning forest to the southeast destroyed!\n\nSince we arrived here, the Ember Clutch has been ablaze; there must be some sort of perverse magic at work. And lately it seems to be growing. My men tell me that if we don't do something quickly, we'll be surrounded on all sides by the fire within a few weeks' time!\n\nGet down there and eliminate the threat by destroying those eggs and the proto-whelps.", objectives = "" }
